def _safe_error(e, context=''):
    """Log the real error server-side, return a generic message for the client."""
    logger.error(f"{context}: {e}" if context else str(e), exc_info=True)
    return 'An internal error occurred'

def require_debug_mode(f):
    """Decorator to restrict endpoints to debug mode only."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        if not DEBUG_MODE:
            return jsonify({'error': 'Not found'}), 404
        return f(*args, **kwargs)
    return decorated

def _ensure_removed_items_table(cur):
    """Create/migrate the durable rack-history table."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS removed_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_id TEXT,
            barcode TEXT,
            title TEXT,
            quantity_removed INTEGER,
            removed_at TEXT,
            searchrack_id INTEGER,
            old_quantity INTEGER,
            new_quantity INTEGER,
            removal_type TEXT,
            item_position TEXT,
            undone_at TEXT,
            event_id TEXT,
            source_row_json TEXT,
            result_row_json TEXT,
            from_position TEXT,
            to_position TEXT,
            inventory_row_deleted INTEGER DEFAULT 0,
            event_status TEXT DEFAULT 'applied',
            applied_at TEXT
        )
    ''')
    cur.execute("PRAGMA table_info(removed_items)")
    existing = {str(row[1]).lower() for row in cur.fetchall()}
    migrations = {
        'order_id': 'TEXT',
        'barcode': 'TEXT',
        'title': 'TEXT',
        'quantity_removed': 'INTEGER',
        'removed_at': 'TEXT',
        'searchrack_id': 'INTEGER',
        'old_quantity': 'INTEGER',
        'new_quantity': 'INTEGER',
        'removal_type': 'TEXT',
        'item_position': 'TEXT',
        'undone_at': 'TEXT',
        'event_id': 'TEXT',
        'source_row_json': 'TEXT',
        'result_row_json': 'TEXT',
        'from_position': 'TEXT',
        'to_position': 'TEXT',
        'inventory_row_deleted': 'INTEGER DEFAULT 0',
        'event_status': "TEXT DEFAULT 'applied'",
        'applied_at': 'TEXT',
    }
    for column, definition in migrations.items():
        if column not in existing:
            cur.execute(f'ALTER TABLE removed_items ADD COLUMN "{column}" {definition}')

    cur.execute('''
        CREATE UNIQUE INDEX IF NOT EXISTS idx_removed_items_event_id
        ON removed_items(event_id)
        WHERE event_id IS NOT NULL AND event_id != ''
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_items_barcode ON removed_items(barcode)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_items_searchrack_id ON removed_items(searchrack_id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_items_position ON removed_items(item_position)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_items_removed_at ON removed_items(removed_at)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_items_order_id ON removed_items(order_id)')


def _ensure_legacy_removed_table(cur):
    """Keep the retired removal log linked to its authoritative detailed event."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS removed (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            barcode TEXT,
            qty INTEGER,
            time_removed TEXT,
            undone_at TEXT,
            detail_history_id INTEGER,
            source_location TEXT
        )
    ''')
    cur.execute('PRAGMA table_info(removed)')
    existing = {str(row[1]).lower() for row in cur.fetchall()}
    if 'undone_at' not in existing:
        cur.execute('ALTER TABLE removed ADD COLUMN undone_at TEXT')
    if 'detail_history_id' not in existing:
        cur.execute('ALTER TABLE removed ADD COLUMN detail_history_id INTEGER')
    if 'source_location' not in existing:
        cur.execute('ALTER TABLE removed ADD COLUMN source_location TEXT')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_removed_detail_history_id ON removed(detail_history_id)')


def _sqlite_ident(name):
    return '"' + str(name).replace('"', '""') + '"'


def _row_casefold_dict(row):
    if row is None:
        return {}
    data = dict(row) if not isinstance(row, dict) else dict(row)
    return {str(key).lower(): value for key, value in data.items()}


def _searchrack_snapshot_location(snapshot):
    data = _row_casefold_dict(snapshot)
    item_position = str(data.get('item_position') or data.get('itemposition') or data.get('position') or '').strip()
    picture_position = str(data.get('pictureposition') or data.get('picture_position') or '').strip()
    if picture_position and item_position.lower() in ('', 'picture'):
        return picture_position
    return item_position or picture_position


def _searchrack_snapshot_value(snapshot, *names, default=''):
    data = _row_casefold_dict(snapshot)
    for name in names:
        value = data.get(str(name).lower())
        if value is not None:
            return value
    return default


def _ensure_searchrack_history_outbox(cur):
    """Outbox lives beside SEARCHRACK so its snapshot and mutation are one WAL transaction."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS searchrack_history_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT NOT NULL UNIQUE,
            event_type TEXT NOT NULL,
            captured_at TEXT NOT NULL,
            searchrack_id INTEGER,
            barcode TEXT,
            title TEXT,
            from_position TEXT,
            to_position TEXT,
            old_quantity INTEGER,
            new_quantity INTEGER,
            source_row_json TEXT,
            result_row_json TEXT,
            processed_at TEXT,
            history_id INTEGER,
            last_error TEXT
        )
    ''')
    cur.execute('''
        CREATE INDEX IF NOT EXISTS idx_searchrack_history_outbox_pending
        ON searchrack_history_outbox(processed_at, id)
    ''')


def _ensure_searchrack_undo_claims(cur):
    """Idempotency claims committed in the same transaction as inventory restoration."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS searchrack_undo_claims (
            history_source TEXT NOT NULL,
            history_id INTEGER NOT NULL,
            claimed_at TEXT NOT NULL,
            searchrack_id INTEGER,
            restore_quantity INTEGER NOT NULL,
            old_quantity INTEGER,
            new_quantity INTEGER,
            recreated INTEGER DEFAULT 0,
            outbox_event_id TEXT,
            PRIMARY KEY (history_source, history_id)
        )
    ''')
    cur.execute('PRAGMA table_info(searchrack_undo_claims)')
    existing = {str(row[1]).lower() for row in cur.fetchall()}
    if 'outbox_event_id' not in existing:
        cur.execute('ALTER TABLE searchrack_undo_claims ADD COLUMN outbox_event_id TEXT')


def _searchrack_trigger_value(prefix, column, fallback='NULL'):
    return f'{prefix}.{_sqlite_ident(column)}' if column else fallback


def _searchrack_trigger_location(prefix, pos_col, pic_col):
    pos = _searchrack_trigger_value(prefix, pos_col, "''")
    pic = _searchrack_trigger_value(prefix, pic_col, "''")
    return f'''(
        CASE
            WHEN LOWER(TRIM(COALESCE({pos}, ''))) IN ('', 'picture')
                 AND TRIM(COALESCE({pic}, '')) != ''
            THEN TRIM(COALESCE({pic}, ''))
            ELSE COALESCE(NULLIF(TRIM(COALESCE({pos}, '')), ''), TRIM(COALESCE({pic}, '')), '')
        END
    )'''


def _searchrack_trigger_snapshot(prefix, columns):
    pairs = []
    for column in columns:
        label = "'" + str(column).replace("'", "''") + "'"
        pairs.extend([label, f'{prefix}.{_sqlite_ident(column)}'])
    return 'json_object(' + ', '.join(pairs) + ')'


def _searchrack_trigger_integral_quantity(value_sql):
    """SQLite expression accepting only integer-valued quantities, including legacy digit text."""
    text_sql = f'TRIM(CAST({value_sql} AS TEXT))'
    return f'''(
        CASE
            WHEN typeof({value_sql}) = 'integer' THEN 1
            WHEN typeof({value_sql}) = 'real'
                 AND {value_sql} = CAST({value_sql} AS INTEGER) THEN 1
            WHEN typeof({value_sql}) = 'text'
                 AND {text_sql} != ''
                 AND (
                     {text_sql} NOT GLOB '*[^0-9]*'
                     OR (
                         SUBSTR({text_sql}, 1, 1) IN ('-', '+')
                         AND LENGTH({text_sql}) > 1
                         AND SUBSTR({text_sql}, 2) NOT GLOB '*[^0-9]*'
                     )
                 ) THEN 1
            ELSE 0
        END
    )'''


def _install_searchrack_history_guard(conn):
    """Install persistent triggers that prevent non-positive rows and capture every stock/location change."""
    cur = conn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND LOWER(name)='searchrack'")
    if not cur.fetchone():
        return {'installed': False, 'reason': 'SEARCHRACK table not found'}

    cur.execute("PRAGMA table_info('SEARCHRACK')")
    columns = [row[1] for row in cur.fetchall()]
    lower = {str(column).lower(): column for column in columns}
    qty_col = lower.get('quantity') or lower.get('qty')
    if not qty_col:
        return {'installed': False, 'reason': 'SEARCHRACK quantity column not found'}

    id_col = lower.get('id')
    barcode_col = lower.get('barcode') or lower.get('upc')
    title_col = lower.get('title')
    pos_col = lower.get('item_position') or lower.get('itemposition') or lower.get('position')
    pic_col = lower.get('pictureposition') or lower.get('picture_position')
    _ensure_searchrack_history_outbox(cur)
    _ensure_searchrack_undo_claims(cur)
    cur.execute('''
        CREATE TABLE IF NOT EXISTS searchrack_history_guard_meta (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
    ''')
    conn.commit()

    qty_new = _searchrack_trigger_value('NEW', qty_col, '0')
    qty_old = _searchrack_trigger_value('OLD', qty_col, '0')
    row_id_new = _searchrack_trigger_value('NEW', id_col, 'NEW.rowid')
    row_id_old = _searchrack_trigger_value('OLD', id_col, 'OLD.rowid')
    barcode_new = _searchrack_trigger_value('NEW', barcode_col, "''")
    barcode_old = _searchrack_trigger_value('OLD', barcode_col, "''")
    title_new = _searchrack_trigger_value('NEW', title_col, "''")
    title_old = _searchrack_trigger_value('OLD', title_col, "''")
    from_location = _searchrack_trigger_location('OLD', pos_col, pic_col)
    to_location = _searchrack_trigger_location('NEW', pos_col, pic_col)
    old_snapshot = _searchrack_trigger_snapshot('OLD', columns)
    new_snapshot = _searchrack_trigger_snapshot('NEW', columns)

    watched_columns = [qty_col]
    for column in (pos_col, pic_col):
        if column and column not in watched_columns:
            watched_columns.append(column)
    watched_sql = ', '.join(_sqlite_ident(column) for column in watched_columns)
    changed_checks = [f'COALESCE(CAST({qty_new} AS INTEGER), 0) != COALESCE(CAST({qty_old} AS INTEGER), 0)']
    if pos_col:
        pos_new = _searchrack_trigger_value('NEW', pos_col, "''")
        pos_old = _searchrack_trigger_value('OLD', pos_col, "''")
        changed_checks.append(
            f"TRIM(COALESCE({pos_new}, '')) != TRIM(COALESCE({pos_old}, ''))"
        )
    if pic_col:
        pic_new = _searchrack_trigger_value('NEW', pic_col, "''")
        pic_old = _searchrack_trigger_value('OLD', pic_col, "''")
        changed_checks.append(
            f"TRIM(COALESCE({pic_new}, '')) != TRIM(COALESCE({pic_old}, ''))"
        )
    changed_when = ' OR '.join(changed_checks)
    integral_new = _searchrack_trigger_integral_quantity(qty_new)

    validate_insert_sql = f'''
        CREATE TRIGGER trg_searchrack_quantity_validate_insert_v3
        BEFORE INSERT ON SEARCHRACK
        WHEN {integral_new} = 0
        BEGIN
            SELECT RAISE(ABORT, 'SEARCHRACK quantity must be a finite whole number');
        END
    '''
    validate_update_sql = f'''
        CREATE TRIGGER trg_searchrack_quantity_validate_update_v3
        BEFORE UPDATE OF {_sqlite_ident(qty_col)} ON SEARCHRACK
        WHEN {integral_new} = 0
        BEGIN
            SELECT RAISE(ABORT, 'SEARCHRACK quantity must be a finite whole number');
        END
    '''
    update_sql = f'''
        CREATE TRIGGER trg_searchrack_history_update_v3
        AFTER UPDATE OF {watched_sql} ON SEARCHRACK
        WHEN {changed_when}
        BEGIN
            INSERT INTO searchrack_history_outbox (
                event_id, event_type, captured_at, searchrack_id, barcode, title,
                from_position, to_position, old_quantity, new_quantity,
                source_row_json, result_row_json
            ) VALUES (
                lower(hex(randomblob(16))),
                CASE
                    WHEN COALESCE(CAST({qty_new} AS INTEGER), 0) <= 0 THEN 'depletion'
                    WHEN COALESCE(CAST({qty_new} AS INTEGER), 0) != COALESCE(CAST({qty_old} AS INTEGER), 0) THEN 'quantity_change'
                    ELSE 'location_change'
                END,
                strftime('%Y-%m-%dT%H:%M:%f', 'now', 'localtime'),
                {row_id_old}, {barcode_old}, {title_old}, {from_location}, {to_location},
                COALESCE(CAST({qty_old} AS INTEGER), 0), COALESCE(CAST({qty_new} AS INTEGER), 0),
                {old_snapshot}, {new_snapshot}
            );
            DELETE FROM SEARCHRACK
            WHERE rowid = NEW.rowid AND COALESCE(CAST({qty_new} AS INTEGER), 0) <= 0;
        END
    '''

    insert_location = _searchrack_trigger_location('NEW', pos_col, pic_col)
    insert_sql = f'''
        CREATE TRIGGER trg_searchrack_history_insert_v3
        AFTER INSERT ON SEARCHRACK
        BEGIN
            INSERT INTO searchrack_history_outbox (
                event_id, event_type, captured_at, searchrack_id, barcode, title,
                from_position, to_position, old_quantity, new_quantity,
                source_row_json, result_row_json
            ) VALUES (
                lower(hex(randomblob(16))),
                CASE WHEN COALESCE(CAST({qty_new} AS INTEGER), 0) <= 0
                     THEN 'invalid_insert_cleanup' ELSE 'inventory_add' END,
                strftime('%Y-%m-%dT%H:%M:%f', 'now', 'localtime'),
                {row_id_new}, {barcode_new}, {title_new}, '', {insert_location},
                0, COALESCE(CAST({qty_new} AS INTEGER), 0),
                {new_snapshot}, {new_snapshot}
            );
            DELETE FROM SEARCHRACK
            WHERE rowid = NEW.rowid AND COALESCE(CAST({qty_new} AS INTEGER), 0) <= 0;
        END
    '''

    delete_location = _searchrack_trigger_location('OLD', pos_col, pic_col)
    delete_sql = f'''
        CREATE TRIGGER trg_searchrack_history_delete_v3
        AFTER DELETE ON SEARCHRACK
        WHEN NOT EXISTS (
            SELECT 1
            FROM searchrack_history_outbox
            WHERE searchrack_id = {row_id_old}
              AND processed_at IS NULL
              AND event_type IN (
                  'depletion', 'invalid_insert_cleanup',
                  'legacy_zero_cleanup', 'invalid_quantity_cleanup'
              )
              AND (
                  json(COALESCE(NULLIF(result_row_json, ''), '{{}}')) = json({old_snapshot})
                  OR (
                      event_type IN ('legacy_zero_cleanup', 'invalid_quantity_cleanup')
                      AND json(COALESCE(NULLIF(source_row_json, ''), '{{}}')) = json({old_snapshot})
                  )
              )
        )
        BEGIN
            INSERT INTO searchrack_history_outbox (
                event_id, event_type, captured_at, searchrack_id, barcode, title,
                from_position, to_position, old_quantity, new_quantity,
                source_row_json, result_row_json
            ) VALUES (
                lower(hex(randomblob(16))), 'inventory_delete',
                strftime('%Y-%m-%dT%H:%M:%f', 'now', 'localtime'),
                {row_id_old}, {barcode_old}, {title_old}, {delete_location}, '',
                COALESCE(CAST({qty_old} AS INTEGER), 0), 0, {old_snapshot}, NULL
            );
        END
    '''

    trigger_sql = [validate_insert_sql, validate_update_sql, update_sql, insert_sql, delete_sql]
    fingerprint = hashlib.sha256('\n'.join(trigger_sql).encode('utf-8')).hexdigest()
    current_names = {
        'trg_searchrack_quantity_validate_insert_v3',
        'trg_searchrack_quantity_validate_update_v3',
        'trg_searchrack_history_update_v3',
        'trg_searchrack_history_insert_v3',
        'trg_searchrack_history_delete_v3',
    }

    # Trigger replacement is transactional, so there is never an unguarded write window.
    cur.execute('BEGIN IMMEDIATE')
    try:
        cur.execute("SELECT value FROM searchrack_history_guard_meta WHERE key = 'trigger_fingerprint'")
        row = cur.fetchone()
        saved_fingerprint = str(row[0] or '') if row else ''
        placeholders = ','.join('?' for _ in current_names)
        cur.execute(
            f"SELECT name FROM sqlite_master WHERE type = 'trigger' AND name IN ({placeholders})",
            tuple(sorted(current_names))
        )
        installed_names = {str(row[0]) for row in cur.fetchall()}

        if saved_fingerprint != fingerprint or installed_names != current_names:
            for version in ('v1', 'v2', 'v3'):
                for kind in ('update', 'insert', 'delete'):
                    cur.execute(
                        f'DROP TRIGGER IF EXISTS {_sqlite_ident(f"trg_searchrack_history_{kind}_{version}")}'
                    )
            for name in (
                'trg_searchrack_quantity_validate_insert_v3',
                'trg_searchrack_quantity_validate_update_v3',
            ):
                cur.execute(f'DROP TRIGGER IF EXISTS {_sqlite_ident(name)}')
            for sql in trigger_sql:
                cur.execute(sql)
            cur.execute('''
                INSERT INTO searchrack_history_guard_meta(key, value)
                VALUES ('trigger_fingerprint', ?)
                ON CONFLICT(key) DO UPDATE SET value = excluded.value
            ''', (fingerprint,))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {'installed': True, 'qty_col': qty_col, 'id_col': id_col, 'columns': columns}


def _strict_inventory_quantity(value):
    if value is None or str(value).strip() == '':
        return None
    try:
        parsed = Decimal(str(value).strip())
        if not parsed.is_finite() or parsed != parsed.to_integral_value():
            return None
        return int(parsed)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def _ensure_searchrack_snapshot_columns(conn):
    """Ensure known inventory metadata is present before snapshot triggers are generated."""
    cur = conn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND LOWER(name)='searchrack'")
    if not cur.fetchone():
        return False
    cur.execute("PRAGMA table_info('SEARCHRACK')")
    existing = {str(row[1]).lower() for row in cur.fetchall()}
    migrations = {
        'created_at': 'ALTER TABLE SEARCHRACK ADD COLUMN CREATED_AT TEXT',
        'image': 'ALTER TABLE SEARCHRACK ADD COLUMN IMAGE TEXT',
        'custom_title': 'ALTER TABLE SEARCHRACK ADD COLUMN CUSTOM_TITLE INTEGER DEFAULT 0',
        'warehouse_note': 'ALTER TABLE SEARCHRACK ADD COLUMN WAREHOUSE_NOTE TEXT DEFAULT ""',
    }
    changed = False
    for column, sql in migrations.items():
        if column not in existing:
            cur.execute(sql)
            changed = True
    conn.commit()
    return changed


def _capture_legacy_zero_searchrack_rows(conn, guard_info):
    """Snapshot and remove pre-guard zero rows; normalize historical blank quantities to one."""
    qty_col = guard_info.get('qty_col')
    id_col = guard_info.get('id_col')
    columns = list(guard_info.get('columns') or [])
    if not qty_col or not columns:
        return {'normalized': 0, 'deleted': 0}

    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    _ensure_searchrack_history_outbox(cur)
    conn.commit()
    cur.execute('BEGIN IMMEDIATE')
    cur.execute('SELECT rowid AS _guard_rowid_, * FROM SEARCHRACK')
    rows = list(cur.fetchall())
    normalized = 0
    deleted = 0

    for row in rows:
        row_dict = dict(row)
        raw_qty = row_dict.get(qty_col)
        parsed_qty = _strict_inventory_quantity(raw_qty)
        rowid = row_dict.get('_guard_rowid_')
        searchrack_id = row_dict.get(id_col) if id_col else rowid

        cleanup_event_type = 'legacy_zero_cleanup'
        if parsed_qty is None:
            if raw_qty is None or str(raw_qty).strip() == '':
                cur.execute(
                    f'UPDATE SEARCHRACK SET {_sqlite_ident(qty_col)} = 1 WHERE rowid = ?',
                    (rowid,)
                )
                normalized += max(0, cur.rowcount)
                continue
            parsed_qty = 0
            cleanup_event_type = 'invalid_quantity_cleanup'
        if parsed_qty > 0:
            continue

        snapshot = {column: row_dict.get(column) for column in columns}
        event_id = uuid.uuid4().hex
        location = _searchrack_snapshot_location(snapshot)
        cur.execute('''
            INSERT OR IGNORE INTO searchrack_history_outbox (
                event_id, event_type, captured_at, searchrack_id, barcode, title,
                from_position, to_position, old_quantity, new_quantity,
                source_row_json, result_row_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, '', ?, 0, ?, NULL)
        ''', (
            event_id,
            cleanup_event_type,
            datetime.datetime.now().isoformat(),
            searchrack_id,
            str(_searchrack_snapshot_value(snapshot, 'barcode', 'upc') or '').strip(),
            str(_searchrack_snapshot_value(snapshot, 'title') or '').strip(),
            location,
            parsed_qty,
            json.dumps(snapshot, ensure_ascii=False, default=str)
        ))
        cur.execute(
            'DELETE FROM SEARCHRACK WHERE rowid = ?',
            (rowid,)
        )
        deleted += max(0, cur.rowcount)

    try:
        cur.execute('DELETE FROM zero_qty_pending_deletion')
    except sqlite3.Error:
        pass
    conn.commit()
    return {'normalized': normalized, 'deleted': deleted}


def _history_timestamp(value):
    text = str(value or '').strip()
    if not text:
        return None
    try:
        parsed = datetime.datetime.fromisoformat(text.replace('Z', '+00:00'))
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone().replace(tzinfo=None)
        return parsed
    except Exception:
        return None


def _history_event_candidate(rem_cur, event):
    searchrack_id = event.get('searchrack_id')
    if searchrack_id is None:
        return None
    rem_cur.execute('''
        SELECT *
        FROM removed_items
        WHERE searchrack_id = ?
          AND COALESCE(event_id, '') = ''
          AND COALESCE(event_status, 'applied') != 'superseded'
        ORDER BY id DESC
        LIMIT 30
    ''', (searchrack_id,))
    candidates = [dict(row) for row in rem_cur.fetchall()]
    if not candidates:
        return None

    event_time = _history_timestamp(event.get('captured_at'))
    event_barcode = str(event.get('barcode') or '').strip().lower()
    event_from = str(event.get('from_position') or '').strip().lower()
    event_to = str(event.get('to_position') or '').strip().lower()
    event_old = _coerce_int(event.get('old_quantity'), 0)
    event_new = _coerce_int(event.get('new_quantity'), 0)
    event_type = str(event.get('event_type') or '')
    best = None
    best_score = -1

    for candidate in candidates:
        candidate_time = _history_timestamp(candidate.get('removed_at'))
        if event_time is not None and candidate_time is not None:
            seconds = abs((event_time - candidate_time).total_seconds())
            if seconds > 600:
                continue
            time_score = 5 if seconds <= 120 else 2
        else:
            continue

        score = time_score
        candidate_old = _coerce_int(candidate.get('old_quantity'), 0)
        candidate_new = _coerce_int(candidate.get('new_quantity'), 0)
        if candidate_old == event_old and candidate_new == event_new:
            score += 8
        elif event_type == 'location_change':
            score += 2

        candidate_barcode = str(candidate.get('barcode') or '').strip().lower()
        if event_barcode and candidate_barcode == event_barcode:
            score += 3

        candidate_position = str(candidate.get('item_position') or '').strip().lower()
        if candidate_position and candidate_position in {event_from, event_to}:
            score += 3

        removal_type = str(candidate.get('removal_type') or '').lower()
        if event_type == 'location_change' and ('location' in removal_type or 'shelf' in removal_type):
            score += 4
        if event_type == 'inventory_add' and candidate_old == 0 and candidate_new == event_new:
            score += 4

        if score > best_score:
            best = candidate
            best_score = score

    return best if best_score >= 8 else None


_searchrack_history_flush_lock = threading.Lock()


def _flush_searchrack_history_outbox(limit=250, settle_seconds=0):
    """Mirror durable SEARCHRACK events into rackhistory.db; retries are idempotent by event_id."""
    if not _searchrack_history_flush_lock.acquire(blocking=False):
        return 0
    rack_conn = None
    rem_conn = None
    processed = 0
    try:
        rack_conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'), timeout=30.0)
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        _ensure_searchrack_history_outbox(rack_cur)
        rack_cur.execute('''
            SELECT * FROM searchrack_history_outbox
            WHERE processed_at IS NULL
            ORDER BY CASE WHEN COALESCE(last_error, '') = '' THEN 0 ELSE 1 END, id
            LIMIT ?
        ''', (max(1, int(limit or 250)),))
        events = [dict(row) for row in rack_cur.fetchall()]
        settle_seconds = max(0.0, float(settle_seconds or 0))
        if settle_seconds:
            cutoff = datetime.datetime.now() - datetime.timedelta(seconds=settle_seconds)
            settled_events = []
            for event in events:
                captured_at = _history_timestamp(event.get('captured_at'))
                if captured_at is not None and captured_at > cutoff:
                    break
                settled_events.append(event)
            events = settled_events
        if not events:
            rack_conn.commit()
            return 0

        rem_conn = sqlite3.connect(str(BASE_DIR / 'rackhistory.db'), timeout=30.0)
        rem_conn.row_factory = sqlite3.Row
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        rem_conn.commit()

        type_map = {
            'legacy_zero_cleanup': 'legacy_zero_cleanup',
            'invalid_quantity_cleanup': 'invalid_quantity_cleanup',
            'invalid_insert_cleanup': 'invalid_zero_insert',
            'depletion': 'inventory_depleted',
            'quantity_change': 'quantity_adjustment',
            'location_change': 'location_change',
            'inventory_add': 'inventory_added',
            'inventory_delete': 'inventory_deleted',
        }

        processed_marks = []
        failed_event = None
        event_savepoint_active = False
        for event in events:
            failed_event = event
            rem_cur.execute('SAVEPOINT searchrack_history_event')
            event_savepoint_active = True
            event_id = str(event.get('event_id') or '').strip()
            if not event_id:
                raise ValueError('Rack-history outbox event has no event_id')
            rem_cur.execute('SELECT id FROM removed_items WHERE event_id = ?', (event_id,))
            existing_event = rem_cur.fetchone()
            if existing_event:
                history_id = existing_event['id']
                rem_cur.execute('''
                    UPDATE removed_items
                    SET source_row_json = COALESCE(NULLIF(source_row_json, ''), ?),
                        result_row_json = COALESCE(NULLIF(result_row_json, ''), ?),
                        from_position = COALESCE(NULLIF(from_position, ''), ?),
                        to_position = COALESCE(NULLIF(to_position, ''), ?),
                        event_status = 'applied',
                        applied_at = COALESCE(NULLIF(applied_at, ''), ?)
                    WHERE id = ?
                ''', (
                    event.get('source_row_json'),
                    event.get('result_row_json'),
                    str(event.get('from_position') or '').strip(),
                    str(event.get('to_position') or '').strip(),
                    str(event.get('captured_at') or datetime.datetime.now().isoformat()),
                    history_id,
                ))
            else:
                candidate = _history_event_candidate(rem_cur, event)
                old_qty = _coerce_int(event.get('old_quantity'), 0)
                new_qty = _coerce_int(event.get('new_quantity'), 0)
                event_type = str(event.get('event_type') or '')
                actual_delta = abs(new_qty - old_qty)
                if event_type == 'location_change':
                    actual_delta = 0
                deleted = 1 if event_type in (
                    'legacy_zero_cleanup', 'invalid_quantity_cleanup',
                    'invalid_insert_cleanup', 'depletion', 'inventory_delete'
                ) else 0
                from_position = str(event.get('from_position') or '').strip()
                to_position = str(event.get('to_position') or '').strip()
                effective_position = from_position or to_position
                applied_at = str(event.get('captured_at') or datetime.datetime.now().isoformat())

                if candidate:
                    history_id = candidate['id']
                    if event_type == 'location_change':
                        rem_cur.execute('''
                            UPDATE removed_items
                            SET event_status = 'superseded'
                            WHERE id != ?
                              AND searchrack_id = ?
                              AND COALESCE(removed_at, '') = COALESCE(?, '')
                              AND COALESCE(removal_type, '') = COALESCE(?, '')
                              AND COALESCE(barcode, '') = COALESCE(?, '')
                              AND COALESCE(event_id, '') = ''
                        ''', (
                            history_id,
                            event.get('searchrack_id'),
                            candidate.get('removed_at'),
                            candidate.get('removal_type'),
                            candidate.get('barcode'),
                        ))
                    rem_cur.execute('''
                        UPDATE removed_items
                        SET event_id = ?, barcode = COALESCE(NULLIF(barcode, ''), ?),
                            title = COALESCE(NULLIF(title, ''), ?), quantity_removed = ?,
                            old_quantity = ?, new_quantity = ?,
                            item_position = COALESCE(NULLIF(item_position, ''), ?),
                            source_row_json = ?, result_row_json = ?,
                            from_position = ?, to_position = ?,
                            inventory_row_deleted = ?, event_status = 'applied', applied_at = ?
                        WHERE id = ?
                    ''', (
                        event_id,
                        str(event.get('barcode') or '').strip(),
                        str(event.get('title') or '').strip(),
                        actual_delta,
                        old_qty,
                        new_qty,
                        effective_position,
                        event.get('source_row_json'),
                        event.get('result_row_json'),
                        from_position,
                        to_position,
                        deleted,
                        applied_at,
                        history_id,
                    ))
                else:
                    rem_cur.execute('''
                        INSERT INTO removed_items (
                            order_id, barcode, title, quantity_removed, removed_at,
                            searchrack_id, old_quantity, new_quantity, removal_type,
                            item_position, event_id, source_row_json, result_row_json,
                            from_position, to_position, inventory_row_deleted,
                            event_status, applied_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'applied', ?)
                    ''', (
                        None,
                        str(event.get('barcode') or '').strip(),
                        str(event.get('title') or '').strip(),
                        actual_delta,
                        applied_at,
                        event.get('searchrack_id'),
                        old_qty,
                        new_qty,
                        type_map.get(event_type, event_type or 'inventory_change'),
                        effective_position,
                        event_id,
                        event.get('source_row_json'),
                        event.get('result_row_json'),
                        from_position,
                        to_position,
                        deleted,
                        applied_at,
                    ))
                    history_id = rem_cur.lastrowid

            rem_cur.execute('RELEASE SAVEPOINT searchrack_history_event')
            event_savepoint_active = False
            processed_marks.append((history_id, event['id']))

        # One history fsync and one outbox fsync per batch keeps this inexpensive on the Pi.
        rem_conn.commit()
        processed_at = datetime.datetime.now().isoformat()
        rack_cur.executemany('''
            UPDATE searchrack_history_outbox
            SET processed_at = ?, history_id = ?, last_error = NULL
            WHERE id = ? AND processed_at IS NULL
        ''', [(processed_at, history_id, event_id) for history_id, event_id in processed_marks])
        rack_conn.commit()
        processed = len(processed_marks)
        return processed
    except Exception as exc:
        # Preserve earlier good events in the batch and move one bad event behind fresh work.
        if event_savepoint_active and rem_conn is not None and rack_conn is not None:
            try:
                rem_cur.execute('ROLLBACK TO SAVEPOINT searchrack_history_event')
                rem_cur.execute('RELEASE SAVEPOINT searchrack_history_event')
                rem_conn.commit()
                processed_at = datetime.datetime.now().isoformat()
                if processed_marks:
                    rack_cur.executemany('''
                        UPDATE searchrack_history_outbox
                        SET processed_at = ?, history_id = ?, last_error = NULL
                        WHERE id = ? AND processed_at IS NULL
                    ''', [
                        (processed_at, history_id, outbox_id)
                        for history_id, outbox_id in processed_marks
                    ])
                if failed_event is not None:
                    rack_cur.execute('''
                        UPDATE searchrack_history_outbox
                        SET last_error = ?
                        WHERE id = ? AND processed_at IS NULL
                    ''', (str(exc)[:1000], failed_event.get('id')))
                rack_conn.commit()
                processed = len(processed_marks)
                print(f'Warning: one rack-history event was deferred without blocking the batch: {exc}')
                return processed
            except Exception:
                try:
                    rem_conn.rollback()
                except Exception:
                    pass
                try:
                    rack_conn.rollback()
                except Exception:
                    pass
        try:
            if rem_conn is not None:
                rem_conn.rollback()
        except Exception:
            pass
        try:
            if rack_conn is not None:
                rack_conn.rollback()
        except Exception:
            pass
        print(f'Warning: rack-history outbox flush deferred: {exc}')
        return processed
    finally:
        if rem_conn is not None:
            rem_conn.close()
        if rack_conn is not None:
            rack_conn.close()
        _searchrack_history_flush_lock.release()


def _initialize_searchrack_history_guard():
    conn = None
    try:
        conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'), timeout=30.0)
        _ensure_searchrack_snapshot_columns(conn)
        guard = _install_searchrack_history_guard(conn)
        if not guard.get('installed'):
            return guard
        cleanup = _capture_legacy_zero_searchrack_rows(conn, guard)
        with sqlite3.connect(str(BASE_DIR / 'rackhistory.db'), timeout=30.0) as history_conn:
            _ensure_removed_items_table(history_conn.cursor())
        mirrored = _flush_searchrack_history_outbox()
        age_summary = _reconcile_inventory_age_batches(conn)
        if cleanup.get('normalized') or cleanup.get('deleted'):
            try:
                _invalidate_searchrack_cache()
            except Exception:
                pass
        return {**guard, **cleanup, 'mirrored': mirrored, 'inventory_age': age_summary}
    finally:
        if conn is not None:
            conn.close()


def _ensure_inventory_age_schema(conn):
    """Create the persistent FIFO receiving-batch ledger in searchRack.db."""
    cur = conn.cursor()
    cur.execute('''
        CREATE TABLE IF NOT EXISTS inventory_age_batches (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            searchrack_id INTEGER NOT NULL,
            barcode TEXT,
            received_at TEXT NOT NULL,
            quantity INTEGER NOT NULL CHECK(quantity > 0),
            source TEXT NOT NULL DEFAULT 'inventory',
            source_history_id INTEGER,
            estimated INTEGER NOT NULL DEFAULT 0,
            lot_number TEXT NOT NULL DEFAULT '',
            evidence_source TEXT NOT NULL DEFAULT '',
            confidence TEXT NOT NULL DEFAULT 'low',
            confidence_score INTEGER NOT NULL DEFAULT 0,
            evidence_json TEXT NOT NULL DEFAULT '{}',
            rebuild_run_id TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute("PRAGMA table_info('inventory_age_batches')")
    existing_columns = {
        str(row[1]).strip().casefold()
        for row in cur.fetchall()
    }
    migration_columns = {
        'lot_number': "TEXT NOT NULL DEFAULT ''",
        'evidence_source': "TEXT NOT NULL DEFAULT ''",
        'confidence': "TEXT NOT NULL DEFAULT 'low'",
        'confidence_score': 'INTEGER NOT NULL DEFAULT 0',
        'evidence_json': "TEXT NOT NULL DEFAULT '{}'",
        'rebuild_run_id': 'TEXT',
    }
    for column, declaration in migration_columns.items():
        if column not in existing_columns:
            cur.execute(
                f'ALTER TABLE inventory_age_batches '
                f'ADD COLUMN {_sqlite_ident(column)} {declaration}'
            )
    cur.execute('''
        CREATE TABLE IF NOT EXISTS inventory_age_meta (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS inventory_age_rebuild_runs (
            run_id TEXT PRIMARY KEY,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            input_digest TEXT NOT NULL,
            plan_digest TEXT NOT NULL,
            mode TEXT NOT NULL DEFAULT 'comprehensive',
            status TEXT NOT NULL,
            summary_json TEXT NOT NULL DEFAULT '{}',
            before_ledger_json TEXT NOT NULL DEFAULT '[]',
            after_ledger_json TEXT NOT NULL DEFAULT '[]'
        )
    ''')
    cur.execute('''
        CREATE INDEX IF NOT EXISTS idx_inventory_age_row_fifo
        ON inventory_age_batches(searchrack_id, received_at, id)
    ''')
    cur.execute('''
        CREATE UNIQUE INDEX IF NOT EXISTS idx_inventory_age_history_event
        ON inventory_age_batches(source_history_id)
        WHERE source_history_id IS NOT NULL
    ''')
    conn.commit()


def _inventory_age_received_at(value, fallback=None):
    text = str(value or '').strip()
    if text:
        try:
            parsed = datetime.datetime.fromisoformat(text.replace('Z', '+00:00'))
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone().replace(tzinfo=None)
            return parsed.isoformat()
        except Exception:
            pass
    fallback_text = str(fallback or '').strip()
    if fallback_text:
        try:
            parsed = datetime.datetime.fromisoformat(fallback_text.replace('Z', '+00:00'))
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone().replace(tzinfo=None)
            return parsed.isoformat()
        except Exception:
            pass
    return datetime.datetime.now().isoformat()


def _inventory_age_insert_batch(
    cur, searchrack_id, barcode, received_at, quantity, *,
    source='inventory', source_history_id=None, estimated=False,
    lot_number='', evidence_source='', confidence='low',
    confidence_score=0, evidence_json='{}', rebuild_run_id=None
):
    quantity = max(0, _coerce_int(quantity, 0))
    if quantity <= 0 or searchrack_id in (None, ''):
        return None
    cur.execute('''
        INSERT OR IGNORE INTO inventory_age_batches (
            searchrack_id, barcode, received_at, quantity,
            source, source_history_id, estimated, lot_number,
            evidence_source, confidence, confidence_score,
            evidence_json, rebuild_run_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ''', (
        int(searchrack_id),
        str(barcode or '').strip(),
        _inventory_age_received_at(received_at),
        quantity,
        str(source or 'inventory'),
        source_history_id,
        1 if estimated else 0,
        str(lot_number or '').strip(),
        str(evidence_source or '').strip(),
        str(confidence or 'low').strip().casefold(),
        max(0, min(100, _coerce_int(confidence_score, 0))),
        (
            json.dumps(evidence_json, sort_keys=True, separators=(',', ':'))
            if isinstance(evidence_json, (dict, list))
            else str(evidence_json or '{}')
        ),
        str(rebuild_run_id or '').strip() or None,
    ))
    return cur.lastrowid


def _inventory_age_consume_fifo(cur, searchrack_id, quantity):
    """Consume and return the oldest batches for one SEARCHRACK row."""
    remaining = max(0, _coerce_int(quantity, 0))
    consumed = []
    if remaining <= 0:
        return consumed
    cur.execute('''
        SELECT id, barcode, received_at, quantity, source, source_history_id,
               estimated, lot_number, evidence_source, confidence,
               confidence_score, evidence_json, rebuild_run_id
        FROM inventory_age_batches
        WHERE searchrack_id = ? AND quantity > 0
        ORDER BY received_at, id
    ''', (int(searchrack_id),))
    for row in cur.fetchall():
        if remaining <= 0:
            break
        (
            batch_id, barcode, received_at, batch_qty, source, history_id,
            estimated, lot_number, evidence_source, confidence,
            confidence_score, evidence_json, rebuild_run_id
        ) = row
        batch_qty = max(0, _coerce_int(batch_qty, 0))
        take = min(batch_qty, remaining)
        if take <= 0:
            continue
        consumed.append({
            'barcode': barcode,
            'received_at': received_at,
            'quantity': take,
            'source': source,
            'source_history_id': history_id,
            'estimated': bool(estimated),
            'lot_number': str(lot_number or ''),
            'evidence_source': str(evidence_source or ''),
            'confidence': str(confidence or 'low'),
            'confidence_score': max(0, _coerce_int(confidence_score, 0)),
            'evidence_json': str(evidence_json or '{}'),
            'rebuild_run_id': rebuild_run_id,
        })
        if take >= batch_qty:
            cur.execute('DELETE FROM inventory_age_batches WHERE id = ?', (batch_id,))
        else:
            cur.execute(
                'UPDATE inventory_age_batches SET quantity = quantity - ? WHERE id = ?',
                (take, batch_id)
            )
        remaining -= take
    return consumed


def _inventory_age_transfer_fifo(cur, source_row_id, destination_row_id, quantity, barcode=''):
    """Move the oldest units and retain their immutable received timestamps."""
    if int(source_row_id) == int(destination_row_id):
        return max(0, _coerce_int(quantity, 0))
    consumed = _inventory_age_consume_fifo(cur, source_row_id, quantity)
    moved = 0
    for batch in consumed:
        batch_qty = max(0, _coerce_int(batch.get('quantity'), 0))
        if batch_qty <= 0:
            continue
        _inventory_age_insert_batch(
            cur,
            destination_row_id,
            batch.get('barcode') or barcode,
            batch.get('received_at'),
            batch_qty,
            source='fifo_move',
            estimated=bool(batch.get('estimated')),
            lot_number=batch.get('lot_number'),
            evidence_source=batch.get('evidence_source'),
            confidence=batch.get('confidence'),
            confidence_score=batch.get('confidence_score'),
            evidence_json=batch.get('evidence_json'),
            rebuild_run_id=batch.get('rebuild_run_id'),
        )
        moved += batch_qty
    return moved


def _backfill_inventory_age_batches(conn):
    """Seed active inventory from add-to-shelf history, with explicit legacy estimates."""
    _ensure_inventory_age_schema(conn)
    cur = conn.cursor()
    cur.execute("SELECT value FROM inventory_age_meta WHERE key = 'backfill_v1'")
    if cur.fetchone():
        return {'backfilled': False, 'rows': 0, 'units': 0}

    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND LOWER(name)='searchrack'")
    if not cur.fetchone():
        cur.execute(
            "INSERT OR REPLACE INTO inventory_age_meta(key, value) VALUES ('backfill_v1', ?)",
            (datetime.datetime.now().isoformat(),)
        )
        conn.commit()
        return {'backfilled': True, 'rows': 0, 'units': 0}

    cur.execute("PRAGMA table_info('SEARCHRACK')")
    cols = {str(row[1]).lower(): row[1] for row in cur.fetchall()}
    id_col = cols.get('id')
    qty_col = cols.get('quantity') or cols.get('qty')
    barcode_col = cols.get('barcode') or cols.get('upc')
    created_col = cols.get('created_at')
    if not qty_col:
        return {'backfilled': False, 'rows': 0, 'units': 0}

    id_expr = _sqlite_ident(id_col) if id_col else 'rowid'
    barcode_expr = _sqlite_ident(barcode_col) if barcode_col else "''"
    created_expr = _sqlite_ident(created_col) if created_col else "''"
    cur.execute(f'''
        SELECT {id_expr} AS searchrack_id,
               {barcode_expr} AS barcode,
               COALESCE(CAST({_sqlite_ident(qty_col)} AS INTEGER), 0) AS quantity,
               {created_expr} AS created_at
        FROM SEARCHRACK
        WHERE COALESCE(CAST({_sqlite_ident(qty_col)} AS INTEGER), 0) > 0
    ''')
    active_rows = [dict(row) for row in cur.fetchall()]

    history_conn = None
    history_cur = None
    try:
        history_conn = sqlite3.connect(str(BASE_DIR / 'rackhistory.db'), timeout=30.0)
        history_conn.row_factory = sqlite3.Row
        history_cur = history_conn.cursor()
        _ensure_removed_items_table(history_cur)
        history_conn.commit()
    except Exception:
        if history_conn is not None:
            history_conn.close()
        history_conn = None
        history_cur = None

    inserted_rows = 0
    inserted_units = 0
    cur.execute('BEGIN IMMEDIATE')
    try:
        for active in active_rows:
            row_id = active['searchrack_id']
            target_qty = max(0, _coerce_int(active['quantity'], 0))
            barcode = str(active.get('barcode') or '').strip()
            event_qty = 0
            if history_cur is not None:
                history_cur.execute('''
                    SELECT id, removed_at, old_quantity, new_quantity
                    FROM removed_items
                    WHERE searchrack_id = ?
                      AND removal_type = 'add_to_shelf'
                      AND COALESCE(new_quantity, 0) > COALESCE(old_quantity, 0)
                      AND (undone_at IS NULL OR undone_at = '')
                      AND COALESCE(event_status, 'applied') != 'superseded'
                    ORDER BY removed_at, id
                ''', (row_id,))
                for event in history_cur.fetchall():
                    delta = max(
                        0,
                        _coerce_int(event['new_quantity'], 0)
                        - _coerce_int(event['old_quantity'], 0)
                    )
                    if delta <= 0:
                        continue
                    _inventory_age_insert_batch(
                        cur, row_id, barcode, event['removed_at'], delta,
                        source='rack_history',
                        source_history_id=event['id'],
                        estimated=False,
                    )
                    event_qty += delta
                    inserted_rows += 1
                    inserted_units += delta

            if event_qty > target_qty:
                _inventory_age_consume_fifo(cur, row_id, event_qty - target_qty)
            elif event_qty < target_qty:
                missing = target_qty - event_qty
                _inventory_age_insert_batch(
                    cur,
                    row_id,
                    barcode,
                    active.get('created_at'),
                    missing,
                    source='legacy_backfill',
                    estimated=True,
                )
                inserted_rows += 1
                inserted_units += missing

        cur.execute(
            "INSERT OR REPLACE INTO inventory_age_meta(key, value) VALUES ('backfill_v1', ?)",
            (datetime.datetime.now().isoformat(),)
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        if history_conn is not None:
            history_conn.close()
    return {'backfilled': True, 'rows': inserted_rows, 'units': inserted_units}


def _reconcile_inventory_age_batches(conn):
    """Keep the batch ledger aligned with active quantities after every mutation path."""
    backfill = _backfill_inventory_age_batches(conn)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("PRAGMA table_info('SEARCHRACK')")
    cols = {str(row[1]).lower(): row[1] for row in cur.fetchall()}
    id_col = cols.get('id')
    qty_col = cols.get('quantity') or cols.get('qty')
    barcode_col = cols.get('barcode') or cols.get('upc')
    created_col = cols.get('created_at')
    if not qty_col:
        return {**backfill, 'added_units': 0, 'consumed_units': 0}

    id_expr = _sqlite_ident(id_col) if id_col else 'rowid'
    barcode_expr = _sqlite_ident(barcode_col) if barcode_col else "''"
    created_expr = _sqlite_ident(created_col) if created_col else "''"
    cur.execute(f'''
        SELECT {id_expr} AS searchrack_id,
               {barcode_expr} AS barcode,
               COALESCE(CAST({_sqlite_ident(qty_col)} AS INTEGER), 0) AS quantity,
               {created_expr} AS created_at
        FROM SEARCHRACK
        WHERE COALESCE(CAST({_sqlite_ident(qty_col)} AS INTEGER), 0) > 0
    ''')
    active = [dict(row) for row in cur.fetchall()]
    active_ids = {int(row['searchrack_id']) for row in active}
    added_units = 0
    consumed_units = 0

    cur.execute('BEGIN IMMEDIATE')
    try:
        for row in active:
            row_id = int(row['searchrack_id'])
            target = max(0, _coerce_int(row['quantity'], 0))
            cur.execute(
                'SELECT COALESCE(SUM(quantity), 0) FROM inventory_age_batches WHERE searchrack_id = ?',
                (row_id,)
            )
            ledger_qty = max(0, _coerce_int(cur.fetchone()[0], 0))
            if ledger_qty < target:
                delta = target - ledger_qty
                _inventory_age_insert_batch(
                    cur,
                    row_id,
                    row.get('barcode'),
                    row.get('created_at'),
                    delta,
                    source='quantity_reconcile',
                    estimated=False,
                )
                added_units += delta
            elif ledger_qty > target:
                delta = ledger_qty - target
                _inventory_age_consume_fifo(cur, row_id, delta)
                consumed_units += delta

        if active_ids:
            placeholders = ','.join('?' for _ in active_ids)
            cur.execute(
                f'DELETE FROM inventory_age_batches WHERE searchrack_id NOT IN ({placeholders})',
                tuple(sorted(active_ids))
            )
        else:
            cur.execute('DELETE FROM inventory_age_batches')
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {**backfill, 'added_units': added_units, 'consumed_units': consumed_units}


_inventory_age_rescan_lock = threading.Lock()


def _inventory_age_exact_key(value):
    return str(
        _normalize_upc_preserve_suffix_for_match(value) or ''
    ).strip().casefold()


def _inventory_age_base_key(value):
    return _inventory_age_exact_key(value).split('-', 1)[0]


def _inventory_age_lot_key(value):
    lot = str(value or '').strip()
    if (
        not lot
        or lot.casefold() in {'nan', 'none', 'null', 'n/a', 'unknown'}
        or lot.casefold().startswith('uncategorized')
    ):
        return ''
    return lot.casefold()


def _inventory_age_confidence_label(score):
    score = max(0, min(100, _coerce_int(score, 0)))
    if score >= 90:
        return 'high'
    if score >= 70:
        return 'medium'
    return 'low'


def _inventory_age_evidence_paths(evidence_paths=None):
    provided = dict(evidence_paths or {})

    def selected(short_name, filename):
        value = provided.get(short_name) or provided.get(filename)
        return Path(value) if value else (BASE_DIR / filename)

    return {
        'rawbol': selected('rawbol', 'rawbol.db'),
        'bol': selected('bol', 'bol.db'),
        'preplog': selected('preplog', 'preplog.db'),
    }


def _inventory_age_load_receipt_evidence(evidence_paths=None):
    """Load immutable receipt dates plus Item Manager/prep lot evidence."""
    from collections import defaultdict

    paths = _inventory_age_evidence_paths(evidence_paths)
    raw_groups = {}
    upload_dates_by_lot = defaultdict(list)
    bol_pairs = set()
    bol_suffix_lots = defaultdict(set)
    prep_by_exact = defaultdict(list)
    status_by_exact_lot = {}
    warnings = []
    fatal_errors = []
    fingerprint_rows = []

    raw_path = paths['rawbol']
    if raw_path.exists():
        raw_conn = sqlite3.connect(str(raw_path), timeout=30.0)
        raw_conn.row_factory = sqlite3.Row
        try:
            raw_cur = raw_conn.cursor()
            try:
                raw_cur.execute('''
                    SELECT id, filename, lot_number, import_date, uploaded_at
                    FROM upload_logs
                    ORDER BY id
                ''')
                for row in raw_cur.fetchall():
                    lot_key = _inventory_age_lot_key(row['lot_number'])
                    import_at = _history_timestamp(row['import_date'])
                    if lot_key and import_at is not None:
                        upload_dates_by_lot[lot_key].append(import_at)
                    fingerprint_rows.append((
                        'upload', row['id'], row['filename'], row['lot_number'],
                        row['import_date'], row['uploaded_at']
                    ))
            except sqlite3.Error as exc:
                fatal_errors.append(f'Raw BOL upload log unavailable: {exc}')

            raw_cur.execute('''
                SELECT id, upc, quantity, lot_number, import_date, created_at
                FROM raw_bol_items
                ORDER BY id
            ''')
            for row in raw_cur.fetchall():
                base_key = _inventory_age_base_key(row['upc'])
                lot_key = _inventory_age_lot_key(row['lot_number'])
                if not base_key or not lot_key:
                    continue
                group = raw_groups.setdefault((base_key, lot_key), {
                    'base_key': base_key,
                    'lot_key': lot_key,
                    'lot_number': str(row['lot_number'] or '').strip(),
                    'quantity': 0,
                    'raw_ids': [],
                    'import_dates': [],
                    'created_dates': [],
                })
                group['quantity'] += max(0, _coerce_int(row['quantity'], 0))
                group['raw_ids'].append(max(0, _coerce_int(row['id'], 0)))
                parsed_import = _history_timestamp(row['import_date'])
                if parsed_import is not None:
                    group['import_dates'].append(parsed_import)
                parsed_created = _history_timestamp(row['created_at'])
                if parsed_created is not None:
                    group['created_dates'].append(parsed_created)
                fingerprint_rows.append((
                    'raw', row['id'], row['upc'], row['quantity'],
                    row['lot_number'], row['import_date'], row['created_at']
                ))
        finally:
            raw_conn.close()
    else:
        fatal_errors.append(
            f'Raw BOL database not found: {raw_path.name}'
        )

    bol_path = paths['bol']
    if bol_path.exists():
        bol_conn = sqlite3.connect(str(bol_path), timeout=30.0)
        bol_conn.row_factory = sqlite3.Row
        try:
            bol_cur = bol_conn.cursor()
            try:
                bol_cur.execute('''
                    SELECT id, upc, lot_number
                    FROM bol_items
                    ORDER BY id
                ''')
                for row in bol_cur.fetchall():
                    exact_key = _inventory_age_exact_key(row['upc'])
                    base_key = _inventory_age_base_key(row['upc'])
                    lot_key = _inventory_age_lot_key(row['lot_number'])
                    if base_key and lot_key:
                        bol_pairs.add((base_key, lot_key))
                        if exact_key and '-' in exact_key:
                            bol_suffix_lots[exact_key].add(lot_key)
                    fingerprint_rows.append((
                        'bol', row['id'], row['upc'], row['lot_number']
                    ))
            except sqlite3.Error as exc:
                fatal_errors.append(f'BOL item evidence unavailable: {exc}')

            try:
                bol_cur.execute('''
                    SELECT id, upc, lot_number, status, quantity, updated_at
                    FROM items_prep_status
                    WHERE LOWER(TRIM(COALESCE(status, ''))) = 'good'
                      AND COALESCE(CAST(quantity AS INTEGER), 0) > 0
                    ORDER BY id
                ''')
                for row in bol_cur.fetchall():
                    exact_key = _inventory_age_exact_key(row['upc'])
                    lot_key = _inventory_age_lot_key(row['lot_number'])
                    if exact_key and lot_key:
                        key = (exact_key, lot_key)
                        status = status_by_exact_lot.setdefault(key, {
                            'exact_key': exact_key,
                            'lot_key': lot_key,
                            'quantity': 0,
                            'ids': [],
                            'updated_at': [],
                        })
                        status['quantity'] += max(
                            0, _coerce_int(row['quantity'], 0)
                        )
                        status['ids'].append(max(0, _coerce_int(row['id'], 0)))
                        parsed_updated = _history_timestamp(row['updated_at'])
                        if parsed_updated is not None:
                            status['updated_at'].append(parsed_updated)
                    fingerprint_rows.append((
                        'status', row['id'], row['upc'], row['lot_number'],
                        row['status'], row['quantity'], row['updated_at']
                    ))
            except sqlite3.Error as exc:
                fatal_errors.append(
                    f'Item Manager prep status unavailable: {exc}'
                )
        finally:
            bol_conn.close()
    else:
        fatal_errors.append(
            f'BOL/Item Manager database not found: {bol_path.name}'
        )

    preplog_path = paths['preplog']
    if preplog_path.exists():
        prep_conn = sqlite3.connect(str(preplog_path), timeout=30.0)
        prep_conn.row_factory = sqlite3.Row
        try:
            prep_cur = prep_conn.cursor()
            try:
                prep_cur.execute('''
                    SELECT id, created_at, upc, base_upc, status, quantity,
                           meta_json, undone
                    FROM prep_log
                    WHERE COALESCE(undone, 0) = 0
                      AND LOWER(TRIM(COALESCE(status, ''))) = 'good'
                      AND COALESCE(CAST(quantity AS INTEGER), 0) > 0
                    ORDER BY created_at, id
                ''')
                for row in prep_cur.fetchall():
                    try:
                        meta = json.loads(row['meta_json'] or '{}')
                    except Exception:
                        meta = {}
                    if not isinstance(meta, dict):
                        meta = {}
                    lot_number = (
                        meta.get('lot_number')
                        or meta.get('assigned_lot')
                        or meta.get('lot')
                    )
                    exact_key = _inventory_age_exact_key(row['upc'])
                    lot_key = _inventory_age_lot_key(lot_number)
                    created_at = _history_timestamp(row['created_at'])
                    if exact_key and lot_key and created_at is not None:
                        prep_by_exact[exact_key].append({
                            'id': max(0, _coerce_int(row['id'], 0)),
                            'exact_key': exact_key,
                            'lot_key': lot_key,
                            'created_at': created_at,
                            'quantity': max(
                                0, _coerce_int(row['quantity'], 0)
                            ),
                            'auto_assigned': bool(meta.get('auto_assigned')),
                            'forced_lot_override': bool(
                                meta.get('forced_lot_override')
                            ),
                            'exception_overage': bool(
                                meta.get('exception_overage')
                            ),
                            'needs_review': bool(meta.get('needs_review')),
                            'continued_without_lot': bool(
                                meta.get('continued_without_lot')
                            ),
                        })
                    fingerprint_rows.append((
                        'prep', row['id'], row['created_at'], row['upc'],
                        row['base_upc'], row['status'], row['quantity'],
                        row['meta_json'], row['undone']
                    ))
            except sqlite3.Error as exc:
                fatal_errors.append(f'Prep-log evidence unavailable: {exc}')
        finally:
            prep_conn.close()
    else:
        fatal_errors.append(
            f'Prep-log database not found: {preplog_path.name}'
        )

    catalog = defaultdict(dict)
    for (base_key, lot_key), group in raw_groups.items():
        import_dates = sorted(group['import_dates'])
        upload_dates = sorted(upload_dates_by_lot.get(lot_key, []))
        if import_dates:
            received_at = import_dates[0]
            date_source = 'raw_bol_import_date'
        elif upload_dates:
            received_at = upload_dates[0]
            date_source = 'upload_log_import_date'
        else:
            # A Raw-BOL ingestion timestamp is not a purchase date, so it is
            # intentionally excluded from the validated receipt catalog.
            continue
        upload_confirmed = any(
            value.date() == received_at.date()
            for value in upload_dates
        )
        catalog[base_key][lot_key] = {
            **group,
            'received_at': received_at,
            'date_source': date_source,
            'upload_confirmed': upload_confirmed,
            'bol_confirmed': (base_key, lot_key) in bol_pairs,
        }

    for exact_key in prep_by_exact:
        prep_by_exact[exact_key].sort(key=lambda item: (
            item['created_at'], item['id']
        ))

    fingerprint_payload = json.dumps(
        sorted(fingerprint_rows, key=lambda value: tuple(str(v) for v in value)),
        ensure_ascii=False,
        default=str,
        separators=(',', ':'),
    )
    fingerprint = hashlib.sha256(
        fingerprint_payload.encode('utf-8')
    ).hexdigest()
    return {
        'paths': paths,
        'catalog': {key: dict(value) for key, value in catalog.items()},
        'prep_by_exact': dict(prep_by_exact),
        'status_by_exact_lot': status_by_exact_lot,
        'bol_suffix_lots': {
            key: set(value) for key, value in bol_suffix_lots.items()
        },
        'warnings': warnings,
        'fatal_errors': fatal_errors,
        'complete': not fatal_errors,
        'fingerprint': fingerprint,
        'raw_pairs': sum(len(value) for value in catalog.values()),
    }


def _inventory_age_load_history(
    active_barcode_keys, history_path=None, active_base_keys=None
):
    """Read relevant rack events and suppress paired location-only snapshots."""
    from collections import defaultdict

    def normalized_location(value):
        text = str(value or '').strip().casefold()
        if not text or text == 'picture':
            return ''
        return re.sub(r'[^a-z0-9]', '', text)

    def snapshot_location(raw_snapshot):
        try:
            snapshot = json.loads(raw_snapshot or '{}')
        except Exception:
            snapshot = {}
        if not isinstance(snapshot, dict):
            return ''
        folded = {
            str(key).casefold(): value
            for key, value in snapshot.items()
        }
        item_location = normalized_location(
            folded.get('item_position')
        )
        if item_location:
            return item_location
        return normalized_location(folded.get('pictureposition'))

    def event_location(event, direction):
        if direction == 'source':
            candidates = (
                event.get('from_position'),
                snapshot_location(event.get('source_row_json')),
                event.get('item_position'),
            )
        else:
            candidates = (
                event.get('to_position'),
                snapshot_location(event.get('result_row_json')),
                event.get('item_position'),
            )
        for candidate in candidates:
            normalized = normalized_location(candidate)
            if normalized:
                return normalized
        return ''

    resolved_path = Path(history_path or (BASE_DIR / 'rackhistory.db'))
    if not resolved_path.exists():
        return {
            'events': [],
            'fingerprint': hashlib.sha256(b'').hexdigest(),
            'movement_events_suppressed': 0,
            'path': resolved_path,
            'available': False,
            'error': f'Rack-history database not found: {resolved_path.name}',
        }

    history_conn = sqlite3.connect(str(resolved_path), timeout=30.0)
    history_conn.row_factory = sqlite3.Row
    active_base_keys = set(active_base_keys or ())
    fingerprint_rows = []
    events = []
    try:
        history_cur = history_conn.cursor()
        history_cur.execute(
            "SELECT 1 FROM sqlite_master "
            "WHERE type='table' AND name='removed_items'"
        )
        if not history_cur.fetchone():
            return {
                'events': [],
                'fingerprint': hashlib.sha256(b'').hexdigest(),
                'movement_events_suppressed': 0,
                'path': resolved_path,
                'available': False,
                'error': 'Rack-history event table is missing',
            }
        history_cur.execute('''
            SELECT id, barcode, removed_at, searchrack_id,
                   old_quantity, new_quantity, removal_type,
                   source_row_json, result_row_json, event_id,
                   event_status, undone_at, item_position,
                   from_position, to_position
            FROM removed_items
            WHERE COALESCE(event_status, 'applied') != 'superseded'
              AND (undone_at IS NULL OR undone_at = '')
            ORDER BY removed_at, id
        ''')
        for raw_event in history_cur.fetchall():
            event = dict(raw_event)
            barcode_key = _inventory_age_exact_key(event.get('barcode'))
            base_key = _inventory_age_base_key(barcode_key)
            occurred_at = _history_timestamp(event.get('removed_at'))
            row_id = event.get('searchrack_id')
            if (
                not barcode_key
                or (
                    barcode_key not in active_barcode_keys
                    and base_key not in active_base_keys
                )
                or occurred_at is None
                or row_id in (None, '')
            ):
                continue
            event['_barcode_key'] = barcode_key
            event['_base_key'] = base_key
            event['_occurred_at'] = occurred_at
            event['_row_id'] = int(row_id)
            event['_source_location'] = event_location(event, 'source')
            event['_destination_location'] = event_location(
                event, 'destination'
            )
            events.append(event)
            fingerprint_rows.append((
                event.get('id'), event.get('barcode'), event.get('removed_at'),
                event.get('searchrack_id'), event.get('old_quantity'),
                event.get('new_quantity'), event.get('removal_type'),
                event.get('source_row_json'), event.get('result_row_json'),
                event.get('event_id'), event.get('event_status'),
                event.get('undone_at'), event.get('item_position'),
                event.get('from_position'), event.get('to_position')
            ))
    finally:
        history_conn.close()

    movement_groups = defaultdict(list)
    for event in events:
        removal_type = str(
            event.get('removal_type') or ''
        ).strip().casefold()
        if removal_type not in {'locationmoved', 'locationcleared'}:
            continue
        group_key = (
            event['_row_id'],
            event['_barcode_key'],
            event['_occurred_at'].isoformat(),
            removal_type,
        )
        movement_groups[group_key].append(event)

    suppressed_ids = set()
    for grouped in movement_groups.values():
        deltas = [
            _coerce_int(event.get('new_quantity'), 0)
            - _coerce_int(event.get('old_quantity'), 0)
            for event in grouped
        ]
        if (
            sum(deltas) == 0
            and any(value > 0 for value in deltas)
            and any(value < 0 for value in deltas)
        ):
            suppressed_ids.update(
                max(0, _coerce_int(event.get('id'), 0))
                for event in grouped
            )
    if suppressed_ids:
        events = [
            event for event in events
            if max(0, _coerce_int(event.get('id'), 0)) not in suppressed_ids
        ]

    events.sort(key=lambda event: (
        event['_occurred_at'],
        max(0, _coerce_int(event.get('id'), 0)),
    ))
    fingerprint_payload = json.dumps(
        fingerprint_rows,
        ensure_ascii=False,
        default=str,
        separators=(',', ':'),
    )
    return {
        'events': events,
        'fingerprint': hashlib.sha256(
            fingerprint_payload.encode('utf-8')
        ).hexdigest(),
        'movement_events_suppressed': len(suppressed_ids),
        'path': resolved_path,
        'available': True,
        'error': '',
    }


def _inventory_age_replay_history(
    history_events, evidence, match_window_days=2
):
    """Rebuild per-unit warehouse lineages and preserve delete/rescan moves."""
    row_units = {}
    parked_by_barcode = {}
    restoring_rows = {}
    stats = {
        'history_events_used': 0,
        'matched_reorg_units': 0,
        'matched_short_gap_reorg_units': 0,
        'matched_historical_exception_units': 0,
        'inferred_history_units': 0,
        'reorg_units_blocked_by_new_receipt': 0,
        'reorg_units_blocked_by_confirmed_receipt': 0,
        'reorg_units_blocked_by_possible_receipt': 0,
        'pending_unmatched_clear_units': 0,
    }
    reusable_removal_types = {
        'inventoryremoved',
        'manual_multidb_delete',
    }
    restore_addition_types = {
        'add_to_shelf',
        'inventory_added',
    }
    match_window = datetime.timedelta(
        days=max(1, int(match_window_days or 2))
    )
    # Audited legacy exception: OR3 was bulk-cleared May 5–6, 2026 and
    # deliberately left empty until its July reinventory. Keep this bounded
    # to the observed operation; future rack clears use the normal 2-day
    # workflow window.
    historical_exception_window = datetime.timedelta(days=180)
    historical_or3_removed_start = datetime.datetime(2026, 5, 5)
    historical_or3_removed_end = datetime.datetime(2026, 5, 7)
    historical_or3_added_start = datetime.datetime(2026, 7, 15)
    historical_or3_added_end = datetime.datetime(2026, 8, 1)
    new_receipt_token_remaining = {
        (exact_key, token['id']): max(
            0, _coerce_int(token.get('quantity'), 0)
        )
        for exact_key, tokens in evidence.get('prep_by_exact', {}).items()
        for token in tokens
    }
    receipt_capacity_remaining = {
        (base_key, lot_key): max(
            0, _coerce_int(lot_info.get('quantity'), 0)
        )
        for base_key, lots in evidence.get('catalog', {}).items()
        for lot_key, lot_info in lots.items()
    }

    def snapshot_created_at(event):
        for raw_snapshot in (
            event.get('source_row_json'),
            event.get('result_row_json'),
        ):
            try:
                snapshot = json.loads(raw_snapshot or '{}')
            except Exception:
                snapshot = {}
            if not isinstance(snapshot, dict):
                continue
            folded = {
                str(key).casefold(): value
                for key, value in snapshot.items()
            }
            parsed = _history_timestamp(folded.get('created_at'))
            if parsed is not None:
                return parsed
        return event['_occurred_at']

    def normalized_location(value):
        text = str(value or '').strip().casefold()
        if not text or text == 'picture':
            return ''
        return re.sub(r'[^a-z0-9]', '', text)

    def snapshot_location(raw_snapshot):
        try:
            snapshot = json.loads(raw_snapshot or '{}')
        except Exception:
            snapshot = {}
        if not isinstance(snapshot, dict):
            return ''
        folded = {
            str(key).casefold(): value
            for key, value in snapshot.items()
        }
        item_location = normalized_location(
            folded.get('item_position')
        )
        if item_location:
            return item_location
        return normalized_location(folded.get('pictureposition'))

    def event_location(event, direction):
        derived_key = (
            '_source_location'
            if direction == 'source'
            else '_destination_location'
        )
        derived_location = normalized_location(event.get(derived_key))
        if derived_location:
            return derived_location
        if direction == 'source':
            candidates = (
                event.get('from_position'),
                snapshot_location(event.get('source_row_json')),
                event.get('item_position'),
            )
        else:
            candidates = (
                event.get('to_position'),
                snapshot_location(event.get('result_row_json')),
                event.get('item_position'),
            )
        for candidate in candidates:
            location = normalized_location(candidate)
            if location:
                return location
        return ''

    def historical_location_scope(location):
        normalized = normalized_location(location)
        if re.match(r'^or3(?:s|$)', normalized):
            return 'or3'
        if re.match(r'^or2s5(?:b\d+)?$', normalized):
            return 'or2s5'
        if re.match(r'^or2s6(?:b\d+)?$', normalized):
            return 'or2s6'
        return ''

    def reorg_match_type(event, parked):
        gap = event['_occurred_at'] - parked['parked_at']
        if not datetime.timedelta(0) <= gap:
            return ''
        if gap <= match_window:
            return 'short_gap'
        source_scope = historical_location_scope(
            parked.get('source_location')
        )
        if (
            source_scope == 'or3'
            and historical_or3_removed_start
            <= parked['parked_at']
            < historical_or3_removed_end
            and historical_or3_added_start
            <= event['_occurred_at']
            < historical_or3_added_end
            and gap <= historical_exception_window
        ):
            return 'known_historical_office_reinventory'
        return ''

    def receipt_conflict_between(event, parked):
        exact_key = event['_barcode_key']
        base_key = event['_base_key']
        catalog = evidence.get('catalog', {}).get(base_key, {})
        if not catalog:
            return ''
        parked_at = parked['parked_at']
        add_at = event['_occurred_at']
        parked_day = parked_at.date()
        add_day = add_at.date()
        for token in evidence.get('prep_by_exact', {}).get(
            exact_key, []
        ):
            token_key = (exact_key, token['id'])
            if new_receipt_token_remaining.get(token_key, 0) <= 0:
                continue
            lot_info = catalog.get(token['lot_key'])
            if not lot_info:
                continue
            capacity_key = (base_key, token['lot_key'])
            if receipt_capacity_remaining.get(capacity_key, 0) <= 0:
                continue
            received_at = lot_info['received_at']
            token_at = token['created_at']
            if (
                parked_day <= received_at.date() <= add_day
                and parked_at <= token_at
                <= add_at + datetime.timedelta(days=2)
            ):
                new_receipt_token_remaining[token_key] -= 1
                receipt_capacity_remaining[capacity_key] -= 1
                return 'confirmed'
        possible_lots = sorted(
            (
                lot_key,
                lot_info,
            )
            for lot_key, lot_info in catalog.items()
            if (
                lot_info.get('received_at') is not None
                and parked_day
                <= lot_info['received_at'].date()
                <= add_day
                and receipt_capacity_remaining.get(
                    (base_key, lot_key), 0
                ) > 0
            )
        )
        if possible_lots:
            possible_lot_key = possible_lots[0][0]
            receipt_capacity_remaining[
                (base_key, possible_lot_key)
            ] -= 1
            return 'possible'
        return ''

    def row_key(event):
        return (event['_row_id'], event['_barcode_key'])

    def unit_sort_key(unit):
        return (
            unit['received_at'],
            tuple(unit.get('history_ids') or []),
        )

    def sync_row_quantity(event, target_quantity):
        units = row_units.setdefault(row_key(event), [])
        target_quantity = max(0, _coerce_int(target_quantity, 0))
        if len(units) < target_quantity:
            missing = target_quantity - len(units)
            inferred_at = snapshot_created_at(event)
            for _ in range(missing):
                units.append({
                    'received_at': inferred_at,
                    'first_seen': inferred_at,
                    'lineage_source': 'rack_snapshot',
                    'lineage_confidence': 55,
                    'history_ids': [
                        max(0, _coerce_int(event.get('id'), 0))
                    ],
                })
            stats['inferred_history_units'] += missing
        elif len(units) > target_quantity:
            # Unrecorded decrements are treated as FIFO consumption.
            del units[:len(units) - target_quantity]
        units.sort(key=unit_sort_key)
        return units

    for event in history_events:
        old_quantity = max(0, _coerce_int(event.get('old_quantity'), 0))
        new_quantity = max(0, _coerce_int(event.get('new_quantity'), 0))
        if old_quantity == new_quantity:
            continue
        stats['history_events_used'] += 1
        units = sync_row_quantity(event, old_quantity)
        removal_type = str(
            event.get('removal_type') or ''
        ).strip().casefold()

        if new_quantity > old_quantity:
            add_quantity = new_quantity - old_quantity
            restored_units = []
            restore_key = row_key(event)
            last_restore_at = restoring_rows.get(restore_key)
            continuing_restore = (
                last_restore_at is not None
                and datetime.timedelta(0)
                <= event['_occurred_at'] - last_restore_at
                <= datetime.timedelta(days=1)
            )
            if (
                removal_type in restore_addition_types
                and (old_quantity == 0 or continuing_restore)
            ):
                parked = parked_by_barcode.setdefault(
                    event['_barcode_key'], []
                )
                eligible = []
                for item in parked:
                    if item['source_row_id'] == event['_row_id']:
                        continue
                    match_type = reorg_match_type(event, item)
                    if match_type:
                        eligible.append((item, match_type))
                eligible.sort(key=lambda match: (
                    0 if match[1] == 'short_gap' else 1,
                    -match[0]['parked_at'].timestamp(),
                    match[0]['unit']['received_at'],
                ))
                classified_fresh = 0
                for item, match_type in eligible:
                    if (
                        len(restored_units) + classified_fresh
                        >= add_quantity
                    ):
                        break
                    receipt_conflict = receipt_conflict_between(
                        event, item
                    )
                    if receipt_conflict:
                        stats['reorg_units_blocked_by_new_receipt'] += 1
                        stats[
                            'reorg_units_blocked_by_'
                            + receipt_conflict
                            + '_receipt'
                        ] += 1
                        classified_fresh += 1
                        continue
                    restored_unit = item['unit']
                    addition_history_id = max(
                        0, _coerce_int(event.get('id'), 0)
                    )
                    restored_unit['history_ids'] = sorted(set(
                        list(restored_unit.get('history_ids') or [])
                        + [item['history_id'], addition_history_id]
                    ))
                    restored_unit['reorg_match_type'] = match_type
                    continuity_score = (
                        96 if match_type == 'short_gap' else 82
                    )
                    restored_unit['lineage_confidence'] = min(
                        max(
                            0,
                            _coerce_int(
                                restored_unit.get(
                                    'lineage_confidence'
                                ),
                                55,
                            ),
                        ),
                        continuity_score,
                    )
                    restored_unit.setdefault(
                        'reorg_matches', []
                    ).append({
                        'match_type': match_type,
                        'from_location': item.get(
                            'source_location'
                        ) or '',
                        'to_location': event_location(
                            event, 'destination'
                        ),
                        'gap_hours': round(
                            (
                                event['_occurred_at']
                                - item['parked_at']
                            ).total_seconds() / 3600,
                            2,
                        ),
                        'continuity_score': continuity_score,
                        'removal_history_id': item['history_id'],
                        'addition_history_id': addition_history_id,
                    })
                    if match_type == 'known_historical_office_reinventory':
                        restored_unit['lineage_confidence'] = min(
                            55,
                            max(
                                0,
                                _coerce_int(
                                    restored_unit.get(
                                        'lineage_confidence'
                                    ),
                                    55,
                                ),
                            ),
                        )
                        stats[
                            'matched_historical_exception_units'
                        ] += 1
                    else:
                        stats['matched_short_gap_reorg_units'] += 1
                    restored_units.append(restored_unit)
                    parked.remove(item)
                stats['matched_reorg_units'] += len(restored_units)
                if restored_units or classified_fresh:
                    restoring_rows[restore_key] = event['_occurred_at']

            units.extend(restored_units)
            for _ in range(add_quantity - len(restored_units)):
                units.append({
                    'received_at': event['_occurred_at'],
                    'first_seen': event['_occurred_at'],
                    'lineage_source': 'rack_add_event',
                    'lineage_confidence': 65,
                    'history_ids': [
                        max(0, _coerce_int(event.get('id'), 0))
                    ],
                })
            units.sort(key=unit_sort_key)
        else:
            restoring_rows.pop(row_key(event), None)
            remove_quantity = old_quantity - new_quantity
            consumed = units[:remove_quantity]
            del units[:remove_quantity]
            if removal_type in reusable_removal_types and new_quantity == 0:
                parked = parked_by_barcode.setdefault(
                    event['_barcode_key'], []
                )
                for unit in consumed:
                    parked.append({
                        'unit': unit,
                        'parked_at': event['_occurred_at'],
                        'history_id': max(
                            0, _coerce_int(event.get('id'), 0)
                        ),
                        'source_row_id': event['_row_id'],
                        'source_location': event_location(
                            event, 'source'
                        ),
                    })

    stats['pending_unmatched_clear_units'] = sum(
        len(items) for items in parked_by_barcode.values()
    )
    return row_units, stats


def _inventory_age_depleted_raw_capacity(history_events, evidence):
    """Subtract known permanent warehouse exits from Raw-BOL supply FIFO."""
    remaining = {}
    depleted_by_pair = {}
    for base_key, lots in evidence['catalog'].items():
        for lot_key, lot_info in lots.items():
            pair = (base_key, lot_key)
            remaining[pair] = max(
                0, _coerce_int(lot_info.get('quantity'), 0)
            )
            depleted_by_pair[pair] = 0

    permanent_removal_types = {
        'manual_handled',
        'manual_sold_removal',
        'repair_removal',
        'automatic',
        'automatic_allocated',
        'finder_removal',
        'prep_history_delete',
    }
    stats = {
        'known_permanent_removal_units': 0,
        'raw_capacity_depleted_units': 0,
        'unmatched_permanent_removal_units': 0,
        'bases_with_raw_capacity_depletion': set(),
    }
    for event in history_events:
        removal_type = str(
            event.get('removal_type') or ''
        ).strip().casefold()
        if removal_type not in permanent_removal_types:
            continue
        remove_quantity = max(
            0,
            _coerce_int(event.get('old_quantity'), 0)
            - _coerce_int(event.get('new_quantity'), 0),
        )
        if remove_quantity <= 0:
            continue
        stats['known_permanent_removal_units'] += remove_quantity
        base_key = event.get('_base_key') or _inventory_age_base_key(
            event.get('barcode')
        )
        lots = evidence['catalog'].get(base_key, {})
        eligible = sorted(
            (
                (lot_info['received_at'], lot_key)
                for lot_key, lot_info in lots.items()
                if (
                    lot_info.get('received_at') is not None
                    and lot_info['received_at']
                    <= event['_occurred_at'] + datetime.timedelta(days=1)
                )
            ),
            key=lambda value: (value[0], value[1]),
        )
        remaining_to_deplete = remove_quantity
        for _received_at, lot_key in eligible:
            pair = (base_key, lot_key)
            available = max(0, remaining.get(pair, 0))
            take = min(available, remaining_to_deplete)
            if take <= 0:
                continue
            remaining[pair] = available - take
            depleted_by_pair[pair] = (
                depleted_by_pair.get(pair, 0) + take
            )
            stats['raw_capacity_depleted_units'] += take
            stats['bases_with_raw_capacity_depletion'].add(base_key)
            remaining_to_deplete -= take
            if remaining_to_deplete <= 0:
                break
        stats['unmatched_permanent_removal_units'] += remaining_to_deplete

    stats['bases_with_raw_capacity_depletion'] = len(
        stats['bases_with_raw_capacity_depletion']
    )
    return remaining, depleted_by_pair, stats


def _inventory_age_read_ledger_rows(cur):
    cur.execute('''
        SELECT id, searchrack_id, barcode, received_at, quantity, source,
               source_history_id, estimated, lot_number, evidence_source,
               confidence, confidence_score, evidence_json, rebuild_run_id,
               created_at
        FROM inventory_age_batches
        WHERE quantity > 0
        ORDER BY id
    ''')
    return [dict(row) for row in cur.fetchall()]


def _inventory_age_ledger_signature(rows):
    return [(
        int(row['id']),
        int(row['searchrack_id']),
        str(row.get('barcode') or ''),
        str(row.get('received_at') or ''),
        max(0, _coerce_int(row.get('quantity'), 0)),
        str(row.get('source') or ''),
        row.get('source_history_id'),
        max(0, _coerce_int(row.get('estimated'), 0)),
        str(row.get('lot_number') or ''),
        str(row.get('evidence_source') or ''),
        str(row.get('confidence') or ''),
        max(0, _coerce_int(row.get('confidence_score'), 0)),
        str(row.get('evidence_json') or ''),
        str(row.get('rebuild_run_id') or ''),
        str(row.get('created_at') or ''),
    ) for row in rows]


def _inventory_age_unit_signature(unit):
    evidence_json = unit.get('evidence_json') or '{}'
    if isinstance(evidence_json, (dict, list)):
        evidence_json = json.dumps(
            evidence_json, sort_keys=True, separators=(',', ':')
        )
    return (
        _inventory_age_received_at(unit.get('received_at')),
        str(unit.get('source') or ''),
        str(unit.get('lot_number') or ''),
        str(unit.get('evidence_source') or ''),
        str(unit.get('confidence') or 'low'),
        max(0, _coerce_int(unit.get('confidence_score'), 0)),
        1 if unit.get('estimated') else 0,
        str(evidence_json or '{}'),
        unit.get('source_history_id'),
    )


def _inventory_age_group_plan(units, row_id, barcode):
    grouped = {}
    for unit in units:
        key = _inventory_age_unit_signature(unit)
        grouped[key] = grouped.get(key, 0) + 1
    result = []
    for key, quantity in sorted(grouped.items(), key=lambda item: item[0]):
        (
            received_at, source, lot_number, evidence_source, confidence,
            confidence_score, estimated, evidence_json, source_history_id
        ) = key
        result.append({
            'searchrack_id': int(row_id),
            'barcode': str(barcode or '').strip(),
            'received_at': received_at,
            'quantity': quantity,
            'source': source,
            'source_history_id': source_history_id,
            'estimated': bool(estimated),
            'lot_number': lot_number,
            'evidence_source': evidence_source,
            'confidence': confidence,
            'confidence_score': confidence_score,
            'evidence_json': evidence_json,
        })
    return result


def _rescan_inventory_age_from_history(
    conn, history_path=None, match_window_days=2, evidence_paths=None
):
    """Comprehensively rebuild current ages without mutating warehouse stock."""
    from collections import Counter, defaultdict

    started_at = datetime.datetime.now().isoformat()
    run_id = uuid.uuid4().hex
    _ensure_inventory_age_schema(conn)
    reconcile = {
        'backfilled': False,
        'added_units': 0,
        'consumed_units': 0,
        'canonical_rebuild': True,
    }
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute('''
        SELECT ID AS searchrack_id, BARCODE AS barcode,
               COALESCE(CAST(QUANTITY AS INTEGER), 0) AS quantity,
               CREATED_AT AS created_at
        FROM SEARCHRACK
        WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
        ORDER BY ID
    ''')
    active_rows = [dict(row) for row in cur.fetchall()]
    active_keys = {
        _inventory_age_exact_key(row.get('barcode'))
        for row in active_rows
        if _inventory_age_exact_key(row.get('barcode'))
    }
    active_base_keys = {
        _inventory_age_base_key(row.get('barcode'))
        for row in active_rows
        if _inventory_age_base_key(row.get('barcode'))
    }
    expected_inventory = [(
        int(row['searchrack_id']),
        str(row.get('barcode') or '').strip(),
        max(0, _coerce_int(row.get('quantity'), 0)),
    ) for row in active_rows]
    active_row_ids = {
        row_id for row_id, _barcode, _quantity in expected_inventory
    }

    existing_ledger_rows = _inventory_age_read_ledger_rows(cur)
    existing_ledger_signature = _inventory_age_ledger_signature(
        existing_ledger_rows
    )
    stale_ledger_row_ids = sorted({
        int(row['searchrack_id'])
        for row in existing_ledger_rows
        if int(row['searchrack_id']) not in active_row_ids
    })

    evidence = _inventory_age_load_receipt_evidence(evidence_paths)
    if not evidence.get('complete'):
        raise RuntimeError(
            'Comprehensive age evidence is unavailable: '
            + '; '.join(evidence.get('fatal_errors') or ['unknown source error'])
        )
    history = _inventory_age_load_history(
        active_keys, history_path, active_base_keys
    )
    if not history.get('available'):
        raise RuntimeError(
            'Comprehensive age evidence is unavailable: '
            + str(history.get('error') or 'rack history is unavailable')
        )
    row_lineages, replay_stats = _inventory_age_replay_history(
        history['events'], evidence, match_window_days
    )

    all_units = []
    fallback_units = 0
    now = datetime.datetime.now()
    for active in active_rows:
        row_id = int(active['searchrack_id'])
        barcode = str(active.get('barcode') or '').strip()
        exact_key = _inventory_age_exact_key(barcode)
        base_key = _inventory_age_base_key(barcode)
        target_quantity = max(0, _coerce_int(active.get('quantity'), 0))
        created_at = _history_timestamp(active.get('created_at')) or now

        history_units = list(
            row_lineages.get((row_id, exact_key), [])
        )
        history_units.sort(key=lambda unit: unit['received_at'])
        if len(history_units) > target_quantity:
            history_units = history_units[:target_quantity]

        # The plan is canonical and independent of the prior derived ledger.
        # Existing batches are used only for change detection/audit, never as
        # receipt evidence. That makes a second rebuild exactly idempotent.
        while len(history_units) < target_quantity:
            history_units.append({
                'received_at': created_at,
                'first_seen': created_at,
                'lineage_source': 'warehouse_created_at',
                'lineage_confidence': 35,
                'history_ids': [],
            })
            fallback_units += 1
        history_units.sort(key=lambda unit: unit['received_at'])

        for index in range(target_quantity):
            lineage = history_units[index]
            all_units.append({
                'searchrack_id': row_id,
                'barcode': barcode,
                'exact_key': exact_key,
                'base_key': base_key,
                'unit_index': index,
                'received_at': lineage['received_at'],
                'first_seen': (
                    lineage.get('first_seen')
                    or created_at
                ),
                'lineage_source': str(
                    lineage.get('lineage_source')
                    or 'warehouse_created_at'
                ),
                'lineage_confidence': max(
                    0,
                    _coerce_int(
                        lineage.get('lineage_confidence'), 35
                    ),
                ),
                'history_ids': list(lineage.get('history_ids') or []),
                'reorg_match_type': str(
                    lineage.get('reorg_match_type') or ''
                ),
                'reorg_matches': list(
                    lineage.get('reorg_matches') or []
                ),
                'assigned': False,
            })

    (
        remaining_capacity,
        depleted_capacity_by_pair,
        depletion_stats,
    ) = _inventory_age_depleted_raw_capacity(
        history['events'], evidence
    )

    assignment_counts = Counter()
    assigned_by_exact_lot = Counter()

    def lot_is_temporally_eligible(unit, lot_info):
        first_seen = unit.get('first_seen')
        received_at = lot_info.get('received_at')
        if first_seen is None or received_at is None:
            return False
        return received_at <= first_seen + datetime.timedelta(days=1)

    def assign_receipt(unit, lot_key, evidence_source, score, detail):
        base_key = unit['base_key']
        lot_info = evidence['catalog'].get(base_key, {}).get(lot_key)
        capacity_key = (base_key, lot_key)
        if (
            unit.get('assigned')
            or not lot_info
            or remaining_capacity.get(capacity_key, 0) <= 0
            or not lot_is_temporally_eligible(unit, lot_info)
        ):
            return False
        adjusted_score = max(0, min(100, _coerce_int(score, 0)))
        if not lot_info.get('upload_confirmed'):
            adjusted_score -= 3
        if not lot_info.get('bol_confirmed'):
            adjusted_score -= 3
        adjusted_score = max(0, adjusted_score)
        confidence = _inventory_age_confidence_label(adjusted_score)
        evidence_detail = {
            'reason': evidence_source,
            'raw_bol_ids': lot_info.get('raw_ids') or [],
            'raw_bol_quantity': max(
                0, _coerce_int(lot_info.get('quantity'), 0)
            ),
            'known_permanent_depletion': max(
                0,
                depleted_capacity_by_pair.get(
                    (base_key, lot_key), 0
                ),
            ),
            'date_source': lot_info.get('date_source'),
            'upload_log_confirmed': bool(
                lot_info.get('upload_confirmed')
            ),
            'bol_item_confirmed': bool(
                lot_info.get('bol_confirmed')
            ),
            'warehouse_lineage': {
                'lineage_source': unit.get('lineage_source'),
                'history_ids': unit.get('history_ids') or [],
                'reorg_match_type': unit.get('reorg_match_type') or '',
                'reorg_matches': unit.get('reorg_matches') or [],
            },
            **dict(detail or {}),
        }
        unit.update({
            'received_at': lot_info['received_at'],
            'source': 'comprehensive_age_rebuild',
            'source_history_id': None,
            'estimated': adjusted_score < 90,
            'lot_number': lot_info.get('lot_number') or lot_key,
            'evidence_source': evidence_source,
            'confidence': confidence,
            'confidence_score': adjusted_score,
            'evidence_json': json.dumps(
                evidence_detail,
                sort_keys=True,
                separators=(',', ':'),
            ),
            'assigned': True,
        })
        remaining_capacity[capacity_key] -= 1
        assignment_counts[evidence_source] += 1
        assigned_by_exact_lot[(unit['exact_key'], lot_key)] += 1
        return True

    units_by_exact = defaultdict(list)
    for unit in all_units:
        units_by_exact[unit['exact_key']].append(unit)
    for units in units_by_exact.values():
        units.sort(key=lambda unit: (
            unit['first_seen'],
            unit['searchrack_id'],
            unit['unit_index'],
        ))

    # First priority: non-undone GOOD prep events with an exact UPC and an
    # explicit lot. Each logged quantity is consumed once.
    for exact_key, units in sorted(units_by_exact.items()):
        expanded_tokens = []
        for token in evidence['prep_by_exact'].get(exact_key, []):
            for token_index in range(
                max(0, _coerce_int(token.get('quantity'), 0))
            ):
                expanded_tokens.append({
                    **token,
                    'token_index': token_index,
                })
        for unit in units:
            candidates = []
            for token in expanded_tokens:
                lot_info = evidence['catalog'].get(
                    unit['base_key'], {}
                ).get(token['lot_key'])
                if not lot_info:
                    continue
                if not lot_is_temporally_eligible(unit, lot_info):
                    continue
                if (
                    token['created_at']
                    > unit['first_seen'] + datetime.timedelta(days=2)
                ):
                    continue
                if (
                    lot_info['received_at']
                    > token['created_at'] + datetime.timedelta(days=1)
                ):
                    continue
                if remaining_capacity.get(
                    (unit['base_key'], token['lot_key']), 0
                ) <= 0:
                    continue
                distance = abs(
                    (
                        unit['first_seen'] - token['created_at']
                    ).total_seconds()
                )
                candidates.append((distance, token['created_at'], token))
            if not candidates:
                continue
            candidates.sort(key=lambda value: (
                value[0], value[1], value[2]['id'],
                value[2]['token_index'],
            ))
            token = candidates[0][2]
            score = 98
            if (
                token.get('exception_overage')
                or token.get('needs_review')
                or token.get('continued_without_lot')
            ):
                score = 88
            elif (
                token.get('auto_assigned')
                or token.get('forced_lot_override')
            ):
                score = 96
            if assign_receipt(
                unit,
                token['lot_key'],
                'prep_log_exact_lot',
                score,
                {
                    'prep_log_id': token['id'],
                    'prep_event_at': token['created_at'].isoformat(),
                    'auto_assigned': bool(token.get('auto_assigned')),
                    'forced_lot_override': bool(
                        token.get('forced_lot_override')
                    ),
                    'exception_overage': bool(
                        token.get('exception_overage')
                    ),
                    'needs_review': bool(token.get('needs_review')),
                },
            ):
                expanded_tokens.remove(token)

    # Item Manager's current GOOD status can fill only its remaining exact
    # UPC+lot quantity. Its updated_at is deliberately not treated as receipt.
    status_remaining = {}
    for key, status in evidence['status_by_exact_lot'].items():
        status_remaining[key] = max(
            0,
            _coerce_int(status.get('quantity'), 0)
            - assigned_by_exact_lot.get(key, 0),
        )
    for exact_key, units in sorted(units_by_exact.items()):
        for unit in units:
            if unit.get('assigned'):
                continue
            eligible_lots = []
            for (status_exact, lot_key), remaining in status_remaining.items():
                if status_exact != exact_key or remaining <= 0:
                    continue
                lot_info = evidence['catalog'].get(
                    unit['base_key'], {}
                ).get(lot_key)
                if (
                    lot_info
                    and lot_is_temporally_eligible(unit, lot_info)
                    and remaining_capacity.get(
                        (unit['base_key'], lot_key), 0
                    ) > 0
                ):
                    eligible_lots.append(lot_key)
            eligible_lots = sorted(set(eligible_lots))
            if len(eligible_lots) != 1:
                continue
            lot_key = eligible_lots[0]
            status = evidence['status_by_exact_lot'][
                (exact_key, lot_key)
            ]
            if assign_receipt(
                unit,
                lot_key,
                'item_manager_exact_lot',
                95,
                {'item_prep_status_ids': status.get('ids') or []},
            ):
                status_remaining[(exact_key, lot_key)] -= 1

    # A suffixed Item Manager/BOL row is a distinct unit identity. A base BOL
    # row is intentionally not used as a hard pin because it can blend lots.
    for exact_key, units in sorted(units_by_exact.items()):
        if '-' not in exact_key:
            continue
        for unit in units:
            if unit.get('assigned'):
                continue
            lots = [
                lot_key
                for lot_key in evidence['bol_suffix_lots'].get(
                    exact_key, set()
                )
                if (
                    lot_key in evidence['catalog'].get(
                        unit['base_key'], {}
                    )
                    and lot_is_temporally_eligible(
                        unit,
                        evidence['catalog'][unit['base_key']][lot_key],
                    )
                    and remaining_capacity.get(
                        (unit['base_key'], lot_key), 0
                    ) > 0
                )
            ]
            if len(set(lots)) == 1:
                assign_receipt(
                    unit,
                    lots[0],
                    'item_manager_suffix_lot',
                    92,
                    {'exact_suffix_identity': True},
                )

    # When Raw BOL contains only one receipt lot for the base UPC, there is no
    # cross-lot choice to guess. Capacity still applies globally.
    units_by_base = defaultdict(list)
    for unit in all_units:
        units_by_base[unit['base_key']].append(unit)
    for base_key, units in sorted(units_by_base.items()):
        catalog_lots = evidence['catalog'].get(base_key, {})
        if len(catalog_lots) != 1:
            continue
        lot_key = next(iter(catalog_lots))
        for unit in sorted(units, key=lambda item: (
            item['first_seen'], item['searchrack_id'], item['unit_index']
        )):
            if unit.get('assigned'):
                continue
            assign_receipt(
                unit,
                lot_key,
                'raw_bol_unique_lot',
                96,
                {'candidate_lot_count': 1},
            )

    # For repeated UPCs, a trustworthy first warehouse sighting may eliminate
    # all later lots. More than one eligible lot stays ambiguous.
    for base_key, units in sorted(units_by_base.items()):
        catalog_lots = evidence['catalog'].get(base_key, {})
        if len(catalog_lots) <= 1:
            continue
        for unit in sorted(units, key=lambda item: (
            item['first_seen'], item['searchrack_id'], item['unit_index']
        )):
            if unit.get('assigned'):
                continue
            eligible_lots = [
                lot_key
                for lot_key, lot_info in catalog_lots.items()
                if (
                    lot_is_temporally_eligible(unit, lot_info)
                    and remaining_capacity.get((base_key, lot_key), 0) > 0
                )
            ]
            if len(eligible_lots) == 1:
                assign_receipt(
                    unit,
                    eligible_lots[0],
                    'raw_bol_temporal_single_lot',
                    86,
                    {
                        'candidate_lot_count': len(catalog_lots),
                        'eligible_lot_count': 1,
                        'first_seen': unit['first_seen'].isoformat(),
                    },
                )

    # Any unresolved unit retains its best reconstructed lineage date and is
    # explicitly estimated; no arbitrary oldest/newest lot is selected.
    for unit in all_units:
        if unit.get('assigned'):
            continue
        lineage_score = max(
            25, min(65, _coerce_int(unit.get('lineage_confidence'), 35))
        )
        evidence_source = (
            'rack_history_lineage'
            if unit.get('history_ids')
            else 'warehouse_age_fallback'
        )
        unit.update({
            'source': 'comprehensive_age_rebuild',
            'source_history_id': None,
            'estimated': True,
            'lot_number': '',
            'evidence_source': evidence_source,
            'confidence': _inventory_age_confidence_label(lineage_score),
            'confidence_score': lineage_score,
            'evidence_json': json.dumps({
                'reason': evidence_source,
                'lineage_source': unit.get('lineage_source'),
                'history_ids': unit.get('history_ids') or [],
                'reorg_match_type': unit.get('reorg_match_type') or '',
                'reorg_matches': unit.get('reorg_matches') or [],
                'raw_candidate_lots': len(
                    evidence['catalog'].get(unit['base_key'], {})
                ),
            }, sort_keys=True, separators=(',', ':')),
        })

    proposed_units_by_row = defaultdict(list)
    for unit in all_units:
        proposed_units_by_row[int(unit['searchrack_id'])].append(unit)
    for units in proposed_units_by_row.values():
        units.sort(key=_inventory_age_unit_signature)

    active_barcode_by_id = {
        int(row['searchrack_id']): str(row.get('barcode') or '').strip()
        for row in active_rows
    }
    proposed_batches_by_row = {
        row_id: _inventory_age_group_plan(
            units,
            row_id,
            active_barcode_by_id.get(row_id, ''),
        )
        for row_id, units in proposed_units_by_row.items()
    }

    current_units_for_compare = defaultdict(list)
    for batch in existing_ledger_rows:
        for _ in range(max(0, _coerce_int(batch.get('quantity'), 0))):
            current_units_for_compare[int(batch['searchrack_id'])].append({
                'received_at': batch.get('received_at'),
                'source': batch.get('source'),
                'source_history_id': batch.get('source_history_id'),
                'estimated': bool(batch.get('estimated')),
                'lot_number': batch.get('lot_number'),
                'evidence_source': batch.get('evidence_source'),
                'confidence': batch.get('confidence'),
                'confidence_score': batch.get('confidence_score'),
                'evidence_json': batch.get('evidence_json'),
            })
    for units in current_units_for_compare.values():
        units.sort(key=_inventory_age_unit_signature)

    rows_changed = 0
    rows_rebuilt = 0
    units_changed = 0
    units_moved_older = 0
    units_moved_newer = 0
    rows_to_rebuild = []
    for active in active_rows:
        row_id = int(active['searchrack_id'])
        old_units = current_units_for_compare.get(row_id, [])
        new_units = proposed_units_by_row.get(row_id, [])
        old_signatures = [
            _inventory_age_unit_signature(unit) for unit in old_units
        ]
        new_signatures = [
            _inventory_age_unit_signature(unit) for unit in new_units
        ]
        if old_signatures != new_signatures:
            rows_rebuilt += 1
            rows_to_rebuild.append(row_id)
        old_dates = sorted(
            _history_timestamp(unit.get('received_at')) or now
            for unit in old_units
        )
        new_dates = sorted(
            _history_timestamp(unit.get('received_at')) or now
            for unit in new_units
        )
        changed_here = 0
        for old_at, new_at in zip(old_dates, new_dates):
            difference = (new_at - old_at).total_seconds()
            if abs(difference) <= 60:
                continue
            changed_here += 1
            if difference < 0:
                units_moved_older += 1
            else:
                units_moved_newer += 1
        if changed_here:
            rows_changed += 1
            units_changed += changed_here

    ledger_state_changed = bool(
        rows_to_rebuild or stale_ledger_row_ids
    )
    inventory_units = len(all_units)
    current_reorg_units = sum(
        1 for unit in all_units if unit.get('reorg_matches')
    )
    current_short_gap_reorg_units = sum(
        1
        for unit in all_units
        if any(
            match.get('match_type') == 'short_gap'
            for match in unit.get('reorg_matches') or []
        )
    )
    current_historical_reorg_units = sum(
        1
        for unit in all_units
        if any(
            match.get('match_type')
            == 'known_historical_office_reinventory'
            for match in unit.get('reorg_matches') or []
        )
    )
    raw_coverage_units = sum(
        1 for unit in all_units
        if unit['base_key'] in evidence['catalog']
    )
    verified_units = sum(
        1 for unit in all_units
        if _coerce_int(unit.get('confidence_score'), 0) >= 90
    )
    medium_confidence_units = sum(
        1 for unit in all_units
        if 70 <= _coerce_int(unit.get('confidence_score'), 0) < 90
    )
    low_confidence_units = (
        inventory_units - verified_units - medium_confidence_units
    )
    history_only_units = sum(
        1 for unit in all_units
        if unit.get('evidence_source') in {
            'rack_history_lineage', 'warehouse_age_fallback'
        }
    )
    ambiguous_units = sum(
        1 for unit in all_units
        if (
            not unit.get('assigned')
            and len(evidence['catalog'].get(unit['base_key'], {})) > 1
        )
    )
    no_bol_units = sum(
        1 for unit in all_units
        if not evidence['catalog'].get(unit['base_key'])
    )
    estimated_units = sum(
        1 for unit in all_units if bool(unit.get('estimated'))
    )
    raw_capacity_shortfall_units = 0
    for base_key, units in units_by_base.items():
        available_capacity = sum(
            max(
                0,
                _coerce_int(info.get('quantity'), 0)
                - depleted_capacity_by_pair.get(
                    (base_key, lot_key), 0
                ),
            )
            for lot_key, info in evidence['catalog'].get(
                base_key, {}
            ).items()
        )
        if (
            evidence['catalog'].get(base_key)
            and len(units) > available_capacity
        ):
            raw_capacity_shortfall_units += (
                len(units) - available_capacity
            )

    before_ledger_json = (
        json.dumps(
            existing_ledger_rows,
            ensure_ascii=False,
            default=str,
            separators=(',', ':'),
        )
        if ledger_state_changed
        else '[]'
    )
    planned_batches = [
        batch
        for row_id in sorted(proposed_batches_by_row)
        for batch in proposed_batches_by_row[row_id]
    ]
    after_plan_json = json.dumps(
        planned_batches,
        ensure_ascii=False,
        default=str,
        sort_keys=True,
        separators=(',', ':'),
    )
    plan_digest = hashlib.sha256(
        after_plan_json.encode('utf-8')
    ).hexdigest()
    input_digest = hashlib.sha256(json.dumps({
        'inventory': expected_inventory,
        'ledger': existing_ledger_signature,
        'history': history['fingerprint'],
        'evidence': evidence['fingerprint'],
    }, default=str, sort_keys=True, separators=(',', ':')).encode(
        'utf-8'
    )).hexdigest()

    # Re-read every external source immediately before the write. The final
    # SEARCHRACK transaction independently rechecks inventory and ledger state.
    evidence_recheck = _inventory_age_load_receipt_evidence(
        evidence['paths']
    )
    if (
        not evidence_recheck.get('complete')
        or evidence_recheck['fingerprint'] != evidence['fingerprint']
    ):
        raise RuntimeError(
            'BOL or Item Manager data changed during the age rebuild; please retry'
        )
    history_recheck = _inventory_age_load_history(
        active_keys, history['path'], active_base_keys
    )
    if (
        not history_recheck.get('available')
        or history_recheck['fingerprint'] != history['fingerprint']
    ):
        raise RuntimeError(
            'Rack history changed during the age rebuild; please retry'
        )

    completed_at = datetime.datetime.now().isoformat()
    summary = {
        'run_id': run_id,
        'started_at': started_at,
        'completed_at': completed_at,
        'mode': 'comprehensive',
        'match_window_days': max(1, int(match_window_days or 2)),
        'inventory_rows': len(active_rows),
        'inventory_units': inventory_units,
        'raw_bol_coverage_units': raw_coverage_units,
        'high_confidence_units': verified_units,
        'strong_evidence_percent': (
            round((verified_units / inventory_units) * 100, 1)
            if inventory_units else 100.0
        ),
        # Kept for older clients; this is evidence coverage, not a measured
        # accuracy rate.
        'verified_units': verified_units,
        'verified_percent': (
            round((verified_units / inventory_units) * 100, 1)
            if inventory_units else 100.0
        ),
        'medium_confidence_units': medium_confidence_units,
        'low_confidence_units': low_confidence_units,
        'estimated_units': estimated_units,
        'history_only_units': history_only_units,
        'ambiguous_units': ambiguous_units,
        'no_bol_units': no_bol_units,
        'raw_capacity_shortfall_units': raw_capacity_shortfall_units,
        'known_permanent_removal_units': depletion_stats[
            'known_permanent_removal_units'
        ],
        'raw_capacity_depleted_units': depletion_stats[
            'raw_capacity_depleted_units'
        ],
        'unmatched_permanent_removal_units': depletion_stats[
            'unmatched_permanent_removal_units'
        ],
        'bases_with_raw_capacity_depletion': depletion_stats[
            'bases_with_raw_capacity_depletion'
        ],
        'history_events_scanned': len(history['events']),
        'history_events_used': replay_stats['history_events_used'],
        'movement_events_suppressed': history[
            'movement_events_suppressed'
        ],
        'matched_reorg_units': current_reorg_units,
        'matched_short_gap_reorg_units': current_short_gap_reorg_units,
        'matched_historical_exception_units': (
            current_historical_reorg_units
        ),
        'history_reorg_operations': replay_stats[
            'matched_reorg_units'
        ],
        'reorg_units_blocked_by_new_receipt': replay_stats[
            'reorg_units_blocked_by_new_receipt'
        ],
        'reorg_units_blocked_by_confirmed_receipt': replay_stats[
            'reorg_units_blocked_by_confirmed_receipt'
        ],
        'reorg_units_blocked_by_possible_receipt': replay_stats[
            'reorg_units_blocked_by_possible_receipt'
        ],
        'pending_unmatched_clear_units': replay_stats[
            'pending_unmatched_clear_units'
        ],
        'inferred_history_units': replay_stats[
            'inferred_history_units'
        ],
        'fallback_units': fallback_units,
        'rows_rebuilt': rows_rebuilt,
        'stale_age_rows_removed': len(stale_ledger_row_ids),
        'rows_changed': rows_changed,
        'units_changed': units_changed,
        'units_moved_older': units_moved_older,
        'units_moved_newer': units_moved_newer,
        'assignment_counts': dict(sorted(assignment_counts.items())),
        'input_digest': input_digest,
        'plan_digest': plan_digest,
        'warnings': evidence['warnings'],
    }

    cur.execute('BEGIN IMMEDIATE')
    try:
        cur.execute('''
            SELECT ID, BARCODE, COALESCE(CAST(QUANTITY AS INTEGER), 0)
            FROM SEARCHRACK
            WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
            ORDER BY ID
        ''')
        current_inventory = [(
            int(row[0]),
            str(row[1] or '').strip(),
            max(0, _coerce_int(row[2], 0)),
        ) for row in cur.fetchall()]
        if current_inventory != expected_inventory:
            raise RuntimeError(
                'Warehouse inventory changed during the age rebuild; please retry'
            )
        current_ledger_rows = _inventory_age_read_ledger_rows(cur)
        if (
            _inventory_age_ledger_signature(current_ledger_rows)
            != existing_ledger_signature
        ):
            raise RuntimeError(
                'Inventory ages changed during the age rebuild; please retry'
            )

        if stale_ledger_row_ids:
            placeholders = ','.join('?' for _ in stale_ledger_row_ids)
            cur.execute(
                f'DELETE FROM inventory_age_batches '
                f'WHERE searchrack_id IN ({placeholders})',
                tuple(stale_ledger_row_ids),
            )
        for row_id in rows_to_rebuild:
            cur.execute(
                'DELETE FROM inventory_age_batches WHERE searchrack_id = ?',
                (row_id,),
            )
            for batch in proposed_batches_by_row.get(row_id, []):
                _inventory_age_insert_batch(
                    cur,
                    row_id,
                    batch['barcode'],
                    batch['received_at'],
                    batch['quantity'],
                    source=batch['source'],
                    source_history_id=batch['source_history_id'],
                    estimated=batch['estimated'],
                    lot_number=batch['lot_number'],
                    evidence_source=batch['evidence_source'],
                    confidence=batch['confidence'],
                    confidence_score=batch['confidence_score'],
                    evidence_json=batch['evidence_json'],
                    rebuild_run_id=run_id,
                )

        cur.execute('''
            SELECT searchrack_id, COALESCE(SUM(quantity), 0)
            FROM inventory_age_batches
            WHERE quantity > 0
            GROUP BY searchrack_id
        ''')
        ledger_quantities = {
            int(row[0]): max(0, _coerce_int(row[1], 0))
            for row in cur.fetchall()
        }
        expected_quantities = {
            row_id: quantity
            for row_id, _barcode, quantity in expected_inventory
        }
        if ledger_quantities != expected_quantities:
            raise RuntimeError(
                'Age rebuild quantity invariant failed; no changes were saved'
            )

        final_ledger_rows = _inventory_age_read_ledger_rows(cur)
        final_ledger_json = (
            json.dumps(
                final_ledger_rows,
                ensure_ascii=False,
                default=str,
                separators=(',', ':'),
            )
            if ledger_state_changed
            else '[]'
        )
        cur.execute('''
            INSERT INTO inventory_age_rebuild_runs (
                run_id, started_at, completed_at, input_digest,
                plan_digest, mode, status, summary_json,
                before_ledger_json, after_ledger_json
            ) VALUES (?, ?, ?, ?, ?, 'comprehensive', 'completed', ?, ?, ?)
        ''', (
            run_id,
            started_at,
            completed_at,
            input_digest,
            plan_digest,
            json.dumps(summary, sort_keys=True, separators=(',', ':')),
            before_ledger_json,
            final_ledger_json,
        ))
        # Retain complete rollback evidence for only the five newest
        # state-changing rebuilds. Older/no-op runs keep their digest/summary.
        cur.execute('''
            UPDATE inventory_age_rebuild_runs
            SET before_ledger_json = '[]',
                after_ledger_json = '[]'
            WHERE run_id NOT IN (
                SELECT run_id
                FROM inventory_age_rebuild_runs
                WHERE before_ledger_json != '[]'
                   OR after_ledger_json != '[]'
                ORDER BY completed_at DESC, started_at DESC
                LIMIT 5
            )
        ''')
        summary_json = json.dumps(
            summary, sort_keys=True, separators=(',', ':')
        )
        cur.execute('''
            INSERT OR REPLACE INTO inventory_age_meta(key, value)
            VALUES ('last_comprehensive_rebuild', ?)
        ''', (summary_json,))
        cur.execute('''
            INSERT OR IGNORE INTO inventory_age_meta(key, value)
            VALUES ('backfill_v1', ?)
        ''', (completed_at,))
        cur.execute('''
            INSERT OR REPLACE INTO inventory_age_meta(key, value)
            VALUES ('last_history_rescan', ?)
        ''', (summary_json,))
        conn.commit()
    except Exception:
        conn.rollback()
        raise

    return {
        **summary,
        'reconcile': reconcile,
        'quantity_invariant': True,
    }


def _inventory_age_lookup(conn, searchrack_ids):
    ids = sorted({
        int(value) for value in (searchrack_ids or [])
        if value not in (None, '') and str(value).lstrip('-').isdigit()
    })
    if not ids:
        return {}
    placeholders = ','.join('?' for _ in ids)
    cur = conn.cursor()
    cur.execute(f'''
        SELECT searchrack_id, received_at, quantity, estimated
        FROM inventory_age_batches
        WHERE searchrack_id IN ({placeholders}) AND quantity > 0
        ORDER BY received_at, id
    ''', tuple(ids))
    result = {row_id: [] for row_id in ids}
    for row_id, received_at, quantity, estimated in cur.fetchall():
        result.setdefault(int(row_id), []).append({
            'received_at': str(received_at or ''),
            'quantity': max(0, _coerce_int(quantity, 0)),
            'estimated': bool(estimated),
        })
    return result


def _history_restore_quantity(history_row):
    """Derive an undo amount from authoritative history, never from browser state."""
    history = dict(history_row) if not isinstance(history_row, dict) else dict(history_row)
    quantity_removed = max(0, _coerce_int(history.get('quantity_removed'), 0))
    old_quantity = _coerce_int(history.get('old_quantity'), 0)
    new_quantity = _coerce_int(history.get('new_quantity'), 0)
    return max(quantity_removed, max(0, old_quantity - new_quantity))


def _restore_searchrack_from_history(rack_cur, history_row, restore_quantity):
    """Restore only to the archived barcode/location identity, recreating the row if needed."""
    restore_quantity = max(0, _coerce_int(restore_quantity, 0))
    if restore_quantity <= 0:
        raise ValueError('Restore quantity must be positive')

    history = dict(history_row) if not isinstance(history_row, dict) else dict(history_row)
    try:
        snapshot = json.loads(history.get('source_row_json') or '{}')
        if not isinstance(snapshot, dict):
            snapshot = {}
    except Exception:
        snapshot = {}

    rack_cur.execute("PRAGMA table_info('SEARCHRACK')")
    columns = [row[1] for row in rack_cur.fetchall()]
    lower = {str(column).lower(): column for column in columns}
    id_col = lower.get('id')
    qty_col = lower.get('quantity') or lower.get('qty')
    barcode_col = lower.get('barcode') or lower.get('upc')
    title_col = lower.get('title')
    pos_col = lower.get('item_position') or lower.get('itemposition') or lower.get('position')
    pic_col = lower.get('pictureposition') or lower.get('picture_position')
    if not qty_col:
        raise RuntimeError('SEARCHRACK quantity column not found')

    snapshot_folded = _row_casefold_dict(snapshot)
    snapshot_barcode = snapshot_folded.get(str(barcode_col).lower()) if barcode_col else ''
    barcode = str(snapshot_barcode or '').strip()
    if not barcode:
        barcode = str(history.get('barcode') or '').strip()
    source_location = _searchrack_snapshot_location(snapshot) or str(
        history.get('from_position') or history.get('item_position') or ''
    ).strip()
    barcode_key = barcode.casefold()
    location_key = source_location.casefold()
    sid = history.get('searchrack_id')
    id_expr = _sqlite_ident(id_col) if id_col else 'rowid'
    sid_reusable = sid not in (None, '')

    if sid_reusable:
        rack_cur.execute(
            f'SELECT rowid AS _rowid_, * FROM SEARCHRACK WHERE {id_expr} = ?',
            (sid,)
        )
        existing = rack_cur.fetchone()
        if existing:
            existing_dict = dict(existing)
            existing_barcode = str(
                _searchrack_snapshot_value(existing_dict, barcode_col or 'barcode', 'barcode', 'upc') or ''
            ).strip().casefold()
            existing_location = _searchrack_snapshot_location(existing_dict).casefold()
            if barcode_key and existing_barcode == barcode_key and existing_location == location_key:
                current_qty = max(0, _coerce_int(existing_dict.get(qty_col), 0))
                new_qty = current_qty + restore_quantity
                rack_cur.execute(
                    f'UPDATE SEARCHRACK SET {_sqlite_ident(qty_col)} = ? WHERE {id_expr} = ?',
                    (new_qty, sid)
                )
                return {
                    'searchrack_id': existing_dict.get(id_col) if id_col else existing_dict.get('_rowid_'),
                    'old_quantity': current_qty,
                    'new_quantity': new_qty,
                    'recreated': False,
                }
            # That numeric ID now belongs to another inventory identity; never overwrite it.
            sid_reusable = False

    if barcode_col and barcode:
        rack_cur.execute(
            f'''SELECT rowid AS _rowid_, * FROM SEARCHRACK
                WHERE {_sqlite_ident(barcode_col)} = ? COLLATE NOCASE
                  AND COALESCE(CAST({_sqlite_ident(qty_col)} AS INTEGER), 0) > 0''',
            (barcode,)
        )
        for row in rack_cur.fetchall():
            row_dict = dict(row)
            if _searchrack_snapshot_location(row_dict).casefold() != location_key:
                continue
            row_id = row_dict.get(id_col) if id_col else row_dict.get('_rowid_')
            current_qty = max(0, _coerce_int(row_dict.get(qty_col), 0))
            new_qty = current_qty + restore_quantity
            rack_cur.execute(
                f'UPDATE SEARCHRACK SET {_sqlite_ident(qty_col)} = ? WHERE {id_expr} = ?',
                (new_qty, row_id)
            )
            return {
                'searchrack_id': row_id, 'old_quantity': current_qty,
                'new_quantity': new_qty, 'recreated': False
            }

    values_by_column = {}
    for column in columns:
        if id_col and column.lower() == id_col.lower():
            continue
        values_by_column[column] = snapshot_folded.get(column.lower())
    values_by_column[qty_col] = restore_quantity
    if barcode_col:
        values_by_column[barcode_col] = barcode
    if title_col and not values_by_column.get(title_col):
        values_by_column[title_col] = str(history.get('title') or '').strip()
    if source_location and pos_col and not values_by_column.get(pos_col):
        values_by_column[pos_col] = source_location
    if pic_col and str(values_by_column.get(pos_col) or '').strip().lower() != 'picture':
        values_by_column[pic_col] = values_by_column.get(pic_col) or ''

    insert_columns = list(values_by_column.keys())
    insert_values = [values_by_column[column] for column in insert_columns]
    if id_col and sid_reusable:
        insert_columns.insert(0, id_col)
        insert_values.insert(0, sid)
    placeholders = ','.join('?' for _ in insert_columns)
    rack_cur.execute(
        f'''INSERT INTO SEARCHRACK ({', '.join(_sqlite_ident(c) for c in insert_columns)})
            VALUES ({placeholders})''',
        tuple(insert_values)
    )
    new_id = sid if id_col and sid_reusable else rack_cur.lastrowid
    return {
        'searchrack_id': new_id, 'old_quantity': 0,
        'new_quantity': restore_quantity, 'recreated': True
    }


def _restore_searchrack_with_undo_claim(
    rack_cur, history_row, restore_quantity, *, history_source='removed_items'
):
    """Restore once; the claim and stock mutation share the SEARCHRACK transaction."""
    history = dict(history_row) if not isinstance(history_row, dict) else dict(history_row)
    history_id = _coerce_int(history.get('id'), 0)
    if history_id <= 0:
        raise ValueError('History event has no stable ID')
    restore_quantity = max(0, _coerce_int(restore_quantity, 0))
    if restore_quantity <= 0:
        raise ValueError('History event has no positive quantity to restore')

    _ensure_searchrack_undo_claims(rack_cur)
    rack_cur.execute('''
        SELECT searchrack_id, restore_quantity, old_quantity, new_quantity, recreated,
               outbox_event_id
        FROM searchrack_undo_claims
        WHERE history_source = ? AND history_id = ?
    ''', (history_source, history_id))
    claimed = rack_cur.fetchone()
    if claimed:
        return {
            'searchrack_id': claimed[0],
            'restore_quantity': claimed[1],
            'old_quantity': claimed[2],
            'new_quantity': claimed[3],
            'recreated': bool(claimed[4]),
            'outbox_event_id': str(claimed[5] or '').strip(),
            'already_claimed': True,
        }

    _ensure_searchrack_history_outbox(rack_cur)
    rack_cur.execute('SELECT COALESCE(MAX(id), 0) FROM searchrack_history_outbox')
    outbox_id_before = _coerce_int(rack_cur.fetchone()[0], 0)
    restored = _restore_searchrack_from_history(rack_cur, history, restore_quantity)
    rack_cur.execute('''
        SELECT event_id
        FROM searchrack_history_outbox
        WHERE id > ? AND searchrack_id = ?
        ORDER BY id DESC
        LIMIT 1
    ''', (outbox_id_before, restored['searchrack_id']))
    outbox_row = rack_cur.fetchone()
    outbox_event_id = str(outbox_row[0] or '').strip() if outbox_row else ''
    rack_cur.execute('''
        INSERT INTO searchrack_undo_claims (
            history_source, history_id, claimed_at, searchrack_id,
            restore_quantity, old_quantity, new_quantity, recreated, outbox_event_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    ''', (
        history_source,
        history_id,
        datetime.datetime.now().isoformat(),
        restored['searchrack_id'],
        restore_quantity,
        restored['old_quantity'],
        restored['new_quantity'],
        1 if restored['recreated'] else 0,
        outbox_event_id,
    ))
    restored['restore_quantity'] = restore_quantity
    restored['outbox_event_id'] = outbox_event_id
    restored['already_claimed'] = False
    return restored


def _insert_inventory_undo_history(
    history_cur, source_row, restored, removal_type, *, order_id=None, undone_at=None
):
    """Insert one idempotent forward audit row for a completed undo."""
    source = dict(source_row) if not isinstance(source_row, dict) else dict(source_row)
    history_id = _coerce_int(source.get('id'), 0)
    if history_id <= 0:
        raise ValueError('History event has no stable ID')
    undone_at = undone_at or datetime.datetime.now().isoformat()
    location = str(source.get('from_position') or source.get('item_position') or '').strip()
    event_id = str(restored.get('outbox_event_id') or '').strip() or f'undo:removed_items:{history_id}'
    history_cur.execute('''
        INSERT OR IGNORE INTO removed_items (
            order_id, barcode, title, quantity_removed, removed_at, searchrack_id,
            old_quantity, new_quantity, removal_type, item_position,
            event_id, from_position, to_position, inventory_row_deleted,
            event_status, applied_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, 0, 'applied', ?)
    ''', (
        order_id,
        str(source.get('barcode') or '').strip(),
        str(source.get('title') or '').strip(),
        max(0, _coerce_int(restored.get('restore_quantity'), 0)),
        undone_at,
        restored.get('searchrack_id'),
        restored.get('old_quantity'),
        restored.get('new_quantity'),
        removal_type,
        location,
        event_id,
        location,
        undone_at,
    ))
    history_cur.execute('''
        UPDATE removed_items
        SET order_id = ?, barcode = ?, title = ?, quantity_removed = ?,
            removed_at = ?, searchrack_id = ?, old_quantity = ?, new_quantity = ?,
            removal_type = ?, item_position = ?, from_position = '', to_position = ?,
            inventory_row_deleted = 0, event_status = 'applied', applied_at = ?
        WHERE event_id = ?
    ''', (
        order_id,
        str(source.get('barcode') or '').strip(),
        str(source.get('title') or '').strip(),
        max(0, _coerce_int(restored.get('restore_quantity'), 0)),
        undone_at,
        restored.get('searchrack_id'),
        restored.get('old_quantity'),
        restored.get('new_quantity'),
        removal_type,
        location,
        location,
        undone_at,
        event_id,
    ))

def _mark_zero_qty_for_deletion_external(item_id):
    """Legacy compatibility helper; the database trigger now deletes depleted rows immediately."""
    _clear_zero_qty_pending_deletions(item_id)

def _clear_zero_qty_pending_deletions(searchrack_id=None):
    """Remove obsolete delayed-deletion queue entries."""
    try:
        with db_connection('searchRack.db') as _conn:
            _cur = _conn.cursor()
            _cur.execute('''
                CREATE TABLE IF NOT EXISTS zero_qty_pending_deletion (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    searchrack_id INTEGER,
                    marked_at TEXT,
                    delete_at TEXT,
                    deletion_cancelled INTEGER DEFAULT 0
                )
            ''')
            if searchrack_id is None:
                _cur.execute('DELETE FROM zero_qty_pending_deletion')
            else:
                _cur.execute('DELETE FROM zero_qty_pending_deletion WHERE searchrack_id = ?', (searchrack_id,))
            cleared = _cur.rowcount
            _conn.commit()
            return cleared
    except Exception:
        return 0

def _ensure_order_removal_allocations_table(cur):
    """Persist explicit ready-to-ship location choices for sold-order removals."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS order_removal_allocations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_row_id INTEGER NOT NULL,
            location_key TEXT NOT NULL,
            location_code TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_order_removal_allocations_order ON order_removal_allocations(order_row_id)')

def _ensure_ready_to_ship_notes_table(cur):
    """Persist Ready to Ship-only shipper notes separate from marketplace/order data."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS ready_to_ship_notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_row_id INTEGER NOT NULL UNIQUE,
            note TEXT NOT NULL,
            label_filename TEXT DEFAULT '',
            label_original_filename TEXT DEFAULT '',
            label_size_bytes INTEGER DEFAULT 0,
            label_uploaded_at TEXT DEFAULT '',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('PRAGMA table_info(ready_to_ship_notes)')
    columns = {str(row[1]) for row in cur.fetchall()}
    migrations = {
        'label_filename': "ALTER TABLE ready_to_ship_notes ADD COLUMN label_filename TEXT DEFAULT ''",
        'label_original_filename': "ALTER TABLE ready_to_ship_notes ADD COLUMN label_original_filename TEXT DEFAULT ''",
        'label_size_bytes': "ALTER TABLE ready_to_ship_notes ADD COLUMN label_size_bytes INTEGER DEFAULT 0",
        'label_uploaded_at': "ALTER TABLE ready_to_ship_notes ADD COLUMN label_uploaded_at TEXT DEFAULT ''",
    }
    for column, sql in migrations.items():
        if column not in columns:
            cur.execute(sql)
    cur.execute('CREATE INDEX IF NOT EXISTS idx_ready_to_ship_notes_order ON ready_to_ship_notes(order_row_id)')

def _ensure_ready_to_ship_unmatched_labels_table(cur):
    """Persist labels that could not be confidently matched to an order."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS ready_to_ship_unmatched_labels (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label_filename TEXT NOT NULL,
            label_original_filename TEXT DEFAULT '',
            label_size_bytes INTEGER DEFAULT 0,
            label_uploaded_at TEXT DEFAULT '',
            extracted_text TEXT DEFAULT '',
            match_error TEXT DEFAULT '',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('PRAGMA table_info(ready_to_ship_unmatched_labels)')
    columns = {str(row[1]) for row in cur.fetchall()}
    migrations = {
        'label_original_filename': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN label_original_filename TEXT DEFAULT ''",
        'label_size_bytes': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN label_size_bytes INTEGER DEFAULT 0",
        'label_uploaded_at': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN label_uploaded_at TEXT DEFAULT ''",
        'extracted_text': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN extracted_text TEXT DEFAULT ''",
        'match_error': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN match_error TEXT DEFAULT ''",
        'updated_at': "ALTER TABLE ready_to_ship_unmatched_labels ADD COLUMN updated_at TEXT DEFAULT ''",
    }
    for column, sql in migrations.items():
        if column not in columns:
            cur.execute(sql)
    cur.execute('CREATE INDEX IF NOT EXISTS idx_ready_to_ship_unmatched_uploaded ON ready_to_ship_unmatched_labels(label_uploaded_at)')

def _ensure_ready_to_ship_order_labels_table(cur):
    """Persist one or more shipping labels attached to a Ready to Ship order."""
    _ensure_ready_to_ship_notes_table(cur)
    cur.execute('''
        CREATE TABLE IF NOT EXISTS ready_to_ship_order_labels (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_row_id INTEGER NOT NULL,
            label_filename TEXT NOT NULL,
            label_original_filename TEXT DEFAULT '',
            label_size_bytes INTEGER DEFAULT 0,
            label_uploaded_at TEXT DEFAULT '',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('PRAGMA table_info(ready_to_ship_order_labels)')
    columns = {str(row[1]) for row in cur.fetchall()}
    migrations = {
        'label_original_filename': "ALTER TABLE ready_to_ship_order_labels ADD COLUMN label_original_filename TEXT DEFAULT ''",
        'label_size_bytes': "ALTER TABLE ready_to_ship_order_labels ADD COLUMN label_size_bytes INTEGER DEFAULT 0",
        'label_uploaded_at': "ALTER TABLE ready_to_ship_order_labels ADD COLUMN label_uploaded_at TEXT DEFAULT ''",
        'updated_at': "ALTER TABLE ready_to_ship_order_labels ADD COLUMN updated_at TEXT DEFAULT ''",
    }
    for column, sql in migrations.items():
        if column not in columns:
            cur.execute(sql)
    cur.execute('CREATE INDEX IF NOT EXISTS idx_ready_to_ship_order_labels_order ON ready_to_ship_order_labels(order_row_id)')
    cur.execute('CREATE UNIQUE INDEX IF NOT EXISTS idx_ready_to_ship_order_labels_file ON ready_to_ship_order_labels(order_row_id, label_filename)')
    cur.execute('''
        INSERT OR IGNORE INTO ready_to_ship_order_labels
            (order_row_id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at)
        SELECT order_row_id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at
        FROM ready_to_ship_notes
        WHERE COALESCE(TRIM(label_filename), '') <> ''
    ''')

def _ready_to_ship_row_value(row, key, default=''):
    if not row:
        return default
    try:
        if hasattr(row, 'keys') and key not in row.keys():
            return default
        value = row[key]
        return default if value is None else value
    except Exception:
        try:
            value = row.get(key, default)
            return default if value is None else value
        except Exception:
            return default

def _ready_to_ship_order_label_payload(row=None, order_id=None):
    if not row:
        return {}
    label_id = _coerce_int(_ready_to_ship_row_value(row, 'id', 0), 0)
    row_order_id = _coerce_int(_ready_to_ship_row_value(row, 'order_row_id', order_id or 0), 0)
    order_id = row_order_id or _coerce_int(order_id, 0)
    filename = str(_ready_to_ship_row_value(row, 'label_filename', '') or '').strip()
    original = str(_ready_to_ship_row_value(row, 'label_original_filename', '') or '').strip()
    uploaded_at = str(_ready_to_ship_row_value(row, 'label_uploaded_at', '') or '').strip()
    size_raw = _ready_to_ship_row_value(row, 'label_size_bytes', 0)
    try:
        size_bytes = max(0, int(size_raw or 0))
    except Exception:
        size_bytes = 0
    label_url = ''
    if filename and order_id:
        label_url = (
            f"/api/ready-to-ship/label/{order_id}/file/{label_id}"
            if label_id else
            f"/api/ready-to-ship/label/{order_id}/file"
        )
    return {
        'id': label_id,
        'label_id': label_id,
        'order_id': order_id,
        'label_filename': filename,
        'label_original_filename': original,
        'label_size_bytes': size_bytes,
        'label_uploaded_at': uploaded_at,
        'label_url': label_url,
        'filename': original or filename,
        'saved': bool(filename)
    }

def _ready_to_ship_legacy_label_row(note_row=None):
    filename = str(_ready_to_ship_row_value(note_row, 'label_filename', '') or '').strip()
    if not filename:
        return None
    return {
        'id': 0,
        'order_row_id': _ready_to_ship_row_value(note_row, 'order_row_id', ''),
        'label_filename': filename,
        'label_original_filename': str(_ready_to_ship_row_value(note_row, 'label_original_filename', '') or '').strip(),
        'label_size_bytes': _ready_to_ship_row_value(note_row, 'label_size_bytes', 0),
        'label_uploaded_at': str(_ready_to_ship_row_value(note_row, 'label_uploaded_at', '') or '').strip()
    }

def _ready_to_ship_label_payload(note_row=None, label_rows=None):
    order_id = _ready_to_ship_row_value(note_row, 'order_row_id', '')
    rows = list(label_rows or [])
    if not rows:
        legacy_row = _ready_to_ship_legacy_label_row(note_row)
        if legacy_row:
            rows.append(legacy_row)
    labels = [
        payload for payload in (
            _ready_to_ship_order_label_payload(row, order_id=order_id) for row in rows
        )
        if payload.get('label_filename')
    ]
    primary = labels[0] if labels else {}
    filename = str(primary.get('label_filename') or '').strip()
    original = str(primary.get('label_original_filename') or '').strip()
    uploaded_at = str(primary.get('label_uploaded_at') or '').strip()
    size_bytes = int(primary.get('label_size_bytes') or 0)
    has_label = bool(filename)
    label_url = str(primary.get('label_url') or '').strip()
    return {
        'ready_to_ship_label_filename': filename,
        'ready_to_ship_label_original_filename': original,
        'ready_to_ship_label_size_bytes': size_bytes,
        'ready_to_ship_label_uploaded_at': uploaded_at,
        'ready_to_ship_label_url': label_url,
        'ready_to_ship_label_id': int(primary.get('label_id') or primary.get('id') or 0),
        'ready_to_ship_labels': labels,
        'ready_to_ship_label_count': len(labels),
        'has_ready_to_ship_label': has_label
    }

def _ready_to_ship_unmatched_label_payload(row=None):
    if not row:
        return {}
    label_id = _coerce_int(_ready_to_ship_row_value(row, 'id', 0), 0)
    filename = str(_ready_to_ship_row_value(row, 'label_filename', '') or '').strip()
    original = str(_ready_to_ship_row_value(row, 'label_original_filename', '') or '').strip()
    uploaded_at = str(_ready_to_ship_row_value(row, 'label_uploaded_at', '') or '').strip()
    match_error = str(_ready_to_ship_row_value(row, 'match_error', '') or '').strip()
    try:
        size_bytes = max(0, int(_ready_to_ship_row_value(row, 'label_size_bytes', 0) or 0))
    except Exception:
        size_bytes = 0
    label_url = f"/api/ready-to-ship/labels/unmatched/{label_id}/file" if label_id and filename else ''
    return {
        'id': label_id,
        'unmatched_label_id': label_id,
        'label_filename': filename,
        'label_original_filename': original,
        'label_size_bytes': size_bytes,
        'label_uploaded_at': uploaded_at,
        'label_url': label_url,
        'filename': original or filename,
        'match_error': match_error,
        'saved': bool(label_id and filename)
    }

def _ready_to_ship_label_dir():
    path = BASE_DIR / 'debug_uploads' / 'ready_to_ship_labels'
    path.mkdir(parents=True, exist_ok=True)
    return path

def _ready_to_ship_label_path(filename):
    safe_name = os.path.basename(str(filename or '').strip())
    if not safe_name or safe_name != str(filename or '').strip() or not safe_name.lower().endswith('.pdf'):
        return None
    path = (_ready_to_ship_label_dir() / safe_name).resolve()
    root = _ready_to_ship_label_dir().resolve()
    try:
        path.relative_to(root)
    except Exception:
        return None
    return path

def _ready_to_ship_delete_label_file(filename):
    path = _ready_to_ship_label_path(filename)
    if not path:
        return
    try:
        if path.exists():
            path.unlink()
    except Exception as exc:
        print(f"Warning: failed deleting Ready to Ship label {path}: {exc}")

def _ready_to_ship_extract_pdf_text(pdf_path):
    """Best-effort PDF text extraction for label-to-order matching."""
    text_parts = []

    try:
        from pypdf import PdfReader
        reader = PdfReader(str(pdf_path))
        for page in reader.pages[:3]:
            try:
                text_parts.append(page.extract_text() or '')
            except Exception:
                pass
    except Exception:
        try:
            from PyPDF2 import PdfReader
            reader = PdfReader(str(pdf_path))
            for page in reader.pages[:3]:
                try:
                    text_parts.append(page.extract_text() or '')
                except Exception:
                    pass
        except Exception:
            pass

    if not ''.join(text_parts).strip():
        try:
            import fitz
            doc = fitz.open(str(pdf_path))
            for page in list(doc)[:3]:
                text_parts.append(page.get_text('text') or '')
            doc.close()
        except Exception:
            pass

    if not ''.join(text_parts).strip():
        try:
            result = subprocess.run(
                ['pdftotext', '-layout', str(pdf_path), '-'],
                capture_output=True,
                text=True,
                timeout=8
            )
            if result.returncode == 0 and result.stdout:
                text_parts.append(result.stdout)
        except Exception:
            pass

    if not ''.join(text_parts).strip():
        try:
            raw = Path(pdf_path).read_bytes()
            decoded = raw.decode('latin-1', errors='ignore')
            text_parts.append(' '.join(re.findall(r'[A-Za-z0-9][A-Za-z0-9 .,#/\-]{2,}', decoded)))
        except Exception:
            pass

    return '\n'.join(part for part in text_parts if part).strip()

def _ready_to_ship_match_norm(value):
    return re.sub(r'\s+', ' ', re.sub(r'[^a-z0-9]+', ' ', str(value or '').lower())).strip()

def _ready_to_ship_match_compact(value):
    return re.sub(r'[^a-z0-9]+', '', str(value or '').lower())

_READY_TO_SHIP_ADDRESS_TOKEN_ALIASES = {
    'aly': 'alley', 'alley': 'alley',
    'apt': 'apartment', 'apartment': 'apartment',
    'ave': 'avenue', 'av': 'avenue', 'aven': 'avenue', 'avenue': 'avenue',
    'blvd': 'boulevard', 'boul': 'boulevard', 'boulevard': 'boulevard',
    'bldg': 'building', 'building': 'building',
    'cir': 'circle', 'circle': 'circle',
    'ct': 'court', 'court': 'court',
    'ctr': 'center', 'center': 'center', 'centre': 'center',
    'dr': 'drive', 'drive': 'drive',
    'e': 'east', 'east': 'east',
    'fl': 'floor', 'floor': 'floor',
    'hwy': 'highway', 'highway': 'highway',
    'ln': 'lane', 'lane': 'lane',
    'n': 'north', 'north': 'north',
    'pkwy': 'parkway', 'parkway': 'parkway',
    'pl': 'place', 'place': 'place',
    'rd': 'road', 'road': 'road',
    'rm': 'room', 'room': 'room',
    's': 'south', 'south': 'south',
    'sq': 'square', 'square': 'square',
    'st': 'street', 'str': 'street', 'street': 'street',
    'ste': 'suite', 'suite': 'suite',
    'ter': 'terrace', 'terrace': 'terrace',
    'trl': 'trail', 'trail': 'trail',
    'unit': 'unit',
    'w': 'west', 'west': 'west',
    'wy': 'way', 'way': 'way',
}

_READY_TO_SHIP_STREET_GENERIC_TOKENS = {
    'alley', 'apartment', 'avenue', 'boulevard', 'building', 'circle',
    'court', 'center', 'drive', 'east', 'floor', 'highway', 'lane',
    'north', 'parkway', 'place', 'road', 'room', 'south', 'square',
    'street', 'suite', 'terrace', 'trail', 'unit', 'west', 'way'
}

_READY_TO_SHIP_STATE_CODES = {
    'alabama': 'al', 'alaska': 'ak', 'arizona': 'az', 'arkansas': 'ar',
    'california': 'ca', 'colorado': 'co', 'connecticut': 'ct', 'delaware': 'de',
    'district of columbia': 'dc', 'florida': 'fl', 'georgia': 'ga', 'hawaii': 'hi',
    'idaho': 'id', 'illinois': 'il', 'indiana': 'in', 'iowa': 'ia',
    'kansas': 'ks', 'kentucky': 'ky', 'louisiana': 'la', 'maine': 'me',
    'maryland': 'md', 'massachusetts': 'ma', 'michigan': 'mi', 'minnesota': 'mn',
    'mississippi': 'ms', 'missouri': 'mo', 'montana': 'mt', 'nebraska': 'ne',
    'nevada': 'nv', 'new hampshire': 'nh', 'new jersey': 'nj', 'new mexico': 'nm',
    'new york': 'ny', 'north carolina': 'nc', 'north dakota': 'nd', 'ohio': 'oh',
    'oklahoma': 'ok', 'oregon': 'or', 'pennsylvania': 'pa', 'rhode island': 'ri',
    'south carolina': 'sc', 'south dakota': 'sd', 'tennessee': 'tn', 'texas': 'tx',
    'utah': 'ut', 'vermont': 'vt', 'virginia': 'va', 'washington': 'wa',
    'west virginia': 'wv', 'wisconsin': 'wi', 'wyoming': 'wy'
}
_READY_TO_SHIP_STATE_NAMES = {code: name for name, code in _READY_TO_SHIP_STATE_CODES.items()}

def _ready_to_ship_address_norm(value):
    tokens = []
    for token in _ready_to_ship_match_norm(value).split():
        tokens.append(_READY_TO_SHIP_ADDRESS_TOKEN_ALIASES.get(token, token))
    return ' '.join(tokens)

def _ready_to_ship_state_variants(value):
    norm = _ready_to_ship_match_norm(value)
    if not norm:
        return []
    variants = {norm}
    code = _READY_TO_SHIP_STATE_CODES.get(norm)
    if code:
        variants.add(code)
    name = _READY_TO_SHIP_STATE_NAMES.get(norm)
    if name:
        variants.add(name)
    return sorted(variants, key=len, reverse=True)

def _ready_to_ship_insert_unmatched_label(cur, filename, original_filename, size_bytes, extracted_text='', match_error='No address match found'):
    _ensure_ready_to_ship_unmatched_labels_table(cur)
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'
    cur.execute('''
        INSERT INTO ready_to_ship_unmatched_labels
            (label_filename, label_original_filename, label_size_bytes, label_uploaded_at, extracted_text, match_error)
        VALUES (?, ?, ?, ?, ?, ?)
    ''', (
        filename,
        original_filename,
        int(size_bytes or 0),
        now_iso,
        str(extracted_text or '')[:20000],
        str(match_error or '')[:500]
    ))
    return cur.execute('''
        SELECT id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at, match_error, created_at, updated_at
        FROM ready_to_ship_unmatched_labels
        WHERE id = ?
    ''', (cur.lastrowid,)).fetchone()

def _ready_to_ship_label_match_score(label_text, order_row):
    hay = _ready_to_ship_match_norm(label_text)
    hay_compact = _ready_to_ship_match_compact(label_text)
    hay_tokens = set(hay.split())
    hay_address = _ready_to_ship_address_norm(label_text)
    hay_address_compact = _ready_to_ship_match_compact(hay_address)
    hay_address_tokens = set(hay_address.split())
    if not hay:
        return 0, []

    def val(*keys):
        for key in keys:
            raw = _ready_to_ship_row_value(order_row, key, '')
            if str(raw or '').strip():
                return str(raw or '').strip()
        return ''

    name = val('shipping_name', 'buyer_name', 'name')
    street1 = val('shipping_street1', 'shipping_address1', 'street1', 'address1')
    street2 = val('shipping_street2', 'shipping_address2', 'street2', 'address2')
    city = val('shipping_city', 'city')
    state = val('shipping_state', 'state')
    postal = val('shipping_postal_code', 'shipping_zip', 'postal_code', 'zip')
    country = val('shipping_country', 'country')
    order_ref = val('order_id', 'legacy_order_id')
    store = val('store')
    is_amazon_order = _ready_to_ship_match_norm(store) == 'amazon'

    score = 0
    reasons = []

    order_ref_compact = _ready_to_ship_match_compact(order_ref)
    if order_ref_compact and len(order_ref_compact) >= 6 and order_ref_compact in hay_compact:
        score += 50 if len(order_ref_compact) >= 10 else 30
        reasons.append('order')

    postal_digits = re.sub(r'\D+', '', postal)
    postal_compact = _ready_to_ship_match_compact(postal)
    if postal_digits or postal_compact:
        variants = set()
        if postal_compact:
            variants.add(postal_compact)
            if len(postal_compact) >= 5:
                variants.add(postal_compact[:5])
        if postal_digits:
            variants.add(postal_digits)
            if len(postal_digits) >= 5:
                variants.add(postal_digits[:5])
        if len(postal_digits) >= 5:
            variants.add(postal_digits[:5])
        if any(v and len(v) >= 3 and v in hay_compact for v in variants):
            score += 34
            reasons.append('postal')

    street_norm = _ready_to_ship_address_norm(street1)
    street_compact = _ready_to_ship_match_compact(street_norm)
    if street_compact and street_compact in hay_address_compact:
        score += 38
        reasons.append('street')
    elif street_norm:
        street_tokens = street_norm.split()
        words = [
            w for w in street_tokens
            if len(w) > 2 and not w.isdigit() and w not in _READY_TO_SHIP_STREET_GENERIC_TOKENS
        ]
        street_number = next((w for w in street_tokens if re.search(r'\d', w)), '')
        word_hits = sum(1 for w in words if w in hay_address_tokens)
        if street_number and street_number in hay_address and word_hits >= 1:
            score += 32
            reasons.append('street')
        elif len(words) >= 2 and word_hits >= min(2, len(words)):
            score += 20
            reasons.append('street-ish')

    if street2:
        street2_norm = _ready_to_ship_address_norm(street2)
        if street2_norm and street2_norm in hay_address:
            score += 6
            reasons.append('street2')

    name_norm = _ready_to_ship_match_norm(name)
    name_words = [w for w in name_norm.split() if len(w) > 1]
    generic_name = name_norm in {'amazon buyer', 'ebay buyer', 'buyer', 'test customer'}
    name_is_missing_or_generic = (not name_norm) or generic_name
    if name_norm and not generic_name and _ready_to_ship_match_compact(name_norm) in hay_compact:
        score += 22
        reasons.append('name')
    elif name_words and not generic_name:
        name_hits = sum(1 for w in name_words if w in hay_tokens)
        if name_hits >= min(2, len(name_words)):
            score += 16
            reasons.append('name')
        elif len(name_words) >= 2 and name_words[-1] in hay_tokens:
            score += 8
            reasons.append('name-part')

    city_norm = _ready_to_ship_match_norm(city)
    city_tokens = [w for w in city_norm.split() if len(w) > 1]
    if city_norm and (city_norm in hay or (city_tokens and all(w in hay_tokens for w in city_tokens))):
        score += 10
        reasons.append('city')

    state_variants = _ready_to_ship_state_variants(state)
    if state_variants and any(re.search(rf'\b{re.escape(v)}\b', hay) for v in state_variants):
        score += 7
        reasons.append('state')

    country_norm = _ready_to_ship_match_norm(country)
    if country_norm and country_norm in hay:
        score += 3
        reasons.append('country')

    has_street_signal = 'street' in reasons or 'street-ish' in reasons
    if (
        is_amazon_order
        and name_is_missing_or_generic
        and 'postal' in reasons
        and ('city' in reasons or 'state' in reasons)
        and (not street_norm or has_street_signal)
    ):
        score += 8
        reasons.append('amazon-address')

    has_address_anchor = 'postal' in reasons and (
        'street' in reasons or 'street-ish' in reasons or 'name' in reasons or 'name-part' in reasons or 'city' in reasons
    )
    has_street_name = 'street' in reasons and ('name' in reasons or 'name-part' in reasons)
    has_order_anchor = 'order' in reasons and score >= 30
    has_amazon_address_anchor = 'amazon-address' in reasons
    if not (has_order_anchor or has_address_anchor or has_street_name or has_amazon_address_anchor or score >= 72):
        return 0, reasons
    return score, reasons

def _ready_to_ship_find_label_match(cur, label_text, days=2):
    try:
        days_int = max(1, min(int(days or 2), 120))
    except Exception:
        days_int = 2

    cur.execute('''
        SELECT *
        FROM orders
        WHERE paid_time >= date('now', '-' || ? || ' days')
        ORDER BY CASE WHEN COALESCE(TRIM(isHandled), '') = '1' THEN 1 ELSE 0 END,
                 paid_time DESC,
                 id DESC
    ''', (days_int,))

    best = None
    for row in cur.fetchall():
        score, reasons = _ready_to_ship_label_match_score(label_text, row)
        if score <= 0:
            continue
        if best is None or score > best['score']:
            best = {'order': row, 'score': score, 'reasons': reasons}

    return best

def _ready_to_ship_save_uploaded_label_file(file_storage):
    from werkzeug.utils import secure_filename

    original_name = secure_filename(file_storage.filename or 'label.pdf') or 'label.pdf'
    if not original_name.lower().endswith('.pdf'):
        raise ValueError('Only PDF label files are supported.')

    data = file_storage.read()
    if not data:
        raise ValueError('PDF file is empty.')
    if len(data) > 16 * 1024 * 1024:
        raise ValueError('PDF file is too large (max 16 MB).')
    if not data.lstrip().startswith(b'%PDF'):
        raise ValueError('That file does not look like a PDF.')

    filename = f"{datetime.datetime.utcnow().strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex}.pdf"
    path = _ready_to_ship_label_dir() / filename
    path.write_bytes(data)
    return filename, original_name, len(data), path

def _ready_to_ship_get_note_row(cur, order_id):
    return cur.execute('''
        SELECT order_row_id, note, label_filename, label_original_filename, label_size_bytes, label_uploaded_at, created_at, updated_at
        FROM ready_to_ship_notes
        WHERE order_row_id = ?
    ''', (order_id,)).fetchone()

def _ready_to_ship_get_order_label_rows(cur, order_id):
    _ensure_ready_to_ship_order_labels_table(cur)
    return cur.execute('''
        SELECT id, order_row_id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at, created_at, updated_at
        FROM ready_to_ship_order_labels
        WHERE order_row_id = ?
          AND COALESCE(TRIM(label_filename), '') <> ''
        ORDER BY datetime(label_uploaded_at) DESC, id DESC
    ''', (order_id,)).fetchall()

def _ready_to_ship_sync_legacy_label_columns(cur, order_id):
    _ensure_ready_to_ship_notes_table(cur)
    latest = cur.execute('''
        SELECT label_filename, label_original_filename, label_size_bytes, label_uploaded_at
        FROM ready_to_ship_order_labels
        WHERE order_row_id = ?
          AND COALESCE(TRIM(label_filename), '') <> ''
        ORDER BY datetime(label_uploaded_at) DESC, id DESC
        LIMIT 1
    ''', (order_id,)).fetchone()
    existing = cur.execute('SELECT * FROM ready_to_ship_notes WHERE order_row_id = ?', (order_id,)).fetchone()
    note_text = str(_ready_to_ship_row_value(existing, 'note', '') or '').strip() if existing else ''
    if latest:
        if existing:
            cur.execute('''
                UPDATE ready_to_ship_notes
                SET label_filename = ?,
                    label_original_filename = ?,
                    label_size_bytes = ?,
                    label_uploaded_at = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE order_row_id = ?
            ''', (
                str(_ready_to_ship_row_value(latest, 'label_filename', '') or '').strip(),
                str(_ready_to_ship_row_value(latest, 'label_original_filename', '') or '').strip(),
                int(_ready_to_ship_row_value(latest, 'label_size_bytes', 0) or 0),
                str(_ready_to_ship_row_value(latest, 'label_uploaded_at', '') or '').strip(),
                order_id
            ))
        else:
            cur.execute('''
                INSERT INTO ready_to_ship_notes
                    (order_row_id, note, label_filename, label_original_filename, label_size_bytes, label_uploaded_at)
                VALUES (?, '', ?, ?, ?, ?)
            ''', (
                order_id,
                str(_ready_to_ship_row_value(latest, 'label_filename', '') or '').strip(),
                str(_ready_to_ship_row_value(latest, 'label_original_filename', '') or '').strip(),
                int(_ready_to_ship_row_value(latest, 'label_size_bytes', 0) or 0),
                str(_ready_to_ship_row_value(latest, 'label_uploaded_at', '') or '').strip()
            ))
    elif existing:
        if note_text:
            cur.execute('''
                UPDATE ready_to_ship_notes
                SET label_filename = '',
                    label_original_filename = '',
                    label_size_bytes = 0,
                    label_uploaded_at = '',
                    updated_at = CURRENT_TIMESTAMP
                WHERE order_row_id = ?
            ''', (order_id,))
        else:
            cur.execute('DELETE FROM ready_to_ship_notes WHERE order_row_id = ?', (order_id,))

def _ready_to_ship_payload_for_order(cur, order_id):
    _ensure_ready_to_ship_notes_table(cur)
    _ensure_ready_to_ship_order_labels_table(cur)
    note_row = _ready_to_ship_get_note_row(cur, order_id)
    label_rows = _ready_to_ship_get_order_label_rows(cur, order_id)
    return _ready_to_ship_note_payload(note_row, label_rows)

def _ready_to_ship_attach_label(cur, order_id, filename, original_filename, size_bytes):
    _ensure_ready_to_ship_order_labels_table(cur)
    existing = cur.execute('SELECT * FROM ready_to_ship_notes WHERE order_row_id = ?', (order_id,)).fetchone()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'

    if existing:
        cur.execute('''
            UPDATE ready_to_ship_notes
            SET label_filename = ?,
                label_original_filename = ?,
                label_size_bytes = ?,
                label_uploaded_at = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE order_row_id = ?
        ''', (filename, original_filename, int(size_bytes or 0), now_iso, order_id))
    else:
        cur.execute('''
            INSERT INTO ready_to_ship_notes
                (order_row_id, note, label_filename, label_original_filename, label_size_bytes, label_uploaded_at)
            VALUES (?, '', ?, ?, ?, ?)
        ''', (order_id, filename, original_filename, int(size_bytes or 0), now_iso))

    cur.execute('''
        INSERT OR IGNORE INTO ready_to_ship_order_labels
            (order_row_id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at)
        VALUES (?, ?, ?, ?, ?)
    ''', (order_id, filename, original_filename, int(size_bytes or 0), now_iso))

    return _ready_to_ship_get_note_row(cur, order_id)

def _ensure_order_finder_matches_table(cur):
    """Persist the exact SEARCHRACK row chosen from finder.html for an order."""
    cur.execute('''
        CREATE TABLE IF NOT EXISTS order_finder_matches (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_row_id INTEGER NOT NULL UNIQUE,
            searchrack_id INTEGER NOT NULL,
            barcode TEXT,
            location TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_order_finder_matches_order ON order_finder_matches(order_row_id)')
    cur.execute('CREATE INDEX IF NOT EXISTS idx_order_finder_matches_searchrack ON order_finder_matches(searchrack_id)')

def _ready_to_ship_note_payload(note_row=None, label_rows=None):
    if not note_row:
        payload = {
            'ready_to_ship_note': '',
            'ready_to_ship_note_created_at': '',
            'ready_to_ship_note_updated_at': '',
            'has_ready_to_ship_note': False
        }
        payload.update(_ready_to_ship_label_payload(None, label_rows))
        return payload

    note_text = str(_ready_to_ship_row_value(note_row, 'note', '') or '')
    payload = {
        'ready_to_ship_note': note_text,
        'ready_to_ship_note_created_at': str(_ready_to_ship_row_value(note_row, 'created_at', '') or ''),
        'ready_to_ship_note_updated_at': str(_ready_to_ship_row_value(note_row, 'updated_at', '') or ''),
        'has_ready_to_ship_note': bool(note_text.strip())
    }
    payload.update(_ready_to_ship_label_payload(note_row, label_rows))
    return payload

def _apply_ready_to_ship_note_payload(order_dict, note_row=None, label_rows=None):
    payload = _ready_to_ship_note_payload(note_row, label_rows)
    order_dict.update(payload)
    return order_dict

def _load_ready_to_ship_note_lookup(cur, order_row_ids):
    ids = []
    seen = set()
    for raw_id in (order_row_ids or []):
        try:
            order_id = int(raw_id)
        except Exception:
            continue
        if order_id in seen:
            continue
        seen.add(order_id)
        ids.append(order_id)

    if not ids:
        return {}

    _ensure_ready_to_ship_notes_table(cur)
    placeholders = ','.join('?' for _ in ids)
    rows = cur.execute(f'''
        SELECT order_row_id, note, label_filename, label_original_filename, label_size_bytes, label_uploaded_at, created_at, updated_at
        FROM ready_to_ship_notes
        WHERE order_row_id IN ({placeholders})
    ''', ids).fetchall()

    lookup = {}
    for row in rows:
        try:
            lookup[int(row['order_row_id'])] = row
        except Exception:
            continue
    return lookup

def _load_ready_to_ship_label_lookup(cur, order_row_ids):
    ids = []
    seen = set()
    for raw_id in (order_row_ids or []):
        try:
            order_id = int(raw_id)
        except Exception:
            continue
        if order_id in seen:
            continue
        seen.add(order_id)
        ids.append(order_id)

    if not ids:
        return {}

    _ensure_ready_to_ship_order_labels_table(cur)
    placeholders = ','.join('?' for _ in ids)
    rows = cur.execute(f'''
        SELECT id, order_row_id, label_filename, label_original_filename, label_size_bytes, label_uploaded_at, created_at, updated_at
        FROM ready_to_ship_order_labels
        WHERE order_row_id IN ({placeholders})
          AND COALESCE(TRIM(label_filename), '') <> ''
        ORDER BY order_row_id, datetime(label_uploaded_at) DESC, id DESC
    ''', ids).fetchall()

    lookup = {}
    for row in rows:
        try:
            lookup.setdefault(int(row['order_row_id']), []).append(row)
        except Exception:
            continue
    return lookup

def _load_order_finder_match_lookup(cur, order_row_ids):
    ids = []
    seen = set()
    for raw_id in (order_row_ids or []):
        try:
            oid = int(raw_id)
        except Exception:
            continue
        if oid in seen:
            continue
        seen.add(oid)
        ids.append(oid)

    if not ids:
        return {}

    _ensure_order_finder_matches_table(cur)
    placeholders = ','.join('?' for _ in ids)
    rows = cur.execute(f'''
        SELECT order_row_id, searchrack_id, barcode, location, created_at, updated_at
        FROM order_finder_matches
        WHERE order_row_id IN ({placeholders})
    ''', ids).fetchall()

    lookup = {}
    for row in rows:
        try:
            lookup[int(row['order_row_id'])] = row
        except Exception:
            continue
    return lookup

def _sold_location_key(value):
    s = str(value or '').strip()
    if not s:
        return '__no_code__'
    return s.lower()

def _sold_location_label(value):
    s = str(value or '').strip()
    return s if s else '(No Code)'

def _sold_removal_barcode_key(value):
    return _normalize_upc_preserve_suffix_for_match(_normalize_upc(value))

def _sold_removal_barcode_variants(value):
    raw = _normalize_upc(value)
    key = _sold_removal_barcode_key(raw)
    variants = set()

    for candidate in (raw, key):
        s = str(candidate or '').strip()
        if s:
            variants.add(s)

    if key and '-' in key:
        base, suffix = key.split('-', 1)
        if base.isdigit():
            for width in (8, 11, 12, 13, 14):
                if len(base) < width:
                    variants.add(f"{base.zfill(width)}-{suffix}")
            # Include base-only variants: suffixed store SKUs (e.g. "035886267162-1")
            # must still match inventory stored under the plain base barcode.
            stripped_base = base.lstrip('0') or base
            variants.add(stripped_base)
            for width in (8, 11, 12, 13, 14):
                if len(stripped_base) < width:
                    variants.add(stripped_base.zfill(width))
    elif key and key.isdigit():
        for width in (8, 11, 12, 13, 14):
            if len(key) < width:
                variants.add(key.zfill(width))

    if raw and raw.isdigit():
        stripped = raw.lstrip('0') or '0'
        variants.add(stripped)
        for width in (8, 11, 12, 13, 14):
            if len(stripped) < width:
                variants.add(stripped.zfill(width))

    return {str(v).strip() for v in variants if str(v).strip()}

def _searchrack_removal_schema(cur):
    cur.execute("PRAGMA table_info('SEARCHRACK')")
    cols = [r[1] for r in cur.fetchall()]
    cols_lower = {c.lower(): c for c in cols}
    return {
        'id_col': cols_lower.get('id'),
        'barcode_col': cols_lower.get('barcode') or cols_lower.get('upc'),
        'qty_col': cols_lower.get('quantity') or cols_lower.get('qty'),
        'title_col': cols_lower.get('title'),
        'image_col': cols_lower.get('image') or cols_lower.get('images'),
        'custom_title_col': cols_lower.get('custom_title'),
        'pos_col': cols_lower.get('item_position') or cols_lower.get('itemposition') or cols_lower.get('position'),
        'pic_col': cols_lower.get('pictureposition'),
        'created_col': cols_lower.get('created_at')
    }

def _searchrack_matches_for_barcode(cur, barcode, schema=None, include_zero=False):
    schema = schema or _searchrack_removal_schema(cur)
    barcode_col = schema.get('barcode_col')
    qty_col = schema.get('qty_col')
    id_col = schema.get('id_col')
    title_col = schema.get('title_col')
    image_col = schema.get('image_col')
    custom_title_col = schema.get('custom_title_col')
    pos_col = schema.get('pos_col')
    pic_col = schema.get('pic_col')

    target_key = _sold_removal_barcode_key(barcode)
    if not target_key or not barcode_col:
        return []

    base_sql = f'''
        SELECT rowid AS _rowid_, *
        FROM SEARCHRACK
        WHERE {barcode_col} IS NOT NULL
          AND TRIM({barcode_col}) != ''
    '''

    variants = sorted(v.lower() for v in _sold_removal_barcode_variants(barcode))
    rows = []
    if variants:
        placeholders = ','.join('?' for _ in variants)
        cur.execute(base_sql + f" AND LOWER(TRIM({barcode_col})) IN ({placeholders})", tuple(variants))
        rows = [dict(r) for r in cur.fetchall()]
    else:
        cur.execute(base_sql)
        rows = [dict(r) for r in cur.fetchall()]

    # When the target barcode has a suffix (e.g. "35886267162-1"), also accept rows
    # whose stored barcode is the plain base (e.g. "035886267162") — covers the case
    # where eBay/Amazon SKUs are suffixed but inventory was scanned under the base UPC.
    _target_base_key = target_key.split('-', 1)[0] if target_key and '-' in target_key else None

    exact_matches = []
    exact_seen = False
    fallback_matches = []
    for row in rows:
        raw_barcode = str(row.get(barcode_col) or '').strip()
        row_key = _sold_removal_barcode_key(raw_barcode)
        is_exact = row_key == target_key
        is_base_fallback = bool(_target_base_key and row_key == _target_base_key)
        if not is_exact and not is_base_fallback:
            continue
        if is_exact:
            exact_seen = True

        qty = max(0, _coerce_int(row.get(qty_col) if qty_col else None, 0))
        if not include_zero and qty <= 0:
            continue

        raw_id = row.get(id_col) if id_col else row.get('_rowid_')
        try:
            row_id = int(raw_id)
        except Exception:
            continue

        item_position = str(row.get(pos_col) or '').strip() if pos_col else ''
        pictureposition = str(row.get(pic_col) or '').strip() if pic_col else ''
        location_code = item_position or pictureposition
        location_label = _sold_location_label(location_code)

        match = {
            'id': row_id,
            'barcode': raw_barcode,
            'title': str(row.get(title_col) or '').strip() if title_col else '',
            'image': str(row.get(image_col) or '').strip() if image_col else '',
            'custom_title': bool(_coerce_int(row.get(custom_title_col), 0)) if custom_title_col else False,
            'quantity': qty,
            'item_position': item_position,
            'pictureposition': pictureposition,
            'warehouse_note': str(row.get('WAREHOUSE_NOTE') or row.get('warehouse_note') or '').strip(),
            'location_code': location_label,
            'location_key': _sold_location_key(location_label),
            'location_preview': pictureposition or item_position or location_label
        }
        if is_exact:
            exact_matches.append(match)
        else:
            fallback_matches.append(match)

    matches = exact_matches if exact_seen else fallback_matches
    matches.sort(key=lambda m: (m.get('location_key') or '', int(m.get('id') or 0)))
    return matches


def _ready_to_ship_suffix_inventory_matches(cur, barcode, schema=None):
    """Return available SEARCHRACK rows whose barcode is a suffix variant."""
    schema = schema or _searchrack_removal_schema(cur)
    barcode_col = schema.get('barcode_col')
    base_barcode = _barcode_base_without_suffix(barcode)
    target_base_key = _sold_removal_barcode_key(base_barcode).split('-', 1)[0]
    if not barcode_col or not target_base_key:
        return []

    base_variants = {
        str(value or '').strip().lower()
        for value in _sold_removal_barcode_variants(base_barcode)
        if value and '-' not in str(value)
    }
    if not base_variants:
        return []

    where_bits = [f"LOWER(TRIM({barcode_col})) LIKE ?" for _ in base_variants]
    params = tuple(f"{value}-%" for value in sorted(base_variants))
    cur.execute(f'''
        SELECT DISTINCT TRIM({barcode_col}) AS barcode
        FROM SEARCHRACK
        WHERE {barcode_col} IS NOT NULL
          AND ({' OR '.join(where_bits)})
    ''', params)

    matches = []
    seen_ids = set()
    for row in cur.fetchall():
        candidate_barcode = str(row['barcode'] or '').strip()
        candidate_base_key = _sold_removal_barcode_key(
            _barcode_base_without_suffix(candidate_barcode)
        ).split('-', 1)[0]
        if candidate_base_key != target_base_key:
            continue
        for match in _searchrack_matches_for_barcode(
            cur, candidate_barcode, schema=schema, include_zero=False
        ):
            match_id = _coerce_int(match.get('id'), 0)
            if match_id and match_id not in seen_ids:
                seen_ids.add(match_id)
                matches.append(match)

    matches.sort(key=lambda match: (
        _sold_removal_barcode_key(match.get('barcode')),
        match.get('location_key') or '',
        _coerce_int(match.get('id'), 0)
    ))
    return matches


def _ready_to_ship_condition_is_new(order):
    raw = str((order or {}).get('item_condition') or (order or {}).get('condition') or '').strip()
    normalized = re.sub(r'[^a-z0-9]+', '_', raw.lower()).strip('_')
    return normalized in {'11', '1000', 'new_new', 'new', 'brand_new'}


def _ready_to_ship_valid_suffix_suggestion(order_barcode, suggested_barcode):
    order_key = _sold_removal_barcode_key(order_barcode)
    suggested_key = _sold_removal_barcode_key(suggested_barcode)
    if not order_key or not suggested_key or '-' not in suggested_key:
        return False
    return order_key.split('-', 1)[0] == suggested_key.split('-', 1)[0]


def _ready_to_ship_valid_requested_match(order, suggested_barcode):
    suggested = str(suggested_barcode or '').strip()
    order_barcode = _effective_sold_order_barcode(order, prefer_manual_override=True)
    if _ready_to_ship_valid_suffix_suggestion(order_barcode, suggested):
        return True
    mapping = _listing_inventory_match_for_order(order)
    mapped_barcode = str((mapping or {}).get('inventory_barcode') or '').strip()
    return bool(
        suggested
        and mapped_barcode
        and _sold_removal_barcode_key(suggested) == _sold_removal_barcode_key(mapped_barcode)
    )


def _ready_to_ship_suffix_alternatives(matches, selected_barcode=''):
    selected_key = _sold_removal_barcode_key(selected_barcode)
    grouped = {}
    for match in matches or []:
        barcode = str((match or {}).get('barcode') or '').strip()
        barcode_key = _sold_removal_barcode_key(barcode)
        if not barcode_key or barcode_key == selected_key:
            continue
        bucket = grouped.setdefault(barcode_key, {
            'barcode': barcode,
            'quantity': 0,
            'locations': []
        })
        bucket['quantity'] += max(0, _coerce_int((match or {}).get('quantity'), 0))
        location = _ready_to_ship_match_display_location(match)
        if location and location not in bucket['locations']:
            bucket['locations'].append(location)
    return sorted(grouped.values(), key=lambda item: _sold_removal_barcode_key(item.get('barcode')))


def _searchrack_matches_for_removal_context(cur, barcode, *, fallback_barcodes=None, preferred_location=''):
    """Find removable inventory using the same fallbacks as Ready to Ship location lookup."""
    schema = _searchrack_removal_schema(cur)
    seen_barcode_keys = set()

    def _seen_key(value):
        return str(_normalize_upc_preserve_suffix_for_match(value) or '').strip().lower()

    def _try_barcode(value):
        raw = str(value or '').strip()
        key = _seen_key(raw)
        if not raw or not key or key in seen_barcode_keys:
            return []
        seen_barcode_keys.add(key)

        found = _searchrack_matches_for_barcode(cur, raw, schema=schema, include_zero=False)
        if found:
            return found

        base_barcode = _barcode_base_without_suffix(raw)
        base_key = _seen_key(base_barcode)
        if base_barcode and base_key and base_key != key and base_key not in seen_barcode_keys:
            seen_barcode_keys.add(base_key)
            return _searchrack_matches_for_barcode(cur, base_barcode, schema=schema, include_zero=False)
        return []

    candidates = [barcode]
    for fallback in (fallback_barcodes or []):
        if str(fallback or '').strip():
            candidates.append(fallback)

    for candidate in candidates:
        matches = _try_barcode(candidate)
        if matches:
            return matches

    location = str(preferred_location or '').strip()
    qty_col = schema.get('qty_col')
    barcode_col = schema.get('barcode_col')
    pos_col = schema.get('pos_col')
    pic_col = schema.get('pic_col')
    location_cols = []
    for col in (pos_col, pic_col):
        if col and col not in location_cols:
            location_cols.append(col)
    if not location or not qty_col or not barcode_col or not location_cols:
        return []

    try:
        where_bits = [f"LOWER(TRIM(COALESCE({col}, ''))) = LOWER(TRIM(?))" for col in location_cols]
        cur.execute(
            f"""
            SELECT rowid AS _rowid_, *
            FROM SEARCHRACK
            WHERE ({' OR '.join(where_bits)})
              AND COALESCE({qty_col}, 0) > 0
            """,
            tuple(location for _ in location_cols)
        )
        location_rows = cur.fetchall()
    except Exception:
        return []

    if not location_rows:
        return []

    order_variant_keys = set()
    for candidate in candidates:
        order_variant_keys.update(
            _sold_removal_barcode_key(v)
            for v in _sold_removal_barcode_variants(candidate)
            if str(v or '').strip()
        )
    order_variant_keys.discard('')

    chosen_barcode = ''
    for row in location_rows:
        row_dict = dict(row)
        row_barcode = str(row_dict.get(barcode_col) or '').strip()
        if row_barcode and _sold_removal_barcode_key(row_barcode) in order_variant_keys:
            chosen_barcode = row_barcode
            break
    if not chosen_barcode:
        for row in location_rows:
            row_dict = dict(row)
            row_barcode = str(row_dict.get(barcode_col) or '').strip()
            if row_barcode:
                chosen_barcode = row_barcode
                break

    if not chosen_barcode:
        return []

    found = _searchrack_matches_for_barcode(cur, chosen_barcode, schema=schema, include_zero=False)
    if found:
        return found

    base_barcode = _barcode_base_without_suffix(chosen_barcode)
    if base_barcode and _seen_key(base_barcode) != _seen_key(chosen_barcode):
        return _searchrack_matches_for_barcode(cur, base_barcode, schema=schema, include_zero=False)
    return []

def _ready_to_ship_searchrack_match_from_row(row, schema):
    row_dict = dict(row)
    id_col = schema.get('id_col')
    barcode_col = schema.get('barcode_col')
    qty_col = schema.get('qty_col')
    title_col = schema.get('title_col')
    image_col = schema.get('image_col')
    custom_title_col = schema.get('custom_title_col')
    pos_col = schema.get('pos_col')
    pic_col = schema.get('pic_col')
    note_col = None
    for candidate in ('WAREHOUSE_NOTE', 'warehouse_note'):
        if candidate in row_dict:
            note_col = candidate
            break

    raw_id = row_dict.get(id_col) if id_col else row_dict.get('_rowid_')
    try:
        row_id = int(raw_id)
    except Exception:
        return None

    item_position = str(row_dict.get(pos_col) or '').strip() if pos_col else ''
    pictureposition = str(row_dict.get(pic_col) or '').strip() if pic_col else ''
    location_code = item_position or pictureposition
    location_label = _sold_location_label(location_code)

    return {
        'id': row_id,
        'barcode': str(row_dict.get(barcode_col) or '').strip() if barcode_col else '',
        'title': str(row_dict.get(title_col) or '').strip() if title_col else '',
        'image': str(row_dict.get(image_col) or '').strip() if image_col else '',
        'custom_title': bool(_coerce_int(row_dict.get(custom_title_col), 0)) if custom_title_col else False,
        'quantity': max(0, _coerce_int(row_dict.get(qty_col) if qty_col else None, 0)),
        'item_position': item_position,
        'pictureposition': pictureposition,
        'warehouse_note': str(row_dict.get(note_col) or '').strip() if note_col else '',
        'location_code': location_label,
        'location_key': _sold_location_key(location_label),
        'location_preview': pictureposition or item_position or location_label
    }


def _ready_to_ship_rank_inventory_matches(matches, order):
    """Prefer the same-barcode warehouse row whose custom identity matches the sold item."""
    order_title = ' '.join(str((order or {}).get('title') or '').casefold().split())
    order_image = str((order or {}).get('image') or (order or {}).get('image_url') or '').strip().casefold()

    def _image_key(value):
        raw = str(value or '').strip().casefold().split('?', 1)[0].rstrip('/')
        return raw.rsplit('/', 1)[-1] if raw else ''

    order_image_key = _image_key(order_image)

    def _score(match):
        match_title = ' '.join(str((match or {}).get('title') or '').casefold().split())
        match_image = str((match or {}).get('image') or '').strip().casefold()
        match_image_key = _image_key(match_image)
        title_exact = bool(order_title and match_title and order_title == match_title)
        image_exact = bool(
            order_image and match_image
            and (order_image == match_image or (order_image_key and order_image_key == match_image_key))
        )
        custom = bool((match or {}).get('custom_title'))
        return (
            1 if title_exact and image_exact else 0,
            1 if title_exact else 0,
            1 if image_exact else 0,
            1 if custom and (title_exact or image_exact) else 0,
            1 if custom else 0,
            max(0, _coerce_int((match or {}).get('id'), 0)),
        )

    return sorted(list(matches or []), key=_score, reverse=True)

def _ready_to_ship_match_display_location(match):
    item_position = str((match or {}).get('item_position') or '').strip()
    pictureposition = str((match or {}).get('pictureposition') or '').strip()
    if pictureposition and item_position.lower() in ('', 'picture'):
        return pictureposition
    return item_position or pictureposition or str((match or {}).get('location_code') or '').strip()

def _ready_to_ship_searchrack_match_by_id(cur, searchrack_id, schema=None):
    try:
        row_id = int(searchrack_id)
    except Exception:
        return None
    if row_id <= 0:
        return None

    schema = schema or _searchrack_removal_schema(cur)
    id_col = schema.get('id_col')

    def _ident(name):
        return '"' + str(name).replace('"', '""') + '"'

    lookup_expr = _ident(id_col) if id_col else 'rowid'

    try:
        cur.execute(
            f"SELECT rowid AS _rowid_, * FROM SEARCHRACK WHERE {lookup_expr} = ? LIMIT 1",
            (row_id,)
        )
        row = cur.fetchone()
    except Exception:
        return None
    if not row:
        return None
    match = _ready_to_ship_searchrack_match_from_row(row, schema)
    if not match or max(0, _coerce_int(match.get('quantity'), 0)) <= 0:
        return None
    return match

def _ready_to_ship_match_location_equals(match, location):
    wanted = _sold_location_key(location)
    if not location or wanted == '__no_code__':
        return False
    for key in ('location_key', 'location_code', 'item_position', 'pictureposition', 'location_preview'):
        value = match.get(key)
        if key == 'location_key':
            if str(value or '').strip().lower() == wanted:
                return True
        elif _sold_location_key(value) == wanted:
            return True
    return False

def _ready_to_ship_resolve_searchrack_location_match(cur, barcode, location, fallback_barcodes=None):
    """Best-effort resolver for older Finder locks that predate stored SEARCHRACK row ids."""
    location = str(location or '').strip()
    schema = _searchrack_removal_schema(cur)
    candidates = []
    for value in [barcode] + list(fallback_barcodes or []):
        raw = str(value or '').strip()
        if raw:
            candidates.append(raw)

    candidate_keys = set()
    seen_candidate_keys = set()
    for candidate in candidates:
        candidate_key = str(_normalize_upc_preserve_suffix_for_match(candidate) or '').strip().lower()
        if not candidate_key or candidate_key in seen_candidate_keys:
            continue
        seen_candidate_keys.add(candidate_key)
        for variant in _sold_removal_barcode_variants(candidate):
            variant_key = _sold_removal_barcode_key(variant)
            if variant_key:
                candidate_keys.add(variant_key)

        matches = _searchrack_matches_for_barcode(cur, candidate, schema=schema, include_zero=False)
        if location:
            exact = next((m for m in matches if _ready_to_ship_match_location_equals(m, location)), None)
            if exact:
                return exact
        elif len(matches) == 1:
            return matches[0]

        base_barcode = _barcode_base_without_suffix(candidate)
        base_key = str(_normalize_upc_preserve_suffix_for_match(base_barcode) or '').strip().lower()
        if base_barcode and base_key and base_key != candidate_key and base_key not in seen_candidate_keys:
            seen_candidate_keys.add(base_key)
            base_matches = _searchrack_matches_for_barcode(cur, base_barcode, schema=schema, include_zero=False)
            if location:
                exact = next((m for m in base_matches if _ready_to_ship_match_location_equals(m, location)), None)
                if exact:
                    return exact
            elif len(base_matches) == 1:
                return base_matches[0]

    if not location:
        return None

    qty_col = schema.get('qty_col')
    barcode_col = schema.get('barcode_col')
    pos_col = schema.get('pos_col')
    pic_col = schema.get('pic_col')
    location_cols = []
    for col in (pos_col, pic_col):
        if col and col not in location_cols:
            location_cols.append(col)
    if not location_cols:
        return None

    def _ident(name):
        return '"' + str(name).replace('"', '""') + '"'

    try:
        where_bits = [f"LOWER(TRIM(COALESCE({_ident(col)}, ''))) = LOWER(TRIM(?))" for col in location_cols]
        cur.execute(
            f"""
            SELECT rowid AS _rowid_, *
            FROM SEARCHRACK
            WHERE {' OR '.join(where_bits)}
            """,
            tuple(location for _ in location_cols)
        )
        location_rows = cur.fetchall()
    except Exception:
        return None

    matches = []
    for row in location_rows:
        match = _ready_to_ship_searchrack_match_from_row(row, schema)
        if match:
            matches.append(match)

    if not matches:
        return None

    if candidate_keys and barcode_col:
        exact_barcode = next(
            (m for m in matches if _sold_removal_barcode_key(m.get('barcode')) in candidate_keys),
            None
        )
        if exact_barcode:
            return exact_barcode

    if len(matches) == 1:
        return matches[0]
    return None

def _group_searchrack_matches_by_location(matches):
    groups = {}
    for row in (matches or []):
        loc_key = _sold_location_key(row.get('location_key') or row.get('location_code'))
        bucket = groups.get(loc_key)
        if bucket is None:
            bucket = {
                'location_key': loc_key,
                'location_code': _sold_location_label(row.get('location_code')),
                'preview_key': str(row.get('location_preview') or row.get('location_code') or '').strip(),
                'available_qty': 0,
                'rows': []
            }
            groups[loc_key] = bucket
        bucket['available_qty'] += max(0, _coerce_int(row.get('quantity'), 0))
        bucket['rows'].append(row)

    out = []
    for bucket in groups.values():
        bucket['rows'].sort(key=lambda r: int(r.get('id') or 0))
        out.append(bucket)
    out.sort(key=lambda g: str(g.get('location_code') or '').lower())
    return out

def _serialize_prep_location_entry(group):
    """Convert a grouped SEARCHRACK location bucket into a lightweight API payload."""
    group = group or {}
    rows = list(group.get('rows') or [])
    first_row = rows[0] if rows else {}
    clear_target_row_id = None
    for row in rows:
        try:
            clear_target_row_id = int(row.get('id'))
            break
        except Exception:
            continue

    location_code = _sold_location_label(group.get('location_code') or first_row.get('location_code') or '')
    preview_key = str(
        group.get('preview_key')
        or first_row.get('location_preview')
        or first_row.get('pictureposition')
        or first_row.get('item_position')
        or location_code
        or ''
    ).strip()

    return {
        'location_key': str(group.get('location_key') or _sold_location_key(location_code)).strip(),
        'location_code': location_code,
        'preview_key': preview_key,
        'available_qty': max(0, _coerce_int(group.get('available_qty'), 0)),
        'clear_target_row_id': clear_target_row_id,
        'clearable': clear_target_row_id is not None
    }

def _prep_history_inventory_fallback(base_upc):
    """Collect live inventory rows for a base UPC so prep history can fall back to warehouse locations."""
    base_key = _sold_removal_barcode_key(base_upc)
    if not base_key:
        return {}

    out = {}
    try:
        with db_connection('searchRack.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            schema = _searchrack_removal_schema(cur)
            id_col = schema.get('id_col')
            barcode_col = schema.get('barcode_col')
            qty_col = schema.get('qty_col')
            title_col = schema.get('title_col') or "''"
            pos_col = schema.get('pos_col') or "''"
            pic_col = schema.get('pic_col') or "''"
            created_col = schema.get('created_col') or "''"
            if not barcode_col or not qty_col:
                return {}
            id_expr = id_col or 'rowid'

            variants = sorted(str(v).strip().lower() for v in _sold_removal_barcode_variants(base_key) if str(v).strip())
            if not variants:
                return {}

            exact_clause = f"LOWER(TRIM({barcode_col})) IN ({','.join('?' for _ in variants)})"
            like_patterns = []
            for variant in variants:
                safe_variant = variant.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
                like_patterns.append(f'{safe_variant}-%')
            like_clause = ' OR '.join(
                f"LOWER(TRIM({barcode_col})) LIKE ? ESCAPE '\\'" for _ in like_patterns
            )

            sql = f'''
                SELECT COALESCE({id_expr}, rowid) AS searchrack_id,
                       COALESCE({barcode_col}, '') AS barcode,
                       COALESCE({title_col}, '') AS title,
                       COALESCE({pos_col}, '') AS item_position,
                       COALESCE({pic_col}, '') AS pictureposition,
                       COALESCE({qty_col}, 0) AS quantity,
                       COALESCE({created_col}, '') AS created_at
                FROM SEARCHRACK
                WHERE ({exact_clause}{(' OR ' + like_clause) if like_clause else ''})
                  AND COALESCE({qty_col}, 0) > 0
            '''
            params = list(variants) + like_patterns
            cur.execute(sql, tuple(params))
            rows = cur.fetchall()
    except Exception:
        return {}

    for row in rows:
        raw_barcode = str(row['barcode'] or '').strip()
        barcode_key = _sold_removal_barcode_key(raw_barcode)
        if not raw_barcode or not barcode_key:
            continue

        qty = max(0, _coerce_int(row['quantity'], 0))
        if qty <= 0:
            continue
        row_id = max(0, _coerce_int(row['searchrack_id'], 0))

        bucket = out.get(barcode_key)
        if bucket is None:
            bucket = {
                'upc': raw_barcode,
                'title': str(row['title'] or '').strip(),
                'updated_at': str(row['created_at'] or '').strip(),
                'quantity': 0,
                'row_ids': [],
                'locations': {}
            }
            out[barcode_key] = bucket
        elif not bucket.get('title'):
            bucket['title'] = str(row['title'] or '').strip()

        created_at = str(row['created_at'] or '').strip()
        if created_at and (not bucket.get('updated_at') or created_at > bucket['updated_at']):
            bucket['updated_at'] = created_at
        bucket['quantity'] += qty
        if row_id > 0 and row_id not in bucket['row_ids']:
            bucket['row_ids'].append(row_id)

        item_position = str(row['item_position'] or '').strip()
        pictureposition = str(row['pictureposition'] or '').strip()
        location_raw = item_position or pictureposition
        if not location_raw:
            continue

        location_label = _sold_location_label(location_raw)
        location_key = _sold_location_key(location_label)
        location_bucket = bucket['locations'].get(location_key)
        if location_bucket is None:
            location_bucket = {
                'location_code': location_label,
                'preview_key': pictureposition or item_position or location_label,
                'available_qty': 0,
                'row_ids': [],
                'clear_target_row_id': row_id or None,
                'clearable': row_id > 0
            }
            bucket['locations'][location_key] = location_bucket
        location_bucket['available_qty'] += qty
        if row_id > 0 and row_id not in location_bucket['row_ids']:
            location_bucket['row_ids'].append(row_id)
        if row_id > 0 and not location_bucket.get('clear_target_row_id'):
            location_bucket['clear_target_row_id'] = row_id
            location_bucket['clearable'] = True

    final = {}
    for barcode_key, bucket in out.items():
        locations = list(bucket.get('locations', {}).values())
        locations.sort(key=lambda loc: str(loc.get('location_code') or '').lower())
        final[barcode_key] = {
            'upc': bucket.get('upc') or '',
            'title': bucket.get('title') or '',
            'updated_at': bucket.get('updated_at') or '',
            'quantity': max(0, _coerce_int(bucket.get('quantity'), 0)),
            'row_ids': list(bucket.get('row_ids') or []),
            'locations': locations
        }
    return final

def _prep_history_inventory_bucket_for_upc(upc):
    """Resolve the live-inventory fallback bucket for this exact UPC key only."""
    upc_key = _sold_removal_barcode_key(upc)
    if not upc_key:
        return {}
    inventory_map = _prep_history_inventory_fallback(upc)
    return inventory_map.get(upc_key) or {}

def _prep_select_inventory_match(upc, preferred_location='', preferred_preview=''):
    """Pick a single live inventory row for a UPC, preferring an explicit location/picture match."""
    try:
        with db_connection('searchRack.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            schema = _searchrack_removal_schema(cur)
            matches = _searchrack_matches_for_barcode(cur, upc, schema=schema, include_zero=False)
    except Exception:
        return {'match': None, 'location_groups': [], 'clearable': False, 'ambiguous': False}

    target_key = _sold_removal_barcode_key(upc)
    if target_key:
        matches = [
            row for row in matches
            if _sold_removal_barcode_key(row.get('barcode')) == target_key
        ]

    location_groups = _group_searchrack_matches_by_location(matches)
    pref_values = {
        str(v or '').strip().lower()
        for v in (preferred_location, preferred_preview)
        if str(v or '').strip()
    }

    def _row_matches_pref(row):
        if not pref_values:
            return False
        candidates = {
            str(row.get('location_key') or '').strip().lower(),
            str(row.get('location_code') or '').strip().lower(),
            str(row.get('item_position') or '').strip().lower(),
            str(row.get('pictureposition') or '').strip().lower(),
            str(row.get('location_preview') or '').strip().lower()
        }
        candidates.discard('')
        return bool(candidates & pref_values)

    preferred_matches = [row for row in matches if _row_matches_pref(row)]
    if preferred_matches:
        preferred_matches.sort(key=lambda r: (str(r.get('location_key') or ''), int(r.get('id') or 0)))
        return {
            'match': preferred_matches[0],
            'location_groups': location_groups,
            'clearable': True,
            'ambiguous': False
        }

    if len(matches) == 1 or len(location_groups) == 1:
        chosen = matches[0] if matches else None
        return {
            'match': chosen,
            'location_groups': location_groups,
            'clearable': bool(chosen),
            'ambiguous': False
        }

    return {
        'match': None,
        'location_groups': location_groups,
        'clearable': False,
        'ambiguous': len(location_groups) > 1
    }

def _clear_searchrack_row_location(row_id):
    """Remove exactly one unit from the selected SEARCHRACK row/location."""
    if row_id is None or str(row_id).strip() == '':
        return {'success': False, 'error': 'Missing inventory row id'}

    conn = None
    rem_conn = None
    try:
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        _reconcile_inventory_age_batches(conn)
        cur = conn.cursor()
        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        cols_lower = {c.lower(): c for c in cols}
        id_col = cols_lower.get('id')
        id_lookup_col = id_col or 'rowid'
        barcode_col = cols_lower.get('barcode') or cols_lower.get('upc')
        title_col = cols_lower.get('title')
        qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
        pos_col = cols_lower.get('item_position') or cols_lower.get('itemposition') or cols_lower.get('position')
        pic_col = cols_lower.get('pictureposition')
        if not qty_col:
            return {'success': False, 'error': 'Inventory quantity column not found'}

        cur.execute(f"SELECT rowid AS _rowid_, * FROM SEARCHRACK WHERE {id_lookup_col} = ?", (row_id,))
        existing = cur.fetchone()
        if not existing:
            return {'success': False, 'error': 'Inventory row not found'}

        row = dict(existing)
        barcode = str(row.get(barcode_col) or '').strip() if barcode_col else ''
        title = str(row.get(title_col) or '').strip() if title_col else ''
        current_qty = max(0, _coerce_int(row.get(qty_col) if qty_col else None, 1))
        if current_qty <= 0:
            return {'success': False, 'error': 'Inventory row has no quantity'}

        item_position = str(row.get(pos_col) or '').strip() if pos_col else ''
        pictureposition = str(row.get(pic_col) or '').strip() if pic_col else ''
        source_location = pictureposition if (pictureposition and item_position.lower() in ('', 'picture')) else (item_position or pictureposition)
        if not source_location:
            return {'success': True, 'row_id': int(row_id), 'source_location': '', 'quantity_cleared': 0}

        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        try:
            rem_cur.execute("PRAGMA table_info(removed_items)")
            rem_cols = [c[1] for c in rem_cur.fetchall()]
            if 'item_position' not in rem_cols:
                rem_cur.execute('ALTER TABLE removed_items ADD COLUMN item_position TEXT')
        except Exception:
            pass

        now = datetime.datetime.now().isoformat()
        new_qty = max(0, current_qty - 1)
        if qty_col:
            cur.execute(
                f"UPDATE SEARCHRACK SET {qty_col} = ? WHERE {id_lookup_col} = ?",
                (new_qty, row_id)
            )
        _inventory_age_consume_fifo(cur, row_id, 1)

        rem_cur.execute('''
            INSERT INTO removed_items
            (order_id, barcode, title, quantity_removed, removed_at, searchrack_id,
             old_quantity, new_quantity, removal_type, item_position, event_status)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')
        ''', (None, barcode, title, 1, now, row_id, current_qty, new_qty, 'locationcleared', source_location))

        rem_conn.commit()
        conn.commit()
        try:
            _invalidate_searchrack_cache()
            update_data_version()
        except Exception:
            pass
        return {'success': True, 'row_id': int(row_id), 'source_location': source_location, 'quantity_cleared': 1}
    except Exception as e:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.rollback()
        except Exception:
            pass
        return {'success': False, 'error': _safe_error(e)}
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.close()
        except Exception:
            pass

def _items_prep_delete_legacy_inventory_entry(*, upc, qty=1, row_ids=None):
    """Remove a live SEARCHRACK fallback row shown as an older prep-history entry."""
    target_key = _sold_removal_barcode_key(upc)
    if not target_key:
        return {'success': False, 'error': 'Missing upc', 'status_code': 400}

    qty_n = _strict_inventory_quantity(qty if qty is not None else 1)
    if qty_n is None or qty_n < 1:
        return {'success': False, 'error': 'Quantity must be a positive whole number', 'status_code': 400}

    raw_ids = row_ids if isinstance(row_ids, (list, tuple)) else ([row_ids] if row_ids not in (None, '') else [])
    wanted_ids = []
    for raw_id in raw_ids:
        try:
            row_id = int(raw_id)
        except Exception:
            continue
        if row_id > 0 and row_id not in wanted_ids:
            wanted_ids.append(row_id)

    def _ident(name):
        return '"' + str(name).replace('"', '""') + '"'

    rack_conn = None
    rem_conn = None
    zero_qty_row_ids = []
    try:
        rack_conn = sqlite3.connect('searchRack.db', isolation_level='IMMEDIATE')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        schema = _searchrack_removal_schema(rack_cur)
        id_col = schema.get('id_col')
        qty_col = schema.get('qty_col')
        if not qty_col:
            return {'success': False, 'error': 'Inventory quantity column not found', 'status_code': 500}

        id_lookup_expr = _ident(id_col) if id_col else 'rowid'
        qty_expr = _ident(qty_col)
        candidates = []

        if wanted_ids:
            placeholders = ','.join('?' for _ in wanted_ids)
            rack_cur.execute(
                f"SELECT rowid AS _rowid_, * FROM SEARCHRACK WHERE {id_lookup_expr} IN ({placeholders})",
                tuple(wanted_ids)
            )
            for row in rack_cur.fetchall():
                match = _ready_to_ship_searchrack_match_from_row(row, schema)
                if match:
                    candidates.append(match)

        if not candidates:
            candidates = _searchrack_matches_for_barcode(rack_cur, upc, schema=schema, include_zero=False)

        matches = []
        seen_ids = set()
        for match in candidates:
            row_id = max(0, _coerce_int(match.get('id'), 0))
            if row_id <= 0 or row_id in seen_ids:
                continue
            if _sold_removal_barcode_key(match.get('barcode')) != target_key:
                continue
            if max(0, _coerce_int(match.get('quantity'), 0)) <= 0:
                continue
            seen_ids.add(row_id)
            matches.append(match)

        matches.sort(key=lambda m: (str(m.get('location_key') or ''), int(m.get('id') or 0)))
        available_qty = sum(max(0, _coerce_int(match.get('quantity'), 0)) for match in matches)
        if available_qty <= 0:
            return {'success': False, 'error': 'No matching live inventory was found for this older entry', 'status_code': 404}
        if available_qty < qty_n:
            return {
                'success': False,
                'error': f'Only {available_qty} unit(s) are available to delete for this older entry',
                'status_code': 409
            }

        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)
        now_iso = datetime.datetime.now().isoformat()
        remaining = qty_n
        removed_rows = []

        for match in matches:
            if remaining <= 0:
                break
            row_id = int(match.get('id') or 0)
            current_qty = max(0, _coerce_int(match.get('quantity'), 0))
            if row_id <= 0 or current_qty <= 0:
                continue
            take_qty = min(current_qty, remaining)
            new_qty = current_qty - take_qty
            rack_cur.execute(
                f'UPDATE SEARCHRACK SET {qty_expr} = ? WHERE {id_lookup_expr} = ?',
                (new_qty, row_id)
            )
            if rack_cur.rowcount == 0:
                raise RuntimeError(f'Inventory row {row_id} changed before delete could complete')

            location = _sold_location_label(
                match.get('location_code') or
                match.get('item_position') or
                match.get('pictureposition') or
                ''
            )
            rem_cur.execute('''
                INSERT INTO removed_items
                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id,
                 old_quantity, new_quantity, removal_type, item_position, event_status)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')
            ''', (
                None,
                str(match.get('barcode') or upc).strip(),
                str(match.get('title') or '').strip(),
                take_qty,
                now_iso,
                row_id,
                current_qty,
                new_qty,
                'prep_history_delete',
                location
            ))
            removed_rows.append({
                'searchrack_id': row_id,
                'from_qty': current_qty,
                'to_qty': new_qty,
                'quantity_removed': take_qty,
                'location_code': location
            })
            if new_qty <= 0:
                zero_qty_row_ids.append(row_id)
            remaining -= take_qty

        if remaining > 0:
            raise RuntimeError('Inventory changed before all requested quantity could be removed')

        rem_conn.commit()
        rack_conn.commit()
        for row_id in zero_qty_row_ids:
            try:
                _clear_zero_qty_pending_deletions(row_id)
            except Exception:
                pass
        try:
            _invalidate_searchrack_cache()
            update_data_version()
        except Exception:
            pass
        return {
            'success': True,
            'upc': str(upc or '').strip(),
            'requested_qty': qty_n,
            'removed_qty': qty_n,
            'removed_rows': removed_rows
        }
    except Exception as e:
        try:
            if rack_conn is not None:
                rack_conn.rollback()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.rollback()
        except Exception:
            pass
        return {
            'success': False,
            'error': _safe_error(e, 'items_prep:legacy_inventory_delete'),
            'status_code': 500
        }
    finally:
        try:
            if rack_conn is not None:
                rack_conn.close()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.close()
        except Exception:
            pass

def _load_order_removal_allocations(cur, order_row_id):
    _ensure_order_removal_allocations_table(cur)
    cur.execute('''
        SELECT location_key, location_code, quantity
        FROM order_removal_allocations
        WHERE order_row_id = ?
        ORDER BY id ASC
    ''', (order_row_id,))
    rows = cur.fetchall()
    out = []
    for r in rows:
        location_code = _sold_location_label(r['location_code'] if isinstance(r, sqlite3.Row) else r[1])
        location_key_raw = (r['location_key'] if isinstance(r, sqlite3.Row) else r[0]) or location_code
        qty_raw = (r['quantity'] if isinstance(r, sqlite3.Row) else r[2])
        qty = max(0, _coerce_int(qty_raw, 0))
        if qty <= 0:
            continue
        out.append({
            'location_key': _sold_location_key(location_key_raw),
            'location_code': location_code,
            'quantity': qty
        })
    return out

def _save_order_removal_allocations(cur, order_row_id, allocations):
    _ensure_order_removal_allocations_table(cur)
    cur.execute('DELETE FROM order_removal_allocations WHERE order_row_id = ?', (order_row_id,))
    for alloc in (allocations or []):
        qty = max(0, _coerce_int(alloc.get('quantity'), 0))
        if qty <= 0:
            continue
        location_code = _sold_location_label(alloc.get('location_code'))
        location_key = _sold_location_key(alloc.get('location_key') or location_code)
        cur.execute('''
            INSERT INTO order_removal_allocations (order_row_id, location_key, location_code, quantity)
            VALUES (?, ?, ?, ?)
        ''', (order_row_id, location_key, location_code, qty))


def _marketplace_lookup_rawbol_item(barcode):
    variants = _marketplace_upc_lookup_variants(barcode)
    if not variants:
        return None

    conn = None
    try:
        conn = sqlite3.connect('rawbol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        placeholders = ','.join('?' for _ in variants)
        cur.execute(f'''
            SELECT rowid AS _rowid_, upc, item_description, image_url
            FROM raw_bol_items
            WHERE upc IS NOT NULL
              AND TRIM(upc) != ''
              AND LOWER(TRIM(upc)) IN ({placeholders})
            ORDER BY rowid DESC
        ''', tuple(variants))
        rows = cur.fetchall()
        if not rows:
            return None

        target = str(_normalize_upc(barcode) or '').strip().lower()

        def _score(row):
            raw_upc = str(row['upc'] or '').strip().lower()
            exact = 1 if raw_upc == target else 0
            return (exact, int(row['_rowid_'] or 0))

        best = max(rows, key=_score)
        return {
            'upc': str(best['upc'] or '').strip(),
            'title': str(best['item_description'] or '').strip(),
            'image_url': str(best['image_url'] or '').strip(),
        }
    except Exception:
        return None
    finally:
        if conn is not None:
            conn.close()


def _normalize_marketplace_allocations(incoming_allocations):
    grouped = {}
    if not isinstance(incoming_allocations, list):
        return []
    for alloc in incoming_allocations:
        if not isinstance(alloc, dict):
            continue
        qty = max(0, _coerce_int(alloc.get('quantity', alloc.get('qty')), 0))
        if qty <= 0:
            continue
        location_code = _sold_location_label(alloc.get('location_code') or alloc.get('code'))
        location_key = _sold_location_key(alloc.get('location_key') or location_code)
        bucket = grouped.get(location_key)
        if bucket is None:
            bucket = {
                'location_key': location_key,
                'location_code': location_code,
                'quantity': 0
            }
            grouped[location_key] = bucket
        bucket['quantity'] += qty
    return list(grouped.values())


def _build_marketplace_removal_plan(barcode, quantity, allocations=None, fallback_barcodes=None, preferred_location=''):
    rack_conn = None
    try:
        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()

        matches = _searchrack_matches_for_removal_context(
            rack_cur,
            barcode,
            fallback_barcodes=fallback_barcodes,
            preferred_location=preferred_location
        )
        location_groups = _group_searchrack_matches_by_location(matches)
        locations = [
            {
                'location_key': g['location_key'],
                'location_code': g['location_code'],
                'available_qty': max(0, _coerce_int(g.get('available_qty'), 0)),
                'preview_key': str(g.get('preview_key') or g.get('location_code') or '').strip()
            }
            for g in location_groups
        ]
        total_available = sum(max(0, _coerce_int(x.get('available_qty'), 0)) for x in locations)
        normalized_allocations = _normalize_marketplace_allocations(allocations)

        plan = {
            'success': True,
            'needs_choice': len(locations) > 1 and not normalized_allocations,
            'locations': locations,
            'total_available': total_available,
            'can_fulfill': total_available >= max(1, _coerce_int(quantity, 1)),
            'normalized_allocations': normalized_allocations,
            'planned_steps': []
        }

        sold_qty = max(1, _coerce_int(quantity, 1))
        if not location_groups:
            return plan

        group_map = {g['location_key']: g for g in location_groups}

        if normalized_allocations:
            alloc_total = 0
            for alloc in normalized_allocations:
                loc_key = alloc['location_key']
                qty = max(0, _coerce_int(alloc['quantity'], 0))
                group = group_map.get(loc_key)
                if not group:
                    return {
                        'success': False,
                        'error': f"Unknown location selected: {alloc['location_code']}",
                        'locations': locations,
                        'total_available': total_available,
                        'can_fulfill': total_available >= sold_qty
                    }
                group_available = max(0, _coerce_int(group.get('available_qty'), 0))
                if qty > group_available:
                    return {
                        'success': False,
                        'error': f"Selected quantity exceeds available for {alloc['location_code']}",
                        'locations': locations,
                        'total_available': total_available,
                        'can_fulfill': total_available >= sold_qty
                    }
                alloc_total += qty
            if alloc_total != sold_qty:
                return {
                    'success': False,
                    'error': f'Selected location quantities must total {sold_qty}',
                    'locations': locations,
                    'total_available': total_available,
                    'can_fulfill': total_available >= sold_qty
                }

            for alloc in normalized_allocations:
                remaining = max(0, _coerce_int(alloc['quantity'], 0))
                group = group_map.get(alloc['location_key']) or {}
                for row_match in group.get('rows') or []:
                    if remaining <= 0:
                        break
                    available = max(0, _coerce_int(row_match.get('quantity'), 0))
                    if available <= 0:
                        continue
                    take = min(available, remaining)
                    if take <= 0:
                        continue
                    plan['planned_steps'].append({
                        'searchrack_id': int(row_match['id']),
                        'location_code': group.get('location_code') or row_match.get('location_code'),
                        'quantity': int(take)
                    })
                    remaining -= take
                if remaining > 0:
                    return {
                        'success': False,
                        'error': f"Insufficient inventory in selected location {alloc['location_code']}",
                        'locations': locations,
                        'total_available': total_available,
                        'can_fulfill': total_available >= sold_qty
                    }
            return plan

        if len(location_groups) == 1:
            remaining = sold_qty
            group = location_groups[0]
            for row_match in group.get('rows') or []:
                if remaining <= 0:
                    break
                available = max(0, _coerce_int(row_match.get('quantity'), 0))
                if available <= 0:
                    continue
                take = min(available, remaining)
                if take <= 0:
                    continue
                plan['planned_steps'].append({
                    'searchrack_id': int(row_match['id']),
                    'location_code': group.get('location_code') or row_match.get('location_code'),
                    'quantity': int(take)
                })
                remaining -= take
            if remaining > 0:
                plan['planned_steps'] = []
            return plan

        return plan
    finally:
        if rack_conn is not None:
            rack_conn.close()


def _apply_marketplace_removal_plan(plan, *, order_ref, barcode, title, removal_type='manual_sold_removal'):
    steps = list((plan or {}).get('planned_steps') or [])
    if not steps:
        return {'removed': False, 'removed_units': 0, 'locations': []}

    rack_conn = None
    rem_conn = None
    try:
        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        schema = _searchrack_removal_schema(rack_cur)
        qty_col = schema.get('qty_col')
        id_lookup_col = schema.get('id_col') or 'rowid'
        pos_col = schema.get('pos_col')
        if not qty_col:
            return {'removed': False, 'removed_units': 0, 'locations': [], 'error': 'SEARCHRACK quantity column not found'}

        rem_conn = sqlite3.connect('rackhistory.db')
        rem_cur = rem_conn.cursor()
        _ensure_removed_items_table(rem_cur)

        removed_units = 0
        used_locations = []
        touched_row_ids = set()
        now_iso = datetime.datetime.now().isoformat()

        def _abort(error_message):
            try:
                rack_conn.rollback()
            except Exception:
                pass
            try:
                rem_conn.rollback()
            except Exception:
                pass
            return {'removed': False, 'removed_units': 0, 'locations': [], 'error': error_message}

        for step in steps:
            row_id = max(0, _coerce_int(step.get('searchrack_id'), 0))
            take_qty = max(0, _coerce_int(step.get('quantity'), 0))
            if row_id <= 0 or take_qty <= 0:
                continue

            pos_expr = f", {pos_col} AS _item_position" if pos_col else ""
            rack_cur.execute(
                f"SELECT {qty_col} AS _qty{pos_expr} FROM SEARCHRACK WHERE {id_lookup_col} = ?",
                (row_id,)
            )
            row = rack_cur.fetchone()
            if not row:
                return _abort(f'Inventory row no longer exists for {step.get("location_code")}')

            current_qty = max(0, _coerce_int(row['_qty'], 0))
            if current_qty < take_qty:
                return _abort(f'Inventory changed before removal could complete for {step.get("location_code")}')

            new_qty = current_qty - take_qty
            rack_cur.execute(
                f'UPDATE SEARCHRACK SET {qty_col} = ? WHERE {id_lookup_col} = ?',
                (new_qty, row_id)
            )

            item_position = str((row['_item_position'] if '_item_position' in row.keys() else '') or '').strip()
            location_code = _sold_location_label(step.get('location_code') or item_position)
            rem_cur.execute('''
                INSERT INTO removed_items
                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id,
                 old_quantity, new_quantity, removal_type, item_position, event_status)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')
            ''', (
                order_ref,
                barcode,
                title or '',
                take_qty,
                now_iso,
                row_id,
                current_qty,
                new_qty,
                removal_type,
                item_position or location_code
            ))
            removed_units += take_qty
            touched_row_ids.add(row_id)
            if location_code not in used_locations:
                used_locations.append(location_code)

        rem_conn.commit()
        rack_conn.commit()
        for row_id in touched_row_ids:
            _clear_zero_qty_pending_deletions(row_id)
        return {'removed': removed_units > 0, 'removed_units': removed_units, 'locations': used_locations}
    except Exception as e:
        try:
            if rack_conn is not None:
                rack_conn.rollback()
        except Exception:
            pass
        try:
            if rem_conn is not None:
                rem_conn.rollback()
        except Exception:
            pass
        return {'removed': False, 'removed_units': 0, 'locations': [], 'error': str(e)}
    finally:
        if rack_conn is not None:
            rack_conn.close()
        if rem_conn is not None:
            rem_conn.close()

def _ensure_listing_alerts_tables():
    """Create listing_alerts.db tables if they don't exist."""
    try:
        conn = sqlite3.connect('listing_alerts.db')
        cur = conn.cursor()
        cur.execute('''
            CREATE TABLE IF NOT EXISTS dismissed_alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                alert_type TEXT NOT NULL,
                upc TEXT NOT NULL,
                store TEXT,
                listing_ids TEXT,
                dismissed_at TEXT DEFAULT CURRENT_TIMESTAMP,
                snapshot_hash TEXT NOT NULL,
                UNIQUE(alert_type, snapshot_hash)
            )
        ''')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_dismissed_hash ON dismissed_alerts(alert_type, snapshot_hash)')
        cur.execute('''
            CREATE TABLE IF NOT EXISTS inventory_zero_tracker (
                upc TEXT PRIMARY KEY,
                ever_in_inventory INTEGER DEFAULT 0,
                last_qty INTEGER DEFAULT 0,
                last_nonzero_at TEXT,
                zero_triggered_at TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_zero_tracker_zero ON inventory_zero_tracker(zero_triggered_at)')
        cur.execute('''
            CREATE TABLE IF NOT EXISTS ebay_listing_health_cache (
                item_id TEXT PRIMARY KEY,
                is_active INTEGER NOT NULL DEFAULT 1,
                checked_at TEXT DEFAULT CURRENT_TIMESTAMP,
                source TEXT,
                note TEXT
            )
        ''')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_ebay_listing_health_checked_at ON ebay_listing_health_cache(checked_at)')
        cur.execute('''
            CREATE TABLE IF NOT EXISTS listing_inventory_matches (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                store TEXT NOT NULL,
                listing_key TEXT NOT NULL COLLATE NOCASE,
                listing_id TEXT,
                marketplace_barcode TEXT,
                listing_title TEXT,
                searchrack_id INTEGER NOT NULL,
                inventory_barcode TEXT NOT NULL,
                inventory_location TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(store, listing_key)
            )
        ''')
        cur.execute('CREATE INDEX IF NOT EXISTS idx_listing_inventory_match_rack ON listing_inventory_matches(searchrack_id)')
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"Error initializing listing_alerts.db: {e}")

def _listing_alert_upc_key(raw_upc):
    """Normalize UPC/Barcode for cross-db matching in listing alert logic."""
    upc = (str(raw_upc or '').strip())
    if not upc:
        return ''
    normalized = _strip_leading_zeros_numeric(upc)
    return (normalized or upc).lower()


def _normalize_store_listing_identity(store, listing_key):
    normalized_store = str(store or '').strip().lower()
    normalized_key = str(listing_key or '').strip()
    if normalized_store not in {'ebay', 'amazon', 'facebook'} or not normalized_key:
        return '', ''
    prefix = f'{normalized_store}:'
    if normalized_key.lower().startswith(prefix):
        normalized_key = normalized_key[len(prefix):].strip()
    return normalized_store, normalized_key


def _store_listing_order_identity_candidates(order):
    store = str(_sold_order_value(order, 'store', '') or '').strip().lower()
    values = []
    if store == 'ebay':
        values = [
            _sold_order_value(order, 'listing_listing_id', ''),
            _sold_order_value(order, 'item_id', ''),
            _sold_order_value(order, 'listing_sku', ''),
            _sold_order_value(order, 'sku', '')
        ]
    elif store == 'amazon':
        values = [
            _sold_order_value(order, 'listing_sku', ''),
            _sold_order_value(order, 'sku', ''),
            _sold_order_value(order, 'listing_asin', ''),
            _sold_order_value(order, 'item_id', '')
        ]

    out = []
    for value in values:
        _, key = _normalize_store_listing_identity(store, value)
        key_lower = key.lower()
        if key and key_lower not in out:
            out.append(key_lower)
    return store, out


def _load_listing_inventory_match_lookup():
    _ensure_listing_alerts_tables()
    lookup = {}
    try:
        with sqlite3.connect(str(BASE_DIR / 'listing_alerts.db')) as conn:
            conn.row_factory = sqlite3.Row
            for row in conn.execute('SELECT * FROM listing_inventory_matches'):
                store, key = _normalize_store_listing_identity(row['store'], row['listing_key'])
                if store and key:
                    lookup[(store, key.lower())] = dict(row)
    except Exception as e:
        print(f'Warning: Could not load store-listing inventory matches: {e}')
    return lookup


def _listing_inventory_match_for_order(order, lookup=None):
    mapping_lookup = lookup if lookup is not None else _load_listing_inventory_match_lookup()
    store, candidates = _store_listing_order_identity_candidates(order)
    for candidate in candidates:
        match = mapping_lookup.get((store, candidate))
        if match:
            return match
    return None

def _listing_alert_base_upc_key(raw_upc):
    """Normalize base UPC (strip -suffix + leading zeros) for broader matching."""
    upc = (str(raw_upc or '').strip())
    if not upc:
        return ''
    base = upc.split('-', 1)[0].strip()
    if not base:
        return ''
    normalized = _strip_leading_zeros_numeric(base)
    return (normalized or base).lower()

def _coerce_int(value, default=0):
    try:
        if value is None:
            return default
        if isinstance(value, str):
            s = value.strip().lower()
            if s in ('', 'n/a', 'na', 'null'):
                return default
        return int(float(value))
    except Exception:
        return default

def _parse_iso_utc_naive(raw):
    txt = (str(raw or '').strip())
    if not txt:
        return None
    try:
        if 'T' in txt:
            if txt.endswith('Z'):
                dt = datetime.datetime.fromisoformat(txt.replace('Z', '+00:00'))
            else:
                dt = datetime.datetime.fromisoformat(txt)
        else:
            dt = datetime.datetime.fromisoformat(txt)
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt
    except Exception:
        return None


def _sold_order_sale_datetime(order):
    """Return the best available timestamp identifying this specific sale."""
    for field in ('paid_time', 'sold_date', 'sale_date', 'created_at'):
        try:
            value = order.get(field) if isinstance(order, dict) else order[field]
        except Exception:
            value = None
        parsed = _parse_iso_utc_naive(value)
        if parsed is not None:
            return parsed
    return None


def _sold_removal_event_is_current(order, removal):
    """Reject barcode history that predates the sold-order occurrence."""
    sold_at = _sold_order_sale_datetime(order)
    if sold_at is None:
        return True
    try:
        removed_value = removal.get('removed_at') if isinstance(removal, dict) else removal['removed_at']
    except Exception:
        removed_value = None
    removed_text = str(removed_value or '').strip()
    removed_at = None
    if removed_text:
        try:
            parsed_removed = datetime.datetime.fromisoformat(removed_text.replace('Z', '+00:00'))
            if parsed_removed.tzinfo is None:
                # Rack-history events are written with datetime.now(), so their
                # otherwise-naive timestamps are local warehouse time.
                try:
                    from zoneinfo import ZoneInfo
                    parsed_removed = parsed_removed.replace(tzinfo=ZoneInfo('America/New_York'))
                except Exception:
                    parsed_removed = parsed_removed.replace(tzinfo=datetime.datetime.now().astimezone().tzinfo)
            removed_at = parsed_removed.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            removed_at = None
    return removed_at is not None and removed_at >= sold_at


def _probe_ebay_listing_live(item_id, url=''):
    """
    Best-effort live check against eBay listing page.
    Returns: (is_active_or_none, note)
      - True: page looks active
      - False: page shows ended markers
      - None: network/parse uncertainty, caller should treat as unknown
    """
    iid = (str(item_id or '').strip())
    if not iid:
        return None, 'missing_item_id'

    target_url = (str(url or '').strip()) or f'https://www.ebay.com/itm/{iid}'
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0 Safari/537.36',
        'Accept-Language': 'en-US,en;q=0.9'
    }

    try:
        resp = requests.get(target_url, timeout=8, headers=headers)
    except Exception as e:
        return None, f'request_error:{type(e).__name__}'

    status = int(resp.status_code or 0)
    if status >= 500:
        return None, f'http_{status}'

    body = (resp.text or '').lower()
    ended_markers = (
        'this listing was ended',
        'this listing ended',
        'listing has ended',
        'you can no longer bid on this item',
        'this item is no longer available',
        'this item is out of stock'
    )
    for marker in ended_markers:
        if marker in body:
            return False, f'ended_marker:{marker}'

    return True, f'http_{status}'

def _searchrack_total_qty_for_key(conn, upc_key):
    """Return total warehouse qty for one normalized UPC key."""
    if not upc_key:
        return 0

    cur = conn.cursor()
    cur.execute("PRAGMA table_info('SEARCHRACK')")
    cols = [r[1] for r in cur.fetchall()]
    cols_lower = {c.lower(): c for c in cols}
    upc_col = cols_lower.get('upc') or cols_lower.get('barcode')
    qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
    if not upc_col or not qty_col:
        return 0

    cur.execute(f'''
        SELECT {upc_col} AS upc, {qty_col} AS qty
        FROM SEARCHRACK
        WHERE {upc_col} IS NOT NULL AND TRIM({upc_col}) != ""
    ''')

    total_qty = 0
    for raw_upc, raw_qty in cur.fetchall():
        if _listing_alert_upc_key(raw_upc) != upc_key:
            continue
        qty = max(0, _coerce_int(raw_qty, 0))
        total_qty += qty
    return total_qty


def _sold_order_value(order, key, default=''):
    if order is None:
        return default
    try:
        if isinstance(order, dict):
            return order.get(key, default)
        return order[key]
    except Exception:
        pass
    return default

def _ensure_order_processing_claim_column(cur):
    """Track in-progress Ready to Ship claims so stale ones can be recovered."""
    try:
        cur.execute('PRAGMA table_info(orders)')
        cols = {str(r[1]).lower() for r in cur.fetchall()}
        if 'rackupdated_claimed_at' not in cols:
            cur.execute('ALTER TABLE orders ADD COLUMN rackupdated_claimed_at TEXT')
    except Exception:
        pass

def _is_order_processing_claim_stale(claimed_at_value, timeout_minutes=10):
    """Treat missing or old in-progress claims as recoverable."""
    claimed_at = str(claimed_at_value or '').strip()
    if not claimed_at:
        return True
    try:
        claim_dt = datetime.datetime.fromisoformat(claimed_at.replace('Z', '+00:00'))
        if claim_dt.tzinfo is not None:
            claim_dt = claim_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        age_seconds = (datetime.datetime.utcnow() - claim_dt).total_seconds()
        return age_seconds >= max(60, int(timeout_minutes) * 60)
    except Exception:
        return True
    try:
        return order[key]
    except Exception:
        return default


def _effective_sold_order_barcode(order, prefer_manual_override=False):
    source_upc = str(_sold_order_value(order, 'source_upc', '') or '').strip()
    barcode = str(_sold_order_value(order, 'barcode', '') or '').strip()

    # Finder can manually link a sold order to a different warehouse barcode.
    # In ready-to-ship/removal flows, honor that explicit override instead of
    # forcing the original traced source_upc.
    if prefer_manual_override and source_upc and barcode:
        source_key = _sold_removal_barcode_key(source_upc)
        barcode_key = _sold_removal_barcode_key(barcode)
        if source_key and barcode_key and source_key != barcode_key:
            return barcode

    # When finder explicitly matched an order (it writes both barcode AND location to sold.db)
    # and there is no source_upc to fall back to, trust the stored barcode directly instead of
    # re-resolving from the marketplace SKU (which can return a different UPC).
    if prefer_manual_override and barcode and not source_upc:
        stored_location = str(_sold_order_value(order, 'location', '') or '').strip()
        if stored_location:
            return barcode

    if source_upc:
        return source_upc
    sku = str(_sold_order_value(order, 'sku', '') or '').strip()
    platform = str(_sold_order_value(order, 'store', '') or '').strip().lower()
    item_id = str(_sold_order_value(order, 'item_id', '') or '').strip()
    if not sku or sku.lower() in {'none', 'null', 'n/a', 'na', 'does not apply'}:
        return barcode
    try:
        resolved = resolve_barcode_from_marketplace_sku(
            sku,
            platform=platform,
            item_id=item_id,
            fallback_barcode=barcode
        )
        return str(resolved or barcode).strip()
    except Exception:
        return barcode


def _ready_to_ship_image_value(value):
    """Return a usable image reference, or an empty string for missing values."""
    image = str(value or '').strip()
    if not image or image.lower() in {'nan', 'none', 'null', 'undefined', 'n/a', 'na'}:
        return ''
    return image


def _ready_to_ship_rawbol_image(rawbol_cur, values):
    """Find the newest Raw BOL image matching any form of an order barcode."""
    candidates = []
    seen = set()
    for value in values:
        for candidate in _sold_removal_barcode_variants(value):
            normalized = str(candidate or '').strip().lower()
            if normalized and normalized not in seen:
                seen.add(normalized)
                candidates.append(normalized)
    if not candidates:
        return ''

    placeholders = ','.join('?' for _ in candidates)
    row = rawbol_cur.execute(f'''
        SELECT image_url
        FROM raw_bol_items
        WHERE LOWER(TRIM(COALESCE(upc, ''))) IN ({placeholders})
          AND TRIM(COALESCE(image_url, '')) != ''
        ORDER BY rowid DESC
        LIMIT 1
    ''', candidates).fetchone()
    return _ready_to_ship_image_value(row[0] if row else '')


def _is_exact_traced_suffixed_sold_order(order):
    source_upc = str(_sold_order_value(order, 'source_upc', '') or '').strip()
    if not source_upc or '-' not in source_upc:
        return False
    trace_source = str(_sold_order_value(order, 'listing_trace_source', '') or '').strip().lower()
    trace_id = str(_sold_order_value(order, 'listing_trace_id', '') or '').strip()
    return trace_source == 'listingagent' or bool(trace_id)


def _barcode_base_without_suffix(value):
    upc = _normalize_upc_preserve_suffix_for_match(value)
    if not upc:
        return ''
    return upc.split('-', 1)[0]


def _ready_to_ship_warehouse_qty_for_barcode(barcode):
    rack_conn = None
    try:
        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        matches = _searchrack_matches_for_barcode(rack_cur, barcode, include_zero=False)
        if not matches:
            base_barcode = _barcode_base_without_suffix(barcode)
            if base_barcode and _normalize_upc_preserve_suffix_for_match(base_barcode) != _normalize_upc_preserve_suffix_for_match(barcode):
                matches = _searchrack_matches_for_barcode(rack_cur, base_barcode, include_zero=False)
        return sum(max(0, _coerce_int(row.get('quantity'), 0)) for row in matches)
    except Exception:
        return 0
    finally:
        if rack_conn is not None:
            rack_conn.close()


def _ready_to_ship_rawbol_total_qty_for_barcode(barcode):
    base_barcode = _barcode_base_without_suffix(barcode) or str(barcode or '').strip()
    target_key = _sold_removal_barcode_key(base_barcode)
    variants = sorted(v.lower() for v in _sold_removal_barcode_variants(base_barcode))
    invalid_upc_values = {'null', 'n/a', 'does not apply'}
    if not target_key or target_key in invalid_upc_values:
        return 0

    conn = None
    total_qty = 0
    try:
        conn = sqlite3.connect('rawbol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='raw_bol_items'")
        has_raw_items = bool(cur.fetchone())
        if has_raw_items:
            cur.execute("PRAGMA table_info('raw_bol_items')")
            cols = [r[1] for r in cur.fetchall()]
            cols_lower = {c.lower(): c for c in cols}
            upc_col = cols_lower.get('upc') or cols_lower.get('barcode')
            qty_col = cols_lower.get('quantity') or cols_lower.get('qty')
            if upc_col and qty_col:
                base_sql = f'''
                    SELECT {upc_col} AS upc, {qty_col} AS qty
                    FROM raw_bol_items
                    WHERE {upc_col} IS NOT NULL
                      AND TRIM({upc_col}) != ''
                '''
                if variants:
                    placeholders = ','.join('?' for _ in variants)
                    cur.execute(base_sql + f" AND LOWER(TRIM({upc_col})) IN ({placeholders})", tuple(variants))
                else:
                    cur.execute(base_sql)
                for row in cur.fetchall():
                    raw_upc = str(row['upc'] or '').strip()
                    if _sold_removal_barcode_key(raw_upc) != target_key:
                        continue
                    total_qty += max(0, _coerce_int(row['qty'], 0))
                if total_qty > 0:
                    return total_qty

        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='rawbol'")
        has_legacy = bool(cur.fetchone())
        if has_legacy:
            cur.execute("PRAGMA table_info('rawbol')")
            cols = [r[1] for r in cur.fetchall()]
            cols_lower = {c.lower(): c for c in cols}
            upc_col = cols_lower.get('upc') or cols_lower.get('barcode')
            qty_col = cols_lower.get('qty') or cols_lower.get('quantity')
            if upc_col and qty_col:
                base_sql = f'''
                    SELECT {upc_col} AS upc, {qty_col} AS qty
                    FROM rawbol
                    WHERE {upc_col} IS NOT NULL
                      AND TRIM({upc_col}) != ''
                '''
                if variants:
                    placeholders = ','.join('?' for _ in variants)
                    cur.execute(base_sql + f" AND LOWER(TRIM({upc_col})) IN ({placeholders})", tuple(variants))
                else:
                    cur.execute(base_sql)
                for row in cur.fetchall():
                    raw_upc = str(row['upc'] or '').strip()
                    if _sold_removal_barcode_key(raw_upc) != target_key:
                        continue
                    total_qty += max(0, _coerce_int(row['qty'], 0))
        return total_qty
    except Exception:
        return 0
    finally:
        if conn is not None:
            conn.close()


def _ready_to_ship_sold_count_for_barcode(barcode):
    base_barcode = _barcode_base_without_suffix(barcode) or str(barcode or '').strip()
    target_key = _sold_removal_barcode_key(base_barcode)
    variants = sorted(v.lower() for v in _sold_removal_barcode_variants(base_barcode))
    invalid_upc_values = {'null', 'n/a', 'does not apply'}
    if not target_key or target_key in invalid_upc_values:
        return 0
    conn = None
    try:
        conn = sqlite3.connect('sold.db')
        cur = conn.cursor()
        if variants:
            placeholders = ','.join('?' for _ in variants)
            cur.execute(
                f"SELECT COALESCE(SUM(COALESCE(quantity,1)),0) FROM orders WHERE LOWER(TRIM(barcode)) IN ({placeholders})",
                tuple(variants)
            )
        else:
            cur.execute(
                "SELECT COALESCE(SUM(COALESCE(quantity,1)),0) FROM orders WHERE LOWER(TRIM(barcode)) = ?",
                (base_barcode.lower(),)
            )
        row = cur.fetchone()
        return max(0, _coerce_int(row[0], 0)) if row else 0
    except Exception:
        return 0
    finally:
        if conn is not None:
            conn.close()


def _ready_to_ship_items_to_list_stats_for_barcode(barcode):
    upc = _normalize_upc_preserve_suffix_for_match(barcode)
    base_upc = upc.split('-', 1)[0] if upc else ''
    payload = {
        'base_barcode': base_upc,
        'prepped_qty': 0,
        'items_to_list_url': _items_prep_items_to_list_url(base_upc) if base_upc else '/items-to-list'
    }
    if not base_upc:
        return payload

    like_related = _ready_to_ship_prep_related_like(base_upc)

    try:
        _ensure_items_prep_tables()
        with db_connection('bol.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("PRAGMA table_info('bol_items')")
            cols = [r[1] for r in cur.fetchall()]
            if not cols:
                return payload

            has_itemprepped = any(c.lower() == 'itemprepped' for c in cols)
            has_original_qty = any(c.lower() == 'original_qty' for c in cols)
            has_good_qty = any(c.lower() == 'good_qty' for c in cols)
            has_bad_qty = any(c.lower() == 'bad_qty' for c in cols)
            has_unchecked_qty = any(c.lower() == 'unchecked_qty' for c in cols)

            prep_status_expr = "COALESCE(s_exact.status, s_fallback.status)"
            prep_qty_expr = "COALESCE(s_exact.quantity, s_fallback.quantity)"
            prep_join = (
                " FROM bol_items b "
                "LEFT JOIN items_prep_status s_exact "
                "ON s_exact.upc = b.upc "
                "AND COALESCE(s_exact.lot_number, '') = COALESCE(b.lot_number, '') "
                "LEFT JOIN items_prep_status s_fallback "
                "ON s_fallback.upc = b.upc "
                "AND COALESCE(s_fallback.lot_number, '') = '' "
                "AND s_exact.id IS NULL "
            )

            sql = (
                'SELECT b.upc, COALESCE(b.lot_number, "") AS lot_number, COALESCE(b.quantity, 1) AS quantity, ' +
                ('COALESCE(b.original_qty, NULL) AS original_qty, ' if has_original_qty else 'NULL AS original_qty, ') +
                ('COALESCE(b.good_qty, NULL) AS good_qty, ' if has_good_qty else 'NULL AS good_qty, ') +
                ('COALESCE(b.bad_qty, NULL) AS bad_qty, ' if has_bad_qty else 'NULL AS bad_qty, ') +
                ('COALESCE(b.unchecked_qty, NULL) AS unchecked_qty, ' if has_unchecked_qty else 'NULL AS unchecked_qty, ') +
                f'{prep_status_expr} AS prep_status, {prep_qty_expr} AS prep_quantity '
                + prep_join +
                '''WHERE b.id = (
                        SELECT MAX(b2.id)
                        FROM bol_items b2
                        WHERE b2.upc = b.upc COLLATE NOCASE
                          AND COALESCE(b2.lot_number, '') = COALESCE(b.lot_number, '')
                    ) '''
            )
            if has_itemprepped:
                sql += "AND (b.itemprepped IS NULL OR b.itemprepped = 0) "
            sql += "AND (b.upc = ? COLLATE NOCASE OR b.upc LIKE ? ESCAPE '\\')"

            cur.execute(sql, (base_upc, like_related))
            total_qty = 0
            for row in cur.fetchall():
                row_dict = dict(row)
                row_upc = _normalize_upc_preserve_suffix_for_match(row_dict.get('upc'))
                if not row_upc:
                    continue

                good_bucket = max(0, _coerce_int(row_dict.get('good_qty'), 0))
                bad_bucket = max(0, _coerce_int(row_dict.get('bad_qty'), 0))
                status = _items_to_list_effective_status(
                    row_upc,
                    row_dict.get('prep_status'),
                    good_qty=good_bucket,
                    bad_qty=bad_bucket
                )
                if status not in ('good', 'bad', 'return'):
                    continue

                prep_qty = row_dict.get('prep_quantity')
                if prep_qty is not None:
                    display_qty = max(0, _coerce_int(prep_qty, _coerce_int(row_dict.get('quantity'), 1)))
                elif status == 'good':
                    display_qty = max(0, _coerce_int(row_dict.get('good_qty'), _coerce_int(row_dict.get('quantity'), 1)))
                elif status == 'bad':
                    display_qty = max(0, _coerce_int(row_dict.get('bad_qty'), _coerce_int(row_dict.get('quantity'), 1)))
                else:
                    display_qty = max(0, _coerce_int(row_dict.get('quantity'), 1))

                total_qty += display_qty

            payload['prepped_qty'] = max(0, total_qty)
    except Exception:
        pass

    return payload

def _record_inventory_zero_transition(upc_key, prev_total_qty, current_total_qty, observed_at=None):
    """Persist >0 -> 0 transitions immediately on inventory writes."""
    invalid_upc_values = {'null', 'n/a', 'does not apply'}
    if not upc_key or upc_key in invalid_upc_values:
        return

    prev_total_qty = max(0, _coerce_int(prev_total_qty, 0))
    current_total_qty = max(0, _coerce_int(current_total_qty, 0))
    ts = observed_at or (datetime.datetime.utcnow().isoformat() + 'Z')

    try:
        _ensure_listing_alerts_tables()
        with sqlite3.connect('listing_alerts.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute('''
                SELECT ever_in_inventory, last_qty, last_nonzero_at, zero_triggered_at
                FROM inventory_zero_tracker
                WHERE upc = ?
            ''', (upc_key,))
            row = cur.fetchone()

            if row is None:
                ever_in_inventory = 1 if (prev_total_qty > 0 or current_total_qty > 0) else 0
                last_nonzero_at = ts if (prev_total_qty > 0 or current_total_qty > 0) else None
                zero_triggered_at = ts if (prev_total_qty > 0 and current_total_qty == 0 and ever_in_inventory == 1) else None
                cur.execute('''
                    INSERT INTO inventory_zero_tracker (
                        upc, ever_in_inventory, last_qty, last_nonzero_at, zero_triggered_at, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?)
                ''', (
                    upc_key,
                    ever_in_inventory,
                    current_total_qty,
                    last_nonzero_at,
                    zero_triggered_at,
                    ts,
                    ts
                ))
            else:
                ever_in_inventory = _coerce_int(row['ever_in_inventory'], 0)
                if prev_total_qty > 0 or current_total_qty > 0:
                    ever_in_inventory = 1

                last_nonzero_at = row['last_nonzero_at']
                zero_triggered_at = row['zero_triggered_at']

                if current_total_qty > 0:
                    last_nonzero_at = ts
                    zero_triggered_at = None
                elif prev_total_qty > 0 and ever_in_inventory == 1:
                    zero_triggered_at = ts

                cur.execute('''
                    UPDATE inventory_zero_tracker
                    SET ever_in_inventory = ?,
                        last_qty = ?,
                        last_nonzero_at = ?,
                        zero_triggered_at = ?,
                        updated_at = ?
                    WHERE upc = ?
                ''', (
                    ever_in_inventory,
                    current_total_qty,
                    last_nonzero_at,
                    zero_triggered_at,
                    ts,
                    upc_key
                ))

            conn.commit()
    except Exception as e:
        print(f"Warning: failed to update inventory_zero_tracker from write event: {e}")

