@app.route('/api/listingagent/upc/search', methods=['GET'])
def api_listingagent_upc_search():
    """Typeahead for UPCs from searchRack.db and bol.db."""
    try:
        q = (request.args.get('q') or '').strip()
        limit = _listingagent_parse_int(request.args.get('limit'), 20) or 20
        limit = max(1, min(limit, 50))

        results_by_upc = {}

        like = f"%{q}%"
        with db_connection('searchRack.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT
                    TRIM(BARCODE) AS upc,
                    MAX(TITLE) AS title,
                    SUM(COALESCE(QUANTITY, 1)) AS quantity,
                    MAX(CREATED_AT) AS last_seen,
                    MAX(IMAGE) AS image
                FROM SEARCHRACK
                WHERE BARCODE IS NOT NULL AND TRIM(BARCODE) != ''
                  AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                  AND (? = '' OR BARCODE LIKE ? OR TITLE LIKE ?)
                GROUP BY TRIM(BARCODE)
                ORDER BY MAX(CREATED_AT) DESC
                LIMIT ?
            ''', (q, like, like, limit))

            for row in cur.fetchall():
                upc = (row['upc'] or '').strip()
                if not upc:
                    continue
                results_by_upc[upc] = {
                    'upc': upc,
                    'title': row['title'] or '',
                    'quantity': int(row['quantity'] or 0),
                    'image': row['image'] or '',
                    'source': 'searchRack'
                }

        with db_connection('bol.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT
                    TRIM(upc) AS upc,
                    MAX(item_description) AS title,
                    MAX(image_url) AS image,
                    MAX(COALESCE(good_qty, quantity, original_qty, 1)) AS quantity,
                    MAX(import_date) AS last_seen
                FROM bol_items
                WHERE upc IS NOT NULL AND TRIM(upc) != ''
                  AND (? = '' OR upc LIKE ? OR item_description LIKE ?)
                GROUP BY TRIM(upc)
                ORDER BY MAX(import_date) DESC
                LIMIT ?
            ''', (q, like, like, limit))
            for row in cur.fetchall():
                upc = (row['upc'] or '').strip()
                if not upc:
                    continue
                if upc in results_by_upc:
                    # Fill missing title/image from BOL
                    if not results_by_upc[upc].get('title') and row['title']:
                        results_by_upc[upc]['title'] = row['title'] or ''
                    if not results_by_upc[upc].get('image') and row['image']:
                        results_by_upc[upc]['image'] = row['image'] or ''
                    continue
                results_by_upc[upc] = {
                    'upc': upc,
                    'title': row['title'] or '',
                    'quantity': int(row['quantity'] or 0),
                    'image': row['image'] or '',
                    'source': 'bol'
                }

        # Basic ordering: prioritize UPC prefix matches, then title matches
        def score(item):
            if not q:
                return (0, item.get('upc', ''))
            upc = item.get('upc', '')
            title = (item.get('title') or '').lower()
            ql = q.lower()
            if upc.startswith(q):
                return (0, upc)
            if q in upc:
                return (1, upc)
            if ql in title:
                return (2, upc)
            return (3, upc)

        results = sorted(results_by_upc.values(), key=score)[:limit]
        return jsonify({'success': True, 'results': results})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:upc_search')}), 500

@app.route('/api/listingagent/upc/<upc>', methods=['GET'])
def api_listingagent_upc_detail(upc):
    """Aggregate item info by UPC across local DBs to help auto-fill listings."""
    try:
        upc = (upc or '').strip()
        if not upc:
            return jsonify({'success': False, 'error': 'UPC is required'}), 400

        item = {
            'upc': upc,
            'title': '',
            'images': [],
            'defect': '',
            'inventory': {
                'total_quantity': 0,
                'rows': [],
                'positions': []
            },
            'bol': None,
            'ebay_store': {
                'listings': []
            },
            'amazon_store': {
                'listings': []
            },
            'sold_stats': None
        }

        # Build UPC lookup variants to handle:
        # - suffixed UPCs (e.g. "123456789012-1" → base "123456789012")
        # - leading-zero padding differences ("035886267162" vs "35886267162")
        _upc_base = upc.split('-', 1)[0].strip() if '-' in upc else upc
        _upc_base_stripped = _upc_base.lstrip('0') or _upc_base  # "35886267162"
        _upc_base_padded = _upc_base.zfill(12) if _upc_base.isdigit() else _upc_base  # "035886267162"
        item['base_upc'] = _upc_base
        item['items_to_list_url'] = _items_prep_items_to_list_url(_upc_base or upc)
        # Unique ordered variants: exact, padded, stripped (all base, no suffix for store lookups)
        def _upc_lookup_variants(*extras):
            seen = []
            for v in [upc, _upc_base, _upc_base_padded, _upc_base_stripped] + list(extras):
                v = (v or '').strip()
                if v and v not in seen:
                    seen.append(v)
            return seen
        with db_connection('searchRack.db') as conn:
            cur = conn.cursor()
            _inv_variants = _upc_lookup_variants()
            _inv_placeholders = ','.join('?' for _ in _inv_variants)
            if '-' in upc:
                # Suffixed UPC: match exact variants only
                cur.execute(f'''
                    SELECT ID, TITLE, ITEM_POSITION, PICTUREPOSITION, QUANTITY, IMAGE, IMAGES, ITEMID, CREATED_AT
                    FROM SEARCHRACK
                    WHERE TRIM(BARCODE) COLLATE NOCASE IN ({_inv_placeholders})
                      AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                    ORDER BY CREATED_AT DESC
                ''', _inv_variants)
            else:
                # Base UPC: match padded/stripped variants, but exclude any suffixed rows
                cur.execute(f'''
                    SELECT ID, TITLE, ITEM_POSITION, PICTUREPOSITION, QUANTITY, IMAGE, IMAGES, ITEMID, CREATED_AT
                    FROM SEARCHRACK
                    WHERE TRIM(BARCODE) COLLATE NOCASE IN ({_inv_placeholders})
                      AND TRIM(BARCODE) NOT LIKE '%-_%' COLLATE NOCASE
                      AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                    ORDER BY CREATED_AT DESC
                ''', _inv_variants)
            rows = cur.fetchall()

            total_qty = 0
            positions = []
            for r in rows:
                qty = int(r['QUANTITY'] or 0) if r['QUANTITY'] is not None else 0
                total_qty += qty
                pos = (r['ITEM_POSITION'] or '').strip()
                if pos:
                    positions.append(pos)

                for img in [r['IMAGE'], r['IMAGES']]:
                    if not img:
                        continue
                    s = str(img).strip()
                    if not s:
                        continue
                    if s not in item['images']:
                        item['images'].append(s)

            item['inventory']['total_quantity'] = total_qty
            item['inventory']['positions'] = sorted(set([p for p in positions if p]))
            item['inventory']['rows'] = [{
                'id': r['ID'],
                'title': r['TITLE'] or '',
                'position': r['ITEM_POSITION'] or '',
                'picturePosition': r['PICTUREPOSITION'] or '',
                'quantity': r['QUANTITY'] if r['QUANTITY'] is not None else 1,
                'image': r['IMAGE'] or '',
                'createdAt': r['CREATED_AT'] or ''
            } for r in rows[:50]]

            # Prefer the most recent title
            for r in rows:
                if r['TITLE']:
                    item['title'] = r['TITLE']
                    break

        # rawbol.db — primary source for title + thumbnail; always use base barcode.
        _rawbol_variants = [_upc_base_padded, _upc_base_stripped, _upc_base]
        _rawbol_variants = list(dict.fromkeys(v for v in _rawbol_variants if v))  # dedupe, preserve order
        try:
            with db_connection('rawbol.db') as conn:
                cur = conn.cursor()
                cur.execute('''
                    SELECT item_description, image_url, prep_reason
                    FROM raw_bol_items
                    WHERE TRIM(upc) IN ({})
                    ORDER BY import_date DESC, id DESC
                    LIMIT 1
                '''.format(','.join('?' for _ in _rawbol_variants)),
                tuple(_rawbol_variants))
                raw_row = cur.fetchone()
                if raw_row:
                    if not item['title'] and (raw_row['item_description'] or '').strip():
                        item['title'] = raw_row['item_description'].strip()
                    img = (raw_row['image_url'] or '').strip()
                    if img and img not in item['images']:
                        item['images'].insert(0, img)  # rawbol image first
                    item['defect'] = (raw_row['prep_reason'] or '').strip()
        except Exception:
            pass

        # BOL info (bol.db — processed BOL items with prep quantities)
        with db_connection('bol.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT item_description, image_url, lot_number, import_date,
                       good_qty, bad_qty, unchecked_qty, quantity,
                       listed_ebay, listed_ebay_date
                FROM bol_items
                WHERE TRIM(upc) IN ({})
                ORDER BY import_date DESC
                LIMIT 1
            '''.format(','.join('?' for _ in _upc_lookup_variants())),
            tuple(_upc_lookup_variants()))
            bol_row = cur.fetchone()
            if bol_row:
                item['bol'] = {
                    'description': bol_row['item_description'] or '',
                    'image_url': bol_row['image_url'] or '',
                    'lot_number': bol_row['lot_number'] or '',
                    'import_date': bol_row['import_date'] or '',
                    'good_qty': bol_row['good_qty'],
                    'bad_qty': bol_row['bad_qty'],
                    'unchecked_qty': bol_row['unchecked_qty'],
                    'quantity': bol_row['quantity'],
                    'listed_ebay': bol_row['listed_ebay'],
                    'listed_ebay_date': bol_row['listed_ebay_date'] or ''
                }
                if not item['title'] and item['bol']['description']:
                    item['title'] = item['bol']['description']
                if item['bol']['image_url'] and item['bol']['image_url'] not in item['images']:
                    item['images'].append(item['bol']['image_url'])

        # ebayStore existing listings
        _ev = _upc_lookup_variants()
        with db_connection('ebayStore.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT Title, ItemID, SKU, Price, Quantity, Image, URL, List_State, Sold_Date, List_Date
                FROM INVENTORY
                WHERE TRIM(UPC) IN ({})
                ORDER BY List_Date DESC
                LIMIT 10
            '''.format(','.join('?' for _ in _ev)),
            tuple(_ev))
            for r in cur.fetchall():
                listing = {
                    'title': r['Title'] or '',
                    'item_id': r['ItemID'] or '',
                    'sku': r['SKU'] or '',
                    'price': r['Price'] or '',
                    'quantity': r['Quantity'] or '',
                    'image': r['Image'] or '',
                    'url': r['URL'] or '',
                    'state': r['List_State'] or '',
                    'sold_date': r['Sold_Date'] or '',
                    'list_date': r['List_Date'] or ''
                }
                item['ebay_store']['listings'].append(listing)
                if listing.get('image') and listing['image'] not in item['images']:
                    item['images'].append(listing['image'])

        # amazonStore existing listings
        try:
            _av = _upc_lookup_variants()
            with db_connection('amazonStore.db') as conn:
                cur = conn.cursor()
                cur.execute('''
                    SELECT ASIN, SKU, TITLE, PRICE, QUANTITY, STATUS, IMAGE, UPC, CONDITION, FULFILLMENT_CHANNEL, LAST_UPDATED
                    FROM ITEMS
                    WHERE TRIM(UPC) IN ({})
                    ORDER BY LAST_UPDATED DESC
                    LIMIT 10
                '''.format(','.join('?' for _ in _av)),
                tuple(_av))
                for r in cur.fetchall():
                    asin = (r['ASIN'] or '').strip()
                    listing = {
                        'asin': asin,
                        'sku': r['SKU'] or '',
                        'title': r['TITLE'] or '',
                        'price': r['PRICE'],
                        'quantity': r['QUANTITY'],
                        'status': r['STATUS'] or '',
                        'image': r['IMAGE'] or '',
                        'condition': r['CONDITION'] or '',
                        'fulfillment_channel': r['FULFILLMENT_CHANNEL'] or '',
                        'last_updated': r['LAST_UPDATED'] or '',
                        'product_url': f"https://www.amazon.com/dp/{asin}" if asin else ''
                    }
                    item['amazon_store']['listings'].append(listing)
                    if listing.get('image') and listing['image'] not in item['images']:
                        item['images'].append(listing['image'])
                    if not item['title'] and listing.get('title'):
                        item['title'] = listing['title']
        except Exception:
            # amazonStore.db may not exist in some environments; ignore.
            pass

        # Listing Manager (Item Prep) photos + notes (bol.db items_prep_*) — useful for auto-filling listing images and showing notes.
        item['prep'] = {'notes': [], 'images': [], 'voice_notes': []}
        try:
            _ensure_items_prep_tables()

            _upc_is_suffixed = '-' in upc
            base_upc = (upc.split('-', 1)[0] if _upc_is_suffixed else upc).strip()
            base_upc = _strip_leading_zeros_numeric(base_upc)

            # When the requested UPC has a suffix (e.g. "123456789012-1"), only pull
            # notes/images/audio for that exact suffixed UPC — not all siblings.
            # When there's no suffix, pull base UPC + all suffixed variants (broad view).
            if _upc_is_suffixed:
                # Build padding variants of the suffixed UPC itself
                _suffix_part = upc.split('-', 1)[1]
                _suffixed_padded = f"{_upc_base_padded}-{_suffix_part}"
                _suffixed_stripped = f"{_upc_base_stripped}-{_suffix_part}"
                _prep_exact_variants = list(dict.fromkeys(
                    v for v in [upc, _suffixed_padded, _suffixed_stripped] if v
                ))
                _prep_placeholders = ','.join('?' for _ in _prep_exact_variants)
                def _prep_where_clause():
                    return f'upc COLLATE NOCASE IN ({_prep_placeholders})'
                def _prep_params():
                    return _prep_exact_variants
            else:
                # Base barcode: exact match only — do NOT pull suffixed siblings' notes/media.
                # Each suffix is its own distinct product.
                def _prep_where_clause():
                    return 'upc = ? COLLATE NOCASE'
                def _prep_params():
                    return [base_upc]

            prep_notes = []
            prep_images = []
            prep_audio_rows = []
            prep_video_rows = []

            if base_upc:
                with db_connection('bol.db') as conn:
                    cur = conn.cursor()

                    # Notes (free-form) from Listing Manager / Item Prep
                    cur.execute(f'''
                        SELECT upc, id, note, created_at
                        FROM items_prep_notes
                        WHERE {_prep_where_clause()}
                        ORDER BY created_at DESC, id DESC
                        LIMIT 25
                    ''', _prep_params())
                    prep_notes = [dict(r) for r in cur.fetchall()]

                    # Fallback: if no note bubbles exist, use the status.note (single field) if present.
                    if not prep_notes:
                        cur.execute(f'''
                            SELECT upc, note, updated_at
                            FROM items_prep_status
                            WHERE ({_prep_where_clause()})
                              AND note IS NOT NULL
                              AND TRIM(note) != ''
                            ORDER BY COALESCE(updated_at, '') DESC
                            LIMIT 1
                        ''', _prep_params())
                        sn = cur.fetchone()
                        if sn and (sn['note'] or '').strip():
                            prep_notes = [{
                                'upc': sn['upc'],
                                'id': None,
                                'note': sn['note'],
                                'created_at': sn['updated_at'] or ''
                            }]

                    # Photos from Listing Manager / Item Prep
                    cur.execute(f'''
                        SELECT upc, id, image_path, created_at, rotation
                        FROM items_prep_images
                        WHERE ({_prep_where_clause()})
                          AND (deleted_at IS NULL OR TRIM(COALESCE(deleted_at,'')) = '')
                        ORDER BY created_at DESC, id DESC
                        LIMIT 30
                    ''', _prep_params())
                    prep_images = [dict(r) for r in cur.fetchall()]

                    # Voice notes (audio) from items_prep_media
                    try:
                        cur.execute(f'''
                            SELECT id, upc, COALESCE(row_status,'') AS row_status,
                                   media_type, file_path, COALESCE(mime_type,'') AS mime_type, created_at
                            FROM items_prep_media
                            WHERE ({_prep_where_clause()})
                              AND COALESCE(media_type,'') = 'audio'
                            ORDER BY created_at DESC, id DESC
                            LIMIT 10
                        ''', _prep_params())
                        prep_audio_rows = [dict(r) for r in cur.fetchall()]
                    except Exception:
                        prep_audio_rows = []

                    try:
                        cur.execute(f'''
                            SELECT id, upc, COALESCE(row_status,'') AS row_status,
                                   media_type, file_path, COALESCE(mime_type,'') AS mime_type, created_at
                            FROM items_prep_media
                            WHERE ({_prep_where_clause()})
                              AND COALESCE(media_type,'') = 'video'
                            ORDER BY created_at DESC, id DESC
                            LIMIT 10
                        ''', _prep_params())
                        prep_video_rows = [dict(r) for r in cur.fetchall()]
                    except Exception:
                        prep_video_rows = []

                base_url = (request.url_root or '').rstrip('/')
                prep_urls = []
                for pr in prep_images:
                    rel = (pr.get('image_path') or '').strip()
                    if not rel:
                        continue
                    url = f"{base_url}{url_for('static', filename=rel)}"
                    if url and url not in prep_urls:
                        prep_urls.append(url)

                prep_voice_notes = []
                for ar in prep_audio_rows:
                    rel = (ar.get('file_path') or '').strip()
                    if not rel:
                        continue
                    url = f"{base_url}{url_for('static', filename=rel)}"
                    prep_voice_notes.append({
                        'id': ar.get('id'),
                        'upc': ar.get('upc', ''),
                        'url': url,
                        'mime_type': ar.get('mime_type', ''),
                        'created_at': ar.get('created_at', '')
                    })

                prep_videos = []
                for vr in prep_video_rows:
                    rel = (vr.get('file_path') or '').strip()
                    if not rel:
                        continue
                    url = f"{base_url}{url_for('static', filename=rel)}"
                    prep_videos.append({
                        'id': vr.get('id'),
                        'upc': vr.get('upc', ''),
                        'url': url,
                        'mime_type': vr.get('mime_type', ''),
                        'created_at': vr.get('created_at', '')
                    })

                if prep_urls:
                    # Prefer prep photos ahead of marketplace images, but keep existing order otherwise.
                    merged = []
                    for u in prep_urls + (item.get('images') or []):
                        if not u:
                            continue
                        if u not in merged:
                            merged.append(u)
                    item['images'] = merged

                item['prep'] = {'notes': prep_notes, 'images': prep_urls, 'voice_notes': prep_voice_notes, 'videos': prep_videos}
        except Exception:
            # Item prep tables may not exist in some envs; ignore.
            item['prep'] = {'notes': [], 'images': [], 'voice_notes': [], 'videos': []}

        # Checker requests, notes, and media (listagent.db)
        try:
            checker_req = _listagent_get_check_request(upc)
            checker_notes = _listagent_get_check_notes(upc)
            checker_media_rows = _listagent_get_check_media(upc)
            base = (request.url_root or '').rstrip('/')
            checker_media = []
            for mr in checker_media_rows:
                rel = (mr.get('file_path') or '').strip()
                if not rel:
                    continue
                checker_media.append({
                    'id': mr.get('id'),
                    'upc': mr.get('upc') or '',
                    'url': f"{base}{url_for('static', filename=rel)}",
                    'file_path': rel,
                    'media_type': (mr.get('media_type') or 'image').strip().lower() or 'image',
                    'original_filename': mr.get('original_filename') or '',
                    'size_bytes': mr.get('size_bytes'),
                    'note_type': (mr.get('note_type') or 'checker').strip().lower() or 'checker',
                    'created_at': mr.get('created_at') or ''
                })
            item['checker'] = {
                'request': checker_req,
                'notes': checker_notes,
                'media': checker_media
            }
        except Exception:
            item['checker'] = {'request': None, 'notes': [], 'media': []}

        # Listing Agent uploaded photos (from listagent.db) — prefer these first.
        try:
            photo_rows = _listagent_get_photos(upc, limit=30)
            base = (request.url_root or '').rstrip('/')
            has_macy_image = any(_listagent_is_macy_image_url(img, origin_base=base) for img in (item.get('images') or []))
            uploaded_urls = []
            for pr in photo_rows:
                rel = (pr.get('image_path') or '').strip()
                if not rel:
                    continue
                url = f"{base}{url_for('static', filename=rel)}"
                if url and url not in item['images']:
                    uploaded_urls.append(url)
            if uploaded_urls:
                if has_macy_image:
                    item['images'] = item['images'] + uploaded_urls
                else:
                    item['images'] = uploaded_urls + item['images']
        except Exception:
            pass

        try:
            base = (request.url_root or '').rstrip('/')
            item['images'] = _listagent_prioritize_macy_thumbnail(item.get('images') or [], origin_base=base)
        except Exception:
            pass

        # sold stats (optional)
        with db_connection('sold.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT COUNT(*) AS cnt,
                       AVG(price) AS avg_price,
                       MIN(price) AS min_price,
                       MAX(price) AS max_price,
                       MAX(paid_time) AS last_sold
                FROM orders
                WHERE TRIM(barcode) = ? COLLATE NOCASE
                  AND price IS NOT NULL
                  AND price > 0
            ''', (upc,))
            r = cur.fetchone()
            if r and (r['cnt'] or 0) > 0:
                item['sold_stats'] = {
                    'count': int(r['cnt'] or 0),
                    'avg_price': float(r['avg_price'] or 0),
                    'min_price': float(r['min_price'] or 0),
                    'max_price': float(r['max_price'] or 0),
                    'last_sold': r['last_sold'] or ''
                }

        # Prep qty from items-to-list (matches what /items-to-list page shows)
        try:
            prep_stats = _ready_to_ship_items_to_list_stats_for_barcode(upc)
            item['prep_qty'] = prep_stats.get('prepped_qty', 0)
        except Exception:
            item['prep_qty'] = None

        return jsonify({'success': True, 'item': item})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:upc_detail')}), 500

def _ebay_api_request(method, path, *, params=None, payload=None, timeout=30):
    token = get_access_token()  # refreshes if expired
    headers_local = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Content-Language': 'en-US'
    }
    url = f"https://api.ebay.com{path}"
    resp = requests.request(method, url, headers=headers_local, params=params, json=payload, timeout=timeout)
    return resp

def _ebay_extract_error(resp):
    try:
        data = resp.json()
        # Common eBay error schema: { errors: [ {message, errorId, ...} ] }
        errors = data.get('errors') if isinstance(data, dict) else None
        if errors and isinstance(errors, list):
            first = errors[0] or {}
            msg = first.get('message') or first.get('longMessage') or json.dumps(first)
            return f"eBay API error ({resp.status_code}): {msg}"
        if isinstance(data, dict) and data.get('message'):
            return f"eBay API error ({resp.status_code}): {data.get('message')}"
        return f"eBay API error ({resp.status_code}): {resp.text[:300]}"
    except Exception:
        return f"eBay API error ({resp.status_code}): {resp.text[:300]}"

def _extract_missing_ebay_aspect(error_text):
    """
    Best-effort parser for eBay errors like:
    'The item specific Brand is missing...'
    Returns the aspect name (e.g. 'Brand') or ''.
    """
    s = (error_text or '').strip()
    if not s:
        return ''
    low = s.lower()
    marker = 'item specific '
    end_marker = ' is missing'
    i = low.find(marker)
    if i >= 0:
        j = low.find(end_marker, i + len(marker))
        if j > i:
            raw = s[i + len(marker):j].strip(" .:;,-")
            if raw:
                return raw
    # Fallback pattern: "Add Brand to this listing..."
    marker2 = 'add '
    marker3 = ' to this listing'
    i2 = low.find(marker2)
    if i2 >= 0:
        j2 = low.find(marker3, i2 + len(marker2))
        if j2 > i2:
            raw2 = s[i2 + len(marker2):j2].strip(" .:;,-")
            if raw2:
                return raw2
    return ''

@app.route('/api/listingagent/ebay/locations', methods=['GET'])
def api_listingagent_ebay_locations():
    """Fetch inventory locations (locationKey) from eBay (requires sell.inventory scope)."""
    try:
        force_refresh = (request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes')
        locations = _listingagent_get_ebay_locations(force_refresh=force_refresh)
        return jsonify({
            'success': True,
            'data': {
                'locations': locations,
                'total': len(locations),
            }
        })
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_locations')}), 500

_LISTINGAGENT_EBAY_POLICIES_CACHE = {}
_LISTINGAGENT_EBAY_POLICIES_LOCK = threading.Lock()
_LISTINGAGENT_EBAY_LOCATIONS_CACHE = {'ts': 0.0, 'keys': [], 'locations': []}
_LISTINGAGENT_EBAY_LOCATIONS_LOCK = threading.Lock()
_LISTINGAGENT_EBAY_CONDITIONS_CACHE = {}
_LISTINGAGENT_EBAY_CONDITIONS_LOCK = threading.Lock()
_LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE = {}
_LISTINGAGENT_AMAZON_RESTRICTIONS_LOCK = threading.Lock()
_LISTINGAGENT_AMAZON_RESTRICTIONS_TTL = 300

def _listingagent_get_ebay_business_policies(marketplace_id: str):
    """Fetch eBay business policies (fulfillment/payment/return). Cached in-memory."""
    marketplace_id = (marketplace_id or 'EBAY_US').strip() or 'EBAY_US'
    cache_key = marketplace_id
    now = time.time()

    cached = _LISTINGAGENT_EBAY_POLICIES_CACHE.get(cache_key)
    if cached and (now - float(cached.get('ts') or 0)) < 6 * 3600:
        return cached.get('data') or {}

    def _fetch(path):
        # Sell Account API endpoints only take marketplace_id; passing unknown params can 400.
        resp = _ebay_api_request('GET', path, params={'marketplace_id': marketplace_id})
        if resp.status_code == 403:
            # Most common cause: missing OAuth scope for Sell Account API.
            raise _ListingAgentUserError(
                "eBay API error (403): Forbidden. Your eBay OAuth token likely does not include the "
                "`sell.account` scope required to load business policies. Re-authorize your eBay app "
                "with `https://api.ebay.com/oauth/api_scope/sell.account` (or "
                "`https://api.ebay.com/oauth/api_scope/sell.account.readonly`) and regenerate "
                "`tokens.json`.",
                status_code=400,
                extra={'needs_scope': 'sell.account'}
            )
        if resp.status_code == 401:
            raise _ListingAgentUserError(
                "eBay API error (401): Unauthorized. Your token may be expired or invalid. "
                "Try re-authorizing and regenerating `tokens.json`.",
                status_code=400
            )
        if resp.status_code >= 400:
            raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)
        return resp.json() if resp.text else {}

    with _LISTINGAGENT_EBAY_POLICIES_LOCK:
        cached = _LISTINGAGENT_EBAY_POLICIES_CACHE.get(cache_key)
        now = time.time()
        if cached and (now - float(cached.get('ts') or 0)) < 6 * 3600:
            return cached.get('data') or {}

        ful = _fetch('/sell/account/v1/fulfillment_policy')
        pay = _fetch('/sell/account/v1/payment_policy')
        ret = _fetch('/sell/account/v1/return_policy')

        def _norm_list(payload, list_key, id_key):
            items = payload.get(list_key) or payload.get(list_key[0].upper() + list_key[1:]) or []
            out = []
            if isinstance(items, list):
                for it in items:
                    if not isinstance(it, dict):
                        continue
                    pid = (it.get(id_key) or it.get(id_key[0].lower() + id_key[1:]) or '').strip()
                    if not pid:
                        continue
                    name = (it.get('name') or it.get('policyName') or it.get('policy_name') or '').strip()
                    out.append({
                        'id': pid,
                        'name': name or pid,
                        'categoryTypes': it.get('categoryTypes') or it.get('category_types') or [],
                    })
            out.sort(key=lambda x: (x.get('name') or '').lower())
            return out

        data = {
            'fulfillment': _norm_list(ful, 'fulfillmentPolicies', 'fulfillmentPolicyId'),
            'payment': _norm_list(pay, 'paymentPolicies', 'paymentPolicyId'),
            'returns': _norm_list(ret, 'returnPolicies', 'returnPolicyId'),
        }

        _LISTINGAGENT_EBAY_POLICIES_CACHE[cache_key] = {'ts': now, 'data': data}
        return data

def _listingagent_get_ebay_locations(*, force_refresh=False):
    """Fetch seller inventory locations from eBay Inventory API and cache them in-memory."""
    now = time.time()
    cached = _LISTINGAGENT_EBAY_LOCATIONS_CACHE
    if (not force_refresh) and cached.get('locations') and (now - float(cached.get('ts') or 0)) < 10 * 60:
        return [dict(loc) for loc in (cached.get('locations') or [])]

    with _LISTINGAGENT_EBAY_LOCATIONS_LOCK:
        cached = _LISTINGAGENT_EBAY_LOCATIONS_CACHE
        if (not force_refresh) and cached.get('locations') and (now - float(cached.get('ts') or 0)) < 10 * 60:
            return [dict(loc) for loc in (cached.get('locations') or [])]

        locations_out = []
        keys = []
        offset = 0
        limit = 200
        seen = set()
        # Inventory API pagination via offset/limit
        for _ in range(5):
            resp = _ebay_api_request('GET', '/sell/inventory/v1/location', params={'limit': limit, 'offset': offset})
            if resp.status_code >= 400:
                raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)
            payload = resp.json() if resp.text else {}
            locations = payload.get('locations') or payload.get('Locations') or []
            if not isinstance(locations, list) or not locations:
                break
            for loc in locations:
                if not isinstance(loc, dict):
                    continue
                key = (loc.get('merchantLocationKey') or loc.get('locationKey') or '').strip()
                if not key or key in seen:
                    continue
                seen.add(key)
                keys.append(key)
                normalized = dict(loc)
                if not (normalized.get('locationKey') or '').strip():
                    normalized['locationKey'] = key
                if not (normalized.get('merchantLocationKey') or '').strip():
                    normalized['merchantLocationKey'] = key
                locations_out.append(normalized)
            if len(locations) < limit:
                break
            offset += limit

        _LISTINGAGENT_EBAY_LOCATIONS_CACHE['ts'] = time.time()
        _LISTINGAGENT_EBAY_LOCATIONS_CACHE['keys'] = list(keys)
        _LISTINGAGENT_EBAY_LOCATIONS_CACHE['locations'] = [dict(loc) for loc in locations_out]
        return [dict(loc) for loc in locations_out]

def _listingagent_get_ebay_location_keys(*, force_refresh=False):
    """Fetch seller inventory location keys from eBay Inventory API."""
    locations = _listingagent_get_ebay_locations(force_refresh=force_refresh)
    return [
        (loc.get('merchantLocationKey') or loc.get('locationKey') or '').strip()
        for loc in locations
        if (loc.get('merchantLocationKey') or loc.get('locationKey') or '').strip()
    ]

def _listingagent_resolve_ebay_location_key(preferred_key, *, force_refresh=False):
    """
    Resolve a usable merchant location key.
    Returns: (resolved_key, auto_fixed_bool, all_keys)
    """
    preferred = (preferred_key or '').strip()
    keys = _listingagent_get_ebay_location_keys(force_refresh=force_refresh)
    if not keys:
        raise _ListingAgentUserError(
            "No eBay inventory locations found. Create one in eBay Seller Hub (Inventory Locations), then retry.",
            status_code=400,
            extra={'needs_setup': 'ebay_inventory_location'}
        )
    key_set = {k.lower(): k for k in keys}
    if preferred and preferred.lower() in key_set:
        return key_set[preferred.lower()], False, keys
    return keys[0], True, keys

