@app.route('/api/listingagent/ebay/offers_for_sku', methods=['GET'])
def api_listingagent_ebay_offers_for_sku():
    """Lookup Inventory offers for a SKU (helps edit existing listings)."""
    try:
        sku = (request.args.get('sku') or '').strip()
        if not sku:
            return jsonify({'success': False, 'error': 'sku is required'}), 400

        include_raw = (request.args.get('raw') or '').lower() == 'true'
        resp = _ebay_api_request('GET', '/sell/inventory/v1/offer', params={'sku': sku, 'limit': 50})
        if resp.status_code >= 400:
            return jsonify({'success': False, 'error': _ebay_extract_error(resp)}), 400

        payload = resp.json() if resp.text else {}
        offers = payload.get('offers') or payload.get('Offers') or []
        results = []
        if isinstance(offers, list):
            for o in offers:
                if not isinstance(o, dict):
                    continue
                results.append({
                    'offerId': o.get('offerId') or o.get('offer_id') or '',
                    'listingId': o.get('listingId') or o.get('listing_id') or '',
                    'marketplaceId': o.get('marketplaceId') or o.get('marketplace_id') or '',
                    'status': o.get('status') or '',
                    'format': o.get('format') or '',
                    'availableQuantity': o.get('availableQuantity') if o.get('availableQuantity') is not None else o.get('available_quantity'),
                    'categoryId': o.get('categoryId') or o.get('category_id') or '',
                    'pricingSummary': o.get('pricingSummary') or o.get('pricing_summary') or {},
                })

        out = {'success': True, 'data': {'sku': sku, 'offers': results}}
        if include_raw:
            out['raw'] = payload
        return jsonify(out)
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_offers_for_sku')}), 500

def _listingagent_is_ebay_eps_url(url: str) -> bool:
    """
    eBay EPS-hosted image URLs are typically on ebayimg/ebaystatic domains.
    """
    s = (url or '').strip()
    if not s:
        return False
    try:
        from urllib.parse import urlparse
        u = urlparse(s)
        host = (u.netloc or '').lower()
        if ('ebayimg.com' in host) or ('ebaystatic.com' in host):
            return True
        # Catch proxied/encoded EPS URLs where host is not directly ebayimg.
        low = s.lower()
        return ('ebayimg.com' in low) or ('ebaystatic.com' in low)
    except Exception:
        low = s.lower()
        return ('ebayimg.com' in low) or ('ebaystatic.com' in low)

def _listingagent_is_amazon_image_url(url: str) -> bool:
    """
    Amazon-hosted catalog/listing image host detection.
    """
    try:
        from urllib.parse import urlparse
        u = urlparse((url or '').strip())
        host = (u.netloc or '').lower()
        path = (u.path or '').lower()
        return (
            ('media-amazon.com' in host)
            or ('ssl-images-amazon' in host)
            or ('images-na.ssl-images-amazon' in host)
            or ('images-amazon' in host)
            or (('amazon.' in host) and ('/images/' in path))
        )
    except Exception:
        return False

def _listingagent_dedupe_image_urls(images):
    urls = [i.strip() for i in (images or []) if isinstance(i, str) and i.strip()]
    deduped = []
    seen = set()
    for u in urls:
        if u in seen:
            continue
        seen.add(u)
        deduped.append(u)
    return deduped

def _listingagent_has_mixed_ebay_image_sources(images):
    urls = _listingagent_dedupe_image_urls(images)
    eps = [u for u in urls if _listingagent_is_ebay_eps_url(u)]
    non_eps = [u for u in urls if not _listingagent_is_ebay_eps_url(u)]
    return bool(eps and non_eps)

def _listingagent_prefer_single_ebay_image_source(images):
    """
    Fallback selector when eBay rejects mixed EPS + non-EPS image sets.
    """
    urls = _listingagent_dedupe_image_urls(images)
    eps = [u for u in urls if _listingagent_is_ebay_eps_url(u)]
    non_eps = [u for u in urls if not _listingagent_is_ebay_eps_url(u)]
    if not eps or not non_eps:
        return urls
    # Prefer self-hosted/non-EPS when mixed so local/uploaded images win.
    return non_eps

def _listingagent_is_likely_ebay_image_mix_error(error_text: str) -> bool:
    s = (error_text or '').strip().lower()
    if not s:
        return False
    if not any(k in s for k in ('image', 'picture', 'imageurl', 'image urls')):
        return False
    return any(k in s for k in (
        'only one',
        'one type',
        'mixed',
        'self-hosted',
        'self hosted',
        'not supported',
        'not allowed',
        'invalid'
    ))

def _build_ebay_inventory_item_payload(upc, title, description, images, quantity, condition, *, aspects=None, epid='', condition_description=''):
    images = _listingagent_dedupe_image_urls(images)

    # Remove Amazon-hosted images for eBay listings when other candidates exist.
    non_amazon_images = [u for u in images if not _listingagent_is_amazon_image_url(u)]
    if non_amazon_images:
        images = non_amazon_images

    # eBay does not allow mixing EPS and self-hosted image URLs in one listing.
    # Prefer self-hosted/non-EPS when mixed.
    non_eps_images = [u for u in images if not _listingagent_is_ebay_eps_url(u)]
    if non_eps_images and len(non_eps_images) != len(images):
        images = non_eps_images

    # eBay limits imageUrls to 12
    images = images[:12]
    payload = {
        'availability': {
            'shipToLocationAvailability': {
                'quantity': int(quantity or 1)
            }
        },
        'condition': condition or 'USED_GOOD',
        'product': {
            'title': title or upc,
            'description': description or (title or upc),
            'upc': [upc],
        }
    }
    if images:
        payload['product']['imageUrls'] = images
    epid = str(epid or '').strip()
    if epid:
        payload['product']['epid'] = epid
    condition_description = str(condition_description or '').strip()
    if condition_description:
        payload['conditionDescription'] = condition_description
    if aspects and isinstance(aspects, dict):
        clean = {}
        for k, v in aspects.items():
            name = str(k or '').strip()
            if not name:
                continue
            vals = []
            if isinstance(v, str):
                vals = [v.strip()]
            elif isinstance(v, (list, tuple)):
                vals = [str(x).strip() for x in v if str(x).strip()]
            elif v is not None:
                vals = [str(v).strip()]
            vals = [x for x in vals if x]
            if vals:
                clean[name] = vals[:20]
        if clean:
            payload['product']['aspects'] = clean
    return payload

def _build_ebay_offer_payload(sku, marketplace_id, currency, price, quantity, category_id, listing_description,
                             merchant_location_key, fulfillment_policy_id, payment_policy_id, return_policy_id,
                             listing_duration='GTC', format_='FIXED_PRICE'):
    payload = {
        'sku': sku,
        'marketplaceId': marketplace_id,
        'format': format_,
    }
    if quantity is not None:
        payload['availableQuantity'] = int(quantity)
    if listing_duration:
        payload['listingDuration'] = listing_duration
    if category_id:
        payload['categoryId'] = str(category_id)
    if listing_description:
        payload['listingDescription'] = listing_description
    if merchant_location_key:
        payload['merchantLocationKey'] = str(merchant_location_key)
    if price is not None:
        payload['pricingSummary'] = {
            'price': {'currency': currency or 'USD', 'value': f"{float(price):.2f}"}
        }
    policies = {}
    if fulfillment_policy_id:
        policies['fulfillmentPolicyId'] = str(fulfillment_policy_id)
    if payment_policy_id:
        policies['paymentPolicyId'] = str(payment_policy_id)
    if return_policy_id:
        policies['returnPolicyId'] = str(return_policy_id)
    if policies:
        payload['listingPolicies'] = policies
    # Let eBay enrich if it can match a catalog product
    payload['includeCatalogProductDetails'] = True
    return payload

def _listingagent_find_existing_offer_for_sku(sku: str, marketplace_id: str = ''):
    """Find an existing offer for a SKU and optionally filter by marketplace."""
    sku = (sku or '').strip()
    marketplace_id = (marketplace_id or '').strip()
    if not sku:
        return None
    resp = _ebay_api_request('GET', '/sell/inventory/v1/offer', params={'sku': sku, 'limit': 50})
    if resp.status_code >= 400:
        return None
    payload = resp.json() if resp.text else {}
    offers = payload.get('offers') or payload.get('Offers') or []
    if not isinstance(offers, list):
        return None

    scored = []
    for o in offers:
        if not isinstance(o, dict):
            continue
        offer_id = (o.get('offerId') or o.get('offer_id') or '').strip()
        if not offer_id:
            continue
        mp = (o.get('marketplaceId') or o.get('marketplace_id') or '').strip()
        if marketplace_id and mp and mp != marketplace_id:
            continue
        status = (o.get('status') or '').strip().upper()
        score = 0
        if status == 'UNPUBLISHED':
            score = 3
        elif status == 'PUBLISHED':
            score = 2
        elif status:
            score = 1
        scored.append((score, o))
    if not scored:
        return None
    scored.sort(key=lambda x: x[0], reverse=True)
    return scored[0][1]

def _listingagent_condition_enum_from_policy(condition_id, condition_desc=''):
    cid = str(condition_id or '').strip()
    cdesc = (condition_desc or '').strip().lower()
    direct = {
        '1000': 'NEW',
        '1500': 'NEW_OTHER',
        '1750': 'NEW_WITH_DEFECTS',
        '2000': 'CERTIFIED_REFURBISHED',
        '2010': 'EXCELLENT_REFURBISHED',
        '2020': 'VERY_GOOD_REFURBISHED',
        '2030': 'GOOD_REFURBISHED',
        '2500': 'SELLER_REFURBISHED',
        '2750': 'LIKE_NEW',
        '3000': 'USED_EXCELLENT',
        '4000': 'USED_VERY_GOOD',
        '5000': 'USED_GOOD',
        '6000': 'USED_ACCEPTABLE',
        '7000': 'FOR_PARTS_OR_NOT_WORKING',
    }
    if cid in direct:
        return direct[cid]

    # Fallback by description text when id is unknown/new.
    if ('for parts' in cdesc) or ('not working' in cdesc):
        return 'FOR_PARTS_OR_NOT_WORKING'
    if 'certified refurbished' in cdesc:
        return 'CERTIFIED_REFURBISHED'
    if 'seller refurbished' in cdesc:
        return 'SELLER_REFURBISHED'
    if ('refurbished' in cdesc) and ('excellent' in cdesc):
        return 'EXCELLENT_REFURBISHED'
    if ('refurbished' in cdesc) and ('very good' in cdesc):
        return 'VERY_GOOD_REFURBISHED'
    if ('refurbished' in cdesc) and ('good' in cdesc):
        return 'GOOD_REFURBISHED'
    if ('new with defects' in cdesc) or ('new w/ defects' in cdesc):
        return 'NEW_WITH_DEFECTS'
    if ('new other' in cdesc) or ('open box' in cdesc):
        return 'NEW_OTHER'
    if 'like new' in cdesc:
        return 'LIKE_NEW'
    if 'excellent' in cdesc:
        return 'USED_EXCELLENT'
    if 'very good' in cdesc:
        return 'USED_VERY_GOOD'
    if 'acceptable' in cdesc:
        return 'USED_ACCEPTABLE'
    if 'good' in cdesc:
        return 'USED_GOOD'
    if 'new' in cdesc:
        return 'NEW'
    if 'used' in cdesc:
        return 'USED_GOOD'
    return ''

def _listingagent_get_ebay_allowed_condition_enums(category_id: str, marketplace_id: str):
    category_id = (category_id or '').strip()
    marketplace_id = (marketplace_id or 'EBAY_US').strip() or 'EBAY_US'
    if not category_id:
        return []

    cache_key = f'{marketplace_id}|{category_id}'
    now = time.time()
    cached = _LISTINGAGENT_EBAY_CONDITIONS_CACHE.get(cache_key)
    if cached and (now - float(cached.get('ts') or 0)) < 12 * 3600:
        return list(cached.get('data') or [])

    with _LISTINGAGENT_EBAY_CONDITIONS_LOCK:
        cached = _LISTINGAGENT_EBAY_CONDITIONS_CACHE.get(cache_key)
        now = time.time()
        if cached and (now - float(cached.get('ts') or 0)) < 12 * 3600:
            return list(cached.get('data') or [])

        out = []
        seen = set()
        try:
            resp = _ebay_api_request(
                'GET',
                f'/sell/metadata/v1/marketplace/{marketplace_id}/get_item_condition_policies',
                params={'filter': f'categoryIds:{{{category_id}}}'}
            )
            if resp.status_code < 400:
                payload = resp.json() if resp.text else {}
                policies = payload.get('itemConditionPolicies') or payload.get('item_condition_policies') or []
                if isinstance(policies, list):
                    for p in policies:
                        if not isinstance(p, dict):
                            continue
                        cat = str(p.get('categoryId') or p.get('category_id') or '').strip()
                        if cat and cat != category_id:
                            continue
                        conds = p.get('itemConditions') or p.get('item_conditions') or []
                        if not isinstance(conds, list):
                            continue
                        for c in conds:
                            if not isinstance(c, dict):
                                continue
                            enum_val = _listingagent_condition_enum_from_policy(
                                c.get('conditionId') or c.get('condition_id') or '',
                                c.get('conditionDescription') or c.get('condition_description') or ''
                            )
                            if enum_val and enum_val not in seen:
                                seen.add(enum_val)
                                out.append(enum_val)
        except Exception:
            out = []

        _LISTINGAGENT_EBAY_CONDITIONS_CACHE[cache_key] = {'ts': time.time(), 'data': list(out)}
        return list(out)

def _listingagent_get_condition_candidates(current_condition='', *, category_id='', marketplace_id=''):
    default_order = [
        'NEW',
        'LIKE_NEW',
        'NEW_OTHER',
        'NEW_WITH_DEFECTS',
        'CERTIFIED_REFURBISHED',
        'EXCELLENT_REFURBISHED',
        'VERY_GOOD_REFURBISHED',
        'GOOD_REFURBISHED',
        'SELLER_REFURBISHED',
        'USED_EXCELLENT',
        'USED_VERY_GOOD',
        'USED_GOOD',
        'USED_ACCEPTABLE',
        'FOR_PARTS_OR_NOT_WORKING',
    ]
    allowed = _listingagent_get_ebay_allowed_condition_enums(category_id, marketplace_id)
    out = []
    seen = set()

    def _add(v):
        vv = (v or '').strip().upper()
        if not vv or vv in seen:
            return
        seen.add(vv)
        out.append(vv)

    _add(current_condition)
    for c in allowed:
        _add(c)
    for c in default_order:
        _add(c)
    return out

def _listingagent_put_inventory_item_with_condition_fallback(sku: str, inventory_item_payload: dict, *, category_id='', marketplace_id=''):
    """
    PUT inventory item and auto-retry with fallback conditions when category rejects condition.
    Returns: (resolved_payload, condition_autofixed_bool, original_condition, tried_conditions)
    """
    from urllib.parse import quote
    sku_encoded = quote((sku or '').strip(), safe='')
    payload = dict(inventory_item_payload or {})
    original_condition = (payload.get('condition') or '').strip()
    condition_autofixed = False
    tried = []

    resp_item = _ebay_api_request('PUT', f'/sell/inventory/v1/inventory_item/{sku_encoded}', payload=payload)
    if resp_item.status_code < 400:
        return payload, condition_autofixed, original_condition, tried

    err_item = _ebay_extract_error(resp_item)
    err_item_l = err_item.lower()
    if ('invalid item condition information' not in err_item_l) and ('condition id is invalid' not in err_item_l):
        # If mixed EPS + non-EPS images trigger a rejection, retry once with a single source set.
        product_obj = payload.get('product') if isinstance(payload.get('product'), dict) else {}
        image_urls = _listingagent_dedupe_image_urls((product_obj or {}).get('imageUrls') or [])
        if image_urls and _listingagent_has_mixed_ebay_image_sources(image_urls) and _listingagent_is_likely_ebay_image_mix_error(err_item):
            fallback_images = _listingagent_prefer_single_ebay_image_source(image_urls)[:12]
            if fallback_images and fallback_images != image_urls:
                retry_payload = dict(payload)
                product_retry = dict(product_obj or {})
                product_retry['imageUrls'] = fallback_images
                retry_payload['product'] = product_retry
                resp_item_retry = _ebay_api_request('PUT', f'/sell/inventory/v1/inventory_item/{sku_encoded}', payload=retry_payload)
                if resp_item_retry.status_code < 400:
                    payload = retry_payload
                    return payload, condition_autofixed, original_condition, tried
                err_item = _ebay_extract_error(resp_item_retry)

        missing_aspect = _extract_missing_ebay_aspect(err_item)
        raise _ListingAgentUserError(
            err_item,
            status_code=400,
            extra={'inventoryItem': payload, 'missingAspect': missing_aspect}
        )

    # Prefer category-allowed condition candidates from metadata; fall back to defaults.
    fallback_conditions = _listingagent_get_condition_candidates(
        payload.get('condition') or '',
        category_id=category_id,
        marketplace_id=marketplace_id
    )
    current = (payload.get('condition') or '').strip().upper()
    if current:
        tried.append(current)
    for cond in fallback_conditions:
        if cond == current:
            continue
        retry_payload = dict(payload)
        retry_payload['condition'] = cond
        resp_item_retry = _ebay_api_request('PUT', f'/sell/inventory/v1/inventory_item/{sku_encoded}', payload=retry_payload)
        if resp_item_retry.status_code < 400:
            payload = retry_payload
            condition_autofixed = True
            return payload, condition_autofixed, original_condition, tried
        tried.append(cond)

    missing_aspect = _extract_missing_ebay_aspect(err_item)
    raise _ListingAgentUserError(
        err_item,
        status_code=400,
        extra={
            'inventoryItem': payload,
            'conditionTried': tried,
            'missingAspect': missing_aspect
        }
    )

class _ListingAgentUserError(Exception):
    def __init__(self, message, status_code=400, extra=None):
        super().__init__(message)
        self.status_code = status_code
        self.extra = extra or {}

# eBay Buy/Browse requires an application token (client_credentials). We keep a simple in-memory cache
# to avoid re-auth on every request. This does not touch tokens.json (which is used for Sell APIs).
_LISTINGAGENT_EBAY_APP_TOKEN = {'access_token': None, 'expires_at': 0.0, 'scope': ''}
_LISTINGAGENT_EBAY_APP_TOKEN_LOCK = threading.Lock()

def _listingagent_get_ebay_app_token(scope=None):
    scope = (scope or os.getenv('EBAY_BUY_SCOPE') or 'https://api.ebay.com/oauth/api_scope').strip()
    now = time.time()
    cached = _LISTINGAGENT_EBAY_APP_TOKEN
    if cached.get('access_token') and cached.get('scope') == scope and now < float(cached.get('expires_at') or 0) - 60:
        return cached['access_token']

    if not CLIENT_ID or not CLIENT_SECRET:
        raise _ListingAgentUserError('Missing EBAY_CLIENT_ID / EBAY_CLIENT_SECRET in environment (.env)', status_code=503)

    with _LISTINGAGENT_EBAY_APP_TOKEN_LOCK:
        cached = _LISTINGAGENT_EBAY_APP_TOKEN
        now = time.time()
        if cached.get('access_token') and cached.get('scope') == scope and now < float(cached.get('expires_at') or 0) - 60:
            return cached['access_token']

        encoded = base64.b64encode(f"{CLIENT_ID}:{CLIENT_SECRET}".encode('utf-8')).decode('utf-8')
        headers = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Authorization': f"Basic {encoded}",
        }
        data = {
            'grant_type': 'client_credentials',
            'scope': scope
        }
        resp = requests.post('https://api.ebay.com/identity/v1/oauth2/token', headers=headers, data=data, timeout=30)
        if resp.status_code >= 400:
            try:
                j = resp.json()
                msg = j.get('error_description') or j.get('error') or resp.text[:200]
            except Exception:
                msg = resp.text[:200]
            raise _ListingAgentUserError(f"eBay app token failed: {msg}", status_code=503)

        j = resp.json() if resp.text else {}
        access_token = (j.get('access_token') or '').strip()
        expires_in = int(j.get('expires_in') or 0)
        if not access_token:
            raise _ListingAgentUserError('eBay app token response missing access_token', status_code=503)

        _LISTINGAGENT_EBAY_APP_TOKEN.update({
            'access_token': access_token,
            'expires_at': time.time() + max(60, expires_in),
            'scope': scope
        })
        return access_token

def _ebay_buy_api_request(method, path, *, params=None, timeout=30, marketplace_id='EBAY_US', scope=None):
    token = _listingagent_get_ebay_app_token(scope=scope)
    headers_local = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Accept-Language': 'en-US',
        # Strongly recommended for Browse APIs.
        'X-EBAY-C-MARKETPLACE-ID': marketplace_id or 'EBAY_US',
    }
    url = f"https://api.ebay.com{path}"
    resp = requests.request(method, url, headers=headers_local, params=params, timeout=timeout)
    return resp

@app.route('/api/listingagent/ebay/comps', methods=['GET'])
def api_listingagent_ebay_comps():
    """Fetch live eBay marketplace comps by UPC (Buy Browse API)."""
    try:
        upc = (request.args.get('upc') or request.args.get('gtin') or '').strip()
        if not upc:
            raise _ListingAgentUserError('upc is required', status_code=400)

        limit = _listingagent_parse_int(request.args.get('limit'), 12) or 12
        limit = max(1, min(limit, 50))
        include_raw = (request.args.get('raw') or '').lower() == 'true'

        settings = _listingagent_get_settings()
        marketplace_id = (request.args.get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()
        sort = (request.args.get('sort') or '').strip()

        params = {'q': upc, 'limit': limit}
        if sort:
            params['sort'] = sort

        resp = _ebay_buy_api_request('GET', '/buy/browse/v1/item_summary/search', params=params, marketplace_id=marketplace_id)
        if resp.status_code >= 400:
            raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)

        payload = resp.json() if resp.text else {}
        items = payload.get('itemSummaries') or payload.get('item_summaries') or []

        results = []
        for it in items[:limit]:
            price = it.get('price') or {}

            # shipping cost (best-effort; often empty)
            shipping = None
            ship_opts = it.get('shippingOptions') or it.get('shipping_options') or []
            if ship_opts and isinstance(ship_opts, list):
                sc = (ship_opts[0] or {}).get('shippingCost') or (ship_opts[0] or {}).get('shipping_cost') or {}
                if isinstance(sc, dict) and sc.get('value') is not None:
                    shipping = {'value': sc.get('value'), 'currency': sc.get('currency')}

            image_url = ''
            img = it.get('image') or {}
            if isinstance(img, dict):
                image_url = (img.get('imageUrl') or img.get('image_url') or '').strip()
            if not image_url:
                thumbs = it.get('thumbnailImages') or it.get('thumbnail_images') or []
                if thumbs and isinstance(thumbs, list):
                    t0 = thumbs[0] or {}
                    if isinstance(t0, dict):
                        image_url = (t0.get('imageUrl') or t0.get('image_url') or '').strip()

            seller = ''
            seller_obj = it.get('seller') or {}
            if isinstance(seller_obj, dict):
                seller = (seller_obj.get('username') or '').strip()

            results.append({
                'itemId': it.get('itemId') or it.get('item_id') or '',
                'title': it.get('title') or '',
                'price': {'value': price.get('value'), 'currency': price.get('currency')},
                'shipping': shipping,
                'condition': it.get('condition') or '',
                'conditionId': it.get('conditionId') or it.get('condition_id') or '',
                'itemWebUrl': it.get('itemWebUrl') or it.get('item_web_url') or '',
                'image': image_url,
                'seller': seller,
                'buyingOptions': it.get('buyingOptions') or it.get('buying_options') or [],
            })

        out = {'success': True, 'total': payload.get('total') or len(results), 'results': results}
        if include_raw:
            out['raw'] = payload
        return jsonify(out)

    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_comps')}), 500

_LISTINGAGENT_EBAY_CATEGORY_TREE_ID = {}
_LISTINGAGENT_EBAY_CATEGORY_TREE_LOCK = threading.Lock()

def _listingagent_get_ebay_category_tree_id(marketplace_id: str):
    mp = (marketplace_id or 'EBAY_US').strip() or 'EBAY_US'
    cached = _LISTINGAGENT_EBAY_CATEGORY_TREE_ID.get(mp)
    if cached:
        return cached
    with _LISTINGAGENT_EBAY_CATEGORY_TREE_LOCK:
        cached = _LISTINGAGENT_EBAY_CATEGORY_TREE_ID.get(mp)
        if cached:
            return cached
        resp = _ebay_buy_api_request(
            'GET',
            '/commerce/taxonomy/v1/get_default_category_tree_id',
            params={'marketplace_id': mp},
            marketplace_id=mp,
            scope='https://api.ebay.com/oauth/api_scope'
        )
        if resp.status_code >= 400:
            raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)
        data = resp.json() if resp.text else {}
        tree_id = str(data.get('categoryTreeId') or data.get('category_tree_id') or '').strip()
        if not tree_id:
            raise _ListingAgentUserError('eBay taxonomy did not return categoryTreeId', status_code=502, extra={'raw': data})
        _LISTINGAGENT_EBAY_CATEGORY_TREE_ID[mp] = tree_id
        return tree_id

@app.route('/api/listingagent/ebay/category_suggestions', methods=['GET'])
def api_listingagent_ebay_category_suggestions():
    """Suggest eBay categories for a given query using Commerce Taxonomy API."""
    try:
        q = (request.args.get('q') or request.args.get('query') or '').strip()
        if not q:
            raise _ListingAgentUserError('q is required', status_code=400)

        limit = _listingagent_parse_int(request.args.get('limit'), 12) or 12
        limit = max(1, min(limit, 50))
        include_raw = (request.args.get('raw') or '').lower() == 'true'

        settings = _listingagent_get_settings()
        marketplace_id = (request.args.get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()

        category_tree_id = _listingagent_get_ebay_category_tree_id(marketplace_id)

        resp = _ebay_buy_api_request(
            'GET',
            f'/commerce/taxonomy/v1/category_tree/{category_tree_id}/get_category_suggestions',
            params={'q': q},
            marketplace_id=marketplace_id,
            scope='https://api.ebay.com/oauth/api_scope'
        )
        if resp.status_code >= 400:
            raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)

        payload = resp.json() if resp.text else {}
        suggestions = payload.get('categorySuggestions') or payload.get('category_suggestions') or []

        results = []
        for s in (suggestions or [])[:limit]:
            cat = s.get('category') or {}
            cat_id = str(cat.get('categoryId') or cat.get('category_id') or '').strip()
            cat_name = (cat.get('categoryName') or cat.get('category_name') or '').strip()

            ancestors = s.get('categoryTreeNodeAncestors') or s.get('category_tree_node_ancestors') or []
            path_parts = []
            if isinstance(ancestors, list):
                for a in ancestors:
                    if not isinstance(a, dict):
                        continue
                    nm = (a.get('categoryName') or a.get('category_name') or '').strip()
                    if nm:
                        path_parts.append(nm)
            if cat_name:
                path_parts.append(cat_name)
            path = ' > '.join(path_parts) if path_parts else cat_name

            relevancy = s.get('relevancy')
            try:
                relevancy = float(relevancy) if relevancy is not None else None
            except Exception:
                relevancy = None

            if not cat_id:
                continue
            results.append({
                'categoryId': cat_id,
                'categoryName': cat_name,
                'path': path or cat_name or cat_id,
                'relevancy': relevancy,
            })

        out = {
            'success': True,
            'marketplaceId': marketplace_id,
            'categoryTreeId': category_tree_id,
            'recommended': results[0] if results else None,
            'results': results,
        }
        if include_raw:
            out['raw'] = payload
        return jsonify(out)

    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_category_suggestions')}), 500

_LISTINGAGENT_EBAY_ASPECTS_CACHE = {}
_LISTINGAGENT_EBAY_ASPECTS_LOCK = threading.Lock()

def _listingagent_get_ebay_category_aspects(category_id: str, marketplace_id: str, *, values_limit: int = 140):
    """Fetch item aspects metadata for an eBay category (Commerce Taxonomy). Cached in-memory."""
    category_id = (category_id or '').strip()
    marketplace_id = (marketplace_id or 'EBAY_US').strip() or 'EBAY_US'
    values_limit = int(values_limit or 140)
    values_limit = max(0, min(values_limit, 5000))

    cache_key = (marketplace_id, category_id, values_limit)
    now = time.time()
    cached = _LISTINGAGENT_EBAY_ASPECTS_CACHE.get(cache_key)
    if cached and (now - float(cached.get('ts') or 0)) < 6 * 3600:
        return cached.get('data') or []

    with _LISTINGAGENT_EBAY_ASPECTS_LOCK:
        cached = _LISTINGAGENT_EBAY_ASPECTS_CACHE.get(cache_key)
        if cached and (now - float(cached.get('ts') or 0)) < 6 * 3600:
            return cached.get('data') or []

        category_tree_id = _listingagent_get_ebay_category_tree_id(marketplace_id)
        resp = _ebay_buy_api_request(
            'GET',
            f'/commerce/taxonomy/v1/category_tree/{category_tree_id}/get_item_aspects_for_category',
            params={'category_id': category_id},
            marketplace_id=marketplace_id,
            scope='https://api.ebay.com/oauth/api_scope'
        )
        if resp.status_code >= 400:
            raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=400)

        payload = resp.json() if resp.text else {}
        aspects = payload.get('aspects') or payload.get('Aspects') or []

        results = []
        if isinstance(aspects, list):
            for a in aspects:
                if not isinstance(a, dict):
                    continue
                name = (
                    a.get('aspectName')
                    or a.get('localizedAspectName')
                    or a.get('aspect_name')
                    or a.get('localized_aspect_name')
                    or ''
                ).strip()
                if not name:
                    continue
                constraint = a.get('aspectConstraint') or a.get('aspect_constraint') or {}
                if not isinstance(constraint, dict):
                    constraint = {}

                required = bool(constraint.get('aspectRequired') or constraint.get('aspect_required') or False)
                mode = (constraint.get('aspectMode') or constraint.get('aspect_mode') or '').strip()
                max_values = constraint.get('aspectMaxValues')
                if max_values is None:
                    max_values = constraint.get('aspect_max_values')
                try:
                    max_values = int(max_values) if max_values is not None else 1
                except Exception:
                    max_values = 1
                if max_values < 1:
                    max_values = 1

                values_raw = a.get('aspectValues') or a.get('aspect_values') or []
                values_count = len(values_raw) if isinstance(values_raw, list) else 0
                values = []
                if values_limit and isinstance(values_raw, list):
                    for v in values_raw[:values_limit]:
                        if not isinstance(v, dict):
                            continue
                        if isinstance(v, dict):
                            val = (
                                v.get('localizedAspectValue')
                                or v.get('localized_aspect_value')
                                or v.get('localizedValue')
                                or v.get('localized_value')
                                or v.get('value')
                                or ''
                            ).strip()
                        else:
                            val = str(v or '').strip()
                        if val and val not in values:
                            values.append(val)

                results.append({
                    'name': name,
                    'required': required,
                    'mode': mode,
                    'maxValues': max_values,
                    'values': values,
                    'valuesCount': values_count,
                    'valuesTruncated': bool(values_limit and values_count > len(values))
                })

        # Required first, then A-Z
        results.sort(key=lambda x: (0 if x.get('required') else 1, (x.get('name') or '').lower()))

        _LISTINGAGENT_EBAY_ASPECTS_CACHE[cache_key] = {'ts': now, 'data': results}
        return results

@app.route('/api/listingagent/ebay/category_aspects', methods=['GET'])
def api_listingagent_ebay_category_aspects():
    """Get eBay item specifics (aspects) for a categoryId (Commerce Taxonomy)."""
    try:
        category_id = (request.args.get('categoryId') or request.args.get('category_id') or '').strip()
        if not category_id:
            raise _ListingAgentUserError('categoryId is required', status_code=400)

        values_limit = _listingagent_parse_int(request.args.get('valuesLimit'), 140) or 140
        include_raw = (request.args.get('raw') or '').lower() == 'true'

        settings = _listingagent_get_settings()
        marketplace_id = (request.args.get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()

        aspects = _listingagent_get_ebay_category_aspects(category_id, marketplace_id, values_limit=values_limit)

        out = {
            'success': True,
            'marketplaceId': marketplace_id,
            'categoryId': category_id,
            'aspects': aspects
        }
        if include_raw:
            # Raw is not cached; fetch again with full payload when requested.
            category_tree_id = _listingagent_get_ebay_category_tree_id(marketplace_id)
            resp = _ebay_buy_api_request(
                'GET',
                f'/commerce/taxonomy/v1/category_tree/{category_tree_id}/get_item_aspects_for_category',
                params={'category_id': category_id},
                marketplace_id=marketplace_id,
                scope='https://api.ebay.com/oauth/api_scope'
            )
            out['raw'] = resp.json() if resp.text else {}
        return jsonify(out)
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_category_aspects')}), 500

def _ebay_catalog_aspects_to_dict(aspects_raw):
    """Normalise eBay catalog aspects to {name: first_value} across Catalog/Browse shapes."""
    out = {}
    if not aspects_raw:
        return out

    def _first_text(value):
        if value is None:
            return ''
        if isinstance(value, (list, tuple)):
            for item in value:
                text = _first_text(item)
                if text:
                    return text
            return ''
        if isinstance(value, dict):
            for key in (
                'localizedAspectValue',
                'localized_aspect_value',
                'localizedValue',
                'localized_value',
                'value',
                'name',
            ):
                text = str(value.get(key) or '').strip()
                if text:
                    return text
            return ''
        return str(value).strip()

    if isinstance(aspects_raw, dict):
        for k, v in aspects_raw.items():
            name = str(k or '').strip()
            val = _first_text(v)
            if name and val:
                out[name] = val
        return out

    if isinstance(aspects_raw, list):
        for item in aspects_raw:
            if not isinstance(item, dict):
                continue
            name = (
                item.get('localizedAspectName')
                or item.get('localized_aspect_name')
                or item.get('localizedName')
                or item.get('localized_name')
                or item.get('name')
                or ''
            ).strip()
            val = _first_text(
                item.get('localizedValues')
                or item.get('localized_values')
                or item.get('values')
                or item.get('aspectValues')
                or item.get('aspect_values')
                or item.get('value')
            )
            if name and val:
                out[name] = val
    return out


def _listingagent_ebay_user_request(method, path, *, params=None, payload=None, timeout=30, marketplace_id=''):
    """Call eBay APIs with the seller user token (Authorization Code flow)."""
    token = get_access_token()
    headers_local = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Accept-Language': 'en-US',
    }
    if marketplace_id:
        headers_local['X-EBAY-C-MARKETPLACE-ID'] = marketplace_id
    url = f"https://api.ebay.com{path}"
    return requests.request(method, url, headers=headers_local, params=params, json=payload, timeout=timeout)


def _listingagent_ebay_browse_category_fields(item):
    category_id = str(item.get('categoryId') or item.get('category_id') or '').strip()
    category_path = str(item.get('categoryPath') or item.get('category_path') or '').strip()
    category_id_path = str(item.get('categoryIdPath') or item.get('category_id_path') or '').strip()
    leaf_ids = item.get('leafCategoryIds') or item.get('leaf_category_ids') or []

    if not category_id and category_id_path:
        parts = [p.strip() for p in category_id_path.split('|') if p and str(p).strip()]
        if parts:
            category_id = parts[-1]
    if not category_id and isinstance(leaf_ids, list) and leaf_ids:
        category_id = str(leaf_ids[0] or '').strip()

    if not category_path:
        categories = item.get('categories') or []
        if isinstance(categories, list) and categories:
            first = categories[0] if isinstance(categories[0], dict) else {}
            first_name = str(first.get('categoryName') or first.get('category_name') or '').strip()
            if first_name:
                category_path = first_name

    if category_path and '|' in category_path:
        category_path = ' > '.join(part.strip() for part in category_path.split('|') if part and part.strip())

    category_name = ''
    if category_path:
        parts = [p.strip() for p in category_path.split('>') if p and p.strip()]
        if parts:
            category_name = parts[-1]

    return {
        'categoryId': category_id,
        'categoryName': category_name,
        'categoryPath': category_path,
    }


def _listingagent_ebay_browse_aspects_to_dict(item):
    junk_values = {
        'unbranded', 'does not apply', 'n/a', 'na', 'unknown',
        'not applicable', 'see description', 'other', 'generic'
    }
    aspects = _ebay_catalog_aspects_to_dict(
        item.get('localizedAspects')
        or item.get('localized_aspects')
        or item.get('aspects')
    )
    preferred_fields = {
        'Brand': item.get('brand'),
        'Color': item.get('color'),
        'MPN': item.get('mpn'),
        'Model': item.get('model'),
        'Size': item.get('size'),
        'Material': item.get('material'),
        'Pattern': item.get('pattern'),
        'Style': item.get('style'),
        'Department': item.get('department'),
        'Type': item.get('type'),
    }
    fallback_fields = {
        'UPC': item.get('gtin') or item.get('upc'),
        'EAN': item.get('ean'),
        'ISBN': item.get('isbn'),
    }
    for name, value in preferred_fields.items():
        text = str(value or '').strip()
        if text and text.lower() not in junk_values:
            aspects[name] = text
    for name, value in fallback_fields.items():
        text = str(value or '').strip()
        if text and text.lower() not in junk_values and not aspects.get(name):
            aspects[name] = text
    out = {}
    for name, value in aspects.items():
        safe_name = str(name or '').strip()
        safe_value = str(value or '').strip()
        if not safe_name or not safe_value or safe_value.lower() in junk_values:
            continue
        out[safe_name] = safe_value
    return out


def _listingagent_normalize_ebay_catalog_summary(summary):
    """Shape Catalog API product summaries into the UI payload used by listing-agent."""
    if not isinstance(summary, dict):
        return None

    title = str(summary.get('title') or summary.get('name') or '').strip()
    epid = str(summary.get('epid') or summary.get('ePID') or '').strip()

    image_obj = summary.get('image') or {}
    image = ''
    if isinstance(image_obj, dict):
        image = str(image_obj.get('imageUrl') or image_obj.get('image_url') or '').strip()
    if not image:
        image = str(summary.get('imageUrl') or summary.get('image_url') or '').strip()

    aspects = _ebay_catalog_aspects_to_dict(
        summary.get('aspects')
        or summary.get('localizedAspects')
        or summary.get('localized_aspects')
    )
    brand = (
        str(summary.get('brand') or '').strip()
        or str(summary.get('manufacturer') or '').strip()
        or aspects.get('Brand')
        or aspects.get('brand')
        or ''
    )

    category_id = str(summary.get('categoryId') or summary.get('category_id') or '').strip()
    category_name = str(summary.get('categoryName') or summary.get('category_name') or '').strip()
    category_path = str(summary.get('categoryPath') or summary.get('category_path') or '').strip()

    categories = summary.get('categories') or []
    if not category_id and isinstance(categories, list):
        for cat in categories:
            if not isinstance(cat, dict):
                continue
            category_id = str(cat.get('categoryId') or cat.get('category_id') or '').strip()
            category_name = str(cat.get('categoryName') or cat.get('category_name') or '').strip()
            category_path = str(cat.get('categoryPath') or cat.get('category_path') or '').strip()
            if category_id or category_name or category_path:
                break

    if not category_path and category_name:
        category_path = category_name

    gtins = []
    for key in ('gtins', 'gtin'):
        raw = summary.get(key)
        if isinstance(raw, (list, tuple)):
            gtins.extend(str(x or '').strip() for x in raw)
        elif raw:
            gtins.append(str(raw).strip())
    gtins = [g for g in gtins if g]

    return {
        'epid': epid,
        'title': title,
        'image': image,
        'brand': brand,
        'aspects': aspects,
        'categoryId': category_id,
        'categoryName': category_name,
        'categoryPath': category_path,
        'gtins': gtins,
        'price_min': None,
        'price_max': None,
        'price_count': 0,
        'source': 'catalog',
    }


def _listingagent_ebay_candidate_key(candidate):
    if not isinstance(candidate, dict):
        return ''
    epid = str(candidate.get('epid') or '').strip().lower()
    if epid:
        return f"epid:{epid}"
    gtins = [str(x or '').strip().lower() for x in (candidate.get('gtins') or []) if str(x or '').strip()]
    if gtins:
        return f"gtin:{'|'.join(gtins)}"
    title = str(candidate.get('title') or '').strip().lower()
    source = str(candidate.get('source') or '').strip().lower()
    if title:
        return f"{source}:{title}"
    return ''


def _listingagent_merge_ebay_candidates(existing, incoming, *, limit=10):
    results = list(existing or [])
    seen = {_listingagent_ebay_candidate_key(item) for item in results if _listingagent_ebay_candidate_key(item)}
    for item in incoming or []:
        key = _listingagent_ebay_candidate_key(item)
        if not key or key in seen:
            continue
        seen.add(key)
        results.append(item)
        if len(results) >= limit:
            break
    return results


def _listingagent_browse_items_to_candidates(items, *, limit=10):
    grouped = {}
    junk_values = {
        'unbranded', 'does not apply', 'n/a', 'na', 'unknown',
        'not applicable', 'see description', 'other', 'generic'
    }

    for item in items or []:
        if not isinstance(item, dict):
            continue
        title = str(item.get('title') or '').strip()
        if not title:
            continue
        epid = str(item.get('epid') or '').strip()
        key = (epid or title).strip().lower()
        if not key:
            continue
        group = grouped.get(key)
        if group is None:
            image_obj = item.get('image') or {}
            image = str((image_obj.get('imageUrl') or image_obj.get('image_url') or '')).strip() if isinstance(image_obj, dict) else ''
            category_fields = _listingagent_ebay_browse_category_fields(item)
            group = {
                'itemId': str(item.get('itemId') or item.get('item_id') or '').strip(),
                'legacyItemId': str(item.get('legacyItemId') or item.get('legacy_item_id') or '').strip(),
                'itemWebUrl': str(item.get('itemWebUrl') or item.get('item_web_url') or '').strip(),
                'epid': epid,
                'title': title,
                'image': image,
                'brand': '',
                'aspects': {},
                'categoryId': category_fields.get('categoryId') or '',
                'categoryName': category_fields.get('categoryName') or '',
                'categoryPath': category_fields.get('categoryPath') or '',
                'gtins': [],
                'price_min': None,
                'price_max': None,
                'price_count': 0,
                'source': 'browse',
                '_prices': [],
                '_aspect_votes': {},
            }
            grouped[key] = group

        if not group.get('image'):
            image_obj = item.get('image') or {}
            if isinstance(image_obj, dict):
                group['image'] = str(image_obj.get('imageUrl') or image_obj.get('image_url') or '').strip()

        if not group.get('itemId'):
            group['itemId'] = str(item.get('itemId') or item.get('item_id') or '').strip()
        if not group.get('legacyItemId'):
            group['legacyItemId'] = str(item.get('legacyItemId') or item.get('legacy_item_id') or '').strip()
        if not group.get('itemWebUrl'):
            group['itemWebUrl'] = str(item.get('itemWebUrl') or item.get('item_web_url') or '').strip()

        category_fields = _listingagent_ebay_browse_category_fields(item)
        if not group.get('categoryId') and category_fields.get('categoryId'):
            group['categoryId'] = category_fields.get('categoryId') or ''
        if not group.get('categoryName') and category_fields.get('categoryName'):
            group['categoryName'] = category_fields.get('categoryName') or ''
        if not group.get('categoryPath') and category_fields.get('categoryPath'):
            group['categoryPath'] = category_fields.get('categoryPath') or ''

        try:
            price_val = float((item.get('price') or {}).get('value') or 0)
            if price_val > 0:
                group['_prices'].append(price_val)
        except Exception:
            pass

        for name, value in _listingagent_ebay_browse_aspects_to_dict(item).items():
            if not name or not value or value.lower() in junk_values:
                continue
            norm = name.lower()
            votes = group['_aspect_votes'].setdefault(norm, {'_display': name})
            votes[value] = votes.get(value, 0) + 1

    results = []
    for group in grouped.values():
        aspects = {}
        for norm, votes in group.pop('_aspect_votes', {}).items():
            display = votes.pop('_display', norm)
            if votes:
                aspects[display] = max(votes, key=lambda v: votes[v])
        group['aspects'] = aspects
        group['brand'] = group.get('brand') or aspects.get('Brand') or aspects.get('brand') or ''
        prices = sorted(group.pop('_prices', []))
        if prices:
            group['price_min'] = prices[0]
            group['price_max'] = prices[-1]
            group['price_count'] = len(prices)
        results.append(group)

    results.sort(key=lambda r: (
        0 if r.get('epid') else 1,
        -(r.get('price_count') or 0),
        -(len(r.get('aspects') or {})),
        str(r.get('title') or '').lower()
    ))
    return results[:limit]


def _listingagent_search_ebay_browse_candidates(*, marketplace_id, queries, limit=12):
    results = []
    seen_queries = set()
    for raw_query in queries or []:
        query = str(raw_query or '').strip()
        key = query.lower()
        if not query or key in seen_queries:
            continue
        seen_queries.add(key)
        resp = _ebay_buy_api_request(
            'GET',
            '/buy/browse/v1/item_summary/search',
            params={'q': query, 'limit': min(max(limit * 3, 18), 60), 'fieldgroups': 'EXTENDED'},
            marketplace_id=marketplace_id,
        )
        if resp.status_code >= 400:
            continue
        payload = resp.json() if resp.text else {}
        items = payload.get('itemSummaries') or []
        if not items:
            continue
        browse_candidates = _listingagent_browse_items_to_candidates(items, limit=limit)
        results = _listingagent_merge_ebay_candidates(results, browse_candidates, limit=limit)
        if len(results) >= limit:
            break
    return results


def _listingagent_ebay_title_tokens(text):
    return [tok for tok in re.findall(r'[a-z0-9]+', str(text or '').lower()) if tok]


def _listingagent_detect_color_tokens(text):
    token_set = set(_listingagent_ebay_title_tokens(text))
    known_colors = {
        'black', 'white', 'red', 'blue', 'green', 'yellow', 'orange', 'pink', 'purple',
        'brown', 'beige', 'tan', 'gray', 'grey', 'gold', 'silver', 'ivory', 'navy',
        'teal', 'maroon', 'burgundy'
    }
    return token_set & known_colors


def _listingagent_score_ebay_candidate(candidate, *, upc='', preferred_title=''):
    score = 0.0
    safe_upc = str(upc or '').strip()
    gtins = [str(x or '').strip() for x in (candidate.get('gtins') or []) if str(x or '').strip()]
    if safe_upc and safe_upc in gtins:
        score += 150.0

    title = str(candidate.get('title') or '').strip().lower()
    preferred = str(preferred_title or '').strip().lower()
    title_tokens = set(_listingagent_ebay_title_tokens(title))
    preferred_tokens = set(_listingagent_ebay_title_tokens(preferred))
    overlap = title_tokens & preferred_tokens
    score += len(overlap) * 6.0

    preferred_numbers = {tok for tok in preferred_tokens if tok.isdigit()}
    candidate_numbers = {tok for tok in title_tokens if tok.isdigit()}
    if preferred_numbers and candidate_numbers:
        score += len(preferred_numbers & candidate_numbers) * 10.0

    preferred_colors = _listingagent_detect_color_tokens(preferred)
    candidate_colors = _listingagent_detect_color_tokens(title)
    if preferred_colors and candidate_colors:
        if preferred_colors & candidate_colors:
            score += 12.0
        else:
            score -= 8.0

    category_path = str(candidate.get('categoryPath') or '').lower()
    if 'tablecloth' in category_path and ('tablecloth' in preferred or 'oblong' in preferred):
        score += 6.0

    score += float(len(candidate.get('aspects') or {}))
    score += min(float(candidate.get('price_count') or 0), 5.0)
    return score


def _listingagent_pick_best_ebay_candidate(candidates, *, upc='', preferred_title=''):
    ranked = []
    for idx, candidate in enumerate(candidates or []):
        ranked.append((
            _listingagent_score_ebay_candidate(candidate, upc=upc, preferred_title=preferred_title),
            -idx,
            candidate,
        ))
    if not ranked:
        return None
    ranked.sort(reverse=True)
    return ranked[0][2]


def _listingagent_get_ebay_browse_item_detail(item_id, marketplace_id):
    item_id = str(item_id or '').strip()
    if not item_id:
        return None
    from urllib.parse import quote

    resp = _listingagent_ebay_user_request(
        'GET',
        f"/buy/browse/v1/item/{quote(item_id, safe='')}",
        marketplace_id=marketplace_id,
    )
    if resp.status_code >= 400:
        raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=resp.status_code)

    detail = resp.json() if resp.text else {}
    if not isinstance(detail, dict) or not detail:
        return None

    category_fields = _listingagent_ebay_browse_category_fields(detail)
    aspects = _listingagent_ebay_browse_aspects_to_dict(detail)
    image_obj = detail.get('image') or {}
    image = ''
    if isinstance(image_obj, dict):
        image = str(image_obj.get('imageUrl') or image_obj.get('image_url') or '').strip()

    gtins = []
    for key in ('gtin', 'upc', 'ean', 'isbn'):
        value = detail.get(key)
        if isinstance(value, (list, tuple)):
            gtins.extend(str(v or '').strip() for v in value if str(v or '').strip())
        else:
            text = str(value or '').strip()
            if text:
                gtins.append(text)

    price_min = price_max = None
    price_count = 0
    try:
        price_val = float((detail.get('price') or {}).get('value') or 0)
        if price_val > 0:
            price_min = price_max = price_val
            price_count = 1
    except Exception:
        pass

    return {
        'itemId': str(detail.get('itemId') or '').strip(),
        'legacyItemId': str(detail.get('legacyItemId') or detail.get('legacy_item_id') or '').strip(),
        'itemWebUrl': str(detail.get('itemWebUrl') or detail.get('item_web_url') or '').strip(),
        'epid': str(detail.get('epid') or detail.get('ePID') or '').strip(),
        'title': str(detail.get('title') or '').strip(),
        'image': image,
        'brand': str(detail.get('brand') or aspects.get('Brand') or aspects.get('brand') or '').strip(),
        'aspects': aspects,
        'categoryId': category_fields.get('categoryId') or '',
        'categoryName': category_fields.get('categoryName') or '',
        'categoryPath': category_fields.get('categoryPath') or '',
        'gtins': [g for g in gtins if g],
        'price_min': price_min,
        'price_max': price_max,
        'price_count': price_count,
        'source': 'browse_detail',
    }

@app.route('/api/listingagent/ebay/catalog_search', methods=['GET'])
def api_listingagent_ebay_catalog_search():
    """Search eBay catalog broadly, then append Browse-derived alternatives."""
    try:
        upc = (request.args.get('upc') or request.args.get('gtin') or '').strip()
        q = (request.args.get('q') or request.args.get('query') or '').strip()
        title = (request.args.get('title') or '').strip()
        limit = _listingagent_parse_int(request.args.get('limit'), 10) or 10
        limit = max(1, min(limit, 20))

        if not upc and not q and not title:
            raise _ListingAgentUserError('upc or q is required', status_code=400)

        settings = _listingagent_get_settings()
        marketplace_id = (request.args.get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()

        results = []
        catalog_searches = []
        seen_catalog_queries = set()

        if upc:
            catalog_searches.append({'gtin': upc, 'fieldgroups': 'PRODUCT', 'limit': min(limit, 20)})

        for text in (q, title):
            text = str(text or '').strip()
            key = text.lower()
            if not text or key in seen_catalog_queries:
                continue
            seen_catalog_queries.add(key)
            catalog_searches.append({'q': text, 'fieldgroups': 'PRODUCT', 'limit': min(max(limit, 8), 20)})

        for params in catalog_searches:
            try:
                resp_catalog = _ebay_buy_api_request(
                    'GET',
                    '/commerce/catalog/v1_beta/product_summary/search',
                    params=params,
                    marketplace_id=marketplace_id,
                    scope='https://api.ebay.com/oauth/api_scope/commerce.catalog.readonly',
                )
            except Exception:
                resp_catalog = None
            if resp_catalog is None or resp_catalog.status_code >= 400:
                continue
            payload_catalog = resp_catalog.json() if resp_catalog.text else {}
            summaries = payload_catalog.get('productSummaries') or payload_catalog.get('products') or []
            normalized = []
            if isinstance(summaries, list):
                for summary in summaries:
                    item = _listingagent_normalize_ebay_catalog_summary(summary)
                    if item:
                        normalized.append(item)
            results = _listingagent_merge_ebay_candidates(results, normalized, limit=limit)
            if len(results) >= limit:
                break

        def _browse_search(search_params):
            return _ebay_buy_api_request(
                'GET',
                '/buy/browse/v1/item_summary/search',
                # EXTENDED adds localizedAspects to each item summary
                params={**search_params, 'fieldgroups': 'EXTENDED'},
                marketplace_id=marketplace_id,
            )

        browse_queries = []
        seen_browse = set()
        for text in (q, title, upc):
            text = str(text or '').strip()
            key = text.lower()
            if not text or key in seen_browse:
                continue
            seen_browse.add(key)
            browse_queries.append(text)

        browse_added = False
        for search_q in browse_queries:
            if len(results) >= limit:
                break
            resp = _browse_search({'q': search_q, 'limit': min(max(limit * 3, 18), 60)})
            if resp.status_code >= 400:
                if not results:
                    raise _ListingAgentUserError(_ebay_extract_error(resp), status_code=resp.status_code)
                continue
            data = resp.json() if resp.text else {}
            items = data.get('itemSummaries') or []
            if not items:
                continue
            browse_candidates = _listingagent_browse_items_to_candidates(items, limit=limit)
            before = len(results)
            results = _listingagent_merge_ebay_candidates(results, browse_candidates, limit=limit)
            if len(results) > before:
                browse_added = True

        source = 'mixed' if browse_added and any((r.get('source') == 'catalog') for r in results) else (
            'browse' if browse_added else 'catalog'
        )
        return jsonify({'success': True, 'results': results, 'total': len(results), 'source': source})
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_catalog_search')}), 500


@app.route('/api/listingagent/ebay/product_specifics', methods=['GET'])
def api_listingagent_ebay_product_specifics():
    """Best-effort eBay specifics using live Browse candidates plus item detail."""
    try:
        upc = (request.args.get('upc') or request.args.get('gtin') or '').strip()
        title = (request.args.get('title') or request.args.get('q') or '').strip()
        if not upc and not title:
            return jsonify({'success': True, 'found': False, 'aspects': {}})

        marketplace_id = (request.args.get('marketplaceId') or
                          _listingagent_get_settings().get('ebay_marketplace_id') or 'EBAY_US').strip()

        queries = []
        if title:
            queries.append(title)
        if upc:
            queries.append(upc)
        candidates = _listingagent_search_ebay_browse_candidates(
            marketplace_id=marketplace_id,
            queries=queries,
            limit=8,
        )
        best = _listingagent_pick_best_ebay_candidate(candidates, upc=upc, preferred_title=title or upc)
        if not best:
            return jsonify({'success': True, 'found': False, 'aspects': {}})

        detail = None
        try:
            detail = _listingagent_get_ebay_browse_item_detail(best.get('itemId') or '', marketplace_id)
        except Exception:
            detail = None
        first = detail or best or {}
        aspects = {}
        for name, val in (first.get('aspects') or {}).items():
            value = str(val or '').strip()
            if value and value.lower() not in {'unbranded', 'does not apply', 'n/a', 'na', 'unknown'}:
                aspects[str(name)] = value

        return jsonify({
            'success': True,
            'found': bool(aspects or first.get('itemId') or first.get('epid') or first.get('title')),
            'itemId': str(first.get('itemId') or ''),
            'legacyItemId': str(first.get('legacyItemId') or ''),
            'epid': str(first.get('epid') or ''),
            'title': str(first.get('title') or ''),
            'image': str(first.get('image') or ''),
            'brand': str(first.get('brand') or ''),
            'categoryId': str(first.get('categoryId') or ''),
            'categoryName': str(first.get('categoryName') or ''),
            'categoryPath': str(first.get('categoryPath') or ''),
            'aspects': aspects,
        })
    except Exception as e:
        return jsonify({'success': True, 'found': False, 'aspects': {},
                        'note': _safe_error(e, 'listingagent:ebay_product_specifics')})


@app.route('/api/listingagent/ebay/catalog_item', methods=['GET'])
def api_listingagent_ebay_catalog_item():
    """Fetch full Browse item detail for a selected eBay candidate row."""
    try:
        item_id = (request.args.get('itemId') or request.args.get('item_id') or '').strip()
        if not item_id:
            raise _ListingAgentUserError('itemId is required', status_code=400)

        marketplace_id = (request.args.get('marketplaceId') or
                          _listingagent_get_settings().get('ebay_marketplace_id') or 'EBAY_US').strip()
        detail = _listingagent_get_ebay_browse_item_detail(item_id, marketplace_id)
        if not detail:
            return jsonify({'success': False, 'error': 'No detail returned for selected eBay item.'}), 404
        return jsonify({'success': True, 'result': detail})
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_catalog_item')}), 500


def _listingagent_ebay_create_draft_offer(data, *, dry_run=False):
    upc = (data.get('upc') or '').strip()
    sku = (data.get('sku') or upc).strip()
    if not upc:
        raise _ListingAgentUserError('UPC is required')
    if not sku:
        raise _ListingAgentUserError('SKU is required')

    title = (data.get('title') or '').strip()
    description = (data.get('description') or '').strip()
    condition = (data.get('condition') or '').strip() or 'USED_GOOD'

    quantity = _listingagent_parse_int(data.get('quantity'), 1) or 1
    price = _listingagent_parse_float(data.get('price'), None)

    settings = _listingagent_get_settings()
    marketplace_id = (data.get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()
    currency = (data.get('currency') or settings.get('ebay_currency') or 'USD').strip()
    category_id = (data.get('categoryId') or settings.get('ebay_category_id') or '').strip()
    listing_duration = (data.get('listingDuration') or settings.get('ebay_listing_duration') or 'GTC').strip()

    merchant_location_key_input = (data.get('merchantLocationKey') or settings.get('ebay_location_key') or '').strip()
    fulfillment_policy_id = (data.get('fulfillmentPolicyId') or settings.get('ebay_fulfillment_policy_id') or '').strip()
    payment_policy_id = (data.get('paymentPolicyId') or settings.get('ebay_payment_policy_id') or '').strip()
    return_policy_id = (data.get('returnPolicyId') or settings.get('ebay_return_policy_id') or '').strip()

    listing_description = (data.get('listingDescription') or '').strip()
    condition_description = (data.get('conditionDescription') or data.get('condition_description') or '').strip()

    images = data.get('images') or []
    if isinstance(images, str):
        images = [images]
    images = _listagent_localize_image_urls(upc, images)

    aspects = data.get('aspects') or {}
    if not isinstance(aspects, dict):
        aspects = {}
    catalog_epid = (data.get('catalogEpid') or data.get('epid') or '').strip()

    merchant_location_key, location_autofixed, all_location_keys = _listingagent_resolve_ebay_location_key(merchant_location_key_input)
    if location_autofixed:
        # Persist auto-healed location key so subsequent publishes use a valid key.
        try:
            _listingagent_upsert_settings({'ebay_location_key': merchant_location_key})
        except Exception:
            pass

    inventory_item_payload = _build_ebay_inventory_item_payload(
        upc,
        title,
        description,
        images,
        quantity,
        condition,
        aspects=aspects,
        epid=catalog_epid,
        condition_description=condition_description
    )
    offer_payload = _build_ebay_offer_payload(
        sku, marketplace_id, currency, price, quantity, category_id, listing_description,
        merchant_location_key, fulfillment_policy_id, payment_policy_id, return_policy_id,
        listing_duration=listing_duration
    )

    if dry_run:
        return {
            'success': True,
            'dry_run': True,
            'inventoryItem': inventory_item_payload,
            'offer': offer_payload,
            'resolvedMerchantLocationKey': merchant_location_key,
            'locationAutoFixed': bool(location_autofixed),
            'availableLocationKeys': all_location_keys[:50]
        }

    condition_autofixed = False
    original_condition = (inventory_item_payload.get('condition') or '').strip()
    inventory_item_payload, condition_autofixed, original_condition, _condition_tried = _listingagent_put_inventory_item_with_condition_fallback(
        sku,
        inventory_item_payload,
        category_id=category_id,
        marketplace_id=marketplace_id
    )

    resp_offer = _ebay_api_request('POST', '/sell/inventory/v1/offer', payload=offer_payload)
    if resp_offer.status_code >= 400:
        err_text = _ebay_extract_error(resp_offer)
        # Auto-recover once if configured location key became invalid in eBay.
        if 'location information not found' in err_text.lower():
            fresh_key, _fixed, keys = _listingagent_resolve_ebay_location_key('', force_refresh=True)
            if fresh_key and fresh_key != str(offer_payload.get('merchantLocationKey') or '').strip():
                offer_payload_retry = dict(offer_payload)
                offer_payload_retry['merchantLocationKey'] = fresh_key
                resp_offer_retry = _ebay_api_request('POST', '/sell/inventory/v1/offer', payload=offer_payload_retry)
                if resp_offer_retry.status_code < 400:
                    offer_payload = offer_payload_retry
                    try:
                        _listingagent_upsert_settings({'ebay_location_key': fresh_key})
                    except Exception:
                        pass
                    offer_data = resp_offer_retry.json() if resp_offer_retry.text else {}
                    return {
                        'success': True,
                        'offerId': offer_data.get('offerId'),
                        'inventoryItem': inventory_item_payload,
                        'offer': offer_payload,
                        'raw': offer_data,
                        'resolvedMerchantLocationKey': fresh_key,
                        'locationAutoFixed': True,
                        'availableLocationKeys': keys[:50]
                    }
                err_text = _ebay_extract_error(resp_offer_retry)
        # If offer already exists for this SKU, reuse it.
        if 'offer entity already exists' in err_text.lower():
            existing = _listingagent_find_existing_offer_for_sku(sku, marketplace_id=marketplace_id)
            if existing:
                existing_offer_id = (existing.get('offerId') or existing.get('offer_id') or '').strip()
                existing_offer_updated = False
                existing_location_autofixed = bool(location_autofixed)
                if existing_offer_id:
                    resp_put_existing = _ebay_api_request('PUT', f'/sell/inventory/v1/offer/{existing_offer_id}', payload=offer_payload)
                    put_ok = resp_put_existing.status_code < 400
                    if not put_ok:
                        put_err = _ebay_extract_error(resp_put_existing)
                        put_offer_payload = dict(offer_payload)
                        # Same stale-location recovery used for POST create path.
                        if 'location information not found' in put_err.lower():
                            fresh_key, _fixed, keys = _listingagent_resolve_ebay_location_key('', force_refresh=True)
                            if fresh_key and fresh_key != str(offer_payload.get('merchantLocationKey') or '').strip():
                                put_offer_payload['merchantLocationKey'] = fresh_key
                                resp_put_retry = _ebay_api_request('PUT', f'/sell/inventory/v1/offer/{existing_offer_id}', payload=put_offer_payload)
                                if resp_put_retry.status_code < 400:
                                    offer_payload = put_offer_payload
                                    existing_location_autofixed = True
                                    put_ok = True
                                    try:
                                        _listingagent_upsert_settings({'ebay_location_key': fresh_key})
                                    except Exception:
                                        pass
                                else:
                                    put_err = _ebay_extract_error(resp_put_retry)
                        if not put_ok:
                            raise _ListingAgentUserError(
                                f"Existing offer found for SKU, but updating it failed: {put_err}",
                                status_code=400,
                                extra={
                                    'offer': offer_payload,
                                    'resolvedMerchantLocationKey': merchant_location_key,
                                    'locationAutoFixed': existing_location_autofixed,
                                    'conditionAutoFixed': bool(condition_autofixed),
                                    'resolvedCondition': (inventory_item_payload.get('condition') or '').strip(),
                                    'originalCondition': original_condition,
                                    'missingAspect': _extract_missing_ebay_aspect(put_err),
                                    'existingOfferId': existing_offer_id,
                                    'availableLocationKeys': all_location_keys[:50]
                                }
                            )
                    existing_offer_updated = True
                return {
                    'success': True,
                    'offerId': existing_offer_id or (existing.get('offerId') or existing.get('offer_id') or '').strip(),
                    'inventoryItem': inventory_item_payload,
                    'offer': offer_payload,
                    'raw': {'reusedExistingOffer': True, 'updatedExistingOffer': existing_offer_updated, 'existingOffer': existing},
                    'resolvedMerchantLocationKey': merchant_location_key,
                    'locationAutoFixed': existing_location_autofixed,
                    'conditionAutoFixed': bool(condition_autofixed),
                    'resolvedCondition': (inventory_item_payload.get('condition') or '').strip(),
                    'originalCondition': original_condition,
                    'availableLocationKeys': all_location_keys[:50]
                }
        missing_aspect = _extract_missing_ebay_aspect(err_text)
        raise _ListingAgentUserError(
            err_text,
            status_code=400,
            extra={
                'offer': offer_payload,
                'resolvedMerchantLocationKey': merchant_location_key,
                'locationAutoFixed': bool(location_autofixed),
                'conditionAutoFixed': bool(condition_autofixed),
                'resolvedCondition': (inventory_item_payload.get('condition') or '').strip(),
                'originalCondition': original_condition,
                'missingAspect': missing_aspect,
                'availableLocationKeys': all_location_keys[:50]
            }
        )

    offer_data = resp_offer.json() if resp_offer.text else {}
    return {
        'success': True,
        'offerId': offer_data.get('offerId'),
        'inventoryItem': inventory_item_payload,
        'offer': offer_payload,
        'raw': offer_data,
        'resolvedMerchantLocationKey': merchant_location_key,
        'locationAutoFixed': bool(location_autofixed),
        'conditionAutoFixed': bool(condition_autofixed),
        'resolvedCondition': (inventory_item_payload.get('condition') or '').strip(),
        'originalCondition': original_condition,
        'availableLocationKeys': all_location_keys[:50]
    }

