@app.route('/api/listingagent/ebay/generate_description', methods=['POST'])
def api_listingagent_ebay_generate_description():
    """Generate an AI-powered listing description using Claude API (Anthropic) if configured, else template."""
    try:
        data = request.get_json(force=True) or {}
        title = (data.get('listing_title') or data.get('title') or '').strip()
        system_title = (data.get('system_title') or '').strip()
        category_id = (data.get('category_id') or data.get('categoryId') or '').strip()
        aspects = data.get('aspects') or {}
        upc = (data.get('upc') or '').strip()

        if not title:
            raise _ListingAgentUserError('title is required', status_code=400)

        anthropic_key = os.getenv('ANTHROPIC_API_KEY', '').strip()
        if not anthropic_key:
            raise _ListingAgentUserError('ANTHROPIC_API_KEY not found in environment — check .env on the Pi', status_code=503)

        if anthropic_key:
            # Build a concise prompt from available product data
            aspect_lines = '\n'.join(f'- {k}: {v}' for k, v in aspects.items() if k and v) if aspects else ''
            prompt = (
                f"Write a compelling eBay listing description for the following product. "
                f"Use plain HTML (h2, p, ul/li only). Be concise, highlight key features and condition. "
                f"Do not include price. Do not mention eBay by name.\n\n"
                f"Listing title: {title}\n"
                + (f"Inventory system title: {system_title}\n" if system_title else "")
                + (f"Category ID: {category_id}\n" if category_id else "")
                + (f"UPC: {upc}\n" if upc else "")
                + (f"Item specifics:\n{aspect_lines}\n" if aspect_lines else "")
            )
            resp = requests.post(
                'https://api.anthropic.com/v1/messages',
                headers={
                    'x-api-key': anthropic_key,
                    'anthropic-version': '2023-06-01',
                    'content-type': 'application/json',
                },
                json={
                    'model': 'claude-haiku-4-5-20251001',
                    'max_tokens': 1024,
                    'messages': [{'role': 'user', 'content': prompt}],
                },
                timeout=30,
            )
            if resp.status_code >= 400:
                try:
                    err_body = resp.json()
                    err_msg = (err_body.get('error') or {}).get('message') or resp.text[:300]
                except Exception:
                    err_msg = resp.text[:300]
                raise _ListingAgentUserError(f'Anthropic API error ({resp.status_code}): {err_msg}', status_code=502)
            result = resp.json()
            description = (result.get('content') or [{}])[0].get('text', '').strip()
            if not description:
                raise _ListingAgentUserError(f'Anthropic API returned empty response. Raw: {str(result)[:200]}', status_code=502)
            # Strip markdown code fences Claude sometimes adds
            import re as _re
            description = _re.sub(r'^```[^\n]*\n?', '', description).rstrip('`').strip()
            return jsonify({'success': True, 'description': description + _EBAY_STORE_POLICIES_HTML, 'source': 'claude'})

        # Fallback: structured template description
        aspect_html = ''
        if aspects:
            rows = ''.join(f'<li><strong>{k}:</strong> {v}</li>' for k, v in aspects.items() if k and v)
            if rows:
                aspect_html = f'<ul>{rows}</ul>'
        description = (
            f'<h2>{title}</h2>'
            f'<p>You are purchasing a <strong>{title}</strong>. '
            f'This item ships fast and is carefully packaged.</p>'
            + (f'<h3>Item Details</h3>{aspect_html}' if aspect_html else '')
            + (f'<p><strong>UPC:</strong> {upc}</p>' if upc else '')
            + '<p>Please message us with any questions before purchasing. Thank you!</p>'
        )
        return jsonify({'success': True, 'description': description + _EBAY_STORE_POLICIES_HTML, 'source': 'template'})

    except _ListingAgentUserError as e:
        # Always return 200 so Cloudflare tunnel doesn't swallow the response body
        return jsonify({'success': False, 'error': str(e)})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_generate_description')})

@app.route('/api/listingagent/ebay/generate_title', methods=['POST'])
def api_listingagent_ebay_generate_title():
    """Generate an AI-powered listing title using Claude API (Anthropic) if configured, else template."""
    try:
        data = request.get_json(force=True) or {}
        form_title = (data.get('title') or '').strip()
        system_title = (data.get('system_title') or '').strip()
        title = (system_title or form_title).strip()
        category_id = (data.get('category_id') or data.get('categoryId') or '').strip()
        aspects = data.get('aspects') or {}
        upc = (data.get('upc') or '').strip()

        if not title:
            raise _ListingAgentUserError('title is required', status_code=400)

        anthropic_key = os.getenv('ANTHROPIC_API_KEY', '').strip()
        if not anthropic_key:
            raise _ListingAgentUserError('ANTHROPIC_API_KEY not found in environment — check .env on the Pi', status_code=503)

        if anthropic_key:
            aspect_lines = '\n'.join(f'- {k}: {v}' for k, v in aspects.items() if k and v) if aspects else ''
            prompt = (
                "Write a concise eBay listing title for the following product.\n"
                "Rules:\n"
                "- Return only the title text.\n"
                "- Keep it under 80 characters if possible.\n"
                "- Do not use quotes, bullets, or explanations.\n"
                "- Include the most useful search terms first.\n"
                "- Prefer brand, model, size, and key identifiers.\n\n"
                f"Inventory system title: {title}\n"
                + (f"Current form title: {form_title}\n" if form_title and form_title != title else "")
                + (f"Category ID: {category_id}\n" if category_id else "")
                + (f"UPC: {upc}\n" if upc else "")
                + (f"Item specifics:\n{aspect_lines}\n" if aspect_lines else "")
            )
            resp = requests.post(
                'https://api.anthropic.com/v1/messages',
                headers={
                    'x-api-key': anthropic_key,
                    'anthropic-version': '2023-06-01',
                    'content-type': 'application/json',
                },
                json={
                    'model': 'claude-haiku-4-5-20251001',
                    'max_tokens': 128,
                    'messages': [{'role': 'user', 'content': prompt}],
                },
                timeout=30,
            )
            if resp.status_code >= 400:
                try:
                    err_body = resp.json()
                    err_msg = (err_body.get('error') or {}).get('message') or resp.text[:300]
                except Exception:
                    err_msg = resp.text[:300]
                raise _ListingAgentUserError(f'Anthropic API error ({resp.status_code}): {err_msg}', status_code=502)
            result = resp.json()
            out_text = (result.get('content') or [{}])[0].get('text', '').strip()
            if not out_text:
                raise _ListingAgentUserError(f'Anthropic API returned empty response. Raw: {str(result)[:200]}', status_code=502)
            import re as _re
            out_text = _re.sub(r'^```[^\n]*\n?', '', out_text).rstrip('`').strip()
            out_text = ' '.join(out_text.split())
            out_text = out_text[:80].strip()
            return jsonify({'success': True, 'title': out_text, 'source': 'claude'})

        # Fallback: trim the existing title and add a compact keyword order.
        fallback = ' '.join((title or upc or '').split())
        if aspects:
            brand = str(aspects.get('Brand') or aspects.get('brand') or '').strip()
            model = str(aspects.get('Model') or aspects.get('model') or '').strip()
            color = str(aspects.get('Color') or aspects.get('color') or '').strip()
            size = str(aspects.get('Size') or aspects.get('size') or '').strip()
            parts = [brand, model, color, size, fallback]
            fallback = ' '.join(p for p in parts if p)
        fallback = fallback[:80].strip()
        return jsonify({'success': True, 'title': fallback, 'source': 'template'})

    except _ListingAgentUserError as e:
        return jsonify({'success': False, 'error': str(e)})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_generate_title')})

@app.route('/api/listingagent/ebay/draft', methods=['POST'])
def api_listingagent_ebay_draft():
    """Create/replace an inventory item and create a draft offer (not published)."""
    try:
        data = request.json or {}
        dry_run = bool(data.get('dry_run', False))
        result = _listingagent_ebay_create_draft_offer(data, dry_run=dry_run)
        return jsonify(result)
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_draft')}), 500

@app.route('/api/listingagent/ebay/publish', methods=['POST'])
def api_listingagent_ebay_publish():
    """Publish an offer (creates inventory item + offer if needed)."""
    try:
        data = request.json or {}
        settings = _listingagent_get_settings()
        dry_run = bool(data.get('dry_run', False))

        offer_id = (data.get('offerId') or '').strip()
 
        inventory_payload = None
        offer_payload = None
        # If an offerId was provided, treat this as an edit/revise flow:
        # update inventory item + offer (if we have full fields) and then publish to apply changes.
        if offer_id:
            wants_update = bool(data.get('updateExisting', True))
            upc_for_update = (data.get('upc') or '').strip()
            if wants_update and upc_for_update:
                required = ['upc', 'sku', 'title', 'listingDescription', 'price', 'quantity', 'categoryId',
                            'fulfillmentPolicyId', 'paymentPolicyId', 'returnPolicyId']
                missing = [k for k in required if not str(data.get(k) or '').strip()]
                if missing and not dry_run:
                    return jsonify({'success': False, 'error': f"Missing required fields to update: {', '.join(missing)}"}), 400
  
                # Reuse the draft builder to generate payloads without creating a new offer.
                preview = _listingagent_ebay_create_draft_offer(data, dry_run=True)
                inventory_payload = preview.get('inventoryItem')
                offer_payload = preview.get('offer')
  
                if dry_run:
                    return jsonify({'success': True, 'dry_run': True, 'offerId': offer_id, 'inventoryItem': inventory_payload, 'offer': offer_payload, 'wouldPublish': True, 'wouldUpdate': True})
  
                sku_local = (data.get('sku') or upc_for_update).strip()
                category_for_update = (data.get('categoryId') or (offer_payload or {}).get('categoryId') or '').strip()
                marketplace_for_update = (data.get('marketplaceId') or (offer_payload or {}).get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()
                try:
                    inventory_payload, cond_fixed, orig_cond, _tried = _listingagent_put_inventory_item_with_condition_fallback(
                        sku_local,
                        inventory_payload or {},
                        category_id=category_for_update,
                        marketplace_id=marketplace_for_update
                    )
                except _ListingAgentUserError as e:
                    payload = {'success': False, 'error': str(e)}
                    payload.update(e.extra or {})
                    return jsonify(payload), e.status_code
 
                resp_offer = _ebay_api_request('PUT', f'/sell/inventory/v1/offer/{offer_id}', payload=offer_payload)
                if resp_offer.status_code >= 400:
                    return jsonify({'success': False, 'error': _ebay_extract_error(resp_offer), 'offer': offer_payload}), 400
  
        if not offer_id:
            # Enforce publish-required fields (unless dry_run)
            required = ['upc', 'sku', 'title', 'listingDescription', 'price', 'quantity', 'categoryId',
                        'fulfillmentPolicyId', 'paymentPolicyId', 'returnPolicyId']
            missing = [k for k in required if not str(data.get(k) or '').strip()]
            if missing and not dry_run:
                return jsonify({'success': False, 'error': f"Missing required fields: {', '.join(missing)}"}), 400

            draft_result = _listingagent_ebay_create_draft_offer(data, dry_run=dry_run)
            if dry_run:
                # Tell the UI what would happen next
                return jsonify({**draft_result, 'wouldPublish': True})

            offer_id = (draft_result.get('offerId') or '').strip()
            inventory_payload = draft_result.get('inventoryItem')
            offer_payload = draft_result.get('offer')
            if not offer_id:
                return jsonify({'success': False, 'error': 'Draft offer created but no offerId returned'}), 500

        if dry_run:
            return jsonify({'success': True, 'dry_run': True, 'offerId': offer_id, 'inventoryItem': inventory_payload, 'offer': offer_payload, 'wouldPublish': True})

        def _finish_ebay_publish_success(*, listing_id=None, pub_data=None, extra=None):
            upc = (data.get('upc') or '').strip()
            target_lot = _normalize_lot_number(data.get('lot_number') or data.get('lot'))
            target_item_id = data.get('id')
            if target_item_id is None:
                target_item_id = data.get('item_id')
            if target_item_id is None:
                target_item_id = data.get('bol_id')
            if upc or target_item_id is not None:
                try:
                    _listing_center_mark_bol_listed(
                        'ebay',
                        upc=upc,
                        lot_number=target_lot,
                        item_id=target_item_id
                    )
                except Exception:
                    pass

            try:
                if upc:
                    sku_local = (data.get('sku') or upc).strip() or None
                    try:
                        settings_local = _listingagent_get_settings()
                        marketplace_id_local = (data.get('marketplaceId') or settings_local.get('ebay_marketplace_id') or 'EBAY_US').strip() or 'EBAY_US'
                    except Exception:
                        marketplace_id_local = (data.get('marketplaceId') or 'EBAY_US').strip() or 'EBAY_US'
                    title_local = (data.get('title') or '').strip() or None
                    qty_local = _listingagent_parse_int(data.get('quantity'), None)
                    price_local = _listingagent_parse_float(data.get('price'), None)
                    listing_url_local = f"https://www.ebay.com/itm/{listing_id}" if str(listing_id or '').strip() else None
                    _listagent_mark_listed(
                        upc,
                        platform='ebay',
                        listing_id=listing_id,
                        offer_id=offer_id,
                        sku=sku_local,
                        marketplace_id=marketplace_id_local,
                        title=title_local,
                        price=price_local,
                        quantity=qty_local,
                        url=listing_url_local,
                        source='listingagent'
                    )
            except Exception:
                pass

            payload = {'success': True, 'listingId': listing_id, 'offerId': offer_id, 'raw': pub_data or {}}
            if isinstance(extra, dict):
                payload.update(extra)
            return jsonify(payload)

        resp_pub = _ebay_api_request('POST', f'/sell/inventory/v1/offer/{offer_id}/publish')
        if resp_pub.status_code >= 400:
            err_pub = _ebay_extract_error(resp_pub)
            low = err_pub.lower()
            # Publish-time mixed image source recovery:
            # eBay can reject at publish even if the prior inventory PUT accepted the payload.
            if _listingagent_is_likely_ebay_image_mix_error(err_pub) and offer_id:
                try:
                    from urllib.parse import quote

                    sku_local = (data.get('sku') or (offer_payload or {}).get('sku') or data.get('upc') or '').strip()
                    if not sku_local:
                        # Resolve SKU from the offer when client payload omitted it.
                        resp_offer_state = _ebay_api_request('GET', f'/sell/inventory/v1/offer/{offer_id}')
                        if resp_offer_state.status_code < 400:
                            offer_state = resp_offer_state.json() if resp_offer_state.text else {}
                            sku_local = (offer_state.get('sku') or '').strip()

                    if sku_local:
                        sku_encoded = quote(sku_local, safe='')
                        inv_payload = dict(inventory_payload or {})
                        if not inv_payload:
                            # No local copy (e.g. offerId publish without update path); fetch inventory item.
                            resp_inv_get = _ebay_api_request('GET', f'/sell/inventory/v1/inventory_item/{sku_encoded}')
                            if resp_inv_get.status_code < 400:
                                inv_payload = resp_inv_get.json() if resp_inv_get.text else {}

                        product_obj = inv_payload.get('product') if isinstance(inv_payload.get('product'), dict) else {}
                        image_urls = _listingagent_dedupe_image_urls((product_obj or {}).get('imageUrls') or [])
                        if image_urls and _listingagent_has_mixed_ebay_image_sources(image_urls):
                            fallback_images = _listingagent_prefer_single_ebay_image_source(image_urls)[:12]
                            if fallback_images and fallback_images != image_urls:
                                retry_inv_payload = dict(inv_payload)
                                product_retry = dict(product_obj or {})
                                product_retry['imageUrls'] = fallback_images
                                retry_inv_payload['product'] = product_retry
                                resp_item_retry = _ebay_api_request(
                                    'PUT',
                                    f'/sell/inventory/v1/inventory_item/{sku_encoded}',
                                    payload=retry_inv_payload
                                )
                                if resp_item_retry.status_code < 400:
                                    inventory_payload = retry_inv_payload
                                    resp_pub_retry = _ebay_api_request('POST', f'/sell/inventory/v1/offer/{offer_id}/publish')
                                    if resp_pub_retry.status_code < 400:
                                        pub_data = resp_pub_retry.json() if resp_pub_retry.text else {}
                                        listing_id = pub_data.get('listingId')
                                        return _finish_ebay_publish_success(
                                            listing_id=listing_id,
                                            pub_data=pub_data,
                                            extra={
                                                'imageSourceAutoFixed': True,
                                                'imageCount': len(fallback_images)
                                            }
                                        )
                                    err_pub = _ebay_extract_error(resp_pub_retry)
                                    low = err_pub.lower()
                                else:
                                    err_pub = _ebay_extract_error(resp_item_retry)
                                    low = err_pub.lower()
                except Exception:
                    pass
            # Publish-time condition/category mismatch recovery:
            # try fallback condition updates even when initial inventory PUT succeeded.
            if (('invalid item condition information' in low) or ('condition id is invalid' in low)) and offer_id and inventory_payload:
                tried_conditions = []
                try:
                    sku_local = (data.get('sku') or (offer_payload or {}).get('sku') or data.get('upc') or '').strip()
                    category_for_recovery = (data.get('categoryId') or (offer_payload or {}).get('categoryId') or '').strip()
                    marketplace_for_recovery = (data.get('marketplaceId') or (offer_payload or {}).get('marketplaceId') or settings.get('ebay_marketplace_id') or 'EBAY_US').strip()
                    if sku_local:
                        inv_payload = dict(inventory_payload or {})
                        from urllib.parse import quote
                        sku_encoded = quote(sku_local, safe='')

                        # First, run the standard helper once.
                        inv_payload, _cond_fixed2, _orig_cond2, _tried2 = _listingagent_put_inventory_item_with_condition_fallback(
                            sku_local,
                            inv_payload,
                            category_id=category_for_recovery,
                            marketplace_id=marketplace_for_recovery
                        )
                        if isinstance(_tried2, list):
                            tried_conditions.extend([c for c in _tried2 if c])
                        resp_pub_retry = _ebay_api_request('POST', f'/sell/inventory/v1/offer/{offer_id}/publish')
                        if resp_pub_retry.status_code < 400:
                            pub_data = resp_pub_retry.json() if resp_pub_retry.text else {}
                            listing_id = pub_data.get('listingId')
                            return _finish_ebay_publish_success(
                                listing_id=listing_id,
                                pub_data=pub_data,
                                extra={
                                    'conditionAutoFixed': True,
                                    'resolvedCondition': (inv_payload.get('condition') or '').strip(),
                                    'conditionTried': tried_conditions
                                }
                            )
                        err_pub = _ebay_extract_error(resp_pub_retry)
                        low = err_pub.lower()

                        # If still condition-related, force a condition sweep.
                        if ('invalid item condition information' in low) or ('condition id is invalid' in low):
                            fallback_conditions = _listingagent_get_condition_candidates(
                                inv_payload.get('condition') or '',
                                category_id=category_for_recovery,
                                marketplace_id=marketplace_for_recovery
                            )
                            current = (inv_payload.get('condition') or '').strip().upper()
                            for cond in fallback_conditions:
                                if cond == current:
                                    continue
                                if cond not in tried_conditions:
                                    tried_conditions.append(cond)
                                retry_payload = dict(inv_payload)
                                retry_payload['condition'] = cond
                                resp_item_retry = _ebay_api_request('PUT', f'/sell/inventory/v1/inventory_item/{sku_encoded}', payload=retry_payload)
                                if resp_item_retry.status_code >= 400:
                                    continue
                                inv_payload = retry_payload
                                resp_pub_retry2 = _ebay_api_request('POST', f'/sell/inventory/v1/offer/{offer_id}/publish')
                                if resp_pub_retry2.status_code < 400:
                                    pub_data = resp_pub_retry2.json() if resp_pub_retry2.text else {}
                                    listing_id = pub_data.get('listingId')
                                    return _finish_ebay_publish_success(
                                        listing_id=listing_id,
                                        pub_data=pub_data,
                                        extra={
                                            'conditionAutoFixed': True,
                                            'resolvedCondition': cond,
                                            'conditionTried': tried_conditions
                                        }
                                    )
                                err_pub = _ebay_extract_error(resp_pub_retry2)
                                low = err_pub.lower()
                                if ('invalid item condition information' not in low) and ('condition id is invalid' not in low):
                                    break
                except _ListingAgentUserError:
                    pass
            # Treat idempotent "already published" style responses as success.
            if ('already published' in low) or ('already listed' in low):
                listing_id = None
                try:
                    resp_offer_state = _ebay_api_request('GET', f'/sell/inventory/v1/offer/{offer_id}')
                    if resp_offer_state.status_code < 400:
                        offer_state = resp_offer_state.json() if resp_offer_state.text else {}
                        listing_id = offer_state.get('listingId') or offer_state.get('listing_id')
                except Exception:
                    pass
                return _finish_ebay_publish_success(
                    listing_id=listing_id,
                    pub_data={'alreadyPublished': True, 'offerId': offer_id}
                )
            return jsonify({'success': False, 'error': err_pub, 'missingAspect': _extract_missing_ebay_aspect(err_pub)}), 400

        pub_data = resp_pub.json() if resp_pub.text else {}
        listing_id = pub_data.get('listingId')
        return _finish_ebay_publish_success(listing_id=listing_id, pub_data=pub_data)
    except _ListingAgentUserError as e:
        payload = {'success': False, 'error': str(e)}
        payload.update(e.extra or {})
        return jsonify(payload), e.status_code
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:ebay_publish')}), 500

# -----------------------------
# Listing Agent - Amazon (SP-API)
# -----------------------------

def _amazon_marketplace_from_id(marketplace_id: str):
    try:
        from sp_api.base import Marketplaces
        if not marketplace_id:
            return Marketplaces.US
        for name in dir(Marketplaces):
            if not name.isupper():
                continue
            mp = getattr(Marketplaces, name)
            if getattr(mp, 'marketplace_id', None) == marketplace_id:
                return mp
        return Marketplaces.US
    except Exception:
        # If SP-API isn't installed or something is misconfigured, default to US.
        return None

def _amazon_spapi_context():
    """Load SP-API credentials + seller/marketplace from amazon_credentials.json."""
    creds_path = BASE_DIR / 'amazon_credentials.json'
    if not creds_path.exists():
        raise _ListingAgentUserError('amazon_credentials.json not found', status_code=503)

    with open(creds_path, 'r', encoding='utf-8') as f:
        c = json.load(f)

    seller_id = (c.get('seller_id') or '').strip()
    marketplace_id = (c.get('marketplace_id') or '').strip() or 'ATVPDKIKX0DER'
    if not seller_id:
        raise _ListingAgentUserError('Amazon seller_id missing in amazon_credentials.json', status_code=503)

    credentials = {
        'refresh_token': c.get('refresh_token'),
        'lwa_app_id': c.get('lwa_app_id'),
        'lwa_client_secret': c.get('lwa_client_secret', ''),
    }
    if c.get('aws_access_key') and c.get('aws_secret_key'):
        credentials['aws_access_key'] = c.get('aws_access_key')
        credentials['aws_secret_key'] = c.get('aws_secret_key')
    if c.get('role_arn'):
        credentials['role_arn'] = c.get('role_arn')

    marketplace = _amazon_marketplace_from_id(marketplace_id)
    return credentials, seller_id, marketplace_id, marketplace

def _amazon_get_listing_product_type(li, seller_id, sku, marketplace_id, cache=None):
    cache = cache if cache is not None else {}
    if sku in cache:
        return cache.get(sku)
    try:
        resp = li.get_listings_item(
            seller_id,
            sku,
            marketplaceIds=[marketplace_id],
            includedData=['summaries']
        )
        if getattr(resp, 'errors', None):
            raise Exception(str(resp.errors))
        payload = resp.payload or {}
        summaries = payload.get('summaries') or []
        pt = None
        for s in summaries:
            pt = s.get('productType')
            if pt:
                break
        if not pt:
            pt = payload.get('productType')
        if pt:
            cache[sku] = pt
        return pt
    except Exception:
        return None

def _amazon_get_catalog_product_type(credentials, marketplace, marketplace_id, asin):
    if not asin:
        return None
    try:
        from sp_api.api import CatalogItems
        ci = CatalogItems(credentials=credentials, marketplace=marketplace, version='2022-04-01')
        resp = ci.get_catalog_item(
            asin,
            marketplaceIds=[marketplace_id],
            includedData=['productTypes', 'summaries']
        )
        if getattr(resp, 'errors', None):
            return None
        payload = resp.payload or {}
        pts = payload.get('productTypes') or []
        for pt in pts:
            if isinstance(pt, str) and pt.strip():
                return pt.strip()
            if isinstance(pt, dict):
                v = (pt.get('productType') or pt.get('product_type') or pt.get('name') or '').strip()
                if v:
                    return v

        summaries = payload.get('summaries') or []
        for s in summaries:
            if not isinstance(s, dict):
                continue
            v = (s.get('productType') or s.get('product_type') or '').strip()
            if v:
                return v

        # Some responses may nest product types elsewhere
        pt = payload.get('productType')
        if isinstance(pt, str) and pt.strip():
            return pt.strip()
        if isinstance(pt, dict):
            v = (pt.get('productType') or pt.get('product_type') or '').strip()
            if v:
                return v
        return None
    except Exception:
        return None

def _amazon_resolve_asin_from_upc(credentials, marketplace, marketplace_id, upc):
    """Best-effort Catalog lookup: resolve first ASIN for a UPC/EAN/GTIN."""
    upc = (upc or '').strip()
    if not upc:
        return None
    try:
        from sp_api.api import CatalogItems
        ci = CatalogItems(credentials=credentials, marketplace=marketplace, version='2022-04-01')
        id_type = 'UPC'
        if upc.isdigit():
            if len(upc) == 13:
                id_type = 'EAN'
            elif len(upc) == 14:
                id_type = 'GTIN'
        resp = ci.search_catalog_items(
            identifiers=[upc],
            identifiersType=id_type,
            marketplaceIds=[marketplace_id],
            includedData=['summaries'],
            pageSize=8
        )
        if getattr(resp, 'errors', None):
            return None
        payload = resp.payload or {}
        items = payload.get('items') or []
        if not isinstance(items, list):
            return None
        for it in items:
            if not isinstance(it, dict):
                continue
            asin = (it.get('asin') or '').strip()
            if asin:
                return asin
        return None
    except Exception:
        return None

def _amazon_find_local_sku_by_asin(asin):
    asin = (asin or '').strip()
    if not asin:
        return None
    try:
        with db_connection('amazonStore.db') as conn:
            cur = conn.cursor()
            cur.execute('''
                SELECT TRIM(COALESCE(SKU, '')) AS sku
                FROM ITEMS
                WHERE TRIM(COALESCE(ASIN, '')) = ? COLLATE NOCASE
                ORDER BY COALESCE(LAST_UPDATED, '') DESC, ID DESC
                LIMIT 1
            ''', (asin,))
            row = cur.fetchone()
            if not row:
                return None
            sku = (row['sku'] or '').strip()
            return sku or None
    except Exception:
        return None

def _amazon_build_price_feed_xml(*, seller_id, jobs, currency='USD'):
    # Legacy XML feed for price updates (does not require product type).
    from xml.sax.saxutils import escape as _xesc
    lines = [
        '<?xml version="1.0" encoding="utf-8"?>',
        '<AmazonEnvelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="amzn-envelope.xsd">',
        '  <Header>',
        '    <DocumentVersion>1.01</DocumentVersion>',
        f'    <MerchantIdentifier>{_xesc(str(seller_id))}</MerchantIdentifier>',
        '  </Header>',
        '  <MessageType>Price</MessageType>',
    ]
    msg_id = 1
    for j in jobs:
        sku = j.get('sku')
        price = j.get('new_price')
        if not sku or price is None:
            continue
        lines.extend([
            '  <Message>',
            f'    <MessageID>{msg_id}</MessageID>',
            '    <Price>',
            f'      <SKU>{_xesc(str(sku))}</SKU>',
            f'      <StandardPrice currency="{_xesc(str(currency).upper())}">{float(price):.2f}</StandardPrice>',
            '    </Price>',
            '  </Message>',
        ])
        msg_id += 1
    lines.append('</AmazonEnvelope>')
    return '\n'.join(lines).encode('utf-8')

def _amazon_submit_price_feed_json(*, credentials, marketplace, marketplace_id, seller_id, jobs, currency='USD', offer_audience='ALL'):
    from sp_api.api import Feeds
    feed = {
        'header': {
            'sellerId': seller_id,
            'version': '2.0',
            'issueLocale': 'en_US'
        },
        'messages': []
    }
    msg_id = 1
    for j in jobs:
        sku = j.get('sku')
        product_type = j.get('product_type')
        price = j.get('new_price')
        if not sku or not product_type:
            continue
        attrs = _amazon_offer_price_attrs(currency, price, marketplace_id, offer_audience=offer_audience)
        feed['messages'].append({
            'messageId': msg_id,
            'sku': sku,
            'operationType': 'PATCH',
            'productType': product_type,
            'patches': [{
                'op': 'replace',
                'path': '/attributes/purchasable_offer',
                'value': attrs.get('purchasable_offer')
            }]
        })
        msg_id += 1

    if not feed['messages']:
        raise Exception('No feed messages to submit')

    feeds = Feeds(credentials=credentials, marketplace=marketplace)
    content_type = 'application/json; charset=UTF-8'
    body = json.dumps(feed, ensure_ascii=True).encode('utf-8')
    try:
        doc_id, url, uploaded = _amazon_create_feed_document(feeds, content_type, body)
    except Exception as e:
        raise Exception(_amazon_feeds_error(e, 'create_feed_document'))
    if not doc_id:
        raise Exception('Failed to create feed document')
    if not uploaded:
        if not url:
            raise Exception('Feed document upload URL missing')
        up = requests.put(url, data=body, headers={'Content-Type': content_type})
        if up.status_code >= 400:
            raise Exception(f'Feed upload failed ({up.status_code})')

    try:
        feed_resp = _amazon_create_feed(
            feeds,
            feed_type='JSON_LISTINGS_FEED',
            marketplace_ids=[marketplace_id],
            input_feed_document_id=doc_id
        )
        feed_payload = getattr(feed_resp, 'payload', None) or {}
    except Exception as e:
        raise Exception(_amazon_feeds_error(e, 'create_feed'))
    feed_id = feed_payload.get('feedId') or feed_payload.get('feed_id')
    if not feed_id:
        raise Exception('Feed submission failed')
    return feed_id

def _amazon_submit_price_feed_xml(*, credentials, marketplace, marketplace_id, seller_id, jobs, currency='USD'):
    from sp_api.api import Feeds
    feeds = Feeds(credentials=credentials, marketplace=marketplace)
    content_type = 'text/xml; charset=UTF-8'
    body = _amazon_build_price_feed_xml(seller_id=seller_id, jobs=jobs, currency=currency)
    try:
        doc_id, url, uploaded = _amazon_create_feed_document(feeds, content_type, body)
    except Exception as e:
        raise Exception(_amazon_feeds_error(e, 'create_feed_document'))
    if not doc_id:
        raise Exception('Failed to create feed document')
    if not uploaded:
        if not url:
            raise Exception('Feed document upload URL missing')
        up = requests.put(url, data=body, headers={'Content-Type': content_type})
        if up.status_code >= 400:
            raise Exception(f'Feed upload failed ({up.status_code})')

    try:
        feed_resp = _amazon_create_feed(
            feeds,
            feed_type='POST_PRODUCT_PRICING_DATA',
            marketplace_ids=[marketplace_id],
            input_feed_document_id=doc_id
        )
        feed_payload = getattr(feed_resp, 'payload', None) or {}
    except Exception as e:
        raise Exception(_amazon_feeds_error(e, 'create_feed'))
    feed_id = feed_payload.get('feedId') or feed_payload.get('feed_id')
    if not feed_id:
        raise Exception('Feed submission failed')
    return feed_id

def _amazon_submit_price_feed(*, credentials, marketplace, marketplace_id, seller_id, jobs, currency='USD', offer_audience='ALL'):
    try:
        return _amazon_submit_price_feed_json(
            credentials=credentials,
            marketplace=marketplace,
            marketplace_id=marketplace_id,
            seller_id=seller_id,
            jobs=jobs,
            currency=currency,
            offer_audience=offer_audience
        )
    except Exception as e:
        json_err = _amazon_format_spapi_error(e)
        try:
            return _amazon_submit_price_feed_xml(
                credentials=credentials,
                marketplace=marketplace,
                marketplace_id=marketplace_id,
                seller_id=seller_id,
                jobs=jobs,
                currency=currency
            )
        except Exception as e2:
            xml_err = _amazon_format_spapi_error(e2)
            raise Exception(f"JSON feed failed: {json_err} | XML feed failed: {xml_err}")

def _amazon_parse_feed_report(body_bytes):
    """Parse Amazon feed processing report (JSON or XML). Returns dict with errors/warnings."""
    out = {
        'error_count': 0,
        'warning_count': 0,
        'errors': [],
        'warnings': [],
        'raw_excerpt': ''
    }
    if not body_bytes:
        return out
    try:
        raw = body_bytes.decode('utf-8', errors='replace')
    except Exception:
        try:
            raw = body_bytes.decode('latin-1', errors='replace')
        except Exception:
            raw = ''
    out['raw_excerpt'] = (raw[:1200] + '...') if len(raw) > 1200 else raw

    # Try JSON first
    try:
        import json as _json
        js = _json.loads(raw)
        issues = []
        if isinstance(js, dict):
            issues = js.get('issues') or js.get('issuesWithAttributes') or js.get('messagesWithIssues') or []
        if isinstance(issues, dict):
            issues = [issues]
        for it in issues:
            sev = str(it.get('severity') or it.get('Severity') or '').upper()
            msg = it.get('message') or it.get('messageText') or it.get('description') or it.get('Message') or ''
            code = it.get('code') or it.get('Code') or ''
            if sev == 'ERROR':
                out['error_count'] += 1
                out['errors'].append({'code': code, 'message': msg})
            elif sev == 'WARNING':
                out['warning_count'] += 1
                out['warnings'].append({'code': code, 'message': msg})
        return out
    except Exception:
        pass

    # Fallback: XML
    try:
        import xml.etree.ElementTree as _ET
        root = _ET.fromstring(raw)
        for result in root.findall('.//Result'):
            code = (result.findtext('ResultCode') or '').strip().lower()
            msg = (result.findtext('ResultMessage') or '').strip()
            if code == 'error':
                out['error_count'] += 1
                out['errors'].append({'code': 'Error', 'message': msg})
            elif code == 'warning':
                out['warning_count'] += 1
                out['warnings'].append({'code': 'Warning', 'message': msg})
        return out
    except Exception:
        return out

def _amazon_get_feed_document_info(feeds, feed_document_id):
    import inspect as _inspect
    try:
        params = _inspect.signature(feeds.get_feed_document).parameters
    except Exception:
        params = {}
    if not params or 'feedDocumentId' in params or any(p.kind == _inspect.Parameter.VAR_KEYWORD for p in params.values()):
        try:
            return feeds.get_feed_document(feedDocumentId=feed_document_id)
        except TypeError:
            pass
    return feeds.get_feed_document(feed_document_id)

def _amazon_get_feed_status(credentials, marketplace, feed_id):
    from sp_api.api import Feeds
    feeds = Feeds(credentials=credentials, marketplace=marketplace)
    try:
        resp = feeds.get_feed(feedId=feed_id)
    except TypeError:
        resp = feeds.get_feed(feed_id)
    payload = getattr(resp, 'payload', None) or {}
    status = payload.get('processingStatus') or payload.get('processing_status') or payload.get('status')
    result_doc = payload.get('resultFeedDocumentId') or payload.get('result_feed_document_id')
    return {
        'feed_id': feed_id,
        'status': status,
        'result_feed_document_id': result_doc,
        'raw': payload
    }

def _amazon_download_feed_document(url):
    import gzip as _gzip
    if not url:
        return None
    resp = requests.get(url, timeout=30)
    if resp.status_code != 200:
        return None
    data = resp.content or b''
    # Decompress if gzipped
    try:
        if data[:2] == b'\x1f\x8b':
            data = _gzip.decompress(data)
    except Exception:
        pass
    return data

@app.route('/api/listingagent/amazon/account_check', methods=['GET'])
def api_listingagent_amazon_account_check():
    """Diagnostic endpoint: validate Amazon account linkage and seller-id usability."""
    try:
        credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        mp_override = (request.args.get('marketplaceId') or '').strip()
        mp_id = mp_override or marketplace_id
        probe_sku = (request.args.get('sku') or '').strip()

        def _mask(v):
            s = (v or '').strip()
            if len(s) <= 8:
                return s
            return f"{s[:4]}...{s[-4:]}"

        out = {
            'success': True,
            'seller_id_hint': _mask(seller_id),
            'marketplace_id': mp_id,
            'sellers_api': {},
            'listings_probe': {},
        }

        # 1) Sellers API probe (does not require sellerId argument in most versions).
        try:
            from sp_api.api import Sellers
            sellers = Sellers(credentials=credentials, marketplace=marketplace)
            resp = sellers.get_marketplace_participations()
            if getattr(resp, 'errors', None):
                out['sellers_api']['errors'] = resp.errors
            else:
                payload = getattr(resp, 'payload', None) or {}
                mps = []
                parts = payload.get('marketplaceParticipations') or payload.get('marketplace_participations') or []
                if isinstance(parts, list):
                    for p in parts:
                        if not isinstance(p, dict):
                            continue
                        m = p.get('marketplace') or {}
                        pid = (m.get('id') or m.get('marketplaceId') or '').strip()
                        name = (m.get('name') or '').strip()
                        is_part = bool((p.get('participation') or {}).get('isParticipating'))
                        if pid:
                            mps.append({'id': pid, 'name': name, 'participating': is_part})
                out['sellers_api']['marketplaces'] = mps[:32]
                out['sellers_api']['marketplace_enabled'] = any((x.get('id') == mp_id and x.get('participating')) for x in mps)
        except Exception as e:
            out['sellers_api']['error'] = _amazon_format_spapi_error(e)

        # 2) Listings probe using seller_id (this is what put_offer depends on).
        try:
            from sp_api.api import ListingsItems
            li = ListingsItems(credentials=credentials, marketplace=marketplace)

            if not probe_sku:
                try:
                    with db_connection('amazonStore.db') as conn:
                        cur = conn.cursor()
                        cur.execute('''
                            SELECT TRIM(COALESCE(SKU,'')) AS sku
                            FROM ITEMS
                            WHERE TRIM(COALESCE(SKU,'')) != ''
                            ORDER BY COALESCE(LAST_UPDATED,'') DESC, ID DESC
                            LIMIT 1
                        ''')
                        r = cur.fetchone()
                        probe_sku = ((r['sku'] if r else '') or '').strip()
                except Exception:
                    probe_sku = ''

            out['listings_probe']['sku'] = probe_sku
            if probe_sku:
                resp = li.get_listings_item(
                    seller_id,
                    probe_sku,
                    marketplaceIds=[mp_id],
                    includedData=['summaries']
                )
                if getattr(resp, 'errors', None):
                    out['listings_probe']['errors'] = resp.errors
                else:
                    out['listings_probe']['ok'] = True
            else:
                out['listings_probe']['note'] = 'No SKU available for probe'
        except Exception as e:
            out['listings_probe']['error'] = _amazon_format_spapi_error(e)

        return jsonify(out)
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_account_check')}), 500

@app.route('/api/listingagent/amazon/restriction_check', methods=['GET'])
def api_listingagent_amazon_restriction_check():
    """Lightweight pre-check for ASIN gating/restrictions (cached)."""
    try:
        asin = (request.args.get('asin') or '').strip().upper()
        if not asin:
            return jsonify({'success': False, 'error': 'asin is required'}), 400

        condition_type = (request.args.get('conditionType') or '').strip()
        mp_override = (request.args.get('marketplaceId') or '').strip()
        force_refresh = (request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes', 'on')

        credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        mp_id = mp_override or marketplace_id
        info = _amazon_check_listing_restrictions_cached(
            credentials,
            marketplace,
            seller_id,
            mp_id,
            asin,
            condition_type=condition_type,
            force_refresh=force_refresh
        ) or {}

        warning = ''
        if not bool(info.get('checked')):
            hints = _amazon_restriction_error_hints(info, mp_id)
            warning = ' '.join(hints).strip()

        return jsonify({
            'success': True,
            'asin': asin,
            'marketplaceId': mp_id,
            'conditionType': condition_type,
            'restriction': {
                'checked': bool(info.get('checked')),
                'restricted': bool(info.get('restricted')),
                'reasons': (info.get('reasons') or [])[:12]
            },
            'cached': bool(info.get('_cached')),
            'warning': warning
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_restriction_check')}), 500

@app.route('/api/listingagent/amazon/catalog_search', methods=['GET'])
def api_listingagent_amazon_catalog_search():
    """Search Amazon catalog by keyword/UPC (best-effort) to suggest ASINs."""
    try:
        q = (request.args.get('q') or request.args.get('upc') or '').strip()
        if not q:
            return jsonify({'success': False, 'error': 'q is required'}), 400

        limit = _listingagent_parse_int(request.args.get('limit'), 8) or 8
        limit = max(1, min(limit, 20))
        include_raw = (request.args.get('raw') or '').lower() == 'true'
        mode = (request.args.get('mode') or '').strip().lower()
        title_hint = (request.args.get('title') or '').strip()  # optional item title for supplemental keyword search
        identifiers_type = (request.args.get('identifiersType') or '').strip().upper()
        q_no_space = q.replace(' ', '')

        credentials, _seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        from sp_api.api import CatalogItems
        from sp_api.base.exceptions import SellingApiException

        ci = CatalogItems(credentials=credentials, marketplace=marketplace, version='2022-04-01')

        # Prefer identifier search when q looks like a UPC/GTIN (or explicitly requested).
        use_identifiers = False
        if mode in ('upc', 'gtin', 'identifier'):
            use_identifiers = True
        elif identifiers_type:
            use_identifiers = True
        elif mode in ('asin',):
            use_identifiers = True
            if not identifiers_type:
                identifiers_type = 'ASIN'
        elif q_no_space.isalnum() and len(q_no_space) == 10 and any(ch.isdigit() for ch in q_no_space) and any(ch.isalpha() for ch in q_no_space):
            # Likely ASIN (avoid treating plain words as ASIN).
            use_identifiers = True
            if not identifiers_type:
                identifiers_type = 'ASIN'
        elif q.isdigit() and 8 <= len(q) <= 14:
            use_identifiers = True

        if use_identifiers:
            # Heuristic: UPC=8/10/11/12, EAN=13, GTIN=14. Allow override via identifiersType=...
            if not identifiers_type:
                if len(q) == 13:
                    identifiers_type = 'EAN'
                elif len(q) == 14:
                    identifiers_type = 'GTIN'
                elif len(q) == 10:
                    # Commonly ISBN-10 when numeric; if this is actually UPC/other, keyword fallback will still work.
                    identifiers_type = 'ISBN'
                else:
                    identifiers_type = 'UPC'

        def _do_keywords():
            return ci.search_catalog_items(
                keywords=[q],
                marketplaceIds=[marketplace_id],
                includedData=['summaries', 'images'],
                pageSize=limit
            )

        def _do_identifiers():
            return ci.search_catalog_items(
                identifiers=[q],
                identifiersType=identifiers_type,
                marketplaceIds=[marketplace_id],
                includedData=['summaries', 'images'],
                pageSize=limit
            )

        try:
            resp = _do_identifiers() if use_identifiers else _do_keywords()
        except SellingApiException:
            # Some accounts/marketplaces/product-types can be finicky; fall back to keyword search.
            if use_identifiers:
                resp = _do_keywords()
            else:
                raise
        if resp.errors:
            return jsonify({'success': False, 'error': str(resp.errors)}), 400

        payload = resp.payload or {}
        items = payload.get('items') or []
        # If identifier search returned nothing and the caller didn't force identifier mode, try keywords.
        if use_identifiers and not items and mode not in ('upc','gtin','identifier','asin') and not (request.args.get('identifiersType') or '').strip():
            try:
                resp_kw = _do_keywords()
                if not resp_kw.errors:
                    payload = resp_kw.payload or {}
                    items = payload.get('items') or []
            except Exception:
                pass

        # Supplement identifier results with a keyword search using the item title, to surface
        # more ASIN variants. Deduplicate by ASIN; identifier results take priority.
        if use_identifiers and title_hint and len(items) < limit:
            try:
                resp_title = ci.search_catalog_items(
                    keywords=[title_hint],
                    marketplaceIds=[marketplace_id],
                    includedData=['summaries', 'images'],
                    pageSize=limit
                )
                if not resp_title.errors:
                    existing_asins = {(it.get('asin') or '').strip().upper() for it in items}
                    for extra_it in (resp_title.payload or {}).get('items') or []:
                        asin_up = (extra_it.get('asin') or '').strip().upper()
                        if asin_up and asin_up not in existing_asins:
                            items.append(extra_it)
                            existing_asins.add(asin_up)
                            if len(items) >= limit:
                                break
            except Exception:
                pass

        # Pre-fetch prices from amazonStore.db for any matching ASINs
        asin_prices = {}
        try:
            raw_asins = [(it.get('asin') or '').strip() for it in items[:limit] if (it.get('asin') or '').strip()]
            if raw_asins:
                placeholders = ','.join('?' * len(raw_asins))
                with db_connection('amazonStore.db') as aconn:
                    acur = aconn.cursor()
                    acur.execute(f'SELECT ASIN, PRICE FROM ITEMS WHERE ASIN IN ({placeholders})', raw_asins)
                    for row in acur.fetchall():
                        try:
                            asin_prices[str(row[0] or '').strip().upper()] = float(row[1]) if row[1] is not None else None
                        except Exception:
                            pass
        except Exception:
            pass

        results = []
        for it in items[:limit]:
            asin = (it.get('asin') or '').strip()
            title = ''
            brand = ''
            summaries = it.get('summaries') or []
            if summaries:
                s0 = summaries[0] or {}
                title = s0.get('itemName') or s0.get('item_name') or ''
                brand = s0.get('brandName') or s0.get('brand_name') or ''

            image_url = ''
            for grp in (it.get('images') or []):
                imgs = grp.get('images') or []
                if imgs:
                    image_url = (imgs[0].get('link') or '').strip()
                    if image_url:
                        break

            store_price = asin_prices.get(asin.upper())
            results.append({
                'asin': asin,
                'title': title or '',
                'brand': brand or '',
                'image': image_url or '',
                'store_price': store_price,
            })

        out = {'success': True, 'results': results}
        if include_raw:
            out['raw'] = payload
        return jsonify(out)

    except Exception as e:
        # SellingApiException string tends to be safe+useful (issues, codes, etc.)
        from sp_api.base.exceptions import SellingApiException
        if isinstance(e, SellingApiException):
            return jsonify({'success': False, 'error': str(e)}), 400
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_catalog_search')}), 500

@app.route('/api/listingagent/amazon/catalog_item', methods=['GET'])
def api_listingagent_amazon_catalog_item():
    """Fetch catalog details for an ASIN (public product page template data)."""
    try:
        asin = (request.args.get('asin') or '').strip()
        if not asin:
            return jsonify({'success': False, 'error': 'asin is required'}), 400

        included = (request.args.get('includedData') or 'summaries,images,attributes').strip()
        included_data = [x.strip() for x in included.split(',') if x.strip()]
        include_raw = (request.args.get('raw') or '').lower() == 'true'

        credentials, _seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        from sp_api.api import CatalogItems
        from sp_api.base.exceptions import SellingApiException

        ci = CatalogItems(credentials=credentials, marketplace=marketplace, version='2022-04-01')
        resp = ci.get_catalog_item(
            asin,
            marketplaceIds=[marketplace_id],
            includedData=included_data
        )
        if resp.errors:
            return jsonify({'success': False, 'error': str(resp.errors)}), 400

        payload = resp.payload or {}
        out = {'success': True, 'data': payload}
        if include_raw:
            out['raw'] = payload
        return jsonify(out)

    except Exception as e:
        from sp_api.base.exceptions import SellingApiException
        if isinstance(e, SellingApiException):
            return jsonify({'success': False, 'error': str(e)}), 400
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_catalog_item')}), 500

@app.route('/api/listingagent/amazon/listing', methods=['GET'])
def api_listingagent_amazon_get_listing():
    """Fetch live SKU details from Amazon Listings Items API."""
    try:
        sku = (request.args.get('sku') or '').strip()
        if not sku:
            return jsonify({'success': False, 'error': 'sku is required'}), 400

        included = (request.args.get('includedData') or 'summaries,attributes,issues').strip()
        included_data = [x.strip() for x in included.split(',') if x.strip()]

        credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        from sp_api.api import ListingsItems
        from sp_api.base.exceptions import SellingApiException

        li = ListingsItems(credentials=credentials, marketplace=marketplace)
        resp = li.get_listings_item(
            seller_id,
            sku,
            marketplaceIds=[marketplace_id],
            includedData=included_data
        )
        if resp.errors:
            return jsonify({'success': False, 'error': str(resp.errors)}), 400
        return jsonify({'success': True, 'data': resp.payload or {}})

    except Exception as e:
        from sp_api.base.exceptions import SellingApiException
        if isinstance(e, SellingApiException):
            return jsonify({'success': False, 'error': str(e)}), 400
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_get_listing')}), 500

def _amazon_normalize_condition_type(raw, default_condition='used_good'):
    allowed = {
        'new_new',
        'used_like_new',
        'used_very_good',
        'used_good',
        'used_acceptable',
        'collectible_like_new',
        'collectible_very_good',
        'collectible_good',
        'collectible_acceptable',
        'refurbished_refurbished',
        'club_club',
    }
    if raw is None:
        return default_condition
    s = str(raw).strip()
    if not s:
        return default_condition
    if s.isdigit():
        code_map = {
            11: 'new_new',
            1: 'used_like_new',
            2: 'used_very_good',
            3: 'used_good',
            4: 'used_acceptable',
            5: 'collectible_like_new',
            6: 'collectible_very_good',
            7: 'collectible_good',
            8: 'collectible_acceptable',
            10: 'refurbished_refurbished',
        }
        return code_map.get(int(s), default_condition)

    lowered = s.lower().strip()
    label_map = {
        'new': 'new_new',
        'brand_new': 'new_new',
        'used_like_new': 'used_like_new',
        'used_very_good': 'used_very_good',
        'used_good': 'used_good',
        'used_acceptable': 'used_acceptable',
        'collectible_like_new': 'collectible_like_new',
        'collectible_very_good': 'collectible_very_good',
        'collectible_good': 'collectible_good',
        'collectible_acceptable': 'collectible_acceptable',
        'refurbished': 'refurbished_refurbished',
        'refurbished_refurbished': 'refurbished_refurbished',
        'club': 'club_club',
        'club_club': 'club_club',
    }
    cleaned = _re.sub(r'[^a-z0-9]+', '_', lowered).strip('_')
    if cleaned in label_map:
        return label_map[cleaned]
    if cleaned in allowed:
        return cleaned
    return default_condition

def _amazon_normalize_fulfillment_channel(raw, default_fc='DEFAULT'):
    if raw is None:
        return default_fc
    s = str(raw).strip().upper()
    if not s:
        return default_fc
    if s in ('DEFAULT', 'AMAZON_NA'):
        return s
    if s == 'AFN':
        return 'AMAZON_NA'
    if s == 'MFN':
        return 'DEFAULT'
    return default_fc

def _amazon_format_spapi_error(err):
    try:
        from sp_api.base.exceptions import SellingApiException
        if isinstance(err, SellingApiException):
            payload = getattr(err, 'payload', None) or getattr(err, 'errors', None)
            if payload:
                return f"{err} | payload={payload}"
    except Exception:
        pass
    return str(err)

def _amazon_feeds_error(err, step=''):
    msg = _amazon_format_spapi_error(err)
    if step:
        return f"{step}: {msg}"
    return msg

def _amazon_create_feed_document(feeds, content_type, body_bytes):
    import inspect as _inspect
    f = io.BytesIO(body_bytes)
    params = {}
    try:
        params = _inspect.signature(feeds.create_feed_document).parameters
    except Exception:
        params = {}

    # Try file-based signature (newer sp-api versions)
    if 'file' in params or any(p.kind == _inspect.Parameter.VAR_KEYWORD for p in params.values()):
        for kwargs in (
            {'file': f, 'content_type': content_type},
            {'file': f, 'contentType': content_type},
        ):
            try:
                f.seek(0)
                resp = feeds.create_feed_document(**kwargs)
                payload = getattr(resp, 'payload', None) or {}
                doc_id = payload.get('feedDocumentId') or payload.get('feed_document_id')
                url = payload.get('url')
                return doc_id, url, True
            except TypeError:
                continue
    # Fallback: legacy signature (no file upload)
    resp = feeds.create_feed_document(contentType=content_type)
    payload = getattr(resp, 'payload', None) or {}
    doc_id = payload.get('feedDocumentId') or payload.get('feed_document_id')
    url = payload.get('url')
    return doc_id, url, False

def _amazon_create_feed(feeds, *, feed_type, marketplace_ids, input_feed_document_id):
    import inspect as _inspect
    try:
        params = _inspect.signature(feeds.create_feed).parameters
    except Exception:
        params = {}

    # Newer sp-api supports keyword args
    if not params or 'feedType' in params or 'feed_type' in params or any(p.kind == _inspect.Parameter.VAR_KEYWORD for p in params.values()):
        try:
            return feeds.create_feed(feedType=feed_type, marketplaceIds=marketplace_ids, inputFeedDocumentId=input_feed_document_id)
        except TypeError:
            try:
                return feeds.create_feed(feed_type=feed_type, marketplace_ids=marketplace_ids, input_feed_document_id=input_feed_document_id)
            except Exception:
                pass

    # Legacy signature: (feed_type, input_feed_document_id, marketplace_ids)
    return feeds.create_feed(feed_type, input_feed_document_id, marketplace_ids)

def _amazon_update_price_spapi(li, seller_id, sku, mp_id, *, product_type, requirements, attrs):
    debug = {'attempts': []}

    def _record_attempt(method, body, resp=None, exc=None):
        entry = {'method': method, 'body': body}
        if resp is not None:
            entry['errors'] = getattr(resp, 'errors', None)
            try:
                payload = getattr(resp, 'payload', None) or {}
                if payload:
                    entry['payload_status'] = payload.get('status')
                    issues = payload.get('issues')
                    if issues:
                        entry['payload_issues'] = issues
            except Exception:
                pass
        if exc is not None:
            entry['exception'] = _amazon_format_spapi_error(exc)
        debug['attempts'].append(entry)

    def _payload_has_error(resp):
        try:
            payload = getattr(resp, 'payload', None) or {}
        except Exception:
            payload = {}
        if not payload:
            return False, None
        try:
            status = str(payload.get('status') or '').strip().upper()
        except Exception:
            status = ''
        issues = []
        try:
            issues = payload.get('issues') or []
        except Exception:
            issues = []
        err_issues = []
        try:
            for it in issues:
                sev = str(it.get('severity') or '').strip().upper()
                if sev == 'ERROR':
                    err_issues.append(it)
        except Exception:
            pass
        if err_issues:
            return True, f"issues={err_issues}"
        if status in ('INVALID', 'ERROR', 'REJECTED', 'FAILURE'):
            return True, f"status={status}"
        return False, None

    patch_failed = False
    if hasattr(li, 'patch_listings_item'):
        patch_body = {
            'productType': product_type,
            'patches': []
        }
        if attrs.get('purchasable_offer'):
            patch_body['patches'].append({
                'op': 'replace',
                'path': '/attributes/purchasable_offer',
                'value': attrs['purchasable_offer']
            })
        if attrs.get('condition_type'):
            patch_body['patches'].append({
                'op': 'replace',
                'path': '/attributes/condition_type',
                'value': attrs['condition_type']
            })
        if patch_body['patches']:
            try:
                resp = li.patch_listings_item(
                    seller_id,
                    sku,
                    marketplaceIds=[mp_id],
                    issueLocale='en_US',
                    body=patch_body
                )
                _record_attempt('PATCH', patch_body, resp=resp)
                if not getattr(resp, 'errors', None):
                    payload_err, payload_detail = _payload_has_error(resp)
                    if payload_err:
                        return False, debug, payload_detail
                    return True, debug, None
            except Exception as e:
                _record_attempt('PATCH', patch_body, exc=e)
                patch_failed = True

    put_body = {
        'productType': product_type,
        'requirements': requirements,
        'attributes': attrs
    }
    try:
        resp = li.put_listings_item(
            seller_id,
            sku,
            marketplaceIds=[mp_id],
            issueLocale='en_US',
            body=put_body
        )
        _record_attempt('PUT', put_body, resp=resp)
        if getattr(resp, 'errors', None):
            return False, debug, resp.errors
        payload_err, payload_detail = _payload_has_error(resp)
        if payload_err:
            return False, debug, payload_detail
        return True, debug, None
    except Exception as e:
        _record_attempt('PUT', put_body, exc=e)
        return False, debug, e

def _amazon_price_value_key(marketplace_id):
    # US marketplace expects "value". VAT marketplaces often use "value_with_tax".
    if not marketplace_id:
        return 'value'
    mp = str(marketplace_id).strip().upper()
    if mp == 'ATVPDKIKX0DER':
        return 'value'
    return 'value_with_tax'

def _amazon_offer_audience(settings=None):
    val = None
    try:
        if settings and settings.get('amazon_offer_audience'):
            val = str(settings.get('amazon_offer_audience')).strip()
    except Exception:
        val = None
    return val or 'ALL'

def _amazon_restriction_error_hints(restriction_info, marketplace_id):
    hints = []
    try:
        raw = (restriction_info or {}).get('raw') or {}
        attempts = raw.get('call_attempts') or []
        texts = []
        for a in attempts:
            if not isinstance(a, dict):
                continue
            err = (a.get('error') or '').strip()
            if err:
                texts.append(err.lower())
        joined = ' | '.join(texts)
        if "invalid 'sellerid' provided" in joined or 'invalid \"sellerid\" provided' in joined:
            hints.append('Amazon restriction check reports invalid sellerId for these credentials.')
        if "invalid 'marketplaceids' provided" in joined or 'invalid \"marketplaceids\" provided' in joined:
            hints.append(f"Amazon restriction check reports invalid marketplaceIds. Verify marketplace `{marketplace_id}` is enabled on this seller account.")
    except Exception:
        pass
    return hints

def _amazon_check_listing_restrictions(credentials, marketplace, seller_id, marketplace_id, asin, condition_type=''):
    """
    Best-effort check for Amazon gated/restricted listings.
    Returns:
      {
        'checked': bool,
        'restricted': bool,
        'reasons': [str...],
        'raw': dict
      }
    """
    out = {'checked': False, 'restricted': False, 'reasons': [], 'raw': {}}
    asin = (asin or '').strip()
    if not asin:
        return out
    try:
        from sp_api.api import ListingsRestrictions
        import inspect as _inspect
        lr = ListingsRestrictions(credentials=credentials, marketplace=marketplace)
        fn = getattr(lr, 'get_listings_restrictions', None)
        if not callable(fn):
            out['raw'] = {'error': 'get_listings_restrictions not available'}
            return out

        cond = (condition_type or '').strip()
        debug_attempts = []
        resp = None
        fatal_identity_error = ''

        # Keyword attempts first (different client versions use different names).
        kw_attempts = [
            {'asin': asin, 'sellerId': seller_id, 'marketplaceIds': [marketplace_id], 'conditionType': cond, 'reasonLocale': 'en_US'},
            {'asin': asin, 'sellerId': seller_id, 'marketplaceIds': marketplace_id, 'conditionType': cond, 'reasonLocale': 'en_US'},
            {'asin': asin, 'sellerId': seller_id, 'marketplaceIds': [marketplace_id], 'itemCondition': cond, 'reasonLocale': 'en_US'},
            {'asin': asin, 'sellerId': seller_id, 'marketplaceIds': [marketplace_id], 'reasonLocale': 'en_US'},
            {'asin': asin, 'sellerId': seller_id, 'conditionType': cond, 'reasonLocale': 'en_US'},
            {'asin': asin, 'sellerId': seller_id, 'conditionType': cond},
            {'asin': asin, 'sellerId': seller_id},
            {'asin': asin, 'seller_id': seller_id, 'marketplace_ids': [marketplace_id], 'condition_type': cond, 'reason_locale': 'en_US'},
            {'asin': asin, 'seller_id': seller_id, 'marketplace_ids': marketplace_id, 'condition_type': cond, 'reason_locale': 'en_US'},
            {'asin': asin, 'seller_id': seller_id, 'marketplace_ids': [marketplace_id], 'reason_locale': 'en_US'},
            {'asin': asin, 'seller_id': seller_id, 'condition_type': cond, 'reason_locale': 'en_US'},
            {'asin': asin, 'seller_id': seller_id, 'condition_type': cond},
            {'asin': asin, 'seller_id': seller_id},
        ]
        try:
            sig = _inspect.signature(fn)
            params = sig.parameters
        except Exception:
            sig = None
            params = {}
        has_var_kw = False
        allowed_names = set()
        has_positional = False
        if params:
            for name, p in params.items():
                if name == 'self':
                    continue
                allowed_names.add(name)
                if p.kind == _inspect.Parameter.VAR_KEYWORD:
                    has_var_kw = True
                if p.kind in (_inspect.Parameter.POSITIONAL_ONLY, _inspect.Parameter.POSITIONAL_OR_KEYWORD, _inspect.Parameter.VAR_POSITIONAL):
                    has_positional = True

        for kwargs in kw_attempts:
            try:
                candidate_kwargs = {k: v for k, v in kwargs.items() if v not in (None, '', [])}
                if has_var_kw:
                    # Signature exposes **kwargs: do not pre-filter keys.
                    use_kwargs = candidate_kwargs
                elif allowed_names:
                    use_kwargs = {k: v for k, v in candidate_kwargs.items() if k in allowed_names}
                else:
                    use_kwargs = candidate_kwargs
                if not use_kwargs:
                    debug_attempts.append({'mode': 'kwargs', 'keys': sorted(list(candidate_kwargs.keys())), 'error': 'filtered_empty'})
                    continue
                resp = fn(**use_kwargs)
                out['checked'] = True
                debug_attempts.append({'mode': 'kwargs', 'keys': sorted(list(use_kwargs.keys())), 'ok': True})
                break
            except TypeError as te:
                debug_attempts.append({'mode': 'kwargs', 'keys': sorted(list(kwargs.keys())), 'error': f'TypeError: {te}'})
                continue
            except Exception as e:
                err_txt = str(e)
                debug_attempts.append({'mode': 'kwargs', 'keys': sorted(list(kwargs.keys())), 'error': err_txt})
                low = err_txt.lower()
                if ("invalid 'sellerid' provided" in low) or ("invalid 'marketplaceids' provided" in low):
                    fatal_identity_error = err_txt
                    break
                continue

        # Positional attempts only when signature indicates positional args are supported.
        if resp is None and has_positional and not fatal_identity_error:
            pos_attempts = [
                (asin, seller_id, [marketplace_id], cond, 'en_US'),
                (asin, seller_id, [marketplace_id], cond),
                (asin, seller_id, [marketplace_id]),
            ]
            for args in pos_attempts:
                try:
                    use_args = [a for a in args if a not in (None, '', [])]
                    resp = fn(*use_args)
                    out['checked'] = True
                    debug_attempts.append({'mode': 'args', 'argc': len(use_args), 'ok': True})
                    break
                except TypeError as te:
                    debug_attempts.append({'mode': 'args', 'argc': len(args), 'error': f'TypeError: {te}'})
                    continue
                except Exception as e:
                    debug_attempts.append({'mode': 'args', 'argc': len(args), 'error': str(e)})
                    continue
        elif resp is None and not has_positional and not fatal_identity_error:
            debug_attempts.append({'mode': 'args', 'error': 'skipped_no_positional_signature'})

        if resp is None:
            raw_out = {'call_attempts': debug_attempts[-12:]}
            if fatal_identity_error:
                raw_out['fatal_error'] = fatal_identity_error
            out['raw'] = raw_out
            return out

        out['checked'] = True
        if getattr(resp, 'errors', None):
            # If API returns errors, keep checked=True but don't force restricted.
            out['raw'] = {'errors': resp.errors, 'call_attempts': debug_attempts[-12:]}
            return out

        payload = getattr(resp, 'payload', None) or {}
        out['raw'] = {'payload': payload, 'call_attempts': debug_attempts[-12:]}
        restrictions = payload.get('restrictions') or []
        reasons = []
        restricted = False
        if isinstance(restrictions, list):
            for r in restrictions:
                if not isinstance(r, dict):
                    continue
                rr = r.get('reasons') or []
                if isinstance(rr, list) and rr:
                    restricted = True
                    for reason in rr:
                        if not isinstance(reason, dict):
                            continue
                        code = (reason.get('reasonCode') or reason.get('reason_code') or '').strip()
                        msg = (reason.get('message') or '').strip()
                        txt = f"{code}: {msg}".strip(': ').strip()
                        if txt:
                            reasons.append(txt)
        out['restricted'] = bool(restricted)
        out['reasons'] = reasons[:12]
        return out
    except Exception as e:
        out['raw'] = {'error': str(e)}
        return out

def _amazon_check_listing_restrictions_cached(credentials, marketplace, seller_id, marketplace_id, asin, condition_type='', force_refresh=False):
    asin_clean = (asin or '').strip().upper()
    mp = (marketplace_id or '').strip()
    cond = (condition_type or '').strip().lower()
    sid = (seller_id or '').strip()
    if not asin_clean:
        return {'checked': False, 'restricted': False, 'reasons': [], 'raw': {}}

    key = f'{sid}|{mp}|{asin_clean}|{cond}'
    now = time.time()
    if not force_refresh:
        cached = _LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE.get(key)
        if cached and (now - float(cached.get('ts') or 0)) < _LISTINGAGENT_AMAZON_RESTRICTIONS_TTL:
            out = dict(cached.get('data') or {})
            out['_cached'] = True
            return out

    with _LISTINGAGENT_AMAZON_RESTRICTIONS_LOCK:
        if not force_refresh:
            cached = _LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE.get(key)
            now = time.time()
            if cached and (now - float(cached.get('ts') or 0)) < _LISTINGAGENT_AMAZON_RESTRICTIONS_TTL:
                out = dict(cached.get('data') or {})
                out['_cached'] = True
                return out

        result = _amazon_check_listing_restrictions(
            credentials,
            marketplace,
            seller_id,
            marketplace_id,
            asin_clean,
            condition_type=condition_type
        )
        now_store = time.time()
        if len(_LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE) > 2000:
            expired = []
            for k, v in _LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE.items():
                if (now_store - float((v or {}).get('ts') or 0)) > (_LISTINGAGENT_AMAZON_RESTRICTIONS_TTL * 3):
                    expired.append(k)
            for k in expired[:1000]:
                _LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE.pop(k, None)
        _LISTINGAGENT_AMAZON_RESTRICTIONS_CACHE[key] = {
            'ts': now_store,
            'data': dict(result or {})
        }
        out = dict(result or {})
        out['_cached'] = False
        return out

def _build_amazon_offer_attributes(
    *,
    upc,
    asin,
    condition_type,
    fulfillment_channel_code,
    quantity,
    currency,
    price,
    include_identifiers=True,
    marketplace_id=None,
    offer_audience='ALL',
    merchant_shipping_group=None,
    price_value_key_override=None,
    include_identifier_marketplace=False,
    include_marketplace_fields=True,
    include_offer_audience=True,
    force_include_upc_when_asin=False,
    force_exclude_asin_identifier=False,
    price_model='purchasable_offer',
    condition_note=''
):
    attrs = {}
    asin_clean = (asin or '').strip().upper()
    upc_digits = ''.join(ch for ch in str(upc or '') if ch.isdigit())
    upc_type = ''
    if upc_digits:
        if len(upc_digits) in (8, 11, 12):
            upc_type = 'UPC'
        elif len(upc_digits) == 13:
            upc_type = 'EAN'
        elif len(upc_digits) == 14:
            upc_type = 'GTIN'

    if include_identifiers:
        if asin_clean and not force_exclude_asin_identifier:
            asin_entry = {'value': asin_clean}
            if marketplace_id and include_identifier_marketplace:
                asin_entry['marketplace_id'] = marketplace_id
            attrs['merchant_suggested_asin'] = [asin_entry]

        # Optional: attach UPC to help Amazon match when ASIN is not explicitly supplied.
        # Sending both ASIN and external UPC can trigger generic InvalidInput on some product types.
        if upc_digits and upc_type and (force_include_upc_when_asin or not asin_clean):
            upc_entry = {'value': upc_digits}
            upc_type_entry = {'value': upc_type}
            if marketplace_id and include_identifier_marketplace:
                upc_entry['marketplace_id'] = marketplace_id
                upc_type_entry['marketplace_id'] = marketplace_id
            attrs['externally_assigned_product_identifier'] = [upc_entry]
            attrs['externally_assigned_product_identifier_type'] = [upc_type_entry]

    if condition_type:
        entry = {'value': condition_type}
        if marketplace_id and include_marketplace_fields:
            entry['marketplace_id'] = marketplace_id
        attrs['condition_type'] = [entry]

    condition_note = str(condition_note or '').strip()
    if condition_note:
        note_entry = {'value': condition_note}
        if marketplace_id and include_marketplace_fields:
            note_entry['marketplace_id'] = marketplace_id
        attrs['condition_note'] = [note_entry]

    if fulfillment_channel_code:
        entry = {
            'fulfillment_channel_code': fulfillment_channel_code,
            'quantity': int(quantity or 1)
        }
        if marketplace_id and include_marketplace_fields:
            entry['marketplace_id'] = marketplace_id
        attrs['fulfillment_availability'] = [entry]

    # MFN create-offer flows often require a merchant shipping template id.
    msg = (merchant_shipping_group or '').strip()
    if msg:
        sg = {'value': msg}
        if marketplace_id and include_marketplace_fields:
            sg['marketplace_id'] = marketplace_id
        attrs['merchant_shipping_group'] = [sg]

    if price is not None:
        value_key = (price_value_key_override or '').strip() or _amazon_price_value_key(marketplace_id)
        model = (price_model or 'purchasable_offer').strip().lower()
        if model == 'list_price':
            lp = {
                'currency': (currency or 'USD').upper(),
                'value': float(price)
            }
            if marketplace_id and include_marketplace_fields:
                lp['marketplace_id'] = marketplace_id
            attrs['list_price'] = [lp]
        else:
            price_num = float(price)
            schedule_entry = {}
            # Some Amazon product-type schemas require value_with_tax; include both keys for compatibility.
            if value_key == 'both':
                schedule_entry['value'] = price_num
                schedule_entry['value_with_tax'] = price_num
            elif value_key == 'value_with_tax':
                schedule_entry['value_with_tax'] = price_num
                schedule_entry['value'] = price_num
            else:
                schedule_entry['value'] = price_num
                schedule_entry['value_with_tax'] = price_num
            offer = {
                'currency': (currency or 'USD').upper(),
                'our_price': [{
                    'schedule': [schedule_entry]
                }]
            }
            if include_offer_audience and (offer_audience or '').strip():
                offer['audience'] = offer_audience
            if marketplace_id and include_marketplace_fields:
                offer['marketplace_id'] = marketplace_id
            attrs['purchasable_offer'] = [{
                **offer
            }]

    return attrs

def _amazon_manual_listing_text(value, limit=2000):
    raw = str(value or '').strip()
    if not raw:
        return ''
    try:
        text = _mail_html_to_text(raw)
    except Exception:
        text = raw
    text = re.sub(r'\s+', ' ', str(text or '')).strip()
    if limit and len(text) > limit:
        text = text[:limit].rstrip()
    return text

def _amazon_manual_listing_bullets(description_text, limit=5):
    text = str(description_text or '').replace('\r', '\n')
    parts = []
    for chunk in re.split(r'(?:\n+|[.;]\s+)', text):
        clean = re.sub(r'\s+', ' ', str(chunk or '')).strip(' -\t\r\n')
        if not clean:
            continue
        if len(clean) > 220:
            clean = clean[:220].rstrip()
        parts.append(clean)
        if len(parts) >= max(1, int(limit or 5)):
            break
    return parts

def _build_amazon_manual_listing_attributes(
    *,
    upc,
    asin,
    title,
    description_html,
    brand,
    condition_type,
    condition_note,
    fulfillment_channel_code,
    quantity,
    currency,
    price,
    include_identifiers=True,
    marketplace_id=None,
    offer_audience='ALL',
    merchant_shipping_group=None,
    price_value_key_override=None,
    include_identifier_marketplace=False,
    include_marketplace_fields=True,
    include_offer_audience=True,
    force_include_upc_when_asin=False,
    force_exclude_asin_identifier=False,
    price_model='purchasable_offer',
    submitted_images=None
):
    attrs = _build_amazon_offer_attributes(
        upc=upc,
        asin=asin,
        condition_type=condition_type,
        condition_note=condition_note,
        fulfillment_channel_code=fulfillment_channel_code,
        quantity=quantity,
        currency=currency,
        price=price,
        include_identifiers=include_identifiers,
        marketplace_id=marketplace_id,
        offer_audience=offer_audience,
        merchant_shipping_group=merchant_shipping_group,
        price_value_key_override=price_value_key_override,
        include_identifier_marketplace=include_identifier_marketplace,
        include_marketplace_fields=include_marketplace_fields,
        include_offer_audience=include_offer_audience,
        force_include_upc_when_asin=force_include_upc_when_asin,
        force_exclude_asin_identifier=force_exclude_asin_identifier,
        price_model=price_model
    )

    clean_title = _amazon_manual_listing_text(title, limit=200)
    clean_desc = _amazon_manual_listing_text(description_html, limit=4000)
    clean_brand = _amazon_manual_listing_text(brand, limit=100)

    if clean_title:
        entry = {'value': clean_title}
        if marketplace_id and include_marketplace_fields:
            entry['marketplace_id'] = marketplace_id
        attrs['item_name'] = [entry]

    if clean_desc:
        entry = {'value': clean_desc}
        if marketplace_id and include_marketplace_fields:
            entry['marketplace_id'] = marketplace_id
        attrs['product_description'] = [entry]

        bullets = _amazon_manual_listing_bullets(clean_desc, limit=5)
        if bullets:
            attrs['bullet_point'] = []
            for bullet in bullets:
                bullet_entry = {'value': bullet}
                if marketplace_id and include_marketplace_fields:
                    bullet_entry['marketplace_id'] = marketplace_id
                attrs['bullet_point'].append(bullet_entry)

    if clean_brand:
        entry = {'value': clean_brand}
        if marketplace_id and include_marketplace_fields:
            entry['marketplace_id'] = marketplace_id
        attrs['brand'] = [entry]

    image_urls = [u.strip() for u in (submitted_images or []) if isinstance(u, str) and u.strip()]
    if image_urls:
        attrs['item_image_locator'] = [{'media_location': u} for u in image_urls[:9]]

    return attrs

def _amazon_offer_price_attrs(currency, price, marketplace_id=None, offer_audience='ALL', include_marketplace_fields=True, include_offer_audience=True):
    value_key = _amazon_price_value_key(marketplace_id)
    price_num = float(price)
    schedule_entry = {}
    if value_key == 'value_with_tax':
        schedule_entry['value_with_tax'] = price_num
        schedule_entry['value'] = price_num
    else:
        schedule_entry['value'] = price_num
        schedule_entry['value_with_tax'] = price_num
    offer = {
        'currency': (currency or 'USD').upper(),
        'our_price': [{
            'schedule': [schedule_entry]
        }]
    }
    if include_offer_audience and (offer_audience or '').strip():
        offer['audience'] = offer_audience
    if marketplace_id and include_marketplace_fields:
        offer['marketplace_id'] = marketplace_id
    return {'purchasable_offer': [offer]}

@app.route('/api/listingagent/amazon/put_offer', methods=['POST'])
def api_listingagent_amazon_put_offer():
    """Create/update an Amazon offer using Listings Items API (PUT)."""
    try:
        data = request.json or {}
        dry_run = bool(data.get('dry_run', False))
        debug_mode = str(data.get('debug', '')).strip().lower() in ('1', 'true', 'yes', 'on')

        settings = _listingagent_get_settings()

        upc = (data.get('upc') or '').strip()
        requested_sku = (data.get('sku') or '').strip()
        sku = requested_sku
        effective_sku_source = 'requested'
        asin = (data.get('asin') or '').strip()
        resolved_asin = asin
        submitted_images = [u for u in (data.get('images') or []) if isinstance(u, str) and u.strip()]
        submitted_images = _listagent_localize_image_urls(upc or requested_sku or asin or 'amazon', submitted_images)
        manual_mode = bool(data.get('manualMode') or data.get('manual_mode'))
        manual_title = (data.get('title') or data.get('listingTitle') or '').strip()
        manual_description = (data.get('listingDescription') or data.get('description') or '').strip()
        manual_brand = (data.get('brand') or '').strip()

        if not sku:
            return jsonify({'success': False, 'error': 'SKU is required'}), 400
        if not asin and not upc:
            return jsonify({'success': False, 'error': 'ASIN or UPC is required'}), 400

        quantity = _listingagent_parse_int(data.get('quantity'), 1) or 1
        price = _listingagent_parse_float(data.get('price'), None)
        if price is None:
            return jsonify({'success': False, 'error': 'Price is required'}), 400
        if manual_mode and not asin and not manual_title:
            return jsonify({'success': False, 'error': 'Title is required for Amazon No Catalog mode'}), 400

        condition_type = (data.get('conditionType') or settings.get('amazon_condition_type') or 'used_good').strip()
        condition_note = (data.get('conditionNote') or data.get('condition_note') or '').strip()
        fulfillment_channel_code = (data.get('fulfillmentChannelCode') or settings.get('amazon_fulfillment_channel_code') or 'DEFAULT').strip()
        currency = (data.get('currency') or settings.get('amazon_currency') or 'USD').strip()
        product_type = (data.get('productType') or settings.get('amazon_product_type') or 'PRODUCT').strip()
        requirements = (data.get('requirements') or settings.get('amazon_requirements') or 'LISTING_OFFER_ONLY').strip()
        merchant_shipping_group = (data.get('merchantShippingGroup') or settings.get('amazon_merchant_shipping_group') or '').strip()
        offer_audience = _amazon_offer_audience(settings)
        effective_requirements = requirements or 'LISTING_OFFER_ONLY'
        if manual_mode and not asin and effective_requirements.upper() == 'LISTING_OFFER_ONLY':
            effective_requirements = 'LISTING'

        marketplace_id_override = (data.get('marketplaceId') or '').strip()
        mp_id = marketplace_id_override or (settings.get('amazon_marketplace_id') or 'ATVPDKIKX0DER').strip() or 'ATVPDKIKX0DER'

        condition_type = _amazon_normalize_condition_type(condition_type, settings.get('amazon_condition_type') or 'used_good')
        fulfillment_channel_code = _amazon_normalize_fulfillment_channel(
            fulfillment_channel_code,
            settings.get('amazon_fulfillment_channel_code') or 'DEFAULT'
        )

        is_new_condition = condition_type.lower() in ('new_new', 'new')
        manual_create_mode = bool(manual_mode and not asin)

        def _build_amazon_runtime_attributes(
            *,
            asin_value,
            include_identifiers,
            price_value_key_override=None,
            include_identifier_marketplace=False,
            include_marketplace_fields=True,
            include_offer_audience=True,
            force_include_upc_when_asin=False,
            force_exclude_asin_identifier=False,
            price_model='purchasable_offer',
            condition_value=None,
            fulfillment_value=None,
            quantity_value=None,
            merchant_shipping_group_value=None
        ):
            cond = condition_type if condition_value is None else condition_value
            fc = fulfillment_channel_code if fulfillment_value is None else fulfillment_value
            qty_val = quantity if quantity_value is None else quantity_value
            shipping_group_val = merchant_shipping_group if merchant_shipping_group_value is None else merchant_shipping_group_value
            if manual_create_mode:
                return _build_amazon_manual_listing_attributes(
                    upc=upc,
                    asin=asin_value,
                    title=manual_title,
                    description_html=manual_description,
                    brand=manual_brand,
                    condition_type=cond,
                    condition_note=condition_note,
                    fulfillment_channel_code=fc,
                    quantity=qty_val,
                    currency=currency,
                    price=price,
                    include_identifiers=include_identifiers,
                    marketplace_id=mp_id,
                    offer_audience=offer_audience,
                    merchant_shipping_group=shipping_group_val,
                    price_value_key_override=price_value_key_override,
                    include_identifier_marketplace=include_identifier_marketplace,
                    include_marketplace_fields=include_marketplace_fields,
                    include_offer_audience=include_offer_audience,
                    force_include_upc_when_asin=force_include_upc_when_asin,
                    force_exclude_asin_identifier=force_exclude_asin_identifier,
                    price_model=price_model,
                    submitted_images=submitted_images
                )
            attrs_out = _build_amazon_offer_attributes(
                upc=upc,
                asin=asin_value,
                condition_type=cond,
                condition_note=condition_note,
                fulfillment_channel_code=fc,
                quantity=qty_val,
                currency=currency,
                price=price,
                include_identifiers=include_identifiers,
                marketplace_id=mp_id,
                offer_audience=offer_audience,
                merchant_shipping_group=shipping_group_val,
                price_value_key_override=price_value_key_override,
                include_identifier_marketplace=include_identifier_marketplace,
                include_marketplace_fields=include_marketplace_fields,
                include_offer_audience=include_offer_audience,
                force_include_upc_when_asin=force_include_upc_when_asin,
                force_exclude_asin_identifier=force_exclude_asin_identifier,
                price_model=price_model
            )
            if submitted_images and not is_new_condition:
                attrs_out['item_image_locator'] = [
                    {'media_location': u.strip()} for u in submitted_images[:9] if u.strip()
                ]
            return attrs_out

        attributes = _build_amazon_runtime_attributes(
            asin_value=resolved_asin,
            include_identifiers=True
        )

        body = {
            'productType': product_type,
            'requirements': effective_requirements,
            'attributes': attributes
        }

        if dry_run:
            return jsonify({'success': True, 'dry_run': True, 'body': body})

        credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        mp_id = marketplace_id_override or marketplace_id
        from sp_api.api import ListingsItems
        from sp_api.base.exceptions import SellingApiException
        li = ListingsItems(credentials=credentials, marketplace=marketplace)

        existing_product_type = _amazon_get_listing_product_type(li, seller_id, sku, mp_id)
        sku_exists = bool(existing_product_type)
        if not resolved_asin and upc and not manual_create_mode:
            resolved_asin = _amazon_resolve_asin_from_upc(credentials, marketplace, mp_id, upc)
        if not sku_exists and resolved_asin:
            local_asin_sku = _amazon_find_local_sku_by_asin(resolved_asin)
            if local_asin_sku and local_asin_sku.lower() != sku.lower():
                mapped_pt = _amazon_get_listing_product_type(li, seller_id, local_asin_sku, mp_id)
                if mapped_pt:
                    sku = local_asin_sku
                    existing_product_type = mapped_pt
                    sku_exists = True
                    effective_sku_source = 'local_asin_map'
        manual_create_mode = bool(manual_mode and not resolved_asin and not sku_exists)
        if not resolved_asin and not sku_exists and not manual_create_mode:
            return jsonify({
                'success': False,
                'error': 'Could not resolve ASIN from UPC. Pick an ASIN from Current Store Catalog Select first.'
            }), 400

        catalog_product_type = _amazon_get_catalog_product_type(credentials, marketplace, mp_id, resolved_asin) if resolved_asin else None
        resolved_product_type = (
            existing_product_type
            or catalog_product_type
            or product_type
            or 'PRODUCT'
        )
        # Rebuild attributes/body with runtime marketplace id so price field semantics
        # match the destination marketplace (value vs value_with_tax).
        include_identifiers_primary = not sku_exists
        attributes = _build_amazon_runtime_attributes(
            asin_value=resolved_asin,
            include_identifiers=include_identifiers_primary
        )
        body = {
            'productType': resolved_product_type,
            'requirements': effective_requirements if manual_create_mode else ('LISTING_OFFER_ONLY' if not sku_exists else effective_requirements),
            'attributes': attributes
        }

        restriction_info = None
        if resolved_asin:
            restriction_info = _amazon_check_listing_restrictions_cached(
                credentials,
                marketplace,
                seller_id,
                mp_id,
                resolved_asin,
                condition_type=condition_type
            )
            if restriction_info.get('checked') and restriction_info.get('restricted'):
                reasons = restriction_info.get('reasons') or []
                extra = f" Reasons: {' | '.join(reasons)}" if reasons else ''
                return jsonify({
                    'success': False,
                    'error': f"ASIN appears restricted/gated for this account/marketplace.{extra}",
                    'restriction': restriction_info
                }), 400
            # If restriction API itself reports account/config id errors, fail fast with a clear hint.
            if not restriction_info.get('checked'):
                restriction_hints = _amazon_restriction_error_hints(restriction_info, mp_id)
                if restriction_hints:
                    hint_txt = ' '.join(restriction_hints)
                    return jsonify({
                        'success': False,
                        'error': f"Amazon account configuration issue. {hint_txt}",
                        'restriction': restriction_info,
                        'context': {
                            'requested_sku': requested_sku,
                            'effective_sku': sku,
                            'effective_sku_source': effective_sku_source,
                            'sku_exists': sku_exists,
                            'marketplace_id': mp_id,
                            'asin': resolved_asin,
                            'manual_mode': manual_mode,
                            'manual_create_mode': manual_create_mode,
                        }
                    }), 400

        attempt_trace = []

        def _trace_jsonable(value):
            try:
                return json.loads(json.dumps(value, ensure_ascii=True, default=str))
            except Exception:
                return str(value)

        def _trace_attempt(attempt_label, *, body_obj=None, resp_obj=None, detail='', exc=None):
            if not debug_mode:
                return
            entry = {'attempt': attempt_label}
            if body_obj is not None:
                entry['body'] = _trace_jsonable(body_obj)
            if detail:
                entry['detail'] = str(detail)
            if resp_obj is not None:
                errs = getattr(resp_obj, 'errors', None)
                if errs:
                    entry['errors'] = _trace_jsonable(errs)
                try:
                    payload = getattr(resp_obj, 'payload', None) or {}
                    if payload:
                        entry['payload_status'] = payload.get('status')
                        issues = payload.get('issues') or []
                        if issues:
                            entry['payload_issues'] = _trace_jsonable(issues)
                except Exception:
                    pass
            if exc is not None:
                entry['exception'] = _amazon_format_spapi_error(exc)
            attempt_trace.append(entry)

        def _amazon_resp_error_detail(resp_obj):
            errs = getattr(resp_obj, 'errors', None)
            if errs:
                return str(errs)
            payload = getattr(resp_obj, 'payload', None) or {}
            issues = payload.get('issues') or []
            err_issues = []
            if isinstance(issues, list):
                for it in issues:
                    try:
                        sev = str((it or {}).get('severity') or '').strip().upper()
                        if sev == 'ERROR':
                            err_issues.append(it)
                    except Exception:
                        pass
            if err_issues:
                return str(err_issues)
            status = str(payload.get('status') or '').strip().upper()
            if status in ('INVALID', 'ERROR', 'REJECTED', 'FAILURE'):
                return f"status={status}"
            return ''

        def _put_offer_once(*, body_obj, attempt_label):
            try:
                r = li.put_listings_item(
                    seller_id,
                    sku,
                    marketplaceIds=[mp_id],
                    issueLocale='en_US',
                    body=body_obj
                )
                detail = _amazon_resp_error_detail(r)
                _trace_attempt(attempt_label, body_obj=body_obj, resp_obj=r, detail=detail)
                if detail:
                    return False, r, f"{attempt_label}: {detail}"
                return True, r, ''
            except Exception as ex:
                _trace_attempt(attempt_label, body_obj=body_obj, exc=ex)
                return False, None, f"{attempt_label}: {_amazon_format_spapi_error(ex)}"

        def _unique_values(values):
            out = []
            seen = set()
            for v in values:
                s = str(v or '').strip()
                if not s:
                    continue
                key = s.lower()
                if key in seen:
                    continue
                seen.add(key)
                out.append(s)
            return out

        if (not manual_create_mode) and (not sku_exists) and (not str(catalog_product_type or '').strip()) and str(product_type or '').strip().upper() in ('', 'PRODUCT'):
            return jsonify({
                'success': False,
                'error': 'Could not resolve Amazon productType for this ASIN. Select a catalog item and set Product Type from that category.',
                'resolved_asin': resolved_asin,
                'context': {
                    'requested_sku': requested_sku,
                    'effective_sku': sku,
                    'effective_sku_source': effective_sku_source,
                    'sku_exists': sku_exists,
                    'marketplace_id': mp_id,
                    'manual_mode': manual_mode,
                    'manual_create_mode': manual_create_mode,
                    'restriction_checked': bool((restriction_info or {}).get('checked')) if 'restriction_info' in locals() else False,
                    'restriction_restricted': bool((restriction_info or {}).get('restricted')) if 'restriction_info' in locals() else False,
                }
            }), 400

        patch_result_payload = None
        ok, resp, err_detail = _put_offer_once(body_obj=body, attempt_label='primary')
        if not ok:
            err_low = (err_detail or '').lower()
            is_invalid_input = ('invalidinput' in err_low) or ('invalid parameters' in err_low) or ('invalid parameter' in err_low)
            is_schema_price_error = ('99022' in err_low) or ('invalid_attribute' in err_low) or ('value_with_tax' in err_low)
            is_missing_identifier_error = (
                ('90220' in err_low or 'missing_attribute' in err_low)
                and (
                    'merchant_suggested_asin' in err_low
                    or 'externally_assigned_product_identifier' in err_low
                    or 'merchant suggested asin' in err_low
                    or 'external product id' in err_low
                )
            )
            if is_missing_identifier_error:
                is_invalid_input = True
            resolved_pt = (
                _amazon_get_catalog_product_type(credentials, marketplace, mp_id, resolved_asin)
                or _amazon_get_listing_product_type(li, seller_id, sku, mp_id)
                or resolved_product_type
            )
            product_type_candidates = _unique_values([resolved_pt, resolved_product_type, catalog_product_type, product_type, 'PRODUCT'])
            if is_schema_price_error and 'value_with_tax' in err_low:
                price_value_key_candidates = _unique_values(['value_with_tax', 'both', 'value', _amazon_price_value_key(mp_id)])
            else:
                price_value_key_candidates = _unique_values([_amazon_price_value_key(mp_id), 'value', 'value_with_tax', 'both'])
            if not price_value_key_candidates:
                price_value_key_candidates = ['value']
            upc_digits_ctx = ''.join(ch for ch in str(upc or '') if ch.isdigit())
            preferred_id_mode = 'upc' if manual_create_mode else ('both' if upc_digits_ctx else 'asin')
            preferred_price_key = 'value_with_tax' if ('value_with_tax' in err_low or _amazon_price_value_key(mp_id) == 'value_with_tax') else 'value'
            price_key_candidates = _unique_values([preferred_price_key, 'both', 'value', 'value_with_tax'])[:3]
            product_type_plan = _unique_values([resolved_pt, resolved_product_type, product_type, 'PRODUCT'])[:2]
            shipping_group_plan = _unique_values([merchant_shipping_group, 'legacy-template-id', '']) if not sku_exists else ['']
            condition_plan = _unique_values([condition_type, 'new_new'])

            if is_invalid_input or is_schema_price_error:
                fallback_specs = []

                if sku_exists:
                    for pt in product_type_plan:
                        for pkey in price_key_candidates:
                            fallback_specs.append({
                                'label': f'fallback:update:{pt}:price_only:{pkey}',
                                'product_type': pt,
                                'requirements': 'LISTING_OFFER_ONLY',
                                'include_identifiers': False,
                                'include_condition': False,
                                'condition_value': '',
                                'include_qty': False,
                                'merchant_shipping_group': '',
                                'price_value_key': pkey,
                                'price_model': 'purchasable_offer',
                                'include_marketplace_fields': False,
                                'include_offer_audience': False,
                                'identifier_mode': 'asin',
                                'include_identifier_marketplace': False,
                            })
                            fallback_specs.append({
                                'label': f'fallback:update:{pt}:with_condition:{pkey}',
                                'product_type': pt,
                                'requirements': 'LISTING_OFFER_ONLY',
                                'include_identifiers': False,
                                'include_condition': True,
                                'condition_value': condition_type,
                                'include_qty': True,
                                'merchant_shipping_group': '',
                                'price_value_key': pkey,
                                'price_model': 'purchasable_offer',
                                'include_marketplace_fields': False,
                                'include_offer_audience': False,
                                'identifier_mode': 'asin',
                                'include_identifier_marketplace': False,
                            })
                            if is_missing_identifier_error:
                                id_modes = ['both', 'asin'] if upc_digits_ctx else ['asin']
                                for id_mode in id_modes:
                                    fallback_specs.append({
                                        'label': f'fallback:update:{pt}:with_identifiers:{id_mode}:{pkey}',
                                        'product_type': pt,
                                        'requirements': 'LISTING_OFFER_ONLY',
                                        'include_identifiers': True,
                                        'include_condition': True,
                                        'condition_value': condition_type,
                                        'include_qty': True,
                                        'merchant_shipping_group': '',
                                        'price_value_key': pkey,
                                        'price_model': 'purchasable_offer',
                                        'include_marketplace_fields': False,
                                        'include_offer_audience': False,
                                        'identifier_mode': id_mode,
                                        'include_identifier_marketplace': False,
                                    })
                else:
                    for pt in product_type_plan:
                        for pkey in price_key_candidates:
                            for sgroup in shipping_group_plan[:2]:
                                for cval in condition_plan[:2]:
                                    fallback_specs.append({
                                        'label': f'fallback:create:{pt}:full:{cval}:{preferred_id_mode}:{pkey}',
                                        'product_type': pt,
                                        'requirements': 'LISTING' if manual_create_mode else 'LISTING_OFFER_ONLY',
                                        'include_identifiers': True,
                                        'include_condition': True,
                                        'condition_value': cval,
                                        'include_qty': True,
                                        'merchant_shipping_group': sgroup,
                                        'price_value_key': pkey,
                                        'price_model': 'purchasable_offer',
                                        'include_marketplace_fields': False,
                                        'include_offer_audience': False,
                                        'identifier_mode': preferred_id_mode,
                                        'include_identifier_marketplace': False,
                                    })
                                fallback_specs.append({
                                    'label': f'fallback:create:{pt}:list_price:{preferred_id_mode}:{pkey}',
                                    'product_type': pt,
                                    'requirements': 'LISTING',
                                    'include_identifiers': True,
                                    'include_condition': False,
                                    'condition_value': '',
                                    'include_qty': True,
                                    'merchant_shipping_group': sgroup,
                                    'price_value_key': pkey,
                                    'price_model': 'list_price',
                                    'include_marketplace_fields': False,
                                    'include_offer_audience': False,
                                    'identifier_mode': preferred_id_mode,
                                    'include_identifier_marketplace': False,
                                })

                # Deterministic and compact fallback set for production.
                max_fallback_attempts = 48 if debug_mode else 18
                fallback_specs = fallback_specs[:max_fallback_attempts]

                for spec in fallback_specs:
                    cond_val = (spec.get('condition_value') or '') if spec.get('include_condition') else ''
                    fc_val = fulfillment_channel_code if spec.get('include_qty') else ''
                    qty_val = quantity if spec.get('include_qty') else 0
                    id_mode = (spec.get('identifier_mode') or 'asin').strip().lower()
                    force_upc_with_asin = id_mode in ('upc', 'both')
                    force_exclude_asin = id_mode == 'upc'
                    attrs_fb = _build_amazon_runtime_attributes(
                        asin_value=resolved_asin,
                        include_identifiers=bool(spec.get('include_identifiers')),
                        price_value_key_override=(spec.get('price_value_key') or ''),
                        include_marketplace_fields=bool(spec.get('include_marketplace_fields', True)),
                        include_offer_audience=bool(spec.get('include_offer_audience', True)),
                        force_include_upc_when_asin=force_upc_with_asin,
                        force_exclude_asin_identifier=force_exclude_asin,
                        include_identifier_marketplace=bool(spec.get('include_identifier_marketplace', False)),
                        price_model=(spec.get('price_model') or 'purchasable_offer'),
                        condition_value=cond_val,
                        fulfillment_value=fc_val,
                        quantity_value=qty_val,
                        merchant_shipping_group_value=(spec.get('merchant_shipping_group') or '')
                    )
                    body_fb = {
                        'productType': (spec.get('product_type') or resolved_pt or product_type),
                        'requirements': (spec.get('requirements') or 'LISTING_OFFER_ONLY'),
                        'attributes': attrs_fb
                    }
                    ok_fb, resp_fb, err_fb = _put_offer_once(body_obj=body_fb, attempt_label=spec.get('label') or 'fallback')
                    if ok_fb:
                        body = body_fb
                        resp = resp_fb
                        err_detail = ''
                        ok = True
                        break
                    err_detail = err_fb or err_detail

                # Existing SKU fallback: patch price only to avoid create-offer validation paths.
                if not ok and sku_exists:
                    try:
                        live_pt = _amazon_get_listing_product_type(li, seller_id, sku, mp_id) or resolved_pt or product_type
                        attrs_patch = _amazon_offer_price_attrs(currency, price, mp_id, offer_audience=offer_audience)
                        ok_patch, debug_patch, err_patch = _amazon_update_price_spapi(
                            li,
                            seller_id,
                            sku,
                            mp_id,
                            product_type=live_pt,
                            requirements='LISTING_OFFER_ONLY',
                            attrs=attrs_patch
                        )
                        _trace_attempt(
                            'fallback:price_patch',
                            body_obj={
                                'productType': live_pt,
                                'requirements': 'LISTING_OFFER_ONLY',
                                'attributes': attrs_patch
                            },
                            detail=err_patch or '',
                            exc=None if ok_patch else Exception(str(err_patch or 'price_patch failed'))
                        )
                        if ok_patch:
                            ok = True
                            resp = None
                            patch_result_payload = {
                                'fallback': 'price_patch',
                                'productType': live_pt,
                                'debug': debug_patch
                            }
                            err_detail = ''
                        elif err_patch:
                            err_detail = f"{err_detail} | patch:{err_patch}" if err_detail else f"patch:{err_patch}"
                    except Exception as e_patch:
                        ep = _amazon_format_spapi_error(e_patch)
                        err_detail = f"{err_detail} | patch:{ep}" if err_detail else f"patch:{ep}"

            if not ok:
                # Last chance: include restrictions signal if available.
                if resolved_asin:
                    try:
                        if not restriction_info:
                            restriction_info = _amazon_check_listing_restrictions_cached(
                                credentials, marketplace, seller_id, mp_id, resolved_asin, condition_type=condition_type
                            )
                    except Exception:
                        restriction_info = restriction_info or {}
                payload = {
                    'success': False,
                    'error': err_detail or 'Amazon offer update failed',
                    'body': body,
                    'resolved_asin': resolved_asin,
                    'resolved_product_type': resolved_product_type,
                    'context': {
                        'requested_sku': requested_sku,
                        'effective_sku': sku,
                        'effective_sku_source': effective_sku_source,
                        'sku_exists': sku_exists,
                        'marketplace_id': mp_id,
                        'condition_type': condition_type,
                        'fulfillment_channel_code': fulfillment_channel_code,
                        'merchant_shipping_group': merchant_shipping_group,
                        'manual_mode': manual_mode,
                        'manual_create_mode': manual_create_mode,
                        'restriction_checked': bool((restriction_info or {}).get('checked')),
                        'restriction_restricted': bool((restriction_info or {}).get('restricted')),
                        'restriction_raw': ((restriction_info or {}).get('raw') if isinstance((restriction_info or {}).get('raw'), dict) else {}),
                    }
                }
                if debug_mode and attempt_trace:
                    payload['attempts'] = attempt_trace[-80:]
                if restriction_info:
                    payload['restriction'] = restriction_info
                    if restriction_info.get('checked') and restriction_info.get('restricted'):
                        reasons = restriction_info.get('reasons') or []
                        if reasons:
                            payload['error'] = f"{payload['error']} | gated: {' | '.join(reasons)}"
                if debug_mode:
                    # Include compact context in debug mode only.
                    ctx_bits = [
                        f"sku_exists={sku_exists}",
                        f"marketplace={mp_id}",
                        f"asin={resolved_asin or ''}",
                        f"productType={resolved_product_type or ''}",
                        f"restriction_checked={bool((restriction_info or {}).get('checked'))}",
                        f"restricted={bool((restriction_info or {}).get('restricted'))}",
                    ]
                    payload['error'] = f"{payload['error']} | ctx: {' | '.join(ctx_bits)}"
                return jsonify(payload), 400

        # Mark BOL as listed on Amazon so /items-to-list marketplace checkboxes stay in sync.
        target_lot = _normalize_lot_number(data.get('lot_number') or data.get('lot'))
        target_item_id = data.get('id')
        if target_item_id is None:
            target_item_id = data.get('item_id')
        if target_item_id is None:
            target_item_id = data.get('bol_id')
        if upc or target_item_id is not None:
            try:
                _listing_center_mark_bol_listed(
                    'amazon',
                    upc=upc,
                    lot_number=target_lot,
                    item_id=target_item_id
                )
            except Exception:
                pass
 
        # Record listing completion in listagent.db (if UPC is available)
        try:
            if upc:
                _listagent_mark_listed(
                    upc,
                    platform='amazon',
                    sku=sku,
                    asin=resolved_asin or asin,
                    marketplace_id=mp_id,
                    price=price,
                    quantity=quantity,
                    source='listingagent'
                )
        except Exception:
            pass
 
        data_payload = {}
        try:
            if resp is not None:
                data_payload = getattr(resp, 'payload', None) or {}
        except Exception:
            data_payload = {}
        if patch_result_payload:
            data_payload = {**data_payload, **patch_result_payload}
        out_payload = {
            'success': True,
            'data': data_payload,
            'body': body,
            'resolved_asin': resolved_asin,
            'resolved_product_type': resolved_product_type,
            'context': {
                'requested_sku': requested_sku,
                'effective_sku': sku,
                'effective_sku_source': effective_sku_source,
                'sku_exists': sku_exists,
                'marketplace_id': mp_id,
                'manual_mode': manual_mode,
                'manual_create_mode': manual_create_mode,
                'merchant_shipping_group': merchant_shipping_group,
                'restriction_checked': bool((restriction_info or {}).get('checked')),
                'restriction_restricted': bool((restriction_info or {}).get('restricted')),
            },
        }
        if debug_mode and attempt_trace:
            out_payload['attempts'] = attempt_trace[-80:]
        return jsonify(out_payload)
 
    except Exception as e:
        from sp_api.base.exceptions import SellingApiException
        if isinstance(e, SellingApiException):
            return jsonify({'success': False, 'error': str(e)}), 400
        return jsonify({'success': False, 'error': _safe_error(e, 'listingagent:amazon_put_offer')}), 500

