@app.route('/api/labelmaster/status', methods=['GET'])
def api_labelmaster_status():
    """Return a quick capability check for label buying/printing APIs."""
    settings = _labelmaster_get_settings()
    missing = _labelmaster_missing_settings(settings)

    scope_state = _labelmaster_ebay_scope_state()
    ebay_connected = bool(scope_state.get('connected'))
    ebay_reason = ''
    scope_known = bool(scope_state.get('scope_known'))
    has_logistics_scope = bool(scope_state.get('has_sell_logistics_scope'))
    env_has_logistics_scope = bool(scope_state.get('env_has_sell_logistics_scope'))
    has_effective_logistics_scope = bool(scope_state.get('has_effective_sell_logistics_scope'))

    if not ebay_connected:
        ebay_reason = 'eBay OAuth token missing (run ebay_oauth_setup.py)'
    elif scope_known and not has_logistics_scope:
        ebay_reason = 'Missing sell.logistics scope (reauthorize eBay app)'
    elif missing:
        ebay_reason = f"Missing defaults: {', '.join(missing)}"
    elif not env_has_logistics_scope:
        ebay_reason = 'EBAY_SCOPE does not advertise sell.logistics; proceeding because token scope metadata is unavailable'
    elif not scope_known:
        # Some refresh-token responses omit scope in tokens.json; treat as unknown instead of hard-failing.
        ebay_reason = 'Scope could not be introspected from token metadata (not blocking)'

    amazon_connected = False
    amazon_reason = ''
    if AMAZON_AVAILABLE:
        try:
            credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
            amazon_connected = marketplace is not None
            if not amazon_connected:
                amazon_reason = 'Amazon SP-API not available'
            elif missing:
                amazon_reason = f"Missing defaults: {', '.join(missing)}"
        except Exception as e:
            amazon_connected = False
            amazon_reason = _safe_error(e, 'labelmaster:amazon_status')
    else:
        amazon_reason = 'Amazon SP-API library not available'

    return jsonify({
        'success': True,
        'ebay': {
            'connected': ebay_connected,
            'supported': ebay_connected and has_effective_logistics_scope and not missing,
            'reason': ebay_reason,
            'scope_known': scope_known,
            'has_sell_logistics_scope': has_logistics_scope,
            'env_has_sell_logistics_scope': env_has_logistics_scope
        },
        'amazon': {
            'connected': amazon_connected,
            'supported': amazon_connected and not missing,
            'reason': amazon_reason
        },
        'missing_defaults': missing
    })

@app.route('/api/labelmaster/orders', methods=['GET'])
def api_labelmaster_orders():
    """Return sold orders for label purchasing/printing."""
    try:
        days = int(request.args.get('days', 7))
        store = (request.args.get('store') or '').strip().lower()
        q = (request.args.get('q') or '').strip().lower()

        params = [days]
        where = "paid_time >= date('now', '-' || ? || ' days')"
        if store in ('ebay', 'amazon'):
            where += " AND store = ?"
            params.append(store)

        with sqlite3.connect('sold.db') as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            _labelmaster_init_label_tables(cur)
            cur.execute(f'''
                SELECT o.*,
                       l.label_id,
                       l.label_url,
                       l.label_format,
                       l.label_path,
                       l.created_at AS label_created_at
                FROM orders o
                LEFT JOIN (
                    SELECT store, order_id, MAX(id) AS max_id
                    FROM shipping_labels
                    GROUP BY store, order_id
                ) last
                    ON last.store = o.store AND last.order_id = o.order_id
                LEFT JOIN shipping_labels l
                    ON l.id = last.max_id
                WHERE {where}
                ORDER BY paid_time DESC
                LIMIT 4000
            ''', params)
            rows = cur.fetchall()

        orders = [dict(r) for r in rows]
        for o in orders:
            o['label_ready'] = bool(o.get('label_path') or o.get('label_url'))

        if q:
            def _matches(o):
                hay = ' '.join([
                    str(o.get('order_id') or ''),
                    str(o.get('item_id') or ''),
                    str(o.get('title') or ''),
                    str(o.get('barcode') or ''),
                    str(o.get('shipping_name') or ''),
                    str(o.get('shipping_city') or ''),
                    str(o.get('shipping_state') or ''),
                    str(o.get('shipping_postal_code') or ''),
                    str(o.get('location') or ''),
                ]).lower()
                return q in hay
            orders = [o for o in orders if _matches(o)]

        return jsonify({'success': True, 'orders': orders})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'labelmaster:orders')}), 500

@app.route('/api/labelmaster/buy', methods=['POST'])
def api_labelmaster_buy():
    """Buy a shipping label for an order."""
    try:
        data = request.json or {}
        order_id = (data.get('order_id') or '').strip()
        store = (data.get('store') or '').strip().lower()
        if not order_id or store not in ('ebay', 'amazon'):
            return jsonify({'success': False, 'error': 'order_id and store are required'}), 400

        settings = _labelmaster_get_settings()
        missing = _labelmaster_missing_settings(settings)
        if missing:
            return jsonify({'success': False, 'error': f"Missing defaults: {', '.join(missing)}"}), 400

        order = _labelmaster_find_order(order_id, store)
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        if store == 'ebay':
            scope_state = _labelmaster_ebay_scope_state()
            if scope_state.get('scope_known') and not scope_state.get('has_sell_logistics_scope'):
                return jsonify({
                    'success': False,
                    'error': (
                        'eBay token does not include sell.logistics. Reauthorize eBay OAuth and retry.'
                    )
                }), 400
            if not scope_state.get('env_has_sell_logistics_scope'):
                logger.warning(
                    'labelmaster: buy proceeding with unknown token scope while EBAY_SCOPE lacks sell.logistics'
                )
            result = _labelmaster_buy_ebay(order, settings)
        else:
            ship_to = data.get('ship_to')
            result = _labelmaster_buy_amazon(order, settings, ship_to=ship_to)

        label_url = result.get('label_url')
        if not label_url and result.get('label_path'):
            label_url = url_for('api_labelmaster_label_file', store=store, order_id=order.get('order_id') or order_id)

        return jsonify({
            'success': True,
            'label_url': label_url,
            'label_id': result.get('label_id'),
            'cost': result.get('cost'),
            'currency': result.get('currency'),
            'format': result.get('format')
        })
    except Exception as e:
        err_msg = str(e)
        if err_msg == 'NEED_ADDRESS':
            return jsonify({
                'success': False,
                'need_address': True,
                'error': 'Shipping address required. Please enter the buyer address.',
                'prefill': {
                    'city': order.get('shipping_city') or '',
                    'stateOrRegion': order.get('shipping_state') or '',
                    'postalCode': order.get('shipping_postal_code') or '',
                    'countryCode': order.get('shipping_country') or 'US',
                    'name': order.get('shipping_name') or order.get('buyer_name') or '',
                }
            }), 400
        if (
            'sell.logistics' in err_msg or
            'ACCESS 1100' in err_msg or
            err_msg.startswith('Missing ship-to address') or
            err_msg.startswith('Ship-from defaults are missing') or
            err_msg.startswith('Package dimensions are required') or
            err_msg.startswith('Package weight is required')
        ):
            return jsonify({'success': False, 'error': err_msg}), 400
        logger.error(f"labelmaster:buy: {e}", exc_info=True)
        return jsonify({'success': False, 'error': err_msg}), 500

@app.route('/api/labelmaster/print', methods=['POST'])
def api_labelmaster_print():
    """Return the label URL for printing if purchased."""
    try:
        data = request.json or {}
        order_id = (data.get('order_id') or '').strip()
        store = (data.get('store') or '').strip().lower()
        if not order_id or store not in ('ebay', 'amazon'):
            return jsonify({'success': False, 'error': 'order_id and store are required'}), 400
        order = _labelmaster_find_order(order_id, store)
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        label = _labelmaster_latest_label(store, order.get('order_id') or order_id)
        if not label:
            return jsonify({'success': False, 'error': 'Label not purchased yet'}), 400

        if label.get('label_path'):
            label_url = url_for('api_labelmaster_label_file', store=store, order_id=order.get('order_id') or order_id)
            return jsonify({'success': True, 'label_url': label_url})

        if label.get('label_url'):
            return jsonify({'success': True, 'label_url': label.get('label_url')})

        return jsonify({'success': False, 'error': 'Label file missing'}), 404
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'labelmaster:print')}), 500

@app.route('/api/labelmaster/label', methods=['GET'])
def api_labelmaster_label_file():
    try:
        store = (request.args.get('store') or '').strip().lower()
        order_id = (request.args.get('order_id') or '').strip()
        if not order_id or store not in ('ebay', 'amazon'):
            return jsonify({'success': False, 'error': 'order_id and store are required'}), 400

        label = _labelmaster_latest_label(store, order_id)
        if not label or not label.get('label_path'):
            return jsonify({'success': False, 'error': 'Label file not found'}), 404

        label_path = label.get('label_path')
        if not label_path or not os.path.exists(label_path):
            return jsonify({'success': False, 'error': 'Label file not found on disk'}), 404
        mime = 'application/pdf'
        ext = os.path.splitext(label_path)[1].lower()
        if ext == '.png':
            mime = 'image/png'
        elif ext == '.zpl':
            mime = 'application/octet-stream'
        return send_file(label_path, mimetype=mime)
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'labelmaster:label_file')}), 500

# -----------------------------
# Price Master (Bulk Repricing)
# -----------------------------

def _pricemaster_now_iso():
    # UTC, second precision keeps it readable and stable for sorting.
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'

def _pricemaster_parse_decimal(val):
    try:
        if val is None:
            return None
        if isinstance(val, Decimal):
            return val
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            return Decimal(str(val))
        s = str(val).strip()
        if s == '':
            return None
        s = s.replace('$', '').replace(',', '')
        return Decimal(s)
    except (InvalidOperation, Exception):
        return None

def _pricemaster_money_2dp(val: Decimal):
    try:
        if val is None:
            return None
        return val.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except Exception:
        return None

def _pricemaster_compute_new_price(old_price: Decimal, mode: str, value: Decimal):
    if old_price is None or value is None:
        return None
    mode = (mode or '').strip().lower()
    if mode not in ('delta', 'percent'):
        mode = 'delta'

    try:
        if mode == 'delta':
            nxt = old_price + value
        else:
            nxt = old_price * (Decimal('1') + (value / Decimal('100')))
        if nxt < 0:
            nxt = Decimal('0')
        return _pricemaster_money_2dp(nxt)
    except Exception:
        return None

def _pricemaster_init_tables(cur):
    try:
        cur.execute('PRAGMA journal_mode=WAL')
    except Exception:
        pass

    cur.execute('''
        CREATE TABLE IF NOT EXISTS listing_meta (
            platform TEXT NOT NULL,
            listing_key TEXT NOT NULL,
            first_seen_at TEXT,
            last_price_change_at TEXT,
            last_price_change_price REAL,
            updated_at TEXT,
            PRIMARY KEY (platform, listing_key)
        )
    ''')

    cur.execute('''
        CREATE TABLE IF NOT EXISTS price_changes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            platform TEXT NOT NULL,
            listing_key TEXT NOT NULL,
            old_price REAL,
            new_price REAL,
            changed_at TEXT NOT NULL,
            adjustment_mode TEXT,
            adjustment_value REAL,
            success INTEGER NOT NULL DEFAULT 1,
            error TEXT
        )
    ''')

    cur.execute('CREATE INDEX IF NOT EXISTS idx_price_changes_key_time ON price_changes(platform, listing_key, changed_at)')

    cur.execute('''
        CREATE TABLE IF NOT EXISTS price_feed_jobs (
            feed_id TEXT PRIMARY KEY,
            marketplace_id TEXT,
            submitted_at TEXT,
            status TEXT,
            last_checked_at TEXT,
            result_document_id TEXT,
            items_json TEXT,
            error TEXT
        )
    ''')

def _pricemaster_touch_meta(rows):
    """Insert first_seen_at for listings if missing (platform, key, first_seen_at)."""
    if not rows:
        return
    now = _pricemaster_now_iso()
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        cur.executemany('''
            INSERT OR IGNORE INTO listing_meta (platform, listing_key, first_seen_at, updated_at)
            VALUES (?, ?, ?, ?)
        ''', [(p, k, fs or now, now) for (p, k, fs) in rows if p and k])

def _pricemaster_get_meta_map(platform: str, keys: list):
    """Return dict: listing_key -> meta row."""
    out = {}
    platform = (platform or '').strip().lower()
    keys = [k for k in (keys or []) if k]
    if not platform or not keys:
        return out

    # SQLite default max vars is commonly 999; batch to be safe.
    CHUNK = 900
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        for i in range(0, len(keys), CHUNK):
            batch = keys[i:i+CHUNK]
            ph = ','.join(['?'] * len(batch))
            cur.execute(f'''
                SELECT listing_key, first_seen_at, last_price_change_at, last_price_change_price
                FROM listing_meta
                WHERE platform = ? AND listing_key IN ({ph})
            ''', [platform] + batch)
            for r in cur.fetchall():
                out[r['listing_key']] = {
                    'first_seen_at': r['first_seen_at'],
                    'last_price_change_at': r['last_price_change_at'],
                    'last_price_change_price': r['last_price_change_price'],
                }
    return out

def _pricemaster_save_feed_job(feed_id, marketplace_id, items, error=None, status='SUBMITTED'):
    if not feed_id:
        return
    now = _pricemaster_now_iso()
    try:
        import json as _json
        items_json = _json.dumps(items or [], ensure_ascii=True, default=str)
    except Exception:
        items_json = '[]'
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        cur.execute('''
            INSERT INTO price_feed_jobs (feed_id, marketplace_id, submitted_at, status, last_checked_at, result_document_id, items_json, error)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(feed_id) DO UPDATE SET
                marketplace_id = excluded.marketplace_id,
                status = excluded.status,
                last_checked_at = excluded.last_checked_at,
                result_document_id = excluded.result_document_id,
                items_json = excluded.items_json,
                error = excluded.error
        ''', (feed_id, marketplace_id, now, status or 'SUBMITTED', now, None, items_json, error))

def _pricemaster_get_feed_job(feed_id):
    if not feed_id:
        return None
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        cur.execute('''
            SELECT feed_id, marketplace_id, submitted_at, status, last_checked_at, result_document_id, items_json, error
            FROM price_feed_jobs
            WHERE feed_id = ?
        ''', (feed_id,))
        row = cur.fetchone()
        return dict(row) if row else None

def _pricemaster_update_feed_job(feed_id, *, status=None, error=None, result_document_id=None):
    if not feed_id:
        return
    now = _pricemaster_now_iso()
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        cur.execute('''
            UPDATE price_feed_jobs
            SET status = COALESCE(?, status),
                last_checked_at = ?,
                result_document_id = COALESCE(?, result_document_id),
                error = COALESCE(?, error)
            WHERE feed_id = ?
        ''', (status, now, result_document_id, error, feed_id))

def _pricemaster_record_change(*, platform, listing_key, old_price, new_price, mode, value, success, error=None):
    now = _pricemaster_now_iso()
    with db_connection('pricemaster.db') as conn:
        cur = conn.cursor()
        _pricemaster_init_tables(cur)
        cur.execute('''
            INSERT INTO price_changes (platform, listing_key, old_price, new_price, changed_at, adjustment_mode, adjustment_value, success, error)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            platform, listing_key,
            None if old_price is None else float(old_price),
            None if new_price is None else float(new_price),
            now,
            mode,
            None if value is None else float(value),
            1 if success else 0,
            (str(error) if error else None)
        ))

        if success:
            cur.execute('''
                INSERT INTO listing_meta (platform, listing_key, last_price_change_at, last_price_change_price, updated_at)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(platform, listing_key) DO UPDATE SET
                    last_price_change_at = excluded.last_price_change_at,
                    last_price_change_price = excluded.last_price_change_price,
                    updated_at = excluded.updated_at
            ''', (
                platform, listing_key, now,
                None if new_price is None else float(new_price),
                now
            ))

def _pricemaster_ebay_trading_call(call_name: str, xml_payload: str, timeout=30):
    token = os.getenv("EBAY_OLDAUTH_TOKEN") or ''
    if not token.strip():
        raise Exception("Missing EBAY_OLDAUTH_TOKEN (Trading API token)")

    headers = {
        "X-EBAY-API-SITEID": "0",
        "X-EBAY-API-COMPATIBILITY-LEVEL": "967",
        "X-EBAY-API-CALL-NAME": call_name,
        "X-EBAY-API-DEV-NAME": os.getenv("EBAY_PROD_DEV_ID"),
        "X-EBAY-API-APP-NAME": os.getenv("EBAY_PROD_APP_ID"),
        "X-EBAY-API-CERT-NAME": os.getenv("EBAY_PROD_CERT_ID"),
        "Content-Type": "text/xml",
    }
    resp = requests.post("https://api.ebay.com/ws/api.dll", headers=headers, data=xml_payload, timeout=timeout)
    return resp

def _pricemaster_ebay_revise_prices_bulk(updates: list, currency='USD'):
    """
    updates: list of dicts {item_id, new_price}
    Returns: (ok_item_ids_set, failed_map[item_id]=error)
    """
    updates = [u for u in (updates or []) if u.get('item_id') and u.get('new_price') is not None]
    ok = set()
    failed = {}
    if not updates:
        return ok, failed

    token = os.getenv("EBAY_OLDAUTH_TOKEN") or ''
    token = token.strip()
    if not token:
        for u in updates:
            failed[u['item_id']] = 'Missing EBAY_OLDAUTH_TOKEN'
        return ok, failed

    # Build a single ReviseInventoryStatus call for a batch.
    import html as _html
    inv_chunks = []
    for u in updates:
        item_id = str(u['item_id']).strip()
        sku = str(u.get('sku') or '').strip()
        new_price = float(u['new_price'])
        sku_xml = f"<SKU>{_html.escape(sku)}</SKU>" if sku else ""
        inv_chunks.append(f'''
          <InventoryStatus>
            <ItemID>{item_id}</ItemID>
            {sku_xml}
            <StartPrice currencyID="{currency}">{new_price:.2f}</StartPrice>
          </InventoryStatus>
        ''')

    xml_payload = f'''<?xml version="1.0" encoding="utf-8"?>
      <ReviseInventoryStatusRequest xmlns="urn:ebay:apis:eBLBaseComponents">
        <RequesterCredentials>
          <eBayAuthToken>{token}</eBayAuthToken>
        </RequesterCredentials>
        <WarningLevel>High</WarningLevel>
        {''.join(inv_chunks)}
      </ReviseInventoryStatusRequest>
    '''

    resp = _pricemaster_ebay_trading_call('ReviseInventoryStatus', xml_payload, timeout=30)
    if resp.status_code != 200:
        msg = f"HTTP {resp.status_code}"
        try:
            msg = msg + f": {resp.text[:200]}"
        except Exception:
            pass
        for u in updates:
            failed[str(u['item_id']).strip()] = msg
        return ok, failed

    # Parse response
    ns = {'ebay': 'urn:ebay:apis:eBLBaseComponents'}
    try:
        root = ET.fromstring(resp.text)
    except Exception:
        for u in updates:
            failed[str(u['item_id']).strip()] = 'Invalid XML response from eBay'
        return ok, failed

    ack = (root.findtext('.//ebay:Ack', default='', namespaces=ns) or '').strip()
    errors = root.findall('.//ebay:Errors', ns) or []

    if ack in ('Success', 'Warning', 'PartialFailure'):
        # Best-effort map errors to ItemID via ErrorParameters.
        for err in errors:
            msg = (err.findtext('ebay:LongMessage', default='', namespaces=ns) or err.findtext('ebay:ShortMessage', default='', namespaces=ns) or 'eBay error').strip()
            mapped = False
            for ep in err.findall('ebay:ErrorParameters', ns) or []:
                v = (ep.findtext('ebay:Value', default='', namespaces=ns) or '').strip()
                if v and v.isdigit() and len(v) >= 8:  # item ids are typically long digits
                    failed[v] = msg
                    mapped = True
            if not mapped and ack != 'PartialFailure' and msg:
                # If we can't map and it's not partial, treat as a general failure.
                for u in updates:
                    failed[str(u['item_id']).strip()] = msg
                return ok, failed

        # Anything not marked failed is treated as success.
        for u in updates:
            item_id = str(u['item_id']).strip()
            if item_id and item_id not in failed:
                ok.add(item_id)
        return ok, failed

    # Failure
    msg = 'eBay API error'
    if errors:
        msg = (errors[0].findtext('ebay:LongMessage', default='', namespaces=ns) or errors[0].findtext('ebay:ShortMessage', default='', namespaces=ns) or msg).strip()
    for u in updates:
        failed[str(u['item_id']).strip()] = msg
    return ok, failed

def _pricemaster_ebay_get_item_price(item_id: str):
    """Fetch current price for an eBay listing via Trading API GetItem."""
    item_id = (item_id or '').strip()
    if not item_id:
        raise Exception('Missing item_id')

    token = os.getenv("EBAY_OLDAUTH_TOKEN") or ''
    token = token.strip()
    if not token:
        raise Exception("Missing EBAY_OLDAUTH_TOKEN (Trading API token)")

    xml_payload = f'''<?xml version="1.0" encoding="utf-8"?>
      <GetItemRequest xmlns="urn:ebay:apis:eBLBaseComponents">
        <RequesterCredentials>
          <eBayAuthToken>{token}</eBayAuthToken>
        </RequesterCredentials>
        <ItemID>{item_id}</ItemID>
        <DetailLevel>ReturnAll</DetailLevel>
        <IncludeItemSpecifics>false</IncludeItemSpecifics>
      </GetItemRequest>
    '''

    resp = _pricemaster_ebay_trading_call('GetItem', xml_payload, timeout=30)
    if resp.status_code != 200:
        raise Exception(f"HTTP {resp.status_code}: {resp.text[:200]}")

    ns = {'ebay': 'urn:ebay:apis:eBLBaseComponents'}
    try:
        root = ET.fromstring(resp.text)
    except Exception:
        raise Exception('Invalid XML response from eBay')

    ack = (root.findtext('.//ebay:Ack', default='', namespaces=ns) or '').strip()
    if ack not in ('Success', 'Warning', 'PartialFailure'):
        # Try to extract error
        err = root.find('.//ebay:Errors', ns)
        msg = 'eBay API error'
        if err is not None:
            msg = (err.findtext('ebay:LongMessage', default='', namespaces=ns) or err.findtext('ebay:ShortMessage', default='', namespaces=ns) or msg).strip()
        raise Exception(msg)

    price_el = (
        root.find('.//ebay:CurrentPrice', ns)
        or root.find('.//ebay:StartPrice', ns)
        or root.find('.//ebay:BuyItNowPrice', ns)
    )
    if price_el is None or price_el.text is None:
        raise Exception('Price not found in eBay response')

    currency = price_el.attrib.get('currencyID') or 'USD'
    price_d = _pricemaster_parse_decimal(price_el.text)
    if price_d is None:
        raise Exception('Invalid price value returned by eBay')

    return float(_pricemaster_money_2dp(price_d)), currency

def _pricemaster_fetch_ebay_rows(item_ids: list):
    out = {}
    item_ids = [str(x).strip() for x in (item_ids or []) if str(x).strip()]
    if not item_ids:
        return out
    CHUNK = 900
    with db_connection('ebayStore.db') as conn:
        cur = conn.cursor()
        for i in range(0, len(item_ids), CHUNK):
            batch = item_ids[i:i+CHUNK]
            ph = ','.join(['?'] * len(batch))
            cur.execute(f'''
                SELECT ItemID, Title, UPC, Price, Quantity, URL, List_State, List_Date
                FROM INVENTORY
                WHERE TRIM(COALESCE(ItemID,'')) IN ({ph})
                LIMIT {len(batch)}
            ''', batch)
            for r in cur.fetchall():
                out[(r['ItemID'] or '').strip()] = dict(r)
    return out

def _pricemaster_fetch_amazon_rows(skus: list):
    out = {}
    skus = [str(x).strip() for x in (skus or []) if str(x).strip()]
    if not skus:
        return out
    CHUNK = 900
    with db_connection('amazonStore.db') as conn:
        cur = conn.cursor()
        for i in range(0, len(skus), CHUNK):
            batch = skus[i:i+CHUNK]
            ph = ','.join(['?'] * len(batch))
            cur.execute(f'''
                SELECT SKU, ASIN, UPC, TITLE, PRICE, QUANTITY, STATUS, CONDITION, FULFILLMENT_CHANNEL, LAST_UPDATED
                FROM ITEMS
                WHERE TRIM(COALESCE(SKU,'')) IN ({ph})
                LIMIT {len(batch)}
            ''', batch)
            for r in cur.fetchall():
                out[(r['SKU'] or '').strip()] = dict(r)
    return out

@app.route('/api/pricemaster/listings', methods=['GET'])
def api_pricemaster_listings():
    """Return current store listings (eBay + Amazon) with local meta (first seen + last price change)."""
    try:
        platform_param = (request.args.get('platform') or '').strip().lower()
        include_inactive = (request.args.get('include_inactive') or '').strip() in ('1', 'true', 'yes')

        want_ebay = (platform_param in ('', 'all', 'ebay'))
        want_amazon = (platform_param in ('', 'all', 'amazon'))

        items = []
        ebay_keys = []
        amazon_keys = []
        touch_rows = []

        if want_ebay:
            with db_connection('ebayStore.db') as conn:
                cur = conn.cursor()
                if include_inactive:
                    cur.execute('''
                        SELECT Title, ItemID, SKU, Price, Quantity, URL, List_State, List_Date, UPC
                        FROM INVENTORY
                        WHERE TRIM(COALESCE(ItemID,'')) != ''
                        ORDER BY ID DESC
                        LIMIT 6000
                    ''')
                else:
                    cur.execute('''
                        SELECT Title, ItemID, SKU, Price, Quantity, URL, List_State, List_Date, UPC
                        FROM INVENTORY
                        WHERE TRIM(COALESCE(ItemID,'')) != ''
                          AND (TRIM(COALESCE(List_State,'')) = 'Active')
                        ORDER BY ID DESC
                        LIMIT 6000
                    ''')
                for r in cur.fetchall():
                    item_id = (r['ItemID'] or '').strip()
                    if not item_id:
                        continue
                    price_d = _pricemaster_parse_decimal(r['Price'])
                    price = float(_pricemaster_money_2dp(price_d)) if price_d is not None else None
                    qty = _listingagent_parse_int(r['Quantity'], None)
                    sku = (r['SKU'] or '').strip()
                    if sku.lower() == 'none':
                        sku = ''
                    upc = (r['UPC'] or '').strip()
                    list_date = (r['List_Date'] or '').strip()

                    items.append({
                        'platform': 'ebay',
                        'listing_key': item_id,
                        'item_id': item_id,
                        'sku': sku,
                        'asin': '',
                        'upc': upc,
                        'title': (r['Title'] or '').strip(),
                        'price': price,
                        'currency': 'USD',
                        'quantity': qty,
                        'status': (r['List_State'] or '').strip(),
                        'url': (r['URL'] or '').strip(),
                        'list_date': list_date,
                        'last_updated': '',
                    })
                    ebay_keys.append(item_id)
                    touch_rows.append(('ebay', item_id, list_date or _pricemaster_now_iso()))

        if want_amazon:
            with db_connection('amazonStore.db') as conn:
                cur = conn.cursor()
                if include_inactive:
                    cur.execute('''
                        SELECT TITLE, SKU, ASIN, UPC, PRICE, QUANTITY, STATUS, LAST_UPDATED
                        FROM ITEMS
                        WHERE TRIM(COALESCE(SKU,'')) != ''
                        ORDER BY ID DESC
                        LIMIT 6000
                    ''')
                else:
                    cur.execute('''
                        SELECT TITLE, SKU, ASIN, UPC, PRICE, QUANTITY, STATUS, LAST_UPDATED
                        FROM ITEMS
                        WHERE TRIM(COALESCE(SKU,'')) != ''
                          AND (TRIM(COALESCE(STATUS,'')) = 'Active')
                        ORDER BY ID DESC
                        LIMIT 6000
                    ''')
                for r in cur.fetchall():
                    sku = (r['SKU'] or '').strip()
                    if not sku:
                        continue
                    asin = (r['ASIN'] or '').strip()
                    upc = (r['UPC'] or '').strip()
                    last_updated = (r['LAST_UPDATED'] or '').strip()

                    price_d = _pricemaster_parse_decimal(r['PRICE'])
                    price = float(_pricemaster_money_2dp(price_d)) if price_d is not None else None
                    qty = _listingagent_parse_int(r['QUANTITY'], None)

                    items.append({
                        'platform': 'amazon',
                        'listing_key': sku,
                        'item_id': '',
                        'sku': sku,
                        'asin': asin,
                        'upc': upc,
                        'title': (r['TITLE'] or '').strip(),
                        'price': price,
                        'currency': 'USD',
                        'quantity': qty,
                        'status': (r['STATUS'] or '').strip(),
                        'url': '',
                        'list_date': '',
                        'last_updated': last_updated,
                    })
                    amazon_keys.append(sku)
                    touch_rows.append(('amazon', sku, last_updated or _pricemaster_now_iso()))

        # Ensure meta rows exist for sorting (first_seen_at), then attach meta data.
        _pricemaster_touch_meta(touch_rows)
        ebay_meta = _pricemaster_get_meta_map('ebay', ebay_keys)
        amazon_meta = _pricemaster_get_meta_map('amazon', amazon_keys)

        for it in items:
            key = it.get('listing_key') or ''
            meta = (ebay_meta.get(key) if it.get('platform') == 'ebay' else amazon_meta.get(key)) or {}
            it['first_seen_at'] = meta.get('first_seen_at') or ''
            it['last_price_change_at'] = meta.get('last_price_change_at') or ''
            it['last_price_change_price'] = meta.get('last_price_change_price')

        return jsonify({'success': True, 'items': items})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'pricemaster:listings')}), 500

@app.route('/api/pricemaster/bulk_update', methods=['POST'])
def api_pricemaster_bulk_update():
    """Bulk update prices on the marketplaces and record local price-change history."""
    try:
        data = request.json or {}
        adj = data.get('adjustment') or {}
        mode = (adj.get('mode') or 'delta').strip().lower()
        if mode not in ('delta', 'percent'):
            return jsonify({'success': False, 'error': 'Invalid adjustment mode'}), 400

        value_d = _pricemaster_parse_decimal(adj.get('value'))
        if value_d is None:
            return jsonify({'success': False, 'error': 'Adjustment value is required'}), 400

        targets = data.get('targets') or []
        if not isinstance(targets, list) or len(targets) == 0:
            return jsonify({'success': False, 'error': 'No targets provided'}), 400

        dry_run = bool(data.get('dry_run', False))

        ebay_ids = []
        amazon_skus = []
        for t in targets:
            p = (t.get('platform') or '').strip().lower()
            k = (t.get('listing_key') or '').strip()
            if not p or not k:
                continue
            if p == 'ebay':
                ebay_ids.append(k)
            elif p == 'amazon':
                amazon_skus.append(k)

        ebay_rows = _pricemaster_fetch_ebay_rows(ebay_ids) if ebay_ids else {}
        amazon_rows = _pricemaster_fetch_amazon_rows(amazon_skus) if amazon_skus else {}

        results = []

        # ---- eBay (Trading API) ----
        ebay_updates = []
        for item_id in ebay_ids:
            row = ebay_rows.get(item_id)
            if not row:
                results.append({'platform': 'ebay', 'listing_key': item_id, 'success': False, 'error': 'Listing not found in ebayStore.db'})
                continue

            old_d = _pricemaster_parse_decimal(row.get('Price'))
            old_d = _pricemaster_money_2dp(old_d) if old_d is not None else None
            if old_d is None:
                results.append({'platform': 'ebay', 'listing_key': item_id, 'success': False, 'error': 'Missing current price'})
                continue

            new_d = _pricemaster_compute_new_price(old_d, mode, value_d)
            if new_d is None:
                results.append({'platform': 'ebay', 'listing_key': item_id, 'success': False, 'error': 'Could not compute new price'})
                continue

            results.append({'platform': 'ebay', 'listing_key': item_id, 'success': True, 'old_price': float(old_d), 'new_price': float(new_d), '_dry': True})
            if not dry_run:
                sku = (row.get('SKU') or '').strip()
                ebay_updates.append({'item_id': item_id, 'sku': sku, 'new_price': float(new_d), 'old_price': float(old_d)})

        if not dry_run and ebay_updates:
            # Batch into modest chunks to avoid huge Trading API payloads.
            ok_ids = set()
            fail_map = {}
            BATCH = 25
            for i in range(0, len(ebay_updates), BATCH):
                batch = ebay_updates[i:i+BATCH]
                ok, failed = _pricemaster_ebay_revise_prices_bulk(batch, currency='USD')
                ok_ids |= set(ok)
                fail_map.update(failed or {})

            # Update local DB + record history
            with db_connection('ebayStore.db') as conn:
                cur = conn.cursor()
                for u in ebay_updates:
                    item_id = str(u['item_id']).strip()
                    old_price = u.get('old_price')
                    new_price = u.get('new_price')
                    if item_id in ok_ids:
                        cur.execute('UPDATE INVENTORY SET Price = ? WHERE TRIM(COALESCE(ItemID,\'\')) = ? COLLATE NOCASE', (f"{float(new_price):.2f}", item_id))
                        _pricemaster_record_change(platform='ebay', listing_key=item_id, old_price=old_price, new_price=new_price, mode=mode, value=value_d, success=True)
                    else:
                        err = fail_map.get(item_id) or 'eBay price update failed'
                        _pricemaster_record_change(platform='ebay', listing_key=item_id, old_price=old_price, new_price=new_price, mode=mode, value=value_d, success=False, error=err)

            # Patch results list to reflect real outcomes (replace the earlier _dry placeholders)
            for r in results:
                if r.get('platform') == 'ebay' and r.get('_dry') and not dry_run:
                    item_id = r.get('listing_key')
                    if item_id in ok_ids:
                        r['success'] = True
                    else:
                        r['success'] = False
                        r['error'] = fail_map.get(item_id) or 'eBay price update failed'
                    r.pop('_dry', None)

        # ---- Amazon (SP-API) ----
        amazon_jobs = []
        for sku in amazon_skus:
            row = amazon_rows.get(sku)
            if not row:
                results.append({'platform': 'amazon', 'listing_key': sku, 'success': False, 'error': 'Listing not found in amazonStore.db'})
                continue

            old_d = _pricemaster_parse_decimal(row.get('PRICE'))
            old_d = _pricemaster_money_2dp(old_d) if old_d is not None else None
            if old_d is None:
                results.append({'platform': 'amazon', 'listing_key': sku, 'success': False, 'error': 'Missing current price'})
                continue

            new_d = _pricemaster_compute_new_price(old_d, mode, value_d)
            if new_d is None:
                results.append({'platform': 'amazon', 'listing_key': sku, 'success': False, 'error': 'Could not compute new price'})
                continue

            results.append({'platform': 'amazon', 'listing_key': sku, 'success': True, 'old_price': float(old_d), 'new_price': float(new_d), '_dry': True})
            if not dry_run:
                amazon_jobs.append({
                    'sku': sku,
                    'asin': (row.get('ASIN') or '').strip(),
                    'upc': (row.get('UPC') or '').strip(),
                    'quantity': _listingagent_parse_int(row.get('QUANTITY'), 1) or 1,
                    'condition': (row.get('CONDITION') or '').strip(),
                    'fulfillment_channel': (row.get('FULFILLMENT_CHANNEL') or '').strip(),
                    'old_price': float(old_d),
                    'new_price': float(new_d),
                })

        if not dry_run and amazon_jobs:
            settings = _listingagent_get_settings()
            credentials, seller_id, marketplace_id, marketplace = _amazon_spapi_context()
            if marketplace is None:
                # Record failures consistently
                for j in amazon_jobs:
                    _pricemaster_record_change(platform='amazon', listing_key=j['sku'], old_price=j['old_price'], new_price=j['new_price'], mode=mode, value=value_d, success=False, error='Amazon SP-API not available')
                for r in results:
                    if r.get('platform') == 'amazon' and r.get('_dry'):
                        r['success'] = False
                        r['error'] = 'Amazon SP-API not available'
                        r.pop('_dry', None)
            else:
                from sp_api.api import ListingsItems
                li = ListingsItems(credentials=credentials, marketplace=marketplace)

                mp_id = (settings.get('amazon_marketplace_id') or marketplace_id or 'ATVPDKIKX0DER').strip()
                currency = (settings.get('amazon_currency') or 'USD').strip()
                default_product_type = (settings.get('amazon_product_type') or 'PRODUCT').strip()
                requirements = (settings.get('amazon_requirements') or 'LISTING_OFFER_ONLY').strip()
                default_condition = (settings.get('amazon_condition_type') or 'used_good').strip()
                default_fc = (settings.get('amazon_fulfillment_channel_code') or 'DEFAULT').strip()
                offer_audience = _amazon_offer_audience(settings)

                ok_skus = set()
                fail_skus = {}
                product_type_cache = {}
                feed_candidates = []
                for j in amazon_jobs:
                    sku = j['sku']
                    asin = j.get('asin') or ''
                    upc = j.get('upc') or ''
                    qty = int(j.get('quantity') or 1)
                    condition_type = _amazon_normalize_condition_type(j.get('condition'), default_condition)
                    fc_code = _amazon_normalize_fulfillment_channel(j.get('fulfillment_channel'), default_fc)
                    price = float(j.get('new_price'))

                    try:
                        debug = {'attempts': []}
                        product_type = default_product_type
                        product_type = _amazon_get_listing_product_type(li, seller_id, sku, mp_id, product_type_cache)
                        if not product_type:
                            product_type = _amazon_get_catalog_product_type(credentials, marketplace, mp_id, asin)
                        product_type = product_type or default_product_type

                        def _append_attempts(plan_name, req_used, pt_used, attempt_debug):
                            try:
                                at = (attempt_debug or {}).get('attempts') or []
                            except Exception:
                                at = []
                            for entry in at:
                                item = {
                                    'plan': plan_name,
                                    'requirements': req_used,
                                    'product_type': pt_used,
                                }
                                if isinstance(entry, dict):
                                    item.update(entry)
                                debug['attempts'].append(item)

                        def _format_err_text(err_obj):
                            try:
                                return _amazon_format_spapi_error(err_obj)
                            except Exception:
                                return str(err_obj or '')

                        def _is_retryable_schema_error(err_text):
                            low = str(err_text or '').lower()
                            return (
                                ('invalidinput' in low)
                                or ('invalid parameters' in low)
                                or ('status=invalid' in low)
                                or ('issues=' in low)
                            )

                        def _is_non_retryable_error(err_text):
                            low = str(err_text or '').lower()
                            markers = (
                                'unauthorized',
                                'forbidden',
                                'accessdenied',
                                'access denied',
                                "invalid 'sellerid' provided",
                                'invalid "sellerid" provided',
                                "invalid 'marketplaceids' provided",
                                'invalid "marketplaceids" provided',
                                'quota',
                                'throttl',
                            )
                            return any(m in low for m in markers)

                        req_primary = requirements or 'LISTING_OFFER_ONLY'
                        req_fallback = 'LISTING_OFFER_ONLY'
                        pt_primary = product_type
                        pt_fallback = 'PRODUCT'

                        attrs_full = _build_amazon_offer_attributes(
                            upc=upc,
                            asin=asin,
                            condition_type=condition_type,
                            fulfillment_channel_code=fc_code,
                            quantity=qty,
                            currency=currency,
                            price=price,
                            include_identifiers=False,
                            marketplace_id=mp_id,
                            offer_audience=offer_audience
                        )

                        attrs_list_price = _build_amazon_offer_attributes(
                            upc=upc,
                            asin=asin,
                            condition_type='',
                            fulfillment_channel_code='',
                            quantity=qty,
                            currency=currency,
                            price=price,
                            include_identifiers=False,
                            marketplace_id=mp_id,
                            offer_audience=offer_audience,
                            include_marketplace_fields=False,
                            include_offer_audience=False,
                            price_model='list_price'
                        )

                        attempt_plans = [
                            {
                                'name': 'price_default',
                                'requirements': req_primary,
                                'product_type': pt_primary,
                                'attrs': _amazon_offer_price_attrs(
                                    currency, price, mp_id,
                                    offer_audience=offer_audience,
                                    include_marketplace_fields=True,
                                    include_offer_audience=True
                                ),
                            },
                            {
                                'name': 'price_no_audience',
                                'requirements': req_primary,
                                'product_type': pt_primary,
                                'attrs': _amazon_offer_price_attrs(
                                    currency, price, mp_id,
                                    offer_audience=offer_audience,
                                    include_marketplace_fields=True,
                                    include_offer_audience=False
                                ),
                            },
                            {
                                'name': 'price_no_marketplace',
                                'requirements': req_primary,
                                'product_type': pt_primary,
                                'attrs': _amazon_offer_price_attrs(
                                    currency, price, mp_id,
                                    offer_audience=offer_audience,
                                    include_marketplace_fields=False,
                                    include_offer_audience=True
                                ),
                            },
                            {
                                'name': 'price_minimal_listing_offer',
                                'requirements': req_fallback,
                                'product_type': pt_primary,
                                'attrs': _amazon_offer_price_attrs(
                                    currency, price, mp_id,
                                    offer_audience=offer_audience,
                                    include_marketplace_fields=False,
                                    include_offer_audience=False
                                ),
                            },
                            {
                                'name': 'full_offer_listing_offer',
                                'requirements': req_fallback,
                                'product_type': pt_primary,
                                'attrs': attrs_full,
                            },
                            {
                                'name': 'list_price_product',
                                'requirements': req_fallback,
                                'product_type': pt_fallback,
                                'attrs': attrs_list_price,
                            },
                        ]

                        ok = False
                        last_err = None
                        for plan in attempt_plans:
                            req_used = plan['requirements']
                            pt_used = plan['product_type']
                            attrs_used = plan['attrs']
                            ok_try, debug_try, err_try = _amazon_update_price_spapi(
                                li,
                                seller_id,
                                sku,
                                mp_id,
                                product_type=pt_used,
                                requirements=req_used,
                                attrs=attrs_used
                            )
                            _append_attempts(plan.get('name') or 'attempt', req_used, pt_used, debug_try)
                            if ok_try:
                                ok = True
                                break

                            last_err = err_try
                            err_text = _format_err_text(err_try)
                            if _is_non_retryable_error(err_text):
                                break
                            if not _is_retryable_schema_error(err_text):
                                break

                        if not ok:
                            raise Exception(_format_err_text(last_err) if last_err else 'Amazon price update failed')

                        ok_skus.add(sku)
                        _pricemaster_record_change(platform='amazon', listing_key=sku, old_price=j['old_price'], new_price=j['new_price'], mode=mode, value=value_d, success=True)
                    except Exception as e:
                        msg = _amazon_format_spapi_error(e)
                        try:
                            msg = f"{msg} | product_type={product_type}"
                        except Exception:
                            pass
                        try:
                            import json as json_module
                            msg = f"{msg} | debug={json_module.dumps(debug, ensure_ascii=True, default=str)}"
                        except Exception:
                            pass
                        fail_skus[sku] = msg
                        if 'InvalidInput' in msg:
                            feed_candidates.append({
                                'sku': sku,
                                'product_type': product_type,
                                'new_price': j.get('new_price'),
                                'old_price': j.get('old_price')
                            })
                        _pricemaster_record_change(platform='amazon', listing_key=sku, old_price=j['old_price'], new_price=j['new_price'], mode=mode, value=value_d, success=False, error=msg)

                # Feed fallback for InvalidInput failures
                feed_skus = set()
                pending_skus = set()
                feed_id = None
                if feed_candidates:
                    try:
                        # Attach adjustment info for later reconciliation
                        for fc in feed_candidates:
                            if 'mode' not in fc:
                                fc['mode'] = mode
                            if 'value' not in fc:
                                fc['value'] = float(value_d) if value_d is not None else None
                        feed_id = _amazon_submit_price_feed(
                            credentials=credentials,
                            marketplace=marketplace,
                            marketplace_id=mp_id,
                            seller_id=seller_id,
                            jobs=feed_candidates,
                            currency=currency,
                            offer_audience=offer_audience
                        )
                        _pricemaster_save_feed_job(feed_id, mp_id, feed_candidates, status='SUBMITTED')
                        for j in feed_candidates:
                            feed_skus.add(j['sku'])
                            pending_skus.add(j['sku'])
                            # overwrite failure if feed submitted
                            fail_skus.pop(j['sku'], None)
                    except Exception as e:
                        feed_err = _amazon_format_spapi_error(e)
                        for j in feed_candidates:
                            fail_skus[j['sku']] = f"{fail_skus.get(j['sku'], '')} | feed_error={feed_err}"

                # Update local amazonStore.db for successes
                now_iso = _pricemaster_now_iso()
                with db_connection('amazonStore.db') as conn:
                    cur = conn.cursor()
                    for j in amazon_jobs:
                        sku = j['sku']
                        if sku in ok_skus and sku not in pending_skus:
                            cur.execute('UPDATE ITEMS SET PRICE = ?, LAST_UPDATED = ? WHERE TRIM(COALESCE(SKU,\'\')) = ? COLLATE NOCASE', (float(j['new_price']), now_iso, sku))

                for r in results:
                    if r.get('platform') == 'amazon' and r.get('_dry'):
                        sku = r.get('listing_key')
                        if sku in pending_skus:
                            r['success'] = True
                            r['pending'] = True
                            if feed_id:
                                r['note'] = f"Submitted via Amazon feed {feed_id} (processing)"
                        elif sku in ok_skus:
                            r['success'] = True
                        else:
                            r['success'] = False
                            r['error'] = fail_skus.get(sku) or 'Amazon price update failed'
                        r.pop('_dry', None)

        # Clean up any remaining placeholders
        for r in results:
            r.pop('_dry', None)

        return jsonify({'success': True, 'dry_run': dry_run, 'results': results})

    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'pricemaster:bulk_update')}), 500

@app.route('/api/pricemaster/ebay_verify', methods=['POST'])
def api_pricemaster_ebay_verify():
    """Verify eBay listing prices against live data and sync local DB."""
    try:
        data = request.json or {}
        items = data.get('items') or []
        if not items:
            item_id = (data.get('item_id') or '').strip()
            expected = data.get('expected_price')
            if item_id:
                items = [{'item_id': item_id, 'expected_price': expected}]

        if not items:
            return jsonify({'success': False, 'error': 'No item ids provided'}), 400

        results = []
        # Limit to a reasonable number to avoid rate limits
        items = items[:10]

        for it in items:
            item_id = (it.get('item_id') or '').strip()
            if not item_id:
                continue
            expected_d = _pricemaster_parse_decimal(it.get('expected_price'))
            expected = float(_pricemaster_money_2dp(expected_d)) if expected_d is not None else None
            try:
                price, currency = _pricemaster_ebay_get_item_price(item_id)
                applied = None
                if expected is not None and price is not None:
                    applied = abs(float(price) - float(expected)) <= 0.01
                # Sync local DB price
                with db_connection('ebayStore.db') as conn:
                    cur = conn.cursor()
                    cur.execute('UPDATE INVENTORY SET Price = ? WHERE TRIM(COALESCE(ItemID,\'\')) = ? COLLATE NOCASE', (f"{float(price):.2f}", item_id))
                results.append({
                    'item_id': item_id,
                    'price': price,
                    'currency': currency,
                    'expected_price': expected,
                    'applied': applied,
                })
            except Exception as e:
                results.append({
                    'item_id': item_id,
                    'error': _safe_error(e, 'pricemaster:ebay_verify:item')
                })

        return jsonify({'success': True, 'items': results})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'pricemaster:ebay_verify')}), 500

@app.route('/api/pricemaster/feed_status', methods=['POST'])
def api_pricemaster_feed_status():
    """Check Amazon feed processing status and apply successful feed updates to local DB."""
    try:
        data = request.json or {}
        feed_id = (data.get('feed_id') or '').strip()
        if not feed_id:
            return jsonify({'success': False, 'error': 'feed_id is required'}), 400

        credentials, _seller_id, _marketplace_id, marketplace = _amazon_spapi_context()
        if marketplace is None:
            return jsonify({'success': False, 'error': 'Amazon SP-API not available'}), 503

        info = _amazon_get_feed_status(credentials, marketplace, feed_id)
        status = (info.get('status') or '').strip()
        result_doc_id = info.get('result_feed_document_id')

        report = None
        report_errors = []
        report_warnings = []
        if result_doc_id:
            try:
                from sp_api.api import Feeds
                feeds = Feeds(credentials=credentials, marketplace=marketplace)
                doc_resp = _amazon_get_feed_document_info(feeds, result_doc_id)
                doc_payload = getattr(doc_resp, 'payload', None) or {}
                url = doc_payload.get('url')
                raw = _amazon_download_feed_document(url)
                report = _amazon_parse_feed_report(raw)
                report_errors = report.get('errors') or []
                report_warnings = report.get('warnings') or []
            except Exception as e:
                report = {'error_count': 1, 'errors': [{'code': 'Report', 'message': _amazon_format_spapi_error(e)}]}

        # Update feed job + apply if successful
        job = _pricemaster_get_feed_job(feed_id)
        if status:
            _pricemaster_update_feed_job(feed_id, status=status, result_document_id=result_doc_id)

        applied = False
        if status and status.upper() in ('DONE', 'DONE_NO_DATA', 'DONE_SUCCESS', 'DONE_WARNING', 'SUCCESS'):
            if report and report.get('error_count', 0) == 0:
                # Apply updates to local DB + record history
                items = []
                try:
                    import json as _json
                    items = _json.loads((job or {}).get('items_json') or '[]')
                except Exception:
                    items = []

                now_iso = _pricemaster_now_iso()
                with db_connection('amazonStore.db') as conn:
                    cur = conn.cursor()
                    for it in items:
                        sku = (it.get('sku') or '').strip()
                        if not sku:
                            continue
                        new_price = it.get('new_price')
                        old_price = it.get('old_price')
                        mode = it.get('mode') or 'delta'
                        val = it.get('value')
                        try:
                            cur.execute('UPDATE ITEMS SET PRICE = ?, LAST_UPDATED = ? WHERE TRIM(COALESCE(SKU,\'\')) = ? COLLATE NOCASE', (float(new_price), now_iso, sku))
                        except Exception:
                            pass
                        try:
                            _pricemaster_record_change(platform='amazon', listing_key=sku, old_price=old_price, new_price=new_price, mode=mode, value=_pricemaster_parse_decimal(val), success=True)
                        except Exception:
                            pass
                applied = True
                _pricemaster_update_feed_job(feed_id, status=status, error=None, result_document_id=result_doc_id)
            elif report and report.get('error_count', 0) > 0:
                # Record failures
                items = []
                try:
                    import json as _json
                    items = _json.loads((job or {}).get('items_json') or '[]')
                except Exception:
                    items = []
                err_msg = report_errors[0].get('message') if report_errors else 'Feed processing error'
                for it in items:
                    sku = (it.get('sku') or '').strip()
                    if not sku:
                        continue
                    try:
                        _pricemaster_record_change(platform='amazon', listing_key=sku, old_price=it.get('old_price'), new_price=it.get('new_price'), mode=it.get('mode') or 'delta', value=_pricemaster_parse_decimal(it.get('value')), success=False, error=err_msg)
                    except Exception:
                        pass
                _pricemaster_update_feed_job(feed_id, status=status, error=err_msg, result_document_id=result_doc_id)

        return jsonify({
            'success': True,
            'feed_id': feed_id,
            'status': status,
            'result_feed_document_id': result_doc_id,
            'report': report,
            'report_errors': report_errors,
            'report_warnings': report_warnings,
            'applied': applied
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'pricemaster:feed_status')}), 500

@app.route('/api/listing-helper/scan', methods=['GET'])
def api_listing_helper_scan():
    """Scan for listing issues with low-noise zero inventory gating."""
    import hashlib
    force_refresh = (request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes', 'y')
    if not force_refresh:
        cached_payload = _listing_helper_scan_cache_get(max_age_seconds=20)
        if cached_payload:
            return jsonify(cached_payload)

    alerts = {
        'no_warehouse': [],      # Listings with UPC not in warehouse
        'quantity_alert': [],    # Any single listing qty > total warehouse qty
        'no_listings': [],       # Warehouse stock with no active listing on any store
        'sync_overdue': [],      # Sync manager overdue beyond configured interval
        'listing_matches': []    # Listings needing or already using a manual inventory match
    }

    try:
        _ensure_listing_alerts_tables()
        _ensure_bol_list_status_column()

        def _match_upc_key(raw_upc):
            upc = (str(raw_upc or '').strip())
            if not upc:
                return ''
            normalized = _strip_leading_zeros_numeric(upc)
            return (normalized or upc).lower()

        def _safe_int(val, default=1):
            try:
                if val is None:
                    return default
                if isinstance(val, str):
                    s = val.strip().lower()
                    if s in ('', 'n/a', 'na', 'null'):
                        return default
                return int(float(val))
            except Exception:
                return default

        def _extract_image_url(raw_value):
            raw = (str(raw_value or '').strip())
            if not raw:
                return ''

            # Some rows store image lists (JSON or delimiter-separated).
            if raw.startswith('[') and raw.endswith(']'):
                try:
                    parsed = json.loads(raw)
                    if isinstance(parsed, list):
                        for item in parsed:
                            candidate = (str(item or '').strip().strip('"').strip("'"))
                            if candidate:
                                return candidate
                    elif isinstance(parsed, str):
                        candidate = parsed.strip().strip('"').strip("'")
                        if candidate:
                            return candidate
                except Exception:
                    pass

            for delim in ('|', ',', ';'):
                if delim in raw:
                    for part in raw.split(delim):
                        candidate = (part or '').strip().strip('"').strip("'")
                        if candidate:
                            return candidate
                    return ''

            return raw.strip('"').strip("'")

        def _parse_iso_utc(raw):
            txt = (str(raw or '').strip())
            if not txt:
                return None
            try:
                if 'T' in txt:
                    if txt.endswith('Z'):
                        dt = datetime.datetime.fromisoformat(txt.replace('Z', '+00:00'))
                    else:
                        dt = datetime.datetime.fromisoformat(txt)
                else:
                    dt = datetime.datetime.fromisoformat(txt)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                return dt
            except Exception:
                return None

        invalid_upc_values = {'null', 'n/a', 'does not apply'}
        scan_now_utc = datetime.datetime.utcnow()
        enable_ebay_live_check = (os.getenv('LISTING_HELPER_EBAY_LIVE_CHECK', '0').strip().lower() in ('1', 'true', 'yes', 'y'))

        # Guard against stale "Active" rows in ebayStore.db when sync reconciliation misses a cycle.
        # We only live-check older listings, cache results, and cap checks per scan.
        ebay_live_cache = {}
        ebay_live_cache_updates = []
        ebay_live_check_budget = 30 if enable_ebay_live_check else 0
        ebay_live_checks_used = 0
        ebay_live_cache_ttl_seconds = 24 * 3600
        ebay_live_verify_min_age_days = 120
        ebay_live_filtered_item_ids = set()

        def _ebay_cache_is_fresh(checked_at_raw):
            dt = _parse_iso_utc(checked_at_raw) or _parse_iso_utc_naive(checked_at_raw)
            if dt is None:
                return False
            return (scan_now_utc - dt).total_seconds() <= ebay_live_cache_ttl_seconds

        def _ebay_listing_allowed_for_alert(item_id_raw, list_date_raw, url_raw):
            nonlocal ebay_live_checks_used
            if not enable_ebay_live_check:
                return True
            item_id = (str(item_id_raw or '').strip())
            if not item_id:
                return True

            list_dt = _parse_iso_utc(list_date_raw) or _parse_iso_utc_naive(list_date_raw)
            if list_dt is not None:
                age_days = (scan_now_utc - list_dt).total_seconds() / 86400.0
                if age_days < ebay_live_verify_min_age_days:
                    return True

            cached = ebay_live_cache.get(item_id)
            if cached and _ebay_cache_is_fresh(cached.get('checked_at')):
                return bool(int(cached.get('is_active') or 0))

            if ebay_live_checks_used >= ebay_live_check_budget:
                return True

            ebay_live_checks_used += 1
            is_active, note = _probe_ebay_listing_live(item_id, url_raw)
            if is_active is None:
                return True

            checked_at = datetime.datetime.utcnow().isoformat() + 'Z'
            cache_row = {
                'item_id': item_id,
                'is_active': 1 if is_active else 0,
                'checked_at': checked_at,
                'note': note or ''
            }
            ebay_live_cache[item_id] = cache_row
            ebay_live_cache_updates.append(cache_row)

            if not is_active:
                ebay_live_filtered_item_ids.add(item_id)
            return bool(is_active)

        if enable_ebay_live_check:
            try:
                with sqlite3.connect('listing_alerts.db') as cache_conn:
                    cache_conn.row_factory = sqlite3.Row
                    cache_cur = cache_conn.cursor()
                    cache_cur.execute('SELECT item_id, is_active, checked_at FROM ebay_listing_health_cache')
                    for row in cache_cur.fetchall():
                        item_id = (row['item_id'] or '').strip()
                        if not item_id:
                            continue
                        ebay_live_cache[item_id] = {
                            'item_id': item_id,
                            'is_active': int(row['is_active'] or 0),
                            'checked_at': row['checked_at'] or '',
                            'note': ''
                        }
            except Exception as e:
                print(f"Error reading ebay listing health cache: {e}")

        # Get dismissed alerts
        with sqlite3.connect('listing_alerts.db') as alerts_conn:
            alerts_cur = alerts_conn.cursor()
            alerts_cur.execute('SELECT alert_type, snapshot_hash FROM dismissed_alerts')
            dismissed = {(r[0], r[1]) for r in alerts_cur.fetchall()}

        sync_overdue_alert = _sync_manager_overdue_alert()
        if sync_overdue_alert and ('sync_overdue', sync_overdue_alert.get('hash')) not in dismissed:
            alerts['sync_overdue'].append(sync_overdue_alert)

        # Get warehouse stock (sum qty by UPC/Barcode) + locations where items exist.
        warehouse_stock = {}
        warehouse_locations = {}
        warehouse_stock_by_base = {}
        warehouse_locations_by_base = {}
        warehouse_title_by_base = {}
        warehouse_image_by_base = {}
        warehouse_display_upc_by_base = {}
        warehouse_tokens_by_base = {}
        rawbol_title_by_base = {}
        rawbol_image_by_base = {}
        rawbol_display_upc_by_base = {}
        try:
            with sqlite3.connect('searchRack.db') as sr_conn:
                sr_conn.row_factory = sqlite3.Row
                sr_cur = sr_conn.cursor()
                sr_cur.execute('PRAGMA table_info(SEARCHRACK)')
                sr_cols = [c[1] for c in sr_cur.fetchall()]
                sr_cols_lower = {c.lower(): c for c in sr_cols}
                upc_col = sr_cols_lower.get('upc') or sr_cols_lower.get('barcode')
                qty_col = sr_cols_lower.get('quantity') or sr_cols_lower.get('qty')
                pos_col = sr_cols_lower.get('item_position') or sr_cols_lower.get('itemposition') or sr_cols_lower.get('position')
                pic_col = sr_cols_lower.get('pictureposition')
                title_col = sr_cols_lower.get('title')
                img_col = sr_cols_lower.get('image') or sr_cols_lower.get('images')
                if upc_col and qty_col:
                    pos_expr = f"{pos_col} AS LOC" if pos_col else "NULL AS LOC"
                    pic_expr = f"{pic_col} AS PIC" if pic_col else "NULL AS PIC"
                    title_expr = f"{title_col} AS TITLE" if title_col else "NULL AS TITLE"
                    img_expr = f"{img_col} AS IMG" if img_col else "NULL AS IMG"
                    sr_cur.execute(f'''
                        SELECT rowid AS RID, {upc_col} AS UPC, {qty_col} AS QTY, {pos_expr}, {pic_expr}, {title_expr}, {img_expr}
                        FROM SEARCHRACK
                        WHERE {upc_col} IS NOT NULL AND {upc_col} != ""
                          AND COALESCE(CAST({qty_col} AS INTEGER), 0) > 0
                    ''')
                    for row in sr_cur.fetchall():
                        try:
                            upc_raw = (row['UPC'] or '').strip()
                            upc_key = _match_upc_key(upc_raw)
                            base_upc_key = _listing_alert_base_upc_key(upc_raw)
                            if not upc_key or upc_key in invalid_upc_values:
                                continue

                            qty_val = max(0, _safe_int(row['QTY'], 0))
                            warehouse_stock[upc_key] = warehouse_stock.get(upc_key, 0) + qty_val
                            if base_upc_key and base_upc_key not in invalid_upc_values:
                                warehouse_stock_by_base[base_upc_key] = warehouse_stock_by_base.get(base_upc_key, 0) + qty_val

                            loc = (row['LOC'] or '').strip()
                            pic = (row['PIC'] or '').strip()
                            location_label = loc or pic
                            if location_label:
                                existing_locs = warehouse_locations.get(upc_key)
                                if existing_locs is None:
                                    existing_locs = []
                                    warehouse_locations[upc_key] = existing_locs
                                if location_label not in existing_locs:
                                    existing_locs.append(location_label)
                                if base_upc_key and base_upc_key not in invalid_upc_values:
                                    existing_base_locs = warehouse_locations_by_base.get(base_upc_key)
                                    if existing_base_locs is None:
                                        existing_base_locs = []
                                        warehouse_locations_by_base[base_upc_key] = existing_base_locs
                                    if location_label not in existing_base_locs:
                                        existing_base_locs.append(location_label)

                            if base_upc_key and base_upc_key not in invalid_upc_values:
                                if upc_raw and base_upc_key not in warehouse_display_upc_by_base:
                                    warehouse_display_upc_by_base[base_upc_key] = upc_raw
                                title_val = (row['TITLE'] or '').strip()
                                if title_val and base_upc_key not in warehouse_title_by_base:
                                    warehouse_title_by_base[base_upc_key] = title_val
                                image_val = _extract_image_url(row['IMG'])
                                if image_val and base_upc_key not in warehouse_image_by_base:
                                    warehouse_image_by_base[base_upc_key] = image_val

                                token = str(row['RID'] if row['RID'] is not None else f"{upc_raw}:{location_label}:{qty_val}")
                                token_list = warehouse_tokens_by_base.get(base_upc_key)
                                if token_list is None:
                                    token_list = []
                                    warehouse_tokens_by_base[base_upc_key] = token_list
                                if token not in token_list:
                                    token_list.append(token)
                        except Exception:
                            continue
                else:
                    print("Error reading searchRack: missing UPC/BARCODE or QUANTITY columns")
        except Exception as e:
            print(f"Error reading searchRack: {e}")

        # Raw BOL is source of truth for Store Doctor no-listing card metadata.
        try:
            warehouse_base_keys = {
                key for key in warehouse_stock_by_base.keys()
                if key and key not in invalid_upc_values
            }
            if warehouse_base_keys:
                with sqlite3.connect('rawbol.db') as rb_conn:
                    rb_conn.row_factory = sqlite3.Row
                    rb_cur = rb_conn.cursor()
                    rb_cur.execute('''
                        SELECT upc, item_description, image_url
                        FROM raw_bol_items
                        WHERE upc IS NOT NULL
                          AND TRIM(upc) != ''
                        ORDER BY COALESCE(import_date, '') DESC, rowid DESC
                    ''')
                    for row in rb_cur.fetchall():
                        upc_raw = (row['upc'] or '').strip()
                        base_upc_key = _listing_alert_base_upc_key(upc_raw)
                        if (not base_upc_key) or (base_upc_key in invalid_upc_values) or (base_upc_key not in warehouse_base_keys):
                            continue
                        if upc_raw and base_upc_key not in rawbol_display_upc_by_base:
                            rawbol_display_upc_by_base[base_upc_key] = upc_raw

                        title_val = (row['item_description'] or '').strip()
                        if title_val and base_upc_key not in rawbol_title_by_base:
                            rawbol_title_by_base[base_upc_key] = title_val

                        image_val = _extract_image_url(row['image_url'])
                        if image_val and base_upc_key not in rawbol_image_by_base:
                            rawbol_image_by_base[base_upc_key] = image_val
        except Exception as e:
            print(f"Error reading rawbol metadata for listing helper: {e}")

        # Pending sold orders (rackupdated=0) are inventory that will be auto-removed later.
        # We subtract these immediately so alerts fire right after sale sync, not 24-48h later.
        pending_sale_qty_by_upc = {}
        try:
            recent_window_days = 7
            now_utc = datetime.datetime.utcnow()
            with sqlite3.connect('sold.db') as sold_conn:
                sold_conn.row_factory = sqlite3.Row
                sold_cur = sold_conn.cursor()
                sold_cur.execute('PRAGMA table_info(orders)')
                sold_cols = {c[1].lower() for c in sold_cur.fetchall()}
                has_removal_cancelled = 'removal_cancelled' in sold_cols
                has_store = 'store' in sold_cols

                where_parts = [
                    'rackupdated = 0',
                    "barcode IS NOT NULL",
                    "TRIM(barcode) != ''"
                ]
                if has_removal_cancelled:
                    where_parts.append('COALESCE(removal_cancelled, 0) = 0')
                if has_store:
                    where_parts.append("LOWER(COALESCE(store, '')) != 'test'")

                sold_cur.execute(f'''
                    SELECT barcode, quantity, paid_time, shipped_time
                    FROM orders
                    WHERE {' AND '.join(where_parts)}
                ''')

                for row in sold_cur.fetchall():
                    ts = _parse_iso_utc(row['shipped_time']) or _parse_iso_utc(row['paid_time'])
                    if ts is not None:
                        age_days = (now_utc - ts).total_seconds() / 86400.0
                        if age_days > recent_window_days:
                            continue

                    upc_key = _match_upc_key(row['barcode'])
                    if not upc_key or upc_key in invalid_upc_values:
                        continue

                    sold_qty = _safe_int(row['quantity'], 1)
                    if sold_qty < 1:
                        sold_qty = 1
                    pending_sale_qty_by_upc[upc_key] = pending_sale_qty_by_upc.get(upc_key, 0) + sold_qty
        except Exception as e:
            print(f"Error reading pending sold orders: {e}")

        # Effective stock = physical warehouse stock minus recent pending sold qty.
        effective_stock = {}
        all_effective_upcs = set(warehouse_stock.keys()) | set(pending_sale_qty_by_upc.keys())
        for upc_key in all_effective_upcs:
            physical_qty = int(warehouse_stock.get(upc_key, 0) or 0)
            pending_qty = int(pending_sale_qty_by_upc.get(upc_key, 0) or 0)
            effective_stock[upc_key] = max(0, physical_qty - pending_qty)

        # Track effective qty transitions so no_warehouse only fires after a real >0 -> 0 transition.
        zero_triggered = {}  # upc_key -> zero_triggered_at
        try:
            now_iso = datetime.datetime.utcnow().isoformat() + 'Z'
            with sqlite3.connect('listing_alerts.db') as tracker_conn:
                tracker_conn.row_factory = sqlite3.Row
                tcur = tracker_conn.cursor()
                tcur.execute('''
                    SELECT upc, ever_in_inventory, last_qty, last_nonzero_at, zero_triggered_at
                    FROM inventory_zero_tracker
                ''')
                tracker_rows = tcur.fetchall()
                tracker_map = {}
                for row in tracker_rows:
                    key = _match_upc_key(row['upc'])
                    if key:
                        tracker_map[key] = row

                all_tracked_upcs = set(tracker_map.keys()) | set(effective_stock.keys())
                for upc_key in all_tracked_upcs:
                    physical_qty = int(warehouse_stock.get(upc_key, 0) or 0)
                    current_qty = int(effective_stock.get(upc_key, 0) or 0)
                    row = tracker_map.get(upc_key)

                    if row is None:
                        ever_in_inventory = 1 if (physical_qty > 0 or current_qty > 0) else 0
                        last_nonzero_at = now_iso if current_qty > 0 else (now_iso if physical_qty > 0 else None)
                        zero_triggered_at = None
                        tcur.execute('''
                            INSERT INTO inventory_zero_tracker (
                                upc, ever_in_inventory, last_qty, last_nonzero_at, zero_triggered_at, created_at, updated_at
                            ) VALUES (?, ?, ?, ?, ?, ?, ?)
                        ''', (
                            upc_key,
                            ever_in_inventory,
                            current_qty,
                            last_nonzero_at,
                            zero_triggered_at,
                            now_iso,
                            now_iso
                        ))
                    else:
                        prev_qty = int(row['last_qty'] or 0)
                        ever_in_inventory = int(row['ever_in_inventory'] or 0)
                        if physical_qty > 0 or current_qty > 0:
                            ever_in_inventory = 1

                        last_nonzero_at = row['last_nonzero_at']
                        zero_triggered_at = row['zero_triggered_at']

                        if current_qty > 0:
                            # Reset any previous zero event once stock is replenished.
                            last_nonzero_at = now_iso
                            zero_triggered_at = None
                        elif prev_qty > 0 and ever_in_inventory == 1:
                            # Fire only on transition from positive inventory to zero.
                            zero_triggered_at = now_iso

                        tcur.execute('''
                            UPDATE inventory_zero_tracker
                            SET ever_in_inventory = ?,
                                last_qty = ?,
                                last_nonzero_at = ?,
                                zero_triggered_at = ?,
                                updated_at = ?
                            WHERE upc = ?
                        ''', (
                            ever_in_inventory,
                            current_qty,
                            last_nonzero_at,
                            zero_triggered_at,
                            now_iso,
                            upc_key
                        ))

                    if current_qty == 0 and ever_in_inventory == 1 and zero_triggered_at:
                        zero_triggered[upc_key] = zero_triggered_at

                tracker_conn.commit()
        except Exception as e:
            print(f"Error updating inventory_zero_tracker: {e}")

        # Helper to safely get an ID from a sqlite Row
        def _row_id(row):
            if row is None:
                return None
            keys = row.keys() if hasattr(row, 'keys') else []
            if 'ID' in keys:
                return row['ID']
            if 'rowid' in keys:
                return row['rowid']
            try:
                return row[0]
            except Exception:
                return None

        # Get eBay active listings
        ebay_listings = {}  # upc -> [{id, title, qty, image}, ...]
        try:
            with sqlite3.connect('ebayStore.db') as eb_conn:
                eb_conn.row_factory = sqlite3.Row
                eb_cur = eb_conn.cursor()
                eb_cur.execute('''
                    SELECT ID, ItemID, Title, UPC, Quantity, Image, URL, List_Date
                    FROM INVENTORY
                    WHERE UPC IS NOT NULL AND UPC != ""
                      AND (Quantity > 0 OR Quantity IS NULL)
                      AND LOWER(TRIM(COALESCE(List_State, ''))) = 'active'
                      AND TRIM(COALESCE(ItemID, '')) != ''
                    ORDER BY COALESCE(List_Date, '') ASC, ID ASC
                ''')
                for row in eb_cur.fetchall():
                    if not _ebay_listing_allowed_for_alert(row['ItemID'], row['List_Date'], row['URL']):
                        continue
                    upc = (row['UPC'] or '').strip()
                    upc_key = _match_upc_key(upc)
                    if upc_key and upc_key not in invalid_upc_values:
                        if upc_key not in ebay_listings:
                            ebay_listings[upc_key] = []
                        row_id = _row_id(row)
                        listing_id = row['ItemID'] if row['ItemID'] else f"ebay_row:{row_id}"
                        ebay_listings[upc_key].append({
                            'id': row_id,
                            'listing_id': f"ebay:{listing_id}",
                            'listing_key': str(row['ItemID'] or listing_id),
                            'item_id': row['ItemID'],
                            'title': row['Title'],
                            'qty': _safe_int(row['Quantity'], 1),
                            'image': row['Image'],
                            'url': row['URL'],
                            'list_date': row['List_Date'],
                            'store': 'ebay',
                            'upc': upc
                        })
                if enable_ebay_live_check and ebay_live_filtered_item_ids:
                    ended_ids = sorted(ebay_live_filtered_item_ids)
                    chunk = 500
                    for i in range(0, len(ended_ids), chunk):
                        part = ended_ids[i:i + chunk]
                        placeholders = ','.join('?' for _ in part)
                        eb_cur.execute(f'''
                            UPDATE INVENTORY
                            SET List_State = 'Unsold'
                            WHERE ItemID IN ({placeholders})
                              AND LOWER(TRIM(COALESCE(List_State, ''))) = 'active'
                        ''', tuple(part))
        except Exception as e:
            print(f"Error reading ebayStore: {e}")

        if enable_ebay_live_check and ebay_live_cache_updates:
            try:
                with sqlite3.connect('listing_alerts.db') as cache_conn:
                    cache_cur = cache_conn.cursor()
                    cache_cur.executemany('''
                        INSERT INTO ebay_listing_health_cache (item_id, is_active, checked_at, source, note)
                        VALUES (?, ?, ?, ?, ?)
                        ON CONFLICT(item_id) DO UPDATE SET
                            is_active = excluded.is_active,
                            checked_at = excluded.checked_at,
                            source = excluded.source,
                            note = excluded.note
                    ''', [
                        (
                            row['item_id'],
                            int(row['is_active'] or 0),
                            row['checked_at'],
                            'scan',
                            row.get('note') or ''
                        )
                        for row in ebay_live_cache_updates
                    ])
                    cache_conn.commit()
            except Exception as e:
                print(f"Error writing ebay listing health cache: {e}")

        # Get Amazon active listings
        amazon_listings = {}  # upc -> [{id, title, qty, image}, ...]
        try:
            with sqlite3.connect('amazonStore.db') as am_conn:
                am_conn.row_factory = sqlite3.Row
                am_cur = am_conn.cursor()
                am_cur.execute('''
                    SELECT ID, ASIN, SKU, TITLE, UPC, QUANTITY, IMAGE
                    FROM ITEMS
                    WHERE UPC IS NOT NULL AND UPC != ""
                      AND (QUANTITY > 0 OR QUANTITY IS NULL)
                      AND LOWER(TRIM(COALESCE(STATUS, ''))) = 'active'
                      AND TRIM(COALESCE(ASIN, '')) != ''
                ''')
                for row in am_cur.fetchall():
                    upc = (row['UPC'] or '').strip()
                    upc_key = _match_upc_key(upc)
                    if upc_key and upc_key not in invalid_upc_values:
                        if upc_key not in amazon_listings:
                            amazon_listings[upc_key] = []
                        row_id = _row_id(row)
                        listing_key = row['SKU'] or row['ASIN'] or f"amazon_row:{row_id}"
                        amazon_listings[upc_key].append({
                            'id': row_id,
                            'listing_id': f"amazon:{listing_key}",
                            'listing_key': str(listing_key),
                            'sku': row['SKU'],
                            'asin': row['ASIN'],
                            'title': row['TITLE'],
                            'qty': _safe_int(row['QUANTITY'], 1),
                            'image': row['IMAGE'],
                            'store': 'amazon',
                            'upc': upc
                        })
        except Exception as e:
            print(f"Error reading amazonStore: {e}")

        # Get Facebook active listings (tracked in bol.db)
        facebook_listings = {}  # upc -> [{id, title, qty, image}, ...]
        try:
            with sqlite3.connect('bol.db') as fb_conn:
                fb_conn.row_factory = sqlite3.Row
                fb_cur = fb_conn.cursor()
                fb_cur.execute('''
                    SELECT id,
                           upc,
                           item_description AS title,
                           image_url AS image,
                           COALESCE(listed_facebook_qty, quantity, 1) AS qty
                    FROM bol_items
                    WHERE upc IS NOT NULL
                      AND TRIM(upc) != ''
                      AND (COALESCE(listed_facebook, 0) = 1 OR COALESCE(listed_facebook_qty, 0) > 0)
                ''')
                for row in fb_cur.fetchall():
                    upc = (row['upc'] or '').strip()
                    upc_key = _match_upc_key(upc)
                    if upc_key and upc_key not in invalid_upc_values:
                        if upc_key not in facebook_listings:
                            facebook_listings[upc_key] = []
                        row_id = _row_id(row)
                        listing_id = f"facebook_row:{row_id}" if row_id is not None else f"facebook_upc:{upc_key}"
                        facebook_listings[upc_key].append({
                            'id': row_id,
                            'listing_id': f"facebook:{listing_id}",
                            'listing_key': listing_id,
                            'title': row['title'],
                            'qty': _safe_int(row['qty'], 1),
                            'image': row['image'],
                            'store': 'facebook',
                            'upc': upc
                        })
        except Exception as e:
            print(f"Error reading Facebook listings from bol.db: {e}")

        # Helper to create hash for dismissal tracking
        def make_hash(alert_type, upc, listing_ids, event_token=''):
            data = f"{alert_type}:{upc.lower()}:{','.join(sorted(str(x) for x in listing_ids))}:{event_token or ''}"
            return hashlib.md5(data.encode('utf-8')).hexdigest()

        listing_match_lookup = _load_listing_inventory_match_lookup()
        for listing_map in (ebay_listings, amazon_listings, facebook_listings):
            for listed_upc_key, listing_rows in listing_map.items():
                for listing_row in listing_rows:
                    store, listing_key = _normalize_store_listing_identity(
                        listing_row.get('store'),
                        listing_row.get('listing_key') or listing_row.get('listing_id')
                    )
                    listing_row['listing_key'] = listing_key
                    saved_match = listing_match_lookup.get((store, listing_key.lower())) if store and listing_key else None
                    if saved_match:
                        listing_row['inventory_match'] = {
                            'searchrack_id': saved_match.get('searchrack_id'),
                            'barcode': saved_match.get('inventory_barcode'),
                            'location': saved_match.get('inventory_location')
                        }
                    if int(warehouse_stock.get(listed_upc_key, 0) or 0) <= 0 or saved_match:
                        alerts['listing_matches'].append(listing_row)

        alerts['listing_matches'].sort(key=lambda listing: (
            0 if listing.get('inventory_match') else 1,
            str(listing.get('store') or ''),
            str(listing.get('title') or '').lower(),
            str(listing.get('listing_key') or '').lower()
        ))

        all_upcs = set(ebay_listings.keys()) | set(amazon_listings.keys()) | set(facebook_listings.keys())
        listed_base_upcs = set()
        for listing_map in (ebay_listings, amazon_listings, facebook_listings):
            for listed_upc_key, listing_rows in listing_map.items():
                base_from_key = _listing_alert_base_upc_key(listed_upc_key)
                if base_from_key and base_from_key not in invalid_upc_values:
                    listed_base_upcs.add(base_from_key)
                for listing_row in (listing_rows or []):
                    base_from_row = _listing_alert_base_upc_key(listing_row.get('upc'))
                    if base_from_row and base_from_row not in invalid_upc_values:
                        listed_base_upcs.add(base_from_row)

        for upc_key in all_upcs:
            ebay_items = ebay_listings.get(upc_key, [])
            amazon_items = amazon_listings.get(upc_key, [])
            facebook_items = facebook_listings.get(upc_key, [])
            warehouse_qty = int(warehouse_stock.get(upc_key, 0) or 0)
            pending_sale_qty = int(pending_sale_qty_by_upc.get(upc_key, 0) or 0)
            effective_qty = int(effective_stock.get(upc_key, warehouse_qty) or 0)

            all_listings = ebay_items + amazon_items + facebook_items
            listing_ids = [l.get('listing_id') or f"{l['store']}:{l.get('id')}" for l in all_listings]

            # 1. No warehouse match
            # Gate by transition: item must have been in inventory and then hit zero.
            zero_event_token = zero_triggered.get(upc_key)
            if zero_event_token and effective_qty == 0 and all_listings:
                stores_with_listing = []
                if ebay_items:
                    stores_with_listing.append('ebay')
                if amazon_items:
                    stores_with_listing.append('amazon')
                if facebook_items:
                    stores_with_listing.append('facebook')

                snap_hash = make_hash('no_warehouse', upc_key, listing_ids, event_token=zero_event_token)
                if ('no_warehouse', snap_hash) not in dismissed:
                    # Red if 2 stores, yellow if 1
                    severity = 'red' if len(stores_with_listing) >= 2 else 'yellow'
                    alerts['no_warehouse'].append({
                        'upc': all_listings[0]['upc'],  # Use original case
                        'stores': stores_with_listing,
                        'listings': all_listings,
                        'warehouse_qty': warehouse_qty,
                        'warehouse_locations': warehouse_locations.get(upc_key, []),
                        'pending_sale_qty': pending_sale_qty,
                        'effective_qty': effective_qty,
                        'zero_triggered_at': zero_event_token,
                        'severity': severity,
                        'hash': snap_hash
                    })

            # 2. Quantity alert (per-listing quantity check)
            # Trigger only when warehouse has stock, and one listing's own qty exceeds that stock.
            # This intentionally does NOT sum listing qtys across stores.
            if warehouse_qty > 0:
                for listing in all_listings:
                    listing_qty = int(listing.get('qty') or 0)
                    if listing_qty <= warehouse_qty:
                        continue
                    listing_token = f"{listing.get('listing_id')}:{listing_qty}:warehouse={warehouse_qty}"
                    snap_hash = make_hash('quantity_alert', upc_key, [listing_token])
                    if ('quantity_alert', snap_hash) in dismissed:
                        continue

                    alerts['quantity_alert'].append({
                        'upc': listing.get('upc') or all_listings[0]['upc'],
                        'store': listing.get('store'),
                        'listing': listing,
                        'warehouse_qty': warehouse_qty,
                        'warehouse_locations': warehouse_locations.get(upc_key, []),
                        'effective_qty': effective_qty,
                        'pending_sale_qty': pending_sale_qty,
                        'listing_qty': listing_qty,
                        'overage': listing_qty - warehouse_qty,
                        'severity': 'red',
                        'hash': snap_hash
                    })

        # 3. Warehouse has stock but item is not listed on eBay/Amazon/Facebook.
        for base_upc_key, raw_qty in warehouse_stock_by_base.items():
            if not base_upc_key or base_upc_key in invalid_upc_values:
                continue
            warehouse_qty = max(0, _safe_int(raw_qty, 0))
            if warehouse_qty <= 0:
                continue
            if base_upc_key in listed_base_upcs:
                continue

            source_tokens = warehouse_tokens_by_base.get(base_upc_key) or [base_upc_key]
            snap_hash = make_hash('no_listings', base_upc_key, source_tokens)
            if ('no_listings', snap_hash) in dismissed:
                continue

            title_val = rawbol_title_by_base.get(base_upc_key) or warehouse_title_by_base.get(base_upc_key) or ''
            image_val = rawbol_image_by_base.get(base_upc_key) or warehouse_image_by_base.get(base_upc_key) or ''
            alerts['no_listings'].append({
                'upc': rawbol_display_upc_by_base.get(base_upc_key) or warehouse_display_upc_by_base.get(base_upc_key) or base_upc_key,
                'warehouse_base_upc': base_upc_key,
                'title': title_val,
                'image': image_val,
                'warehouse_qty': warehouse_qty,
                'warehouse_locations': warehouse_locations_by_base.get(base_upc_key, []),
                'severity': 'yellow',
                'hash': snap_hash
            })

        # Keep Quantity Alert cards ordered by the largest overage first.
        alerts['quantity_alert'].sort(
            key=lambda a: (
                -_safe_int(a.get('overage'), 0),
                -_safe_int(a.get('listing_qty'), 0),
                str(a.get('upc') or '').lower(),
                str((a.get('listing') or {}).get('title') or '').lower()
            )
        )
        alerts['no_listings'].sort(
            key=lambda a: (
                -_safe_int(a.get('warehouse_qty'), 0),
                str(a.get('upc') or '').lower(),
                str(a.get('title') or '').lower()
            )
        )

        # Count totals
        counts = {
            'no_warehouse': len(alerts['no_warehouse']),
            'no_listings': len(alerts['no_listings']),
            'quantity_alert': len(alerts['quantity_alert']),
            'listing_matches': len(alerts['listing_matches']),
            'sync_overdue': int((alerts['sync_overdue'][0] or {}).get('overdue_count') or 0) if alerts['sync_overdue'] else 0
        }
        counts['total'] = counts['no_warehouse'] + counts['no_listings'] + counts['quantity_alert'] + counts['sync_overdue']

        payload = {'success': True, 'alerts': alerts, 'counts': counts}
        _listing_helper_scan_cache_set(payload)
        return jsonify(payload)

    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listing-helper-scan')}), 500


@app.route('/api/listing-helper/inventory-match', methods=['POST'])
def api_listing_helper_inventory_match():
    """Persist or clear a store-listing fallback to one exact warehouse row."""
    data = request.get_json() or {}
    store, listing_key = _normalize_store_listing_identity(
        data.get('store'), data.get('listing_key') or data.get('listing_id')
    )
    if not store or not listing_key:
        return jsonify({'success': False, 'error': 'Valid store and listing key are required'}), 400

    _ensure_listing_alerts_tables()
    clear_match = bool(data.get('clear'))
    try:
        with sqlite3.connect(str(BASE_DIR / 'listing_alerts.db')) as match_conn:
            match_conn.row_factory = sqlite3.Row
            match_cur = match_conn.cursor()
            previous = match_cur.execute(
                'SELECT * FROM listing_inventory_matches WHERE store = ? AND LOWER(listing_key) = LOWER(?)',
                (store, listing_key)
            ).fetchone()

            if clear_match:
                match_cur.execute(
                    'DELETE FROM listing_inventory_matches WHERE store = ? AND LOWER(listing_key) = LOWER(?)',
                    (store, listing_key)
                )
                match_conn.commit()
                _listing_helper_scan_cache_clear()
                return jsonify({
                    'success': True,
                    'cleared': True,
                    'old_match': dict(previous) if previous else None
                })

            searchrack_id = _coerce_int(data.get('searchrack_id'), 0)
            if searchrack_id <= 0:
                return jsonify({'success': False, 'error': 'A warehouse item is required'}), 400

            with sqlite3.connect(str(BASE_DIR / 'searchRack.db')) as rack_conn:
                rack_conn.row_factory = sqlite3.Row
                rack_match = _ready_to_ship_searchrack_match_by_id(rack_conn.cursor(), searchrack_id)
            if not rack_match or _coerce_int(rack_match.get('quantity'), 0) <= 0:
                return jsonify({'success': False, 'error': 'The selected warehouse item is unavailable'}), 409

            inventory_barcode = str(rack_match.get('barcode') or '').strip()
            inventory_location = _ready_to_ship_match_display_location(rack_match)
            match_cur.execute('''
                INSERT INTO listing_inventory_matches (
                    store, listing_key, listing_id, marketplace_barcode,
                    listing_title, searchrack_id, inventory_barcode,
                    inventory_location, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                ON CONFLICT(store, listing_key) DO UPDATE SET
                    listing_id = excluded.listing_id,
                    marketplace_barcode = excluded.marketplace_barcode,
                    listing_title = excluded.listing_title,
                    searchrack_id = excluded.searchrack_id,
                    inventory_barcode = excluded.inventory_barcode,
                    inventory_location = excluded.inventory_location,
                    updated_at = CURRENT_TIMESTAMP
            ''', (
                store,
                listing_key,
                str(data.get('listing_id') or '').strip(),
                str(data.get('marketplace_barcode') or '').strip(),
                str(data.get('listing_title') or '').strip(),
                searchrack_id,
                inventory_barcode,
                inventory_location
            ))
            match_conn.commit()
            saved = match_cur.execute(
                'SELECT * FROM listing_inventory_matches WHERE store = ? AND listing_key = ?',
                (store, listing_key)
            ).fetchone()

        _listing_helper_scan_cache_clear()
        return jsonify({
            'success': True,
            'match': dict(saved) if saved else None,
            'old_match': dict(previous) if previous else None
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listing-helper:inventory-match')}), 500


@app.route('/api/listing-helper/dismiss', methods=['POST'])
def api_listing_helper_dismiss():
    """Dismiss an alert by storing its hash"""
    try:
        data = request.get_json() or {}
        alert_type = data.get('alert_type')
        snap_hash = data.get('hash')
        upc = data.get('upc', '')
        store = data.get('store', '')
        listing_ids = data.get('listing_ids', [])

        if not alert_type or not snap_hash:
            return jsonify({'success': False, 'error': 'alert_type and hash required'}), 400

        _ensure_listing_alerts_tables()
        conn = sqlite3.connect('listing_alerts.db')
        cur = conn.cursor()

        import json as json_module
        cur.execute('''
            INSERT OR REPLACE INTO dismissed_alerts (alert_type, upc, store, listing_ids, snapshot_hash)
            VALUES (?, ?, ?, ?, ?)
        ''', (alert_type, upc, store, json_module.dumps(listing_ids), snap_hash))
        conn.commit()
        conn.close()
        _listing_helper_scan_cache_clear()

        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listing-helper-dismiss')}), 500

@app.route('/api/listing-helper/undismiss', methods=['POST'])
def api_listing_helper_undismiss():
    """Remove a dismissal to re-show an alert"""
    try:
        data = request.get_json() or {}
        snap_hash = data.get('hash')

        if not snap_hash:
            return jsonify({'success': False, 'error': 'hash required'}), 400

        conn = sqlite3.connect('listing_alerts.db')
        cur = conn.cursor()
        cur.execute('DELETE FROM dismissed_alerts WHERE snapshot_hash = ?', (snap_hash,))
        conn.commit()
        conn.close()
        _listing_helper_scan_cache_clear()

        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'listing-helper-undismiss')}), 500

