@app.route('/api/amazon/orders', methods=['GET'])
def get_amazon_orders():
    """Get Amazon orders from sold.db"""
    try:
        days = int(request.args.get('days', 30))
        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Get orders from Amazon store
        cur.execute('''
            SELECT * FROM orders 
            WHERE store = 'amazon' 
            AND paid_time >= date('now', '-' || ? || ' days') 
            ORDER BY paid_time DESC
        ''', (days,))
        
        orders = cur.fetchall()
        order_payload = []
        for order in orders:
            order_dict = dict(order)
            effective_barcode = _effective_sold_order_barcode(order_dict)
            if effective_barcode:
                order_dict['stored_barcode'] = str(order_dict.get('barcode') or '').strip()
                order_dict['barcode'] = effective_barcode
            order_payload.append(order_dict)
        
        return jsonify({
            'success': True,
            'orders': order_payload
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()


@app.route('/sold-orders', methods=['GET'])
@cache.cached(timeout=300, query_string=True)  # Cache for 5 minutes based on query params (days parameter)
def sold_orders():
    days = int(request.args.get('days', 1))
    if days < 1:
        days = 1
    elif days > 120:
        days = 120
    
    # Get orders from sold.db
    sold_conn = sqlite3.connect(str(BASE_DIR / 'sold.db'), timeout=30.0)
    prepared_orders = []
    rawbol_conn = None
    try:
        sold_conn.row_factory = sqlite3.Row
        sold_cur = sold_conn.cursor()
        ensure_sold_orders_schema(sold_cur, sold_conn, default_store='ebay')
        _ensure_ready_to_ship_notes_table(sold_cur)
        # Only show orders from the last N days.
        # Keep ordering deterministic for duplicate suppression and UI stability.
        sold_cur.execute('''
            SELECT *
            FROM orders
            WHERE paid_time >= date('now', '-' || ? || ' days')
            ORDER BY paid_time DESC, id DESC
        ''', (days,))
        raw_orders = sold_cur.fetchall()

        # Defensive dedupe: intermittent sync races can leave clone rows.
        # Keep the newest row per strong content signature.
        dedupe_seen = set()
        orders = []
        duplicate_count = 0
        for order in raw_orders:
            try:
                qty_val = int(order['quantity']) if order['quantity'] is not None else 0
            except Exception:
                qty_val = 0
            try:
                price_val = float(order['price']) if order['price'] is not None else 0.0
            except Exception:
                price_val = 0.0
            signature = (
                str(order['store'] or '').strip().lower(),
                str(order['order_id'] or '').strip(),
                str(order['item_id'] or '').strip(),
                _normalize_upc(_effective_sold_order_barcode(order) or ''),
                str(order['title'] or '').strip().lower(),
                qty_val,
                round(price_val, 4),
                str(order['paid_time'] or '').strip(),
                str(order['shipped_time'] or '').strip(),
                str(order['shipping_name'] or '').strip().lower()
            )
            if signature in dedupe_seen:
                duplicate_count += 1
                continue
            dedupe_seen.add(signature)
            orders.append(order)

        if duplicate_count > 0:
            print(f"[sold_orders] Deduped {duplicate_count} transient duplicate row(s) from sold.db query")

        order_row_ids = [order['id'] for order in orders]
        note_lookup = _load_ready_to_ship_note_lookup(sold_cur, order_row_ids)
        label_lookup = _load_ready_to_ship_label_lookup(sold_cur, order_row_ids)
        finder_match_lookup = _load_order_finder_match_lookup(sold_cur, order_row_ids)
        amazon_listing_lookup = {}
        amazon_store_conn = None
        try:
            amazon_store_conn = sqlite3.connect(str(BASE_DIR / 'amazonStore.db'))
            amazon_store_conn.row_factory = sqlite3.Row
            amazon_cols = {str(row[1]).lower() for row in amazon_store_conn.execute('PRAGMA table_info(ITEMS)').fetchall()}
            condition_note_expr = 'CONDITION_NOTE' if 'condition_note' in amazon_cols else "'' AS CONDITION_NOTE"
            image_expr = 'IMAGE' if 'image' in amazon_cols else "'' AS IMAGE"
            upc_expr = 'UPC' if 'upc' in amazon_cols else "'' AS UPC"
            for listing in amazon_store_conn.execute(f'SELECT ASIN, SKU, {upc_expr}, CONDITION, {condition_note_expr}, {image_expr} FROM ITEMS'):
                payload = {
                    'condition': str(listing['CONDITION'] or '').strip(),
                    'condition_description': str(listing['CONDITION_NOTE'] or '').strip(),
                    'image': _ready_to_ship_image_value(listing['IMAGE'])
                }
                for key in (listing['ASIN'], listing['SKU'], listing['UPC']):
                    normalized_key = str(key or '').strip().lower()
                    if normalized_key:
                        amazon_listing_lookup[normalized_key] = payload
        except Exception as e:
            print(f"Warning: Could not load Amazon condition data for Ready to Ship: {e}")
        finally:
            if amazon_store_conn is not None:
                amazon_store_conn.close()
        ebay_listing_lookup = {}
        ebay_store_conn = None
        try:
            ebay_store_conn = sqlite3.connect(str(BASE_DIR / 'ebayStore.db'))
            ebay_store_conn.row_factory = sqlite3.Row
            ebay_cols = {str(row[1]).lower() for row in ebay_store_conn.execute('PRAGMA table_info(INVENTORY)').fetchall()}
            if 'condition' in ebay_cols or 'description' in ebay_cols or 'conditiondescription' in ebay_cols or 'image' in ebay_cols:
                condition_expr = 'Condition' if 'condition' in ebay_cols else "'' AS Condition"
                description_expr = 'Description' if 'description' in ebay_cols else "'' AS Description"
                condition_description_expr = 'ConditionDescription' if 'conditiondescription' in ebay_cols else "'' AS ConditionDescription"
                image_expr = 'Image' if 'image' in ebay_cols else "'' AS Image"
                upc_expr = 'UPC' if 'upc' in ebay_cols else "'' AS UPC"
                for listing in ebay_store_conn.execute(f'SELECT ItemID, SKU, {upc_expr}, {condition_expr}, {description_expr}, {condition_description_expr}, {image_expr} FROM INVENTORY'):
                    payload = {
                        'condition': str(listing['Condition'] or '').strip(),
                        'description': str(listing['Description'] or '').strip(),
                        'condition_description': str(listing['ConditionDescription'] or '').strip(),
                        'image': _ready_to_ship_image_value(listing['Image'])
                    }
                    for key in (listing['ItemID'], listing['SKU'], listing['UPC']):
                        normalized_key = str(key or '').strip().lower()
                        if normalized_key:
                            ebay_listing_lookup[normalized_key] = payload
        except Exception as e:
            print(f"Warning: Could not load eBay condition/description data for Ready to Ship: {e}")
        finally:
            if ebay_store_conn is not None:
                ebay_store_conn.close()
        rawbol_cur = None
        image_backfills = 0
        try:
            rawbol_conn = sqlite3.connect(str(BASE_DIR / 'rawbol.db'))
            rawbol_cur = rawbol_conn.cursor()
            rawbol_cur.execute('SELECT 1 FROM raw_bol_items LIMIT 1')
        except Exception as e:
            print(f"Warning: Could not open Raw BOL image fallback for Ready to Ship: {e}")
            if rawbol_conn is not None:
                rawbol_conn.close()
            rawbol_conn = None
            rawbol_cur = None
        for order in orders:
            order_dict = dict(order)
            stored_image = _ready_to_ship_image_value(order_dict.get('image'))
            if str(order_dict.get('store') or '').strip().lower() == 'amazon':
                for lookup_value in (order_dict.get('listing_asin'), order_dict.get('item_id'), order_dict.get('sku')):
                    listing = amazon_listing_lookup.get(str(lookup_value or '').strip().lower())
                    if not listing:
                        continue
                    if not str(order_dict.get('item_condition') or '').strip() and listing.get('condition'):
                        order_dict['item_condition'] = listing['condition']
                    if not str(order_dict.get('item_condition_description') or '').strip() and listing.get('condition_description'):
                        order_dict['item_condition_description'] = listing['condition_description']
                    if not _ready_to_ship_image_value(order_dict.get('image')) and listing.get('image'):
                        order_dict['image'] = listing['image']
                    break
            if not _ready_to_ship_image_value(order_dict.get('image')):
                image_lookup_values = (
                    order_dict.get('item_id'),
                    order_dict.get('sku'),
                    order_dict.get('barcode'),
                    order_dict.get('source_upc'),
                    order_dict.get('source_base_upc')
                )
                image_lookup_keys = []
                for lookup_value in image_lookup_values:
                    direct_key = str(lookup_value or '').strip().lower()
                    if direct_key and direct_key not in image_lookup_keys:
                        image_lookup_keys.append(direct_key)
                    for variant in _sold_removal_barcode_variants(lookup_value):
                        variant_key = str(variant or '').strip().lower()
                        if variant_key and variant_key not in image_lookup_keys:
                            image_lookup_keys.append(variant_key)
                for listing_lookup in (amazon_listing_lookup, ebay_listing_lookup):
                    for lookup_key in image_lookup_keys:
                        listing = listing_lookup.get(lookup_key)
                        if listing and listing.get('image'):
                            order_dict['image'] = listing['image']
                            break
                    if _ready_to_ship_image_value(order_dict.get('image')):
                        break
            if str(order_dict.get('store') or '').strip().lower() == 'ebay':
                for lookup_value in (order_dict.get('listing_listing_id'), order_dict.get('item_id'), order_dict.get('sku')):
                    listing = ebay_listing_lookup.get(str(lookup_value or '').strip().lower())
                    if not listing:
                        continue
                    if not str(order_dict.get('item_condition') or '').strip() and listing.get('condition'):
                        order_dict['item_condition'] = listing['condition']
                    if not str(order_dict.get('item_description') or '').strip() and listing.get('description'):
                        order_dict['item_description'] = listing['description']
                    if not str(order_dict.get('item_condition_description') or '').strip() and listing.get('condition_description'):
                        order_dict['item_condition_description'] = listing['condition_description']
                    if not _ready_to_ship_image_value(order_dict.get('image')) and listing.get('image'):
                        order_dict['image'] = listing['image']
                    break
            if not _ready_to_ship_image_value(order_dict.get('image')) and rawbol_cur is not None:
                fallback_image = _ready_to_ship_rawbol_image(rawbol_cur, (
                    order_dict.get('barcode'),
                    order_dict.get('source_upc'),
                    order_dict.get('source_base_upc'),
                    order_dict.get('sku')
                ))
                if fallback_image:
                    order_dict['image'] = fallback_image
            repaired_image = _ready_to_ship_image_value(order_dict.get('image'))
            if not stored_image and repaired_image:
                sold_cur.execute('''
                    UPDATE orders
                    SET image = ?
                    WHERE id = ?
                      AND LOWER(TRIM(COALESCE(image, ''))) IN (
                          '', 'nan', 'none', 'null', 'undefined', 'n/a', 'na'
                      )
                ''', (repaired_image, order_dict.get('id')))
                image_backfills += sold_cur.rowcount
            if str(order_dict.get('store') or '').strip().lower() == 'amazon':
                raw_condition = str(order_dict.get('item_condition') or '').strip()
                if raw_condition:
                    order_dict['item_condition'] = _amazon_normalize_condition_type(raw_condition, raw_condition)
            stored_location = str(order_dict.get('location') or '').strip()
            order_dict['stored_location'] = stored_location
            order_dict['location_locked'] = bool(stored_location)
            order_dict['finder_searchrack_id'] = ''
            order_dict['finder_matched_barcode'] = ''
            order_dict['finder_matched_location'] = ''
            try:
                finder_match = finder_match_lookup.get(int(order['id']))
            except Exception:
                finder_match = None
            if finder_match:
                order_dict['finder_searchrack_id'] = _coerce_int(finder_match['searchrack_id'], 0) or ''
                order_dict['finder_matched_barcode'] = str(finder_match['barcode'] or '').strip()
                order_dict['finder_matched_location'] = str(finder_match['location'] or '').strip()
            _apply_ready_to_ship_note_payload(
                order_dict,
                note_lookup.get(int(order['id'])),
                label_lookup.get(int(order['id']), [])
            )
            prepared_orders.append(order_dict)
        if rawbol_conn is not None:
            rawbol_conn.close()
            rawbol_conn = None
        if image_backfills:
            sold_conn.commit()
            print(f"[sold_orders] Repaired {image_backfills} missing image(s) from marketplace/Raw BOL data")
    finally:
        if rawbol_conn is not None:
            rawbol_conn.close()
        sold_conn.close()
    
    # Enrich with location from searchRack.db
    result = []
    rack_conn = None
    try:
        rack_conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'), timeout=30.0)
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()
        listing_inventory_match_lookup = _load_listing_inventory_match_lookup()
        
        for order_dict in prepared_orders:
            effective_barcode = _effective_sold_order_barcode(order_dict, prefer_manual_override=True)
            if effective_barcode:
                order_dict['stored_barcode'] = str(order_dict.get('barcode') or '').strip()
                order_dict['barcode'] = effective_barcode

            finder_searchrack_id = _coerce_int(order_dict.get('finder_searchrack_id'), 0)
            if finder_searchrack_id:
                try:
                    finder_match = _ready_to_ship_searchrack_match_by_id(rack_cur, finder_searchrack_id)
                    if finder_match:
                        if not str(order_dict.get('finder_matched_barcode') or '').strip():
                            order_dict['finder_matched_barcode'] = finder_match.get('barcode') or order_dict.get('barcode') or ''
                        if not str(order_dict.get('finder_matched_location') or '').strip():
                            order_dict['finder_matched_location'] = _ready_to_ship_match_display_location(finder_match)
                        if finder_match.get('warehouse_note'):
                            order_dict['warehouse_note'] = finder_match.get('warehouse_note') or ''
                        if not str(order_dict.get('stored_location') or '').strip() and order_dict.get('finder_matched_location'):
                            order_dict['stored_location'] = order_dict['finder_matched_location']
                            order_dict['location'] = order_dict['finder_matched_location']
                            order_dict['location_locked'] = True
                except Exception as e:
                    print(f"Warning: Failed to load stored Finder warehouse row for order {order_dict.get('id')}: {e}")

            if order_dict.get('location_locked') and not _coerce_int(order_dict.get('finder_searchrack_id'), 0):
                try:
                    resolved_match = _ready_to_ship_resolve_searchrack_location_match(
                        rack_cur,
                        order_dict.get('barcode') or order_dict.get('stored_barcode') or '',
                        order_dict.get('stored_location') or order_dict.get('location') or '',
                        fallback_barcodes=[
                            order_dict.get('stored_barcode') or '',
                            order_dict.get('source_upc') or '',
                            order_dict.get('sku') or ''
                        ]
                    )
                    if resolved_match:
                        order_dict['finder_searchrack_id'] = resolved_match.get('id') or ''
                        order_dict['finder_matched_barcode'] = resolved_match.get('barcode') or order_dict.get('barcode') or ''
                        if resolved_match.get('warehouse_note'):
                            order_dict['warehouse_note'] = resolved_match.get('warehouse_note') or ''
                        order_dict['finder_matched_location'] = (
                            _ready_to_ship_match_display_location(resolved_match)
                            or order_dict.get('stored_location')
                            or ''
                        )
                except Exception as e:
                    print(f"Warning: Failed to resolve Finder warehouse match for order {order_dict.get('id')}: {e}")
            
            # If location is empty and barcode exists, look it up in searchRack
            if (not order_dict.get('location') or order_dict.get('location', '').strip() == '') and order_dict.get('barcode'):
                try:
                    rack_schema = _searchrack_removal_schema(rack_cur)
                    exact_rack_rows = _searchrack_matches_for_barcode(
                        rack_cur, order_dict['barcode'], schema=rack_schema, include_zero=False
                    )
                    suffix_rack_rows = _ready_to_ship_suffix_inventory_matches(
                        rack_cur, order_dict['barcode'], schema=rack_schema
                    )
                    sold_barcode_key = _sold_removal_barcode_key(order_dict['barcode'])
                    sold_barcode_has_suffix = '-' in sold_barcode_key
                    condition_is_new = _ready_to_ship_condition_is_new(order_dict)
                    suggestion_match = False

                    if not condition_is_new and not sold_barcode_has_suffix and suffix_rack_rows:
                        rack_rows = suffix_rack_rows
                        suggestion_match = True
                    else:
                        rack_rows = exact_rack_rows

                    if not rack_rows and not suffix_rack_rows:
                        base_barcode = _barcode_base_without_suffix(order_dict['barcode'])
                        if base_barcode and _normalize_upc_preserve_suffix_for_match(base_barcode) != _normalize_upc_preserve_suffix_for_match(order_dict['barcode']):
                            rack_rows = _searchrack_matches_for_barcode(
                                rack_cur, base_barcode, schema=rack_schema, include_zero=False
                            )
                    if not rack_rows and suffix_rack_rows:
                        rack_rows = suffix_rack_rows
                        suggestion_match = True
                    
                    if rack_rows:
                        rack_rows = _ready_to_ship_rank_inventory_matches(rack_rows, order_dict)
                        preferred_match = rack_rows[0]
                        preferred_barcode = preferred_match.get('barcode') or order_dict.get('barcode') or ''
                        order_dict['location_match_suggested'] = bool(suggestion_match)
                        order_dict['location_match_barcode'] = preferred_barcode
                        order_dict['suffix_variations'] = _ready_to_ship_suffix_alternatives(
                            suffix_rack_rows, preferred_barcode
                        )
                        preferred_barcode_key = _sold_removal_barcode_key(preferred_barcode)
                        rack_rows = [
                            match for match in rack_rows
                            if _sold_removal_barcode_key(match.get('barcode')) == preferred_barcode_key
                        ]
                        order_dict['finder_searchrack_id'] = preferred_match.get('id') or ''
                        order_dict['finder_matched_barcode'] = preferred_barcode
                        order_dict['finder_matched_location'] = _ready_to_ship_match_display_location(preferred_match)
                        if preferred_match.get('warehouse_note'):
                            order_dict['warehouse_note'] = preferred_match.get('warehouse_note') or ''
                        # Collect all locations for this barcode
                        locations = []
                        for rack_row in rack_rows:
                            loc = rack_row.get('item_position') or rack_row.get('pictureposition')
                            if loc:
                                locations.append({
                                    'code': loc,
                                    'image': rack_row.get('pictureposition') if rack_row.get('pictureposition') and str(rack_row.get('pictureposition')).strip() else loc,
                                    'quantity': rack_row.get('quantity') if rack_row.get('quantity') else 1,
                                    'warehouse_note': rack_row.get('warehouse_note') or ''
                                })
                        
                        # Store as JSON array if multiple locations, or single string for backward compatibility
                        if len(locations) > 1:
                            order_dict['locations'] = locations  # Array of location objects
                            order_dict['location'] = locations[0]['code']  # First location for backward compatibility
                        elif len(locations) == 1:
                            order_dict['location'] = locations[0]['code']
                            order_dict['location_image'] = locations[0]['image']
                            order_dict['warehouse_note'] = locations[0].get('warehouse_note') or ''
                except sqlite3.Error as e:
                    # If searchRack query fails, just skip location lookup for this order
                    print(f"Warning: Failed to lookup location for barcode {order_dict['barcode']}: {e}")

            # Store-listing Finder mappings are intentionally a fallback: only
            # use one when the marketplace barcode produced no live location.
            if not str(order_dict.get('location') or '').strip():
                listing_mapping = _listing_inventory_match_for_order(
                    order_dict, listing_inventory_match_lookup
                )
                if listing_mapping:
                    try:
                        mapped_match = _ready_to_ship_searchrack_match_by_id(
                            rack_cur, listing_mapping.get('searchrack_id')
                        )
                        if mapped_match and _coerce_int(mapped_match.get('quantity'), 0) > 0:
                            mapped_location = _ready_to_ship_match_display_location(mapped_match)
                            mapped_barcode = str(mapped_match.get('barcode') or '').strip()
                            if mapped_location and mapped_barcode:
                                order_dict['location'] = mapped_location
                                order_dict['location_image'] = (
                                    mapped_match.get('pictureposition') or mapped_location
                                )
                                order_dict['warehouse_note'] = mapped_match.get('warehouse_note') or ''
                                order_dict['finder_searchrack_id'] = mapped_match.get('id') or ''
                                order_dict['finder_matched_barcode'] = mapped_barcode
                                order_dict['finder_matched_location'] = mapped_location
                                order_dict['location_match_suggested'] = True
                                order_dict['location_match_barcode'] = mapped_barcode
                                order_dict['location_match_source'] = 'store_listing_fallback'
                                order_dict['listing_inventory_match_id'] = listing_mapping.get('id') or ''
                    except Exception as mapping_error:
                        print(
                            f"Warning: Store-listing fallback failed for sold order "
                            f"{order_dict.get('id')}: {mapping_error}"
                        )

            # If still no location, flag for manual search via Finder page
            if not order_dict.get('location') or order_dict.get('location', '').strip() == '':
                if order_dict.get('title'):
                    order_dict['location_search'] = order_dict['title']

            result.append(order_dict)
        
    except Exception as e:
        # If searchRack.db is unavailable, return orders without location enrichment
        print(f"Warning: searchRack.db unavailable, skipping location lookup: {e}")
        result = prepared_orders
    finally:
        try:
            if rack_conn is not None:
                rack_conn.close()
        except Exception:
            pass

    return jsonify(result)

_READY_TO_SHIP_CACHE_DAYS = (1, 2, 3, 5, 7, 14, 30, 60, 90, 120)


def _invalidate_ready_to_ship_cache(day_values=None):
    values = tuple(day_values or _READY_TO_SHIP_CACHE_DAYS)
    for days in values:
        try:
            cache.delete(f'view//sold-orders?days={days}')
        except Exception:
            pass
        try:
            cache.delete(f'view//api/ready-to-ship/count?days={days}')
        except Exception:
            pass


@app.route('/api/ready-to-ship/clear-location/<int:order_id>', methods=['POST'])
def ready_to_ship_clear_location(order_id):
    """Clear a Finder-locked Ready to Ship location without changing the barcode."""
    conn = None
    try:
        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_order_removal_allocations_table(cur)
        _ensure_order_finder_matches_table(cur)
        cur.execute(
            'SELECT id, order_id, location, rackupdated, isHandled FROM orders WHERE id = ?',
            (order_id,)
        )
        order = cur.fetchone()
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        is_handled = str(order['isHandled'] or '').strip() == '1'
        rackupdated = _coerce_int(order['rackupdated'], 0)
        if is_handled or rackupdated == 1:
            return jsonify({
                'success': False,
                'error': 'This order is already completed; its location cannot be cleared here.'
            }), 409

        old_location = str(order['location'] or '').strip()
        cur.execute('UPDATE orders SET location = ? WHERE id = ?', ('', order_id))
        cur.execute('DELETE FROM order_removal_allocations WHERE order_row_id = ?', (order_id,))
        cur.execute('DELETE FROM order_finder_matches WHERE order_row_id = ?', (order_id,))
        conn.commit()
        _invalidate_ready_to_ship_cache()

        return jsonify({
            'success': True,
            'order_id': order_id,
            'old_location': old_location,
            'new_location': ''
        })
    except Exception as e:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass


def _ready_to_ship_poll_state(days):
    conn = sqlite3.connect(str(BASE_DIR / 'sold.db'), timeout=30.0)
    try:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        ensure_sold_orders_schema(cur, conn, default_store='ebay')
        _ensure_ready_to_ship_notes_table(cur)
        cur.execute('''
            SELECT id,
                   COALESCE(TRIM(isHandled), '') AS isHandled,
                   COALESCE(rackupdated, 0) AS rackupdated,
                   COALESCE(barcode, '') AS barcode,
                   COALESCE(location, '') AS location,
                   COALESCE(isHandledDate, '') AS isHandledDate,
                   COALESCE(paid_time, '') AS paid_time,
                   COALESCE(shipped_time, '') AS shipped_time
            FROM orders
            WHERE paid_time >= date('now', '-' || ? || ' days')
            ORDER BY id DESC
        ''', (days,))
        rows = cur.fetchall()
        note_lookup = _load_ready_to_ship_note_lookup(cur, [row['id'] for row in rows])
        label_lookup = _load_ready_to_ship_label_lookup(cur, [row['id'] for row in rows])

        pending_count = 0
        digest = hashlib.sha1()
        for row in rows:
            is_handled = str(row['isHandled'] or '').strip() == '1'
            if not is_handled:
                pending_count += 1
            note_row = note_lookup.get(int(row['id']))
            label_rows = label_lookup.get(int(row['id']), [])
            note_payload = _ready_to_ship_note_payload(note_row, label_rows)
            label_digest = '|'.join(
                f"{str(label.get('label_id') or label.get('id') or '').strip()}:{str(label.get('label_filename') or '').strip()}:{str(label.get('label_uploaded_at') or '').strip()}"
                for label in (note_payload.get('ready_to_ship_labels') or [])
            )
            digest.update(
                (
                    f"{int(row['id'] or 0)}|"
                    f"{1 if is_handled else 0}|"
                    f"{int(row['rackupdated'] or 0)}|"
                    f"{str(row['barcode'] or '').strip()}|"
                    f"{str(row['location'] or '').strip()}|"
                    f"{str(row['isHandledDate'] or '').strip()}|"
                    f"{str(row['paid_time'] or '').strip()}|"
                    f"{str(row['shipped_time'] or '').strip()}|"
                    f"{str(note_payload['ready_to_ship_note'] or '').strip()}|"
                    f"{str(note_payload['ready_to_ship_note_updated_at'] or '').strip()}|"
                    f"{str(note_payload.get('ready_to_ship_label_filename') or '').strip()}|"
                    f"{str(note_payload.get('ready_to_ship_label_uploaded_at') or '').strip()}|"
                    f"{int(note_payload.get('ready_to_ship_label_count') or 0)}|"
                    f"{label_digest}\n"
                ).encode('utf-8', errors='ignore')
            )

        return {
            'count': pending_count,
            'total': len(rows),
            'version': digest.hexdigest(),
        }
    finally:
        conn.close()


@app.route('/api/ready-to-ship/count', methods=['GET'])
def ready_to_ship_count():
    """Return pending count plus a lightweight version fingerprint for cross-session refresh."""
    days = int(request.args.get('days', 2))
    if days < 1:
        days = 1
    elif days > 120:
        days = 120
    try:
        state = _ready_to_ship_poll_state(days)
        return jsonify({'success': True, 'count': state['count'], 'total': state['total'], 'version': state['version'], 'days': days})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'ready_to_ship:count')}), 500


@app.route('/get-order', methods=['GET'])
def get_order():
    order_id = request.args.get('id')
    if not order_id:
        return jsonify({'error': 'Missing order id'}), 400
    conn = None
    try:
        conn = sqlite3.connect(str(BASE_DIR / 'sold.db'), timeout=30.0)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        ensure_sold_orders_schema(cur, conn, default_store='ebay')
        _ensure_ready_to_ship_notes_table(cur)
        cur.execute("SELECT * FROM orders WHERE id = ?", (order_id,))
        order = cur.fetchone()
        
        if not order:
            return jsonify({'error': 'Order not found'}), 404
            
        # Convert sqlite3.Row to dict
        order_dict = dict(order)
        note_lookup = _load_ready_to_ship_note_lookup(cur, [order_id])
        label_lookup = _load_ready_to_ship_label_lookup(cur, [order_id])
        _apply_ready_to_ship_note_payload(order_dict, note_lookup.get(int(order['id'])), label_lookup.get(int(order['id']), []))
        effective_barcode = _effective_sold_order_barcode(order_dict, prefer_manual_override=True)
        if effective_barcode:
            order_dict['stored_barcode'] = str(order_dict.get('barcode') or '').strip()
            order_dict['barcode'] = effective_barcode
        return jsonify(order_dict)
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass

@app.route('/api/ready-to-ship/note/<int:order_id>', methods=['POST'])
def ready_to_ship_save_note(order_id):
    conn = None
    try:
        data = request.get_json(silent=True) or {}
        raw_note = str(data.get('note') or '')
        note = raw_note.replace('\r\n', '\n').replace('\r', '\n').strip()
        if len(note) > 2000:
            return jsonify({'success': False, 'error': 'Note is too long (max 2000 characters).'}), 400

        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_ready_to_ship_notes_table(cur)
        _ensure_ready_to_ship_order_labels_table(cur)

        order = cur.execute('SELECT id FROM orders WHERE id = ?', (order_id,)).fetchone()
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        existing = cur.execute('SELECT * FROM ready_to_ship_notes WHERE order_row_id = ?', (order_id,)).fetchone()
        if note:
            if existing:
                cur.execute('''
                    UPDATE ready_to_ship_notes
                    SET note = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE order_row_id = ?
                ''', (note, order_id))
            else:
                cur.execute('''
                    INSERT INTO ready_to_ship_notes (order_row_id, note)
                    VALUES (?, ?)
                ''', (order_id, note))
        else:
            label_count_row = cur.execute(
                "SELECT COUNT(*) AS c FROM ready_to_ship_order_labels WHERE order_row_id = ? AND COALESCE(TRIM(label_filename), '') <> ''",
                (order_id,)
            ).fetchone()
            label_count = int(_ready_to_ship_row_value(label_count_row, 'c', 0) or 0)
            if existing and (str(_ready_to_ship_row_value(existing, 'label_filename', '') or '').strip() or label_count > 0):
                cur.execute('''
                    UPDATE ready_to_ship_notes
                    SET note = '', updated_at = CURRENT_TIMESTAMP
                    WHERE order_row_id = ?
                ''', (order_id,))
            else:
                cur.execute('DELETE FROM ready_to_ship_notes WHERE order_row_id = ?', (order_id,))

        conn.commit()

        _invalidate_ready_to_ship_cache()

        payload = _ready_to_ship_payload_for_order(cur, order_id)
        payload['success'] = True
        return jsonify(payload)
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'ready_to_ship:note')}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass

@app.route('/api/ready-to-ship/label/<int:order_id>', methods=['POST'])
def ready_to_ship_upload_label(order_id):
    conn = None
    saved_filename = ''
    try:
        file_storage = request.files.get('label') or request.files.get('file')
        if not file_storage:
            return jsonify({'success': False, 'error': 'PDF label file is required.'}), 400

        saved_filename, original_name, size_bytes, pdf_path = _ready_to_ship_save_uploaded_label_file(file_storage)

        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_ready_to_ship_notes_table(cur)

        order = cur.execute('SELECT id FROM orders WHERE id = ?', (order_id,)).fetchone()
        if not order:
            _ready_to_ship_delete_label_file(saved_filename)
            saved_filename = ''
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        _ready_to_ship_attach_label(cur, order_id, saved_filename, original_name, size_bytes)
        conn.commit()
        _invalidate_ready_to_ship_cache()

        payload = _ready_to_ship_payload_for_order(cur, order_id)
        payload['success'] = True
        payload['order_id'] = order_id
        return jsonify(payload)
    except ValueError as e:
        if saved_filename:
            _ready_to_ship_delete_label_file(saved_filename)
        return jsonify({'success': False, 'error': str(e)}), 400
    except Exception as e:
        if saved_filename:
            _ready_to_ship_delete_label_file(saved_filename)
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'error': _safe_error(e, 'ready_to_ship:label_upload')}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass

@app.route('/api/ready-to-ship/labels/upload', methods=['POST'])
def ready_to_ship_upload_labels_bulk():
    conn = None
    try:
        files = request.files.getlist('labels') or request.files.getlist('label') or request.files.getlist('file')
        if not files:
            return jsonify({'success': False, 'error': 'Drop at least one PDF label file.'}), 400

        try:
            days = max(1, min(int(request.form.get('days') or 2), 120))
        except Exception:
            days = 2

        conn = sqlite3.connect('sold.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        _ensure_ready_to_ship_notes_table(cur)
        _ensure_ready_to_ship_unmatched_labels_table(cur)

        results = []
        for file_storage in files:
            saved_filename = ''
            original_name = file_storage.filename or 'label.pdf'
            try:
                saved_filename, safe_original, size_bytes, pdf_path = _ready_to_ship_save_uploaded_label_file(file_storage)
                extracted_text = _ready_to_ship_extract_pdf_text(pdf_path)
                match = _ready_to_ship_find_label_match(cur, f"{extracted_text}\n{safe_original}", days=days)
                if not match:
                    unmatched_row = _ready_to_ship_insert_unmatched_label(
                        cur,
                        saved_filename,
                        safe_original,
                        size_bytes,
                        extracted_text,
                        'No address match found'
                    )
                    unmatched_payload = _ready_to_ship_unmatched_label_payload(unmatched_row)
                    saved_filename = ''
                    results.append({
                        'success': True,
                        'matched': False,
                        'saved': True,
                        'filename': original_name,
                        'error': 'No address match found; saved for manual printing.',
                        **unmatched_payload
                    })
                    continue

                order_row = match['order']
                order_id = int(order_row['id'])
                _ready_to_ship_attach_label(cur, order_id, saved_filename, safe_original, size_bytes)
                payload = _ready_to_ship_payload_for_order(cur, order_id)
                payload.update({
                    'success': True,
                    'matched': True,
                    'order_id': order_id,
                    'order_ref': str(_ready_to_ship_row_value(order_row, 'order_id', '') or ''),
                    'title': str(_ready_to_ship_row_value(order_row, 'title', '') or ''),
                    'shipping_name': str(_ready_to_ship_row_value(order_row, 'shipping_name', '') or ''),
                    'score': match['score'],
                    'reasons': match['reasons'],
                    'filename': safe_original
                })
                results.append(payload)
            except ValueError as e:
                if saved_filename:
                    _ready_to_ship_delete_label_file(saved_filename)
                results.append({
                    'success': False,
                    'matched': False,
                    'filename': original_name,
                    'error': str(e)
                })
            except Exception as e:
                if saved_filename:
                    _ready_to_ship_delete_label_file(saved_filename)
                results.append({
                    'success': False,
                    'matched': False,
                    'filename': original_name,
                    'error': _safe_error(e, 'ready_to_ship:label_bulk_file')
                })

        conn.commit()
        _invalidate_ready_to_ship_cache()
        return jsonify({
            'success': True,
            'results': results,
            'matched_count': sum(1 for r in results if r.get('matched')),
            'unmatched_count': sum(1 for r in results if not r.get('matched'))
        })
    except Exception as e:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'error': _safe_error(e, 'ready_to_ship:labels_upload')}), 500
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass

