@app.route('/api/ready-to-ship/location-options/<int:order_id>', methods=['GET'])
def ready_to_ship_location_options(order_id):
    sold_conn = None
    rack_conn = None
    try:
        sold_conn = sqlite3.connect('sold.db')
        sold_conn.row_factory = sqlite3.Row
        sold_cur = sold_conn.cursor()
        _ensure_order_removal_allocations_table(sold_cur)

        sold_cur.execute('''
            SELECT id, order_id, item_id, sku, store, barcode, source_upc,
                   quantity, title, location, listing_listing_id, listing_sku,
                   listing_asin
            FROM orders WHERE id = ?
        ''', (order_id,))
        order = sold_cur.fetchone()
        if not order:
            return jsonify({'success': False, 'error': 'Order not found'}), 404

        barcode = _effective_sold_order_barcode(order, prefer_manual_override=True)
        suggested_barcode = str(request.args.get('matched_barcode') or '').strip()
        valid_fallback_barcode = (
            suggested_barcode
            if _ready_to_ship_valid_requested_match(order, suggested_barcode)
            else ''
        )
        sold_qty = max(1, _coerce_int(order['quantity'], 1))
        existing_allocations = _load_order_removal_allocations(sold_cur, order_id)

        if not barcode:
            return jsonify({
                'success': True,
                'order_id': order_id,
                'barcode': '',
                'quantity': sold_qty,
                'needs_choice': False,
                'locations': [],
                'existing_allocations': existing_allocations,
                'total_available': 0,
                'can_fulfill': False
            })

        rack_conn = sqlite3.connect('searchRack.db')
        rack_conn.row_factory = sqlite3.Row
        rack_cur = rack_conn.cursor()

        raw_stored_barcode = str(order['barcode'] or '').strip()
        fallback_barcodes = []
        if raw_stored_barcode and raw_stored_barcode != barcode:
            fallback_barcodes.append(raw_stored_barcode)

        matches = _searchrack_matches_for_removal_context(
            rack_cur,
            barcode,
            fallback_barcodes=fallback_barcodes,
            preferred_location=str(order['location'] or '').strip()
        )
        if not matches and valid_fallback_barcode:
            barcode = valid_fallback_barcode
            matches = _searchrack_matches_for_removal_context(
                rack_cur,
                barcode,
                preferred_location=str(order['location'] or '').strip()
            )

        location_groups = _group_searchrack_matches_by_location(matches)
        locations = [
            {
                'location_key': g['location_key'],
                'location_code': g['location_code'],
                'available_qty': max(0, _coerce_int(g['available_qty'], 0)),
                'preview_key': g['preview_key']
            }
            for g in location_groups
        ]
        total_available = sum(max(0, _coerce_int(x['available_qty'], 0)) for x in locations)

        return jsonify({
            'success': True,
            'order_id': order_id,
            'order_ref': order['order_id'],
            'title': order['title'],
            'barcode': barcode,
            'quantity': sold_qty,
            'needs_choice': len(locations) > 1,
            'locations': locations,
            'existing_allocations': existing_allocations,
            'total_available': total_available,
            'can_fulfill': total_available >= sold_qty
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if sold_conn is not None:
                sold_conn.close()
        except Exception:
            pass
        try:
            if rack_conn is not None:
                rack_conn.close()
        except Exception:
            pass

