@app.route('/api/finder/remove', methods=['POST'])
def api_finder_remove():
    """Remove 1 (or sold qty) from inventory for a specific searchRack row."""
    import datetime as _dt
    data = request.get_json() or {}
    searchrack_id = data.get('searchrack_id')
    order_id = data.get('order_id')  # optional — sold order context
    qty_to_remove = _strict_inventory_quantity(data.get('qty', 1))
    if qty_to_remove is None:
        return jsonify({'ok': False, 'error': 'Invalid quantity'}), 400
    if not searchrack_id:
        return jsonify({'ok': False, 'error': 'Missing searchrack_id'}), 400
    if qty_to_remove <= 0:
        return jsonify({'ok': False, 'error': 'Quantity must be positive'}), 400
    if order_id:
        return jsonify({
            'ok': False,
            'error': 'Finder cannot remove sold-order inventory directly anymore. Match the item here if needed, then confirm it from Ready to Ship.',
            'manual_mode': True,
            'redirect_url': '/ready_to_ship'
        }), 409
    try:
        r_conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'))
        r_conn.row_factory = sqlite3.Row
        r_cur = r_conn.cursor()
        r_cur.execute('SELECT ID, TITLE, BARCODE, QUANTITY, ITEM_POSITION FROM SEARCHRACK WHERE ID = ?', (searchrack_id,))
        row = r_cur.fetchone()
        if not row:
            r_conn.close()
            return jsonify({'ok': False, 'error': 'Item not found'}), 404
        current_qty = int(row['QUANTITY'] or 0)
        if current_qty <= 0:
            r_conn.close()
            return jsonify({'ok': False, 'error': 'Item has no active inventory'}), 409
        if qty_to_remove > current_qty:
            r_conn.close()
            return jsonify({
                'ok': False,
                'error': f'Only {current_qty} unit(s) are available at this location'
            }), 409
        new_qty = max(0, current_qty - qty_to_remove)
        r_cur.execute('UPDATE SEARCHRACK SET QUANTITY = ? WHERE ID = ?', (new_qty, searchrack_id))
        r_conn.commit()

        # The SEARCHRACK trigger already made a durable same-transaction snapshot.
        # Add the legacy breadcrumb best-effort; a failure here must not invite a second removal.
        rem_conn = None
        try:
            rem_conn = sqlite3.connect(str(BASE_DIR / 'rackhistory.db'))
            rem_cur = rem_conn.cursor()
            _ensure_removed_items_table(rem_cur)
            _ensure_legacy_removed_table(rem_cur)
            removed_at = _dt.datetime.now().isoformat()
            rem_cur.execute('''
                INSERT INTO removed_items
                (order_id, barcode, title, quantity_removed, removed_at, searchrack_id,
                 old_quantity, new_quantity, removal_type, item_position, event_status)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')
            ''', (
                order_id or '', row['BARCODE'] or '', row['TITLE'] or '', qty_to_remove,
                removed_at, searchrack_id, current_qty, new_qty, 'finder_removal', row['ITEM_POSITION']
            ))
            detail_history_id = rem_cur.lastrowid
            rem_cur.execute('''
                INSERT INTO removed (
                    name, barcode, qty, time_removed, detail_history_id, source_location
                ) VALUES (?, ?, ?, ?, ?, ?)
            ''', (
                row['TITLE'] or '', row['BARCODE'] or '', qty_to_remove, removed_at,
                detail_history_id, row['ITEM_POSITION'] or ''
            ))
            rem_conn.commit()
        except Exception as history_error:
            try:
                if rem_conn is not None:
                    rem_conn.rollback()
            except Exception:
                pass
            logger.warning('Finder removal history breadcrumb deferred: %s', history_error)
        finally:
            try:
                if rem_conn is not None:
                    rem_conn.close()
            except Exception:
                pass

        # If order context, mark order as rackupdated
        if order_id:
            s_conn = sqlite3.connect(str(BASE_DIR / 'sold.db'))
            s_cur = s_conn.cursor()
            s_cur.execute('UPDATE orders SET rackupdated = 1 WHERE id = ?', (order_id,))
            s_conn.commit()
            s_conn.close()

        r_conn.close()
        return jsonify({'ok': True, 'new_qty': new_qty, 'old_qty': current_qty, 'searchrack_id': searchrack_id, 'order_id': order_id or None})
    except Exception as e:
        return jsonify({'ok': False, 'error': _safe_error(e)}), 500

@app.route('/api/finder/undo-remove', methods=['POST'])
def api_finder_undo_remove():
    """Undo a finder removal, recreating a deleted terminal row from its snapshot."""
    data = request.get_json() or {}
    searchrack_id = data.get('searchrack_id')
    order_id = data.get('order_id')
    if not searchrack_id:
        return jsonify({'ok': False, 'error': 'Missing searchrack_id'}), 400

    r_conn = None
    h_conn = None
    s_conn = None
    try:
        _flush_searchrack_history_outbox()
        h_conn = sqlite3.connect(str(BASE_DIR / 'rackhistory.db'))
        h_conn.row_factory = sqlite3.Row
        h_cur = h_conn.cursor()
        _ensure_removed_items_table(h_cur)
        h_cur.execute('''
            SELECT * FROM removed_items
            WHERE searchrack_id = ?
              AND removal_type IN ('finder_removal', 'inventory_depleted')
              AND (undone_at IS NULL OR undone_at = '')
              AND COALESCE(event_status, 'applied') = 'applied'
            ORDER BY id DESC
            LIMIT 1
        ''', (int(searchrack_id),))
        history_row = h_cur.fetchone()
        if not history_row:
            return jsonify({'ok': False, 'error': 'Finder removal history was not found; inventory was not changed'}), 409
        restore_quantity = _history_restore_quantity(history_row)
        if restore_quantity <= 0:
            return jsonify({'ok': False, 'error': 'Finder history has no quantity to restore'}), 409

        r_conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'))
        r_conn.row_factory = sqlite3.Row
        r_cur = r_conn.cursor()
        _ensure_searchrack_undo_claims(r_cur)
        r_conn.commit()
        r_cur.execute('BEGIN IMMEDIATE')
        restored = _restore_searchrack_with_undo_claim(r_cur, history_row, restore_quantity)
        r_conn.commit()

        now_iso = datetime.datetime.now().isoformat()
        h_cur.execute(
            'UPDATE removed_items SET undone_at = ? WHERE id = ? AND (undone_at IS NULL OR undone_at = "")',
            (now_iso, history_row['id'])
        )
        _insert_inventory_undo_history(
            h_cur,
            history_row,
            restored,
            'finder_removal_undo',
            order_id=order_id or None,
            undone_at=now_iso,
        )
        h_conn.commit()

        if order_id:
            s_conn = sqlite3.connect(str(BASE_DIR / 'sold.db'))
            s_cur = s_conn.cursor()
            s_cur.execute('UPDATE orders SET rackupdated = 0 WHERE id = ?', (order_id,))
            s_conn.commit()

        return jsonify({
            'ok': True,
            'restored_qty': restored['new_quantity'],
            'restored_units': restored['restore_quantity'],
            'searchrack_id': restored['searchrack_id'],
            'recreated': restored['recreated']
        })
    except Exception as e:
        for connection in (s_conn, h_conn, r_conn):
            try:
                if connection is not None:
                    connection.rollback()
            except Exception:
                pass
        return jsonify({'ok': False, 'error': _safe_error(e)}), 500
    finally:
        for connection in (s_conn, h_conn, r_conn):
            try:
                if connection is not None:
                    connection.close()
            except Exception:
                pass

@app.route('/cleanup')
def cleanup_page():
    response = make_response(render_template('cleanup.html'))
    response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
    response.headers['Pragma'] = 'no-cache'
    response.headers['Expires'] = '0'
    return response

@app.route('/unified-search')
def unified_search_page():
    """Unified search page that searches across all databases"""
    return render_template('unified_search.html')

@app.route('/searchrack_api')
def searchrack_api():
    q = request.args.get('q', '').strip()
    # Strip leading zeros from barcode searches
    q_stripped = _strip_leading_zeros_numeric(q)
    results = []
    if q_stripped:
        conn = sqlite3.connect('searchRack.db')
        try:
            cur = conn.cursor()
            tokens = []
            seen_tokens = set()
            for part in q_stripped.split():
                token = str(part or '').strip()
                if not token:
                    continue
                token_key = token.lower()
                if token_key in seen_tokens:
                    continue
                seen_tokens.add(token_key)
                tokens.append(token)
            if not tokens:
                tokens = [q_stripped]

            title_sql = ' AND '.join(['TITLE LIKE ? COLLATE NOCASE' for _ in tokens])
            barcode_sql = ' OR '.join(['BARCODE LIKE ? COLLATE NOCASE' for _ in tokens])
            position_sql = ' OR '.join([
                'ITEM_POSITION LIKE ? COLLATE NOCASE',
                'PICTUREPOSITION LIKE ? COLLATE NOCASE'
            ])
            params = tuple(
                [f'%{token}%' for token in tokens]
                + [f'%{token}%' for token in tokens]
                + [f'%{q_stripped}%'] * 2
            )

            cur.execute("PRAGMA table_info(SEARCHRACK)")
            searchrack_cols = [r[1] for r in cur.fetchall()]
            note_expr = 'WAREHOUSE_NOTE' if 'WAREHOUSE_NOTE' in searchrack_cols else "'' AS WAREHOUSE_NOTE"
            cur.execute(f'''
                SELECT TITLE, BARCODE, ITEM_POSITION, IMAGES, PICTUREPOSITION, QUANTITY, IMAGE, ITEMID, {note_expr}
                FROM SEARCHRACK
                WHERE (({title_sql}) OR ({barcode_sql}) OR ({position_sql}))
                  AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
            ''', params)
            for row in cur.fetchall():
                results.append({
                    'title': row[0],
                    'barcode': row[1],
                    'item_position': row[2],
                    'images': row[3],
                    'pictureposition': row[4],
                    'quantity': row[5],
                    'image': row[6],
                    'itemid': row[7],
                    'warehouse_note': row[8],
                })
        finally:
            conn.close()
        # Merge results that share same barcode + item_position by summing quantities
        merged = {}
        for r in results:
            bc = (r.get('barcode') or '').strip()
            pos = (r.get('item_position') or '').strip()
            # only merge when barcode present
            if not bc:
                # use a unique key to preserve as-is
                key = f"__{id(r)}"
            else:
                key = f"{bc.lower()}||{pos.lower()}"
            if key not in merged:
                # initialize quantity from database value
                merged[key] = r.copy()
                # Properly handle quantity: use value from DB if present, otherwise default to 1
                qty_val = r.get('quantity')
                if qty_val is not None:
                    try:
                        merged[key]['quantity'] = int(qty_val)
                    except (ValueError, TypeError):
                        merged[key]['quantity'] = 1
                else:
                    merged[key]['quantity'] = 1
            else:
                # sum quantities from duplicate rows
                qty_val = r.get('quantity')
                if qty_val is not None:
                    try:
                        add_q = int(qty_val)
                    except (ValueError, TypeError):
                        add_q = 1
                else:
                    add_q = 1
                merged[key]['quantity'] = merged[key].get('quantity', 0) + add_q
        # convert merged back to list
        results = list(merged.values())
    return jsonify({'results': results})

@app.route('/searchbol_api')
def searchbol_api():
    q = request.args.get('q', '').strip()
    # Strip leading zeros from barcode searches
    q_stripped = _strip_leading_zeros_numeric(q)
    results = []
    if q_stripped:
        conn = sqlite3.connect('rawbol.db')
        try:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute('''
            SELECT item_description as description, upc, avg_cost, 
                   lot_number, bol_location, quantity
            FROM raw_bol_items 
            WHERE item_description LIKE ? OR upc LIKE ? OR lot_number LIKE ? OR bol_location LIKE ?
        ''', (f'%{q_stripped}%', f'%{q_stripped}%', f'%{q_stripped}%', f'%{q_stripped}%'))
            results = [dict(row) for row in cur.fetchall()]
        finally:
            conn.close()
    return jsonify({'results': results})

@app.route('/view_all/<db_type>')
def view_all(db_type):
    if db_type == 'rack':
        conn = sqlite3.connect('searchRack.db')
        try:
            cur = conn.cursor()
            cur.execute('SELECT * FROM SEARCHRACK WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0')
            columns = [desc[0] for desc in cur.description]
            items = [dict(zip(columns, row)) for row in cur.fetchall()]
            title = 'All Inventory Items'
        finally:
            conn.close()
    elif db_type == 'bol':
        conn = sqlite3.connect('rawbol.db')
        try:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute('SELECT * FROM raw_bol_items')
            items = [dict(row) for row in cur.fetchall()]
            title = 'All BOL Items'
        finally:
            conn.close()
    else:
        return 'Invalid database type', 400
    
    return render_template('view_all.html', items=items, title=title, db_type=db_type)

@app.route('/update_item/<db_type>/<int:item_id>', methods=['POST'])
def update_item(db_type, item_id):
    if db_type not in ['rack', 'bol']:
        return jsonify({'success': False, 'error': 'Invalid database type'}), 400
    
    data = request.get_json()
    if not data:
        return jsonify({'success': False, 'error': 'No data provided'}), 400
    
    try:
        if db_type == 'rack':
            conn = sqlite3.connect('searchRack.db')
        else:  # bol
            conn = sqlite3.connect('rawbol.db')
        
        cur = conn.cursor()
        
        # Get column names to validate fields
        cur.execute(f'PRAGMA table_info({"SEARCHRACK" if db_type == "rack" else "raw_bol_items"})')
        columns = [col[1] for col in cur.fetchall()]
        
        # Normalize data keys to uppercase for searchRack (case-insensitive matching)
        if db_type == 'rack':
            normalized_data = {k.upper(): v for k, v in data.items()}
        else:
            normalized_data = data

        if db_type == 'rack' and 'QUANTITY' in normalized_data:
            parsed_quantity = _strict_inventory_quantity(normalized_data['QUANTITY'])
            if parsed_quantity is None or parsed_quantity < 0:
                return jsonify({
                    'success': False,
                    'error': 'Quantity must be a whole number of 0 or more; 0 archives and removes the row'
                }), 400
            normalized_data['QUANTITY'] = parsed_quantity
        
        tracker_upc_key = None
        tracker_prev_total = None

        # If updating quantity in searchRack, log to removed_items for history
        if db_type == 'rack' and 'QUANTITY' in normalized_data:
            try:
                # Get old quantity and item details
                cur.execute('SELECT QUANTITY, BARCODE, TITLE, ITEM_POSITION FROM SEARCHRACK WHERE ID = ?', (item_id,))
                old_row = cur.fetchone()
                if old_row:
                    old_qty, barcode, title, item_location = old_row
                    old_qty = _coerce_int(old_qty, 0)
                    new_qty = _coerce_int(normalized_data['QUANTITY'], old_qty)
                    qty_change = new_qty - old_qty
                    tracker_upc_key = _listing_alert_upc_key(barcode)
                    if tracker_upc_key:
                        tracker_prev_total = _searchrack_total_qty_for_key(conn, tracker_upc_key)
                    
                    print(f"📝 Manual edit detected: {title} (ID: {item_id}) - Qty change: {old_qty} → {new_qty} (change: {qty_change})")
                    
                    if qty_change == 0:
                        print(f"⚠️ Quantity unchanged, not logging to history")
                    else:
                        # The SEARCHRACK trigger records this in the same transaction as the update.
                        print(f"✅ Manual edit queued in durable rack-history outbox: {title}")
            except Exception as log_err:
                print(f"❌ Error logging quantity change to removed_items: {log_err}")
                import traceback
                traceback.print_exc()
        
        # Build update query using normalized data
        set_clause = ', '.join([f'"{k}"=?' for k in normalized_data.keys() if k in columns])
        values = [v for k, v in normalized_data.items() if k in columns]
        values.append(item_id)
        
        if not set_clause:
            return jsonify({'success': False, 'error': 'No valid fields to update'}), 400
        
        query = f'UPDATE {"SEARCHRACK" if db_type == "rack" else "raw_bol_items"} SET {set_clause} WHERE id=?'
        cur.execute(query, values)
        conn.commit()

        if db_type == 'rack' and tracker_upc_key and tracker_prev_total is not None:
            try:
                tracker_current_total = _searchrack_total_qty_for_key(conn, tracker_upc_key)
                _record_inventory_zero_transition(tracker_upc_key, tracker_prev_total, tracker_current_total)
            except Exception as tracker_err:
                print(f"Warning: zero-transition write tracking failed in update_item: {tracker_err}")

        if db_type == 'rack':
            _invalidate_searchrack_cache()
        
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/search/<db_key>', methods=['POST'])
def api_search_db(db_key):
    data = request.get_json() or {}
    q = (data.get('q') or '').strip()
    print(f"DEBUG: api_search_db hit. db={db_key}, q='{q}'")
    # Strip leading zeros from barcode searches
    q_stripped = _strip_leading_zeros_numeric(q)
    # Accept limit from client. If limit is 0 or None, we will NOT apply a SQL LIMIT (i.e., return all rows).
    limit_raw = data.get('limit')
    try:
        limit = int(limit_raw) if limit_raw is not None else 50
    except Exception:
        limit = 50
    try:
        print(f"[SEARCH DEBUG] db_key={db_key}, query={q}, query_stripped={q_stripped}")
        mapping = {
            'ebayStore': 'ebayStore.db',
            'amazonStore': 'amazonStore.db',
            'sold': 'sold.db',
            'returns': 'sold.db',  # Returns table in sold.db
            'searchRack': 'searchRack.db',
            'found': 'found.db',
            'bol': 'rawbol.db'  # Search rawbol.db to see original imported amounts across all LOTs
        }
        if db_key not in mapping:
            return jsonify({'error': 'Unknown db_key'}), 400
        db_path = mapping[db_key]
        # Ensure created_at and custom_title exist for searchRack
        if db_key == 'searchRack':
            try:
                conn_m = sqlite3.connect(db_path)
                cur_m = conn_m.cursor()
                cur_m.execute("PRAGMA table_info(SEARCHRACK)")
                cols_m = [r[1] for r in cur_m.fetchall()]
                schema_changed = False
                if 'CREATED_AT' not in cols_m:
                    cur_m.execute('ALTER TABLE SEARCHRACK ADD COLUMN CREATED_AT TEXT')
                    schema_changed = True
                if 'CUSTOM_TITLE' not in cols_m:
                    cur_m.execute('ALTER TABLE SEARCHRACK ADD COLUMN CUSTOM_TITLE INTEGER DEFAULT 0')
                    schema_changed = True
                if 'WAREHOUSE_NOTE' not in cols_m:
                    cur_m.execute('ALTER TABLE SEARCHRACK ADD COLUMN WAREHOUSE_NOTE TEXT DEFAULT ""')
                    schema_changed = True
                # Set CREATED_AT for any missing rows to current UTC so timestamps appear
                import datetime as _dt
                now_iso = _dt.datetime.now(_dt.UTC).isoformat()
                cur_m.execute("UPDATE SEARCHRACK SET CREATED_AT = ? WHERE CREATED_AT IS NULL OR TRIM(COALESCE(CREATED_AT,'')) = ''", (now_iso,))
                conn_m.commit()
                if schema_changed:
                    _install_searchrack_history_guard(conn_m)
                _reconcile_inventory_age_batches(conn_m)
            except Exception:
                # Don't block search if migration fails
                pass
            finally:
                conn_m.close()
        
        # Use cached connection for better performance
        conn = get_db_connection(db_path)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
        tables = [r[0] for r in cur.fetchall()]
        if not tables:
            conn.close()
            return jsonify({'results': []})
        prefer = None
        # Special case for returns: use returns table
        if db_key == 'returns':
            prefer = 'returns' if 'returns' in tables else None
        else:
            for t in ['orders','INVENTORY','SEARCHRACK','searchrack','rack','items','bol_items']:
                if t in tables:
                    prefer = t
                    break
        table = prefer or tables[0]
        print(f"[SEARCH DEBUG] db_key={db_key}, db_path={db_path}, table={table}, tables={tables}")
        cur.execute(f"PRAGMA table_info('{table}')")
        cols = [r[1] for r in cur.fetchall()]
        print(f"[SEARCH DEBUG] columns={cols}")
        where_clause = ''
        params = []
        # Accept optional location filter (from client UI) to search Item_Position specifically
        location = (data.get('location') or '').strip()
        # Accept optional LOT filter for BOL database
        lot_filter = (data.get('lot_filter') or '').strip() if db_key == 'bol' else ''
        # Accept optional location_group_id for filtering by shelf group (from location browser)
        location_group_id = data.get('location_group_id')
        # Accept optional custom_only filter for searchRack (user-filled title/image)
        custom_only = bool(data.get('custom_only')) if db_key == 'searchRack' else False
        
        if q_stripped:
            tokens = []
            seen_tokens = set()
            for part in q_stripped.split():
                token = str(part or '').strip()
                if not token:
                    continue
                token_key = token.lower()
                if token_key in seen_tokens:
                    continue
                seen_tokens.add(token_key)
                tokens.append(token)
            if not tokens:
                tokens = [q_stripped]

            if db_key == 'searchRack':
                title_col = next((c for c in cols if c.lower() == 'title'), None)
                barcode_col = next((c for c in cols if c.lower() in ('barcode', 'upc')), None)
                item_id_col = next((c for c in cols if c.lower() in ('itemid', 'item_id', 'sku')), None)
                item_position_col = next((c for c in cols if c.lower() in ('item_position', 'itemposition', 'position')), None)
                picture_position_col = next((c for c in cols if c.lower() in ('pictureposition', 'picture_position')), None)

                disjuncts = []

                if title_col:
                    title_col_sql = '"' + str(title_col).replace('"', '""') + '"'
                    title_parts = [f"LOWER(COALESCE({title_col_sql},'')) LIKE ?" for _ in tokens]
                    disjuncts.append('(' + ' AND '.join(title_parts) + ')')
                    params.extend(f"%{token.lower()}%" for token in tokens)

                aux_parts = []
                aux_params = []
                for col in [barcode_col, item_id_col]:
                    if not col:
                        continue
                    col_sql = '"' + str(col).replace('"', '""') + '"'
                    aux_parts.append(f"LOWER(COALESCE({col_sql},'')) LIKE ?")
                    aux_params.append(f"%{q_stripped.lower()}%")

                location_parts = []
                location_params = []
                for col in [item_position_col, picture_position_col]:
                    if not col:
                        continue
                    col_sql = '"' + str(col).replace('"', '""') + '"'
                    # Exact match for position columns — avoids "h1" matching h10, h11, etc.
                    location_parts.append(f"LOWER(TRIM(COALESCE({col_sql},''))) = ?")
                    location_params.append(q_stripped.lower())

                if aux_parts:
                    disjuncts.append('(' + ' OR '.join(aux_parts) + ')')
                    params.extend(aux_params)

                if location_parts:
                    disjuncts.append('(' + ' OR '.join(location_parts) + ')')
                    params.extend(location_params)

                if disjuncts:
                    where_clause = ' WHERE ' + ' OR '.join(disjuncts)
                else:
                    likes = []
                    for c in cols:
                        col_sql = '"' + str(c).replace('"', '""') + '"'
                        likes.append(f"LOWER(COALESCE({col_sql},'')) LIKE ?")
                        params.append(f"%{q_stripped.lower()}%")
                    where_clause = ' WHERE ' + ' OR '.join(likes)
            else:
                likes = []
                for c in cols:
                    col_sql = '"' + str(c).replace('"', '""') + '"'
                    likes.append(f"LOWER(COALESCE({col_sql},'')) LIKE ?")
                    params.append(f"%{q_stripped.lower()}%")
                where_clause = ' WHERE ' + ' OR '.join(likes)
        
        # If a specific LOT was provided (BOL database only), add filter
        if db_key == 'bol' and lot_filter:
            lot_condition = "lot_number = ?"
            params.append(lot_filter)
            if where_clause:
                where_clause += f' AND {lot_condition}'
            else:
                where_clause = f' WHERE {lot_condition}'
        
        # If a specific location was provided, add an AND clause to filter by item position columns
        if location:
            # try common column names for location
            loc_cols = [c for c in cols if c.lower() in ('item_position','itemposition','position','item_position')]
            if not loc_cols:
                # fallback to any column that looks like position
                loc_cols = [c for c in cols if 'position' in c.lower()]
            if loc_cols:
                loc_likes = []
                for lc in loc_cols:
                    loc_likes.append(f"LOWER(COALESCE({lc},'')) LIKE ?")
                    params.append(f"%{location.lower()}%")
                if where_clause:
                    where_clause += ' AND (' + ' OR '.join(loc_likes) + ')'
                else:
                    where_clause = ' WHERE ' + ' OR '.join(loc_likes)
        
        # If location_group_id is provided (searchRack only), filter by all shelves in that group
        if db_key == 'searchRack' and location_group_id:
            group_conn = None
            try:
                # Get all shelf codes in this group
                group_conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'))
                group_cur = group_conn.cursor()
                group_cur.execute('SELECT shelf_name FROM shelves WHERE group_id = ?', (location_group_id,))
                shelf_codes = [row[0] for row in group_cur.fetchall()]

                if shelf_codes:
                    # Find item_position column
                    loc_cols = [c for c in cols if c.lower() in ('item_position','itemposition','position')]
                    if not loc_cols:
                        loc_cols = [c for c in cols if 'position' in c.lower()]

                    if loc_cols:
                        loc_col = loc_cols[0]
                        # Build OR condition for all shelves in group
                        shelf_conditions = []
                        for shelf_code in shelf_codes:
                            shelf_conditions.append(f"LOWER(TRIM({loc_col})) = LOWER(TRIM(?))")
                            params.append(shelf_code)

                        if where_clause:
                            where_clause += ' AND (' + ' OR '.join(shelf_conditions) + ')'
                        else:
                            where_clause = ' WHERE (' + ' OR '.join(shelf_conditions) + ')'
            except Exception as e:
                print(f"[SEARCH DEBUG] Error filtering by location_group_id: {e}")
            finally:
                if group_conn:
                    group_conn.close()
        
        # If custom_only is set, filter to items with user-filled title or custom image
        if custom_only:
            custom_cond = "(COALESCE(CUSTOM_TITLE, 0) = 1 OR COALESCE(IMAGE, '') LIKE '/static/custom_items/%')"
            if where_clause:
                # The text search is a series of OR expressions. Group all of
                # them before applying custom_only so a title/barcode match
                # cannot bypass the Custom Items filter through SQL precedence.
                where_clause = f" WHERE ({where_clause[7:]}) AND {custom_cond}"
            else:
                where_clause = f' WHERE {custom_cond}'

        if db_key == 'searchRack':
            active_qty_col = next((column for column in cols if column.lower() in ('quantity', 'qty')), None)
            if active_qty_col:
                active_condition = (
                    f'COALESCE(CAST({_sqlite_ident(active_qty_col)} AS INTEGER), 0) > 0'
                )
                if where_clause:
                    where_clause = f" WHERE ({where_clause[7:]}) AND {active_condition}"
                else:
                    where_clause = f' WHERE {active_condition}'

        # compute total matching count for pagination
        count_sql = f"SELECT COUNT(*) FROM {table} {where_clause}"
        print(f"[SEARCH DEBUG] count_sql={count_sql}, params={params}")
        cur.execute(count_sql, params)
        total_count = cur.fetchone()[0]
        print(f"[SEARCH DEBUG] total_count={total_count}")

        # If limit <= 0, return all rows; otherwise apply LIMIT/OFFSET
        offset = int(data.get('offset') or 0)
        if limit and int(limit) > 0:
            sql = f"SELECT * FROM {table} {where_clause} LIMIT ? OFFSET ?"
            exec_params = params + [limit, offset]
            cur.execute(sql, exec_params)
        else:
            sql = f"SELECT * FROM {table} {where_clause}"
            cur.execute(sql, params)
        rows = [dict(r) for r in cur.fetchall()]

        # Pre-load enrichment data in batch for searchRack results (avoids N+1 queries)
        _enrichment_cache = {}
        _inventory_age_cache = {}
        if db_key == 'searchRack' and rows:
            _inventory_age_cache = _inventory_age_lookup(
                conn,
                [r.get('ID') if r.get('ID') is not None else r.get('id') for r in rows]
            )
        if db_key == 'searchRack' and rows:
            # Collect all barcodes that need enrichment
            _barcodes_to_enrich = set()
            for r in rows:
                bc = r.get('BARCODE') or r.get('barcode') or r.get('Barcode') or ''
                if bc:
                    base = str(bc).split('-')[0]
                    base = _strip_leading_zeros_numeric(base)
                    if base:
                        _barcodes_to_enrich.add(base)
            if _barcodes_to_enrich:
                from DBmanager import connect_db
                placeholders = ','.join('?' for _ in _barcodes_to_enrich)
                bc_tuple = tuple(_barcodes_to_enrich)
                # Batch lookup: ebayStore
                try:
                    with connect_db('ebayStore.db') as _ec:
                        _ec.row_factory = sqlite3.Row
                        for r in _ec.cursor().execute(f"SELECT Title, Image, ItemID, UPC FROM INVENTORY WHERE UPC IN ({placeholders}) COLLATE NOCASE", bc_tuple):
                            upc_key = _strip_leading_zeros_numeric(r['UPC'] or '')
                            _enrichment_cache.setdefault(upc_key, {}).update({'title': r['Title'], 'image': r['Image'], 'item_id': r['ItemID']})
                except Exception:
                    pass
                # Batch lookup: amazonStore
                try:
                    with connect_db('amazonStore.db') as _ac:
                        _ac.row_factory = sqlite3.Row
                        for r in _ac.cursor().execute(f"SELECT TITLE, IMAGE, ASIN, UPC FROM ITEMS WHERE UPC IN ({placeholders}) COLLATE NOCASE", bc_tuple):
                            upc_key = _strip_leading_zeros_numeric(r['UPC'] or '')
                            cached = _enrichment_cache.setdefault(upc_key, {})
                            cached.setdefault('title', r['TITLE'])
                            cached.setdefault('image', r['IMAGE'])
                            cached.setdefault('item_id', r['ASIN'])
                except Exception:
                    pass
                # Batch lookup: rawbol
                try:
                    with connect_db('rawbol.db') as _rc:
                        _rc.row_factory = sqlite3.Row
                        for r in _rc.cursor().execute(f"SELECT item_description, image_url, upc FROM raw_bol_items WHERE upc IN ({placeholders}) COLLATE NOCASE", bc_tuple):
                            upc_key = _strip_leading_zeros_numeric(r['upc'] or '')
                            cached = _enrichment_cache.setdefault(upc_key, {})
                            cached.setdefault('title', r['item_description'])
                            cached.setdefault('image', r['image_url'])
                            cached.setdefault('item_id', r['upc'])
                except Exception:
                    pass
                # Batch lookup: bol
                try:
                    with connect_db('bol.db') as _bc:
                        _bc.row_factory = sqlite3.Row
                        for r in _bc.cursor().execute(f"SELECT item_description, image_url, upc FROM bol_items WHERE upc IN ({placeholders}) COLLATE NOCASE", bc_tuple):
                            upc_key = _strip_leading_zeros_numeric(r['upc'] or '')
                            cached = _enrichment_cache.setdefault(upc_key, {})
                            cached.setdefault('title', r['item_description'])
                            cached.setdefault('image', r['image_url'])
                            cached.setdefault('item_id', r['upc'])
                except Exception:
                    pass

        results = []
        for r in rows:
            item = dict(r)
            # default mappings
            if db_key == 'ebayStore':
                barcode_val = item.get('UPC') or item.get('upc') or item.get('BARCODE') or item.get('barcode') or item.get('Barcode') or ''
            elif db_key == 'amazonStore':
                barcode_val = item.get('UPC') or item.get('upc') or item.get('BARCODE') or item.get('barcode') or item.get('Barcode') or ''
            elif db_key == 'sold':
                # Be robust to all case variants and explicit barcode field
                barcode_val = item.get('barcode') or item.get('BARCODE') or item.get('Barcode') or item.get('upc') or item.get('UPC') or ''
            else:
                barcode_val = item.get('BARCODE') or item.get('barcode') or item.get('Barcode') or ''

            # bol.db normalization: different column names (item_description, upc, image_url)
            title_val = item.get('Title') or item.get('title') or item.get('TITLE') or item.get('name') or item.get('Name') or ''
            if db_key == 'sold':
                image_val = item.get('image') or item.get('Image') or item.get('IMAGE') or item.get('image_url') or item.get('images') or ''
            elif db_key == 'amazonStore':
                # amazonStore uses all-caps IMAGE column
                image_val = item.get('IMAGE') or item.get('Image') or item.get('image') or item.get('image_url') or item.get('images') or ''
            else:
                image_val = item.get('Image') or item.get('image') or item.get('IMAGE') or item.get('image_url') or item.get('images') or ''
            if db_key == 'bol':
                # barcode from upc field
                b = item.get('upc') or item.get('UPC') or item.get('Upc') or barcode_val
                # normalize numeric-like UPCs (e.g., '16094950.0') to '16094950'
                if isinstance(b, float) or (isinstance(b, str) and b.endswith('.0') and b.replace('.0','').isdigit()):
                    try:
                        b = str(int(float(b)))
                    except Exception:
                        b = str(b)
                elif b is None:
                    b = ''
                else:
                    b = str(b)
                barcode_val = b

                # title from item_description or description
                t = item.get('item_description') or item.get('description') or title_val
                if not t:
                    # fallback: pick the longest non-URL text field from the row
                    longest = ''
                    for v in item.values():
                        try:
                            s = str(v or '')
                        except Exception:
                            continue
                        if s and not s.lower().startswith('http') and len(s) > len(longest):
                            longest = s
                    t = longest
                title_val = t or ''

                # image from image_url if present
                image_val = item.get('image_url') or item.get('image') or image_val or ''

            # Quantity extraction that properly handles 0 values
            qty_raw = None
            for qkey in ['QUANTITY', 'Quantity', 'quantity', 'qty']:
                if qkey in item and item[qkey] is not None:
                    qty_raw = item[qkey]
                    if db_key == 'searchRack':
                        print(f"[QTY EXTRACT] Found {qkey}={qty_raw}, type={type(qty_raw)}, barcode={item.get('BARCODE') or item.get('barcode')}")
                    break
            if qty_raw is None:
                qty_raw = ''
                if db_key == 'searchRack':
                    print(f"[QTY EXTRACT] No quantity found, defaulting to empty, barcode={item.get('BARCODE') or item.get('barcode')}")
            
            # Debug logging for zero quantity items
            if qty_raw == 0 and db_key == 'searchRack':
                print(f"[DEBUG] Zero quantity item found: barcode={barcode_val}, qty_raw={qty_raw}, type={type(qty_raw)}")
            
            item_out = {
                'source_db': db_key,
                'source_table': table,
                'id': item.get('id') or item.get('ID') or item.get('rowid'),
                'title': title_val,
                'image': image_val,
                'barcode': barcode_val,
                'item_id': item.get('ItemID') or item.get('item_id') or item.get('ItemId') or item.get('ASIN') or item.get('asin') or (barcode_val if barcode_val else ''),
                'pictureposition': item.get('PICTUREPOSITION') or item.get('pictureposition') or item.get('picture_position') or '',
                'item_position': item.get('ITEM_POSITION') or item.get('item_position') or item.get('position') or '',
                'quantity': qty_raw,
                'warehouse_note': item.get('WAREHOUSE_NOTE') or item.get('warehouse_note') or '',
                'is_custom_title': bool(_coerce_int(item.get('CUSTOM_TITLE') if item.get('CUSTOM_TITLE') is not None else item.get('custom_title'), 0)) if db_key == 'searchRack' else False,
                # created_at available on SEARCHRACK rows populated by DBmanager
                'created_at': item.get('CREATED_AT') or item.get('created_at') or '',
                # store field for returns (amazon/ebay)
                'store': item.get('store') or item.get('Store') or item.get('STORE') or '',
                'raw': item
            }
            if db_key == 'searchRack':
                age_row_id = item.get('ID') if item.get('ID') is not None else item.get('id')
                try:
                    age_row_id = int(age_row_id)
                except Exception:
                    age_row_id = None
                age_batches = list(_inventory_age_cache.get(age_row_id, []))
                item_out['age_batches'] = age_batches
                item_out['oldest_received_at'] = (
                    age_batches[0].get('received_at') if age_batches else item_out['created_at']
                )
            # If this row comes from searchRack, enrich from pre-loaded batch cache
            try:
                if db_key == 'searchRack' and item_out.get('barcode'):
                    lookup_barcode = item_out.get('barcode')
                    base_barcode = str(lookup_barcode).split('-')[0] if lookup_barcode else lookup_barcode
                    base_barcode = _strip_leading_zeros_numeric(base_barcode)
                    cached = _enrichment_cache.get(base_barcode, {})
                    if cached:
                        cached_title = str(cached.get('title') or '').strip()
                        current_title = str(item_out.get('title') or '').strip()
                        if item_out.get('is_custom_title'):
                            item_out['custom_title'] = current_title
                            if cached_title and cached_title.casefold() != current_title.casefold():
                                item_out['database_title'] = cached_title
                        item_out['title'] = item_out.get('title') or cached.get('title')
                        item_out['image'] = item_out.get('image') or cached.get('image')
                        item_out['item_id'] = item_out.get('item_id') or cached.get('item_id')
                # If this row comes from sold.db, the data should already be enriched during sync
                # but we can still do a fallback enrichment if needed
                elif db_key == 'sold':
                    # If barcode is missing, try to get it from ebayStore.db
                    if not item_out.get('barcode'):
                        lookup_item_id = item_out.get('item_id')
                        if lookup_item_id:
                            try:
                                es_conn = sqlite3.connect('ebayStore.db')
                                es_conn.row_factory = sqlite3.Row
                                es_cur = es_conn.cursor()
                                es_cur.execute("SELECT UPC FROM INVENTORY WHERE ItemID = ? LIMIT 1", (lookup_item_id,))
                                row_es = es_cur.fetchone()
                                if row_es and row_es['UPC']:
                                    item_out['barcode'] = row_es['UPC']
                            except Exception as e:
                                print(f"Debug: sold barcode lookup error: {e}")
                                pass
                            finally:
                                es_conn.close()
                    
                    # If title or image is missing, try to get from rawbol.db using barcode
                    if item_out.get('barcode') and (not item_out.get('title') or not item_out.get('image')):
                        try:
                            bol_conn = sqlite3.connect('rawbol.db')
                            bol_conn.row_factory = sqlite3.Row
                            bol_cur = bol_conn.cursor()

                            barcode_to_lookup = item_out['barcode']
                            # Normalize barcode (strip .0 artifacts, ensure string)
                            if barcode_to_lookup is None:
                                barcode_to_lookup = ''
                            elif isinstance(barcode_to_lookup, float):
                                try:
                                    barcode_to_lookup = str(int(barcode_to_lookup))
                                except Exception:
                                    barcode_to_lookup = str(barcode_to_lookup)
                            else:
                                barcode_to_lookup = str(barcode_to_lookup).strip()
                                if barcode_to_lookup.endswith('.0') and barcode_to_lookup.replace('.0', '').isdigit():
                                    barcode_to_lookup = barcode_to_lookup[:-2]
                            barcode_stripped = _strip_leading_zeros_numeric(barcode_to_lookup)
                            row_bol = None

                            # Try exact match first
                            bol_cur.execute('SELECT item_description, image_url FROM raw_bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (barcode_to_lookup,))
                            row_bol = bol_cur.fetchone()

                            # Try stripped zeros if no match
                            if not row_bol and barcode_to_lookup.isdigit():
                                stripped = barcode_stripped
                                if stripped != barcode_to_lookup:
                                    bol_cur.execute('SELECT item_description, image_url FROM raw_bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (stripped,))
                                    row_bol = bol_cur.fetchone()

                            # Try padded to 12 digits if no match
                            if not row_bol and barcode_to_lookup.isdigit():
                                padded = barcode_to_lookup.zfill(12)
                                if padded != barcode_to_lookup:
                                    bol_cur.execute('SELECT item_description, image_url FROM raw_bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (padded,))
                                    row_bol = bol_cur.fetchone()

                            # Try padded to 13 digits (EAN) if no match
                            if not row_bol and barcode_to_lookup.isdigit():
                                padded13 = barcode_to_lookup.zfill(13)
                                if padded13 != barcode_to_lookup:
                                    bol_cur.execute('SELECT item_description, image_url FROM raw_bol_items WHERE upc = ? COLLATE NOCASE LIMIT 1', (padded13,))
                                    row_bol = bol_cur.fetchone()

                            # Try suffix match (rawbol UPC has extra leading zeros)
                            if not row_bol and barcode_stripped and barcode_stripped.isdigit() and len(barcode_stripped) >= 8:
                                bol_cur.execute("SELECT item_description, image_url FROM raw_bol_items WHERE REPLACE(upc, '.0', '') LIKE ? COLLATE NOCASE LIMIT 1", ('%' + barcode_stripped,))
                                row_bol = bol_cur.fetchone()

                            # Try integer-cast comparison to normalize leading zeros
                            if not row_bol and barcode_stripped and barcode_stripped.isdigit() and len(barcode_stripped) >= 8:
                                bol_cur.execute("""
                                    SELECT item_description, image_url FROM raw_bol_items
                                    WHERE CAST(CAST(REPLACE(upc, '.0', '') AS INTEGER) AS TEXT) = ?
                                    COLLATE NOCASE LIMIT 1
                                """, (barcode_stripped,))
                                row_bol = bol_cur.fetchone()

                            if row_bol:
                                if not item_out.get('title') and row_bol['item_description']:
                                    item_out['title'] = row_bol['item_description']
                                if not item_out.get('image') and row_bol['image_url']:
                                    item_out['image'] = row_bol['image_url']
                        except Exception as e:
                            print(f"Debug: rawbol enrichment error: {e}")
                            pass
                        finally:
                            bol_conn.close()

                    # Compute inv_status for sold items
                    try:
                        rackupdated_val = _coerce_int(item.get('rackupdated'), 0)
                        order_id_val = str(item.get('order_id') or '').strip()
                        barcode_val = str(item.get('barcode') or '').strip()
                        has_removal_record = False
                        if order_id_val or barcode_val:
                            try:
                                hist_conn = sqlite3.connect('rackhistory.db')
                                hist_cur = hist_conn.cursor()
                                hist_cur.execute("""
                                    SELECT removed_at
                                    FROM removed_items
                                    WHERE (
                                        (? != '' AND COALESCE(order_id, '') = ?)
                                        OR
                                        (? != '' AND COALESCE(barcode, '') = ?)
                                    )
                                    AND removal_type IN (
                                        'automatic',
                                        'automatic_allocated',
                                        'repair_removal',
                                        'manual_sold_removal',
                                        'manual_immediate',
                                        'manual_sold_selection',
                                        'manual_handled',
                                        'finder_removal'
                                    )
                                    AND COALESCE(old_quantity, 0) > COALESCE(new_quantity, 0)
                                    AND (undone_at IS NULL OR undone_at = '')
                                """, (order_id_val, order_id_val, barcode_val, barcode_val))
                                has_removal_record = any(
                                    _sold_removal_event_is_current(item, {'removed_at': row[0]})
                                    for row in hist_cur.fetchall()
                                )
                                hist_conn.close()
                            except Exception:
                                pass

                        sale_time_known = _sold_order_sale_datetime(item) is not None
                        if has_removal_record or (rackupdated_val == 1 and not sale_time_known):
                            item_out['inv_status'] = 'COMPLETE'
                        else:
                            item_out['inv_status'] = 'NOT_REMOVED'
                    except Exception as e:
                        print(f"Debug: inv_status error: {e}")
                        item_out['inv_status'] = 'NOT_REMOVED'
            except Exception:
                pass
            results.append(item_out)
        
        # Note: Not closing connection - using connection pooling for performance
        
        # If searching bol (rawbol.db), aggregate by UPC and handle multiple LOTs
        if db_key == 'bol' and results:
            from collections import defaultdict
            import datetime as _dt
            
            # Group by UPC
            upc_groups = defaultdict(list)
            for r in results:
                upc = (r.get('barcode') or '').strip()
                if upc:
                    upc_groups[upc].append(r)
            
            aggregated = []
            for upc, items in upc_groups.items():
                # Extract LOT information from all items with this UPC
                lot_data = []
                total_qty = 0
                
                # Use first item as base for title, image, etc.
                base_item = items[0].copy()
                
                for item in items:
                    qty = item.get('quantity') or item.get('raw', {}).get('quantity') or 1
                    try:
                        qty = int(qty)
                    except (ValueError, TypeError):
                        qty = 1
                    
                    total_qty += qty
                    
                    lot_num = item.get('raw', {}).get('lot_number') or ''
                    lot_num = str(lot_num).strip() if lot_num else ''
                    if not lot_num or lot_num.lower() in ['nan', 'none', 'null', '']:
                        lot_num = '(No LOT)'
                    
                    import_date = item.get('raw', {}).get('import_date') or ''
                    if not import_date or str(import_date).strip().lower() in ['nan', 'none', 'null', '']:
                        import_date = '(No Date)'
                    
                    lot_data.append({
                        'lot_number': lot_num,
                        'qty': qty,
                        'import_date': import_date
                    })
                
                # Sort lots by import_date (newest first), handling "(No Date)" specially
                def parse_date(date_str):
                    if date_str == '(No Date)':
                        return _dt.datetime.min
                    try:
                        # Try parsing YYYY-MM-DD format
                        return _dt.datetime.strptime(str(date_str).split()[0], '%Y-%m-%d')
                    except Exception:
                        try:
                            # Try ISO format
                            return _dt.datetime.fromisoformat(str(date_str).replace('Z', '+00:00'))
                        except Exception:
                            return _dt.datetime.min
                
                lot_data.sort(key=lambda x: parse_date(x['import_date']), reverse=True)
                
                # Determine LOT display
                unique_lots = list(set([ld['lot_number'] for ld in lot_data]))
                unique_lots = [lot for lot in unique_lots if lot != '(No LOT)']
                
                if len(unique_lots) == 0:
                    lot_display = '(No LOT)'
                    has_multiple = False
                elif len(unique_lots) == 1:
                    lot_display = unique_lots[0]
                    has_multiple = False
                else:
                    lot_display = 'multiple LOTS'
                    has_multiple = True
                
                # Build aggregated item
                aggregated_item = {
                    'source_db': 'bol',
                    'source_table': base_item.get('source_table'),
                    'id': base_item.get('id'),
                    'title': base_item.get('title'),
                    'image': base_item.get('image'),
                    'barcode': upc,
                    'item_id': base_item.get('item_id'),
                    'quantity': total_qty,
                    'lot_number': lot_display,
                    'has_multiple_lots': has_multiple,
                    'lot_data': lot_data,  # Array of {lot_number, qty, import_date}
                    'raw': base_item.get('raw')
                }
                
                aggregated.append(aggregated_item)
            
            results = aggregated
            total_count = len(results)
        
        # If searching the searchRack snapshot, merge rows with same barcode+item_position and sum quantities
        # BUT: picture position items should NEVER be merged (each picture is unique)
        if db_key == 'searchRack' and results:
            merged = {}
            for r in results:
                bc = (r.get('barcode') or '').strip()
                pic = (r.get('pictureposition') or '').strip()
                
                # Picture position items are ALWAYS unique - use pictureposition + row ID for key
                if pic:
                    # Each picture position gets unique key (never merge)
                    key = f"{bc.lower()}||pic||{pic.lower()}||{r.get('id')}"
                else:
                    # Shelf code items: merge by barcode + item_position
                    pos = (r.get('item_position') or '').strip()
                    if not bc:
                        key = f"__{id(r)}_{len(merged)}"
                    else:
                        key = f"{bc.lower()}||shelf||{pos.lower()}"
                
                if key not in merged:
                    merged[key] = r.copy()
                    # normalize quantity - handle 0 values properly
                    qty_val = r.get('quantity')
                    if qty_val is None or qty_val == '':
                        merged[key]['quantity'] = 1
                    elif isinstance(qty_val, (int, float)):
                        merged[key]['quantity'] = int(qty_val)
                    elif str(qty_val).isdigit():
                        merged[key]['quantity'] = int(qty_val)
                    else:
                        merged[key]['quantity'] = 1
                else:
                    qty_val = r.get('quantity')
                    if qty_val is None or qty_val == '':
                        add_q = 1
                    elif isinstance(qty_val, (int, float)):
                        add_q = int(qty_val)
                    elif str(qty_val).isdigit():
                        add_q = int(qty_val)
                    else:
                        add_q = 1
                    merged[key]['quantity'] = merged[key].get('quantity', 0) + add_q
                    merged[key].setdefault('age_batches', []).extend(r.get('age_batches') or [])

            for merged_row in merged.values():
                grouped_batches = {}
                for batch in merged_row.get('age_batches') or []:
                    received_at = str(batch.get('received_at') or '').strip()
                    if not received_at:
                        continue
                    estimated = bool(batch.get('estimated'))
                    batch_key = (received_at, estimated)
                    grouped_batches[batch_key] = grouped_batches.get(batch_key, 0) + max(
                        0, _coerce_int(batch.get('quantity'), 0)
                    )
                merged_row['age_batches'] = [
                    {
                        'received_at': received_at,
                        'quantity': quantity,
                        'estimated': estimated,
                    }
                    for (received_at, estimated), quantity in sorted(
                        grouped_batches.items(), key=lambda entry: entry[0][0]
                    )
                    if quantity > 0
                ]
                merged_row['oldest_received_at'] = (
                    merged_row['age_batches'][0]['received_at']
                    if merged_row['age_batches']
                    else merged_row.get('created_at', '')
                )
            results = list(merged.values())
            # adjust total_count to reflect merged items count
            total_count = len(results)

            prep_lookup = _load_suffixed_item_prep_summary_lookup(
                row.get('barcode') for row in results
            )
            for row in results:
                prep_key = _normalize_upc_preserve_suffix_for_match(row.get('barcode'))
                row['item_prep_summary'] = prep_lookup.get(
                    prep_key,
                    _empty_suffixed_item_prep_summary(prep_key)
                )

        # If client requested debug info, return table/schema/samples plus normalized results
        if data.get('debug'):
            debug_samples = rows[:10] if isinstance(rows, list) else []
            return jsonify({
                'debug': True,
                'db_key': db_key,
                'db_path': db_path,
                'table': table,
                'columns': cols,
                'samples_raw': debug_samples,
                'results': results,
                'total': total_count
            })

        # Calculate total quantity for all results
        total_quantity = 0
        for r in results:
            try:
                qty = r.get('quantity', 0)
                if isinstance(qty, (int, float)):
                    total_quantity += int(qty)
                elif isinstance(qty, str) and qty.isdigit():
                    total_quantity += int(qty)
                else:
                    total_quantity += 1
            except Exception:
                total_quantity += 1

        # Debug: Check what quantities are in results before sending
        if db_key == 'searchRack':
            for r in results:
                if r.get('barcode') == '882864825810':
                    print(f"[BEFORE JSONIFY] barcode={r.get('barcode')}, quantity={r.get('quantity')}, type={type(r.get('quantity'))}")

        return jsonify({'results': results, 'total': total_count, 'total_quantity': total_quantity})
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500


# Quick search cache for UPC/barcode lookups (Option 3: Hybrid search)
_search_all_cache = {}
_search_cache_timeout = 300  # 5 minutes

@app.route('/api/search-all', methods=['POST'])
def api_search_all():
    """Search across all databases simultaneously with cached quick lookups for UPCs"""
    try:
        data = request.get_json() or {}
        query = (data.get('q') or '').strip()
        
        if not query:
            return jsonify({'error': 'No search query provided'}), 400
        
        # Strip leading zeros for numeric barcode searches
        query_stripped = _strip_leading_zeros_numeric(query)
        query_upc = _normalize_upc_preserve_suffix_for_match(query)

        # Determine search type (UPC searches are cached)
        is_upc_search = bool(query_upc and re.fullmatch(r'\d+(?:-\d+)?', query_upc))
        
        # Check cache for UPC searches only
        cache_key = f"search_all:v3:{query_upc or query_stripped}"
        if is_upc_search and cache_key in _search_all_cache:
            cached_data, cached_time = _search_all_cache[cache_key]
            if time.time() - cached_time < _search_cache_timeout:
                cached_data['from_cache'] = True
                return jsonify(cached_data)
        
        # Define databases to search with display info (ordered: warehouse, item-manager, Macy BOL, sold, amazon, ebay)
        databases = [
            {'key': 'shelves', 'path': 'searchRack.db', 'table': 'SEARCHRACK', 'name': 'Warehouse', 'color': '#9b59b6', 'icon': '📦'},
            {'key': 'processed', 'path': 'bol.db', 'table': 'bol_items', 'name': 'Item Manager (processed items)', 'color': '#2ecc71', 'icon': '✅', 'filter': 'checked_only'},
            {'key': 'bol', 'path': 'rawbol.db', 'table': 'raw_bol_items', 'name': 'Macy BOL', 'color': '#3498db', 'icon': '📦'},
            {'key': 'sold', 'path': 'sold.db', 'table': 'sold_items', 'name': 'Sold Items', 'color': '#e74c3c', 'icon': '💰'},
            {'key': 'amazon', 'path': 'amazonStore.db', 'table': 'INVENTORY', 'name': 'Amazon Store', 'color': '#1abc9c', 'icon': '📦'},
            {'key': 'ebay', 'path': 'ebayStore.db', 'table': 'INVENTORY', 'name': 'eBay Store', 'color': '#f39c12', 'icon': '🛒'},
        ]
        
        results = {
            'query': query,
            'search_type': 'upc' if is_upc_search else 'text',
            'databases': {},
            'from_cache': False
        }
        
        # Search each database
        for db_info in databases:
            db_key = db_info['key']
            db_path = BASE_DIR / db_info['path']
            
            if not db_path.exists():
                results['databases'][db_key] = {
                    'name': db_info['name'],
                    'color': db_info['color'],
                    'icon': db_info['icon'],
                    'found': False,
                    'count': 0,
                    'error': 'Database not found'
                }
                continue
            
            try:
                conn = get_db_connection(str(db_path))
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                
                # Check if table exists
                cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (db_info['table'],))
                if not cur.fetchone():
                    results['databases'][db_key] = {
                        'name': db_info['name'],
                        'color': db_info['color'],
                        'icon': db_info['icon'],
                        'found': False,
                        'count': 0,
                        'error': 'Table not found'
                    }
                    continue
                
                # Get table columns
                cur.execute(f"PRAGMA table_info({db_info['table']})")
                cols = [r[1] for r in cur.fetchall()]
                
                # Build search query based on type
                if is_upc_search:
                    db_query_upc = query_upc
                    if db_key == 'bol':
                        db_query_upc = _barcode_base_without_suffix(query_upc) or query_upc
                    # Fast UPC search on indexed columns
                    upc_cols = [c for c in cols if c.lower() in ('upc', 'barcode', 'sku')]
                    if not upc_cols:
                        upc_cols = [c for c in cols if 'upc' in c.lower() or 'barcode' in c.lower()]
                    
                    if upc_cols:
                        where_parts = [f"{col} LIKE ?" for col in upc_cols]
                        where_clause = " OR ".join(where_parts)
                        params = [f"%{db_query_upc}%"] * len(upc_cols)
                    else:
                        where_clause = "1=0"  # No UPC columns found
                        params = []
                else:
                    # Text search across all columns
                    where_parts = [f"LOWER(COALESCE({col},'')) LIKE ?" for col in cols]
                    where_clause = " OR ".join(where_parts)
                    params = [f"%{query_stripped.lower()}%"] * len(cols)
                
                # Apply filters for specific databases
                if db_info.get('filter') == 'checked_only':
                    # For Item Manager (processed), only show checked items (good or bad)
                    # Check for items_prep_status table (bol.db)
                    cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='items_prep_status'")
                    if cur.fetchone():
                        where_clause = f"({where_clause}) AND upc IN (SELECT upc FROM items_prep_status WHERE status IN ('good', 'bad'))"

                if db_key == 'shelves':
                    active_qty_col = next((c for c in cols if c.lower() in ('quantity', 'qty')), None)
                    if active_qty_col:
                        where_clause = (
                            f"({where_clause}) AND "
                            f"COALESCE(CAST({_sqlite_ident(active_qty_col)} AS INTEGER), 0) > 0"
                        )
                
                # Get count and sample results
                count_sql = f"SELECT COUNT(*) as count FROM {db_info['table']} WHERE {where_clause}"
                cur.execute(count_sql, params)
                count = cur.fetchone()['count']

                # For warehouse results, also provide total matched quantity.
                total_quantity = None
                if db_key == 'shelves':
                    qty_col = next((c for c in cols if c.lower() == 'quantity'), None)
                    if qty_col:
                        qty_sql = f"SELECT COALESCE(SUM(CAST({qty_col} AS REAL)), 0) AS total_quantity FROM {db_info['table']} WHERE {where_clause}"
                        cur.execute(qty_sql, params)
                        qty_row = cur.fetchone()
                        try:
                            total_quantity = max(0, int(round(float((qty_row['total_quantity'] if qty_row else 0) or 0))))
                        except Exception:
                            total_quantity = 0
                
                # Get sample results (up to 20)
                sample_results = []
                if count > 0:
                    sample_sql = f"SELECT * FROM {db_info['table']} WHERE {where_clause} LIMIT 20"
                    cur.execute(sample_sql, params)
                    sample_results = [dict(row) for row in cur.fetchall()]

                results['databases'][db_key] = {
                    'name': db_info['name'],
                    'color': db_info['color'],
                    'icon': db_info['icon'],
                    'found': count > 0,
                    'count': count,
                    'total_quantity': total_quantity,
                    'samples': sample_results if count > 0 else []
                }
                
            except Exception as e:
                results['databases'][db_key] = {
                    'name': db_info['name'],
                    'color': db_info['color'],
                    'icon': db_info['icon'],
                    'found': False,
                    'count': 0,
                    'error': _safe_error(e)
                }
        
        # Cache UPC searches
        if is_upc_search:
            _search_all_cache[cache_key] = (results, time.time())
            # Clean old cache entries (keep cache size under control)
            current_time = time.time()
            expired_keys = [k for k, (_, t) in _search_all_cache.items() if current_time - t > _search_cache_timeout]
            for k in expired_keys:
                del _search_all_cache[k]
        
        return jsonify(results)
        
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500


@app.route('/api/get_lot_numbers', methods=['GET'])
def api_get_lot_numbers():
    """Get all distinct LOT numbers from rawbol.db with item counts, sorted by most recent import_date."""
    try:
        conn = sqlite3.connect('rawbol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Get unique LOT numbers with counts and latest import date
        cur.execute('''
            SELECT 
                lot_number,
                COUNT(*) as item_count,
                MAX(import_date) as latest_date
            FROM raw_bol_items
            WHERE lot_number IS NOT NULL 
                AND TRIM(COALESCE(lot_number, '')) != ''
                AND LOWER(lot_number) NOT IN ('nan', 'none', 'null')
            GROUP BY lot_number
            ORDER BY latest_date DESC
        ''')
        
        rows = cur.fetchall()
        lots = [{'lot_number': r['lot_number'], 'item_count': r['item_count'], 'latest_date': r['latest_date']} for r in rows]
        
        return jsonify({'success': True, 'lots': lots})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        conn.close()


@app.route('/api/bol_stats', methods=['GET'])
def api_bol_stats():
    """Calculate BOL statistics using the new quantity tracking system.
    Now properly tracks original_qty, good_qty, bad_qty, and unchecked_qty per LOT.
    """
    conn = None
    try:
        _ensure_bol_list_status_column()
        conn = sqlite3.connect('bol.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Check if new quantity columns exist
        cur.execute('PRAGMA table_info(bol_items)')
        cols = [col[1].lower() for col in cur.fetchall()]
        has_new_columns = all(c in cols for c in ['original_qty', 'good_qty', 'bad_qty', 'unchecked_qty'])
        
        if not has_new_columns:
            return jsonify({
                'success': False, 
                'error': 'Quantity columns not yet migrated. Please restart Flask to run migration.'
            }), 500
        
        # Get all LOT numbers with their stats, ordered by import_date DESC (newest first)
        cur.execute('''
            SELECT 
                lot_number,
                MAX(import_date) as latest_date,
                COUNT(DISTINCT upc) as unique_items,
                SUM(COALESCE(original_qty, 0)) as total_original,
                SUM(COALESCE(good_qty, 0)) as total_good,
                SUM(COALESCE(bad_qty, 0)) as total_bad,
                SUM(COALESCE(unchecked_qty, 0)) as total_unchecked
            FROM bol_items
            WHERE (temporary IS NULL OR temporary = 0)
                AND upc NOT LIKE '%-%'
                AND lot_number IS NOT NULL 
                AND TRIM(COALESCE(lot_number, '')) != ''
                AND LOWER(lot_number) NOT IN ('nan', 'none', 'null')
            GROUP BY lot_number
            ORDER BY latest_date DESC
        ''')
        
        lots = cur.fetchall()
        stats = []
        auto_entries = _preplog_auto_assigned_entries(include_undone=False, limit=None)
        auto_by_lot = {}
        for entry in auto_entries:
            lot_key = _normalize_lot_number(entry.get('lot_number'))
            if not lot_key:
                continue
            auto_by_lot[lot_key] = int(auto_by_lot.get(lot_key, 0) or 0) + 1
        
        for lot_row in lots:
            lot_number = lot_row['lot_number']
            import_date = lot_row['latest_date']
            unique_items = lot_row['unique_items'] or 0
            total_original = lot_row['total_original'] or 0
            total_good = lot_row['total_good'] or 0
            total_bad = lot_row['total_bad'] or 0
            total_unchecked = lot_row['total_unchecked'] or 0
            
            # Calculate prepped quantity (good + bad), then clamp display metrics to sane bounds.
            raw_total_prepped = total_good + total_bad
            total_prepped = max(0, min(raw_total_prepped, total_original)) if total_original > 0 else max(0, raw_total_prepped)
            quantity_delta = (total_good + total_bad + total_unchecked) - total_original
            has_data_issue = (raw_total_prepped > total_original and total_original > 0) or (total_unchecked < 0) or (quantity_delta != 0)

            # Calculate percentage done based on quantity (not item count), capped to [0, 100].
            if total_original > 0:
                percent_done = round((total_prepped / total_original) * 100, 1)
            else:
                percent_done = 0.0
            
            # Calculate loss rate (bad / original), capped to [0, 100].
            if total_original > 0:
                effective_bad = max(0, min(total_bad, total_original))
                loss_rate = round((effective_bad / total_original) * 100, 1)
            else:
                loss_rate = 0.0
            
            stats.append({
                'lot_number': lot_number,
                'import_date': import_date,
                'unique_items': unique_items,
                'total_original': total_original,
                'total_good': total_good,
                'total_bad': total_bad,
                'total_unchecked': total_unchecked,
                'total_prepped': total_prepped,
                'raw_total_prepped': raw_total_prepped,
                'percent_done': percent_done,
                'loss_rate': loss_rate,
                'has_data_issue': has_data_issue,
                'quantity_delta': quantity_delta,
                'auto_assigned_count': int(auto_by_lot.get(lot_number, 0) or 0),
                'review_url': f"/item-prep/log?auto_assigned=1&lot={lot_number}"
            })
        
        
        return jsonify({
            'success': True,
            'stats': stats,
            'auto_assigned_total': len(auto_entries),
            'auto_assigned_lots': len(auto_by_lot)
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

@app.route('/api/bol_stats/auto_assigned', methods=['GET'])
def api_bol_stats_auto_assigned():
    """Return prep-log rows flagged as lot auto-assigned for QA review."""
    try:
        lot_filter = _normalize_lot_number(request.args.get('lot_number') or request.args.get('lot'))
        include_undone = (request.args.get('include_undone') or '0').strip().lower() in ('1', 'true', 'yes', 'y')
        limit = _listingagent_parse_int(request.args.get('limit'), 500) or 500
        limit = max(1, min(limit, 5000))
        items = _preplog_auto_assigned_entries(include_undone=include_undone, lot_number=lot_filter, limit=limit)
        return jsonify({
            'success': True,
            'items': items,
            'count': len(items),
            'lot_number': lot_filter
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e, 'bol_stats:auto_assigned')}), 500


@app.route('/api/lookup_location', methods=['POST'])
def api_lookup_location():
    data = request.get_json() or {}
    barcode = data.get('barcode')
    item_id = data.get('item_id')
    try:
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        row = None
        if barcode:
            cur.execute('''
                SELECT * FROM SEARCHRACK
                WHERE BARCODE = ? COLLATE NOCASE
                  AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                LIMIT 1
            ''', (barcode,))
            row = cur.fetchone()
        if not row and item_id:
            cur.execute('''
                SELECT * FROM SEARCHRACK
                WHERE BARCODE = ? COLLATE NOCASE
                  AND COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                LIMIT 1
            ''', (item_id,))
            row = cur.fetchone()
        if not row:
            return jsonify({'found': False})
        r = dict(row)
        return jsonify({'found': True, 'item_position': r.get('ITEM_POSITION') or r.get('item_position'), 'pictureposition': r.get('PICTUREPOSITION') or r.get('pictureposition') or r.get('image')})
    except Exception as e:
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        conn.close()


@app.route('/api/set_rack_location', methods=['POST'])
def api_set_rack_location():
    """Set ITEM_POSITION for a SEARCHRACK row. Expects JSON: { id: <id>, item_position: <pos> }"""
    data = request.get_json() or {}
    item_id_raw = data.get('id')
    pos = (data.get('item_position') or '').strip()
    pictureposition = (data.get('pictureposition') or '').strip()
    
    # WORKAROUND: Parse move_qty from item_id if encoded as "id:qty" (for cache issues)
    move_qty_from_id = None
    if item_id_raw and ':' in str(item_id_raw):
        parts = str(item_id_raw).split(':')
        if len(parts) == 2:
            item_id_raw = parts[0]
            try:
                move_qty_from_id = int(parts[1])
            except Exception:
                pass
    
    item_id = item_id_raw
    
    # Optional move quantity: how many items to move from this row's Quantity
    try:
        move_qty = int(data.get('move_qty')) if data.get('move_qty') is not None else None
    except Exception:
        move_qty = None
    
    # Use move_qty from encoded ID if not provided in data
    if move_qty is None and move_qty_from_id is not None:
        move_qty = move_qty_from_id
    
    # Require id and at least one of pos or pictureposition
    if not item_id or (not pos and not pictureposition):
        return jsonify({'success': False, 'error': 'Missing id or item_position/pictureposition'}), 400
    try:
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        # Try updating by id column; fall back to rowid if id column not present
        cur.execute("PRAGMA table_info('SEARCHRACK')")
        cols = [r[1] for r in cur.fetchall()]
        pk = None
        if 'id' in cols:
            pk = 'id'
        elif 'ID' in cols:
            pk = 'ID'
        else:
            pk = None
        # Load current row to inspect Quantity and other columns (we may need to split)
        # Determine how to address the row (by pk or rowid)
        id_col = pk
        id_val = item_id
        if not id_col:
            id_col = 'rowid'
            id_val = item_id

        cur.execute(f"SELECT * FROM SEARCHRACK WHERE {id_col} = ?", (id_val,))
        existing = cur.fetchone()
        # If we couldn't find a matching row, return error
        if not existing:
            return jsonify({'success': False, 'error': 'Row not found'}), 404

        # Extract current quantity (try common column names)
        existing_dict = {d[0]: existing[idx] for idx, d in enumerate(cur.description)} if cur.description else dict(zip([c[0] for c in cur.description], existing))
        
        # Get barcode and title for history logging
        barcode = existing_dict.get('BARCODE') or existing_dict.get('barcode') or existing_dict.get('Barcode') or ''
        title = existing_dict.get('TITLE') or existing_dict.get('title') or existing_dict.get('Title') or ''
        old_location = existing_dict.get('ITEM_POSITION') or existing_dict.get('item_position') or existing_dict.get('ItemPosition') or ''
        
        qty_cols = ['Quantity','quantity','Qty','QTY','QUANTITY']
        current_qty = None
        for qc in qty_cols:
            if qc in existing_dict and existing_dict.get(qc) is not None:
                try:
                    current_qty = int(existing_dict.get(qc))
                    break
                except Exception:
                    current_qty = None
        # default to 1 when quantity is not known
        if current_qty is None:
            current_qty = 1

        # If a pictureposition is provided, update PICTUREPOSITION and clear ITEM_POSITION
        if pictureposition:
            if 'PICTUREPOSITION' in cols or 'pictureposition' in [c.lower() for c in cols]:
                pic_col = 'PICTUREPOSITION' if 'PICTUREPOSITION' in cols else next((c for c in cols if c.lower() == 'pictureposition'), 'PICTUREPOSITION')
            else:
                pic_col = 'PICTUREPOSITION'
            # enforce single-location rule: set pictureposition and clear item_position
            # Handle splitting when move_qty provided and less than current_qty
            target_move = move_qty or current_qty
            if target_move < 1 or target_move > current_qty:
                return jsonify({'success': False, 'error': 'move_qty out of range'}), 400

            if target_move < current_qty:
                # decrement existing row's Quantity and insert a new row for moved qty
                # find quantity column name to update (if any)
                qty_col_name = None
                for qc in qty_cols:
                    if qc in cols:
                        qty_col_name = qc
                        break
                if qty_col_name:
                    # update original row quantity
                    if pk:
                        cur.execute(f"UPDATE SEARCHRACK SET {qty_col_name} = {qty_col_name} - ? WHERE {pk} = ?", (target_move, item_id))
                    else:
                        cur.execute(f"UPDATE SEARCHRACK SET {qty_col_name} = {qty_col_name} - ? WHERE rowid = ?", (target_move, item_id))
                else:
                    # no quantity column; treat as items of qty 1, so we will just insert new row and delete original
                    pass

                # prepare new row columns/values copied from existing, but with moved qty and new pictureposition/item_position
                # Exclude primary key column from INSERT so it auto-increments
                col_names = [c for c in cols if c not in (pk, 'id', 'ID', 'Id', 'rowid')]
                placeholders = ','.join('?' for _ in col_names)
                # build values copying existing row values, replacing quantity and picture/item position
                cur_vals = []
                for c in col_names:
                    # Find value from existing row (need to get column index from full cols list)
                    col_idx = cols.index(c)
                    val = existing[col_idx]
                    # replace quantity if applicable
                    if c == qty_col_name:
                        val = target_move
                    if c.lower() == 'pictureposition':
                        val = pictureposition
                    if c.lower() == 'item_position' or c == 'ITEM_POSITION' or c.lower() == 'itemposition':
                        # clear item position when pictureposition is set
                        val = ''
                    cur_vals.append(val)
                # Insert new row (without specifying rowid)
                cur.execute(f"INSERT INTO SEARCHRACK ({', '.join(col_names)}) VALUES ({placeholders})", tuple(cur_vals))
            else:
                # moving all items: update in-place
                if pk:
                    cur.execute(f"UPDATE SEARCHRACK SET {pic_col} = ?, ITEM_POSITION = ? WHERE {pk} = ?", (pictureposition, '', item_id))
                else:
                    cur.execute(f"UPDATE SEARCHRACK SET {pic_col} = ?, ITEM_POSITION = ? WHERE rowid = ?", (pictureposition, '', item_id))
        # Otherwise update only ITEM_POSITION and clear PICTUREPOSITION
        elif pos:
            # find picture column name if exists
            pic_col = None
            if 'PICTUREPOSITION' in cols:
                pic_col = 'PICTUREPOSITION'
            else:
                for c in cols:
                    if c.lower() == 'pictureposition':
                        pic_col = c
                        break
            # Handle splitting similar to pictureposition case
            target_move = move_qty or current_qty
            
            if target_move < 1 or target_move > current_qty:
                return jsonify({'success': False, 'error': 'move_qty out of range'}), 400

            if target_move < current_qty:
                # decrement existing row's Quantity
                qty_col_name = None
                for qc in qty_cols:
                    if qc in cols:
                        qty_col_name = qc
                        break
                if qty_col_name:
                    if pk:
                        cur.execute(f"UPDATE SEARCHRACK SET {qty_col_name} = {qty_col_name} - ? WHERE {pk} = ?", (target_move, item_id))
                    else:
                        cur.execute(f"UPDATE SEARCHRACK SET {qty_col_name} = {qty_col_name} - ? WHERE rowid = ?", (target_move, item_id))
                    
                    # Log the quantity reduction to history
                    try:
                        from datetime import datetime
                        now = datetime.now().isoformat()
                        removed_conn = sqlite3.connect('rackhistory.db')
                        removed_cur = removed_conn.cursor()
                        removed_cur.execute('''
                            INSERT INTO removed_items 
                            (barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                        ''', (barcode, title, target_move, now, item_id, current_qty, current_qty - target_move, 'location_edit', old_location))
                        removed_conn.commit()
                    except Exception:
                        pass
                    finally:
                        removed_conn.close()

                # insert new row for moved qty
                # Exclude primary key column from INSERT so it auto-increments
                col_names = [c for c in cols if c not in (pk, 'id', 'ID', 'Id', 'rowid')]
                placeholders = ','.join('?' for _ in col_names)
                cur_vals = []
                for c in col_names:
                    # Find value from existing row (need to get column index from full cols list)
                    col_idx = cols.index(c)
                    val = existing[col_idx]
                    if c == qty_col_name:
                        val = target_move
                    if c.lower() == 'pictureposition':
                        val = ''
                    if c.lower() == 'item_position' or c == 'ITEM_POSITION' or c.lower() == 'itemposition':
                        val = pos
                    cur_vals.append(val)
                cur.execute(f"INSERT INTO SEARCHRACK ({', '.join(col_names)}) VALUES ({placeholders})", tuple(cur_vals))
                
                # Log the new row creation to history
                try:
                    from datetime import datetime
                    now = datetime.now().isoformat()
                    removed_conn = sqlite3.connect('rackhistory.db')
                    removed_cur = removed_conn.cursor()
                    removed_cur.execute('''
                        INSERT INTO removed_items 
                        (barcode, title, quantity_removed, removed_at, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (barcode, title, target_move, now, 0, target_move, 'location_edit', pos))
                    removed_conn.commit()
                except Exception:
                    pass
                finally:
                    removed_conn.close()
            else:
                # update in-place - log location change
                if pk:
                    if pic_col:
                        cur.execute(f"UPDATE SEARCHRACK SET ITEM_POSITION = ?, {pic_col} = ? WHERE {pk} = ?", (pos, '', item_id))
                    else:
                        cur.execute(f"UPDATE SEARCHRACK SET ITEM_POSITION = ? WHERE {pk} = ?", (pos, item_id))
                else:
                    if pic_col:
                        cur.execute(f"UPDATE SEARCHRACK SET ITEM_POSITION = ?, {pic_col} = ? WHERE rowid = ?", (pos, '', item_id))
                    else:
                        cur.execute("UPDATE SEARCHRACK SET ITEM_POSITION = ? WHERE rowid = ?", (pos, item_id))
        conn.commit()
        updated = cur.rowcount
        _invalidate_searchrack_cache()
        return jsonify({'success': True, 'updated': updated})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()


def _get_table_and_pk(db_path, table_hint=None):
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
        tables = [r[0] for r in cur.fetchall()]
        if not tables:
            return None, None
        # Prefer common application tables if present (avoid picking auxiliary tables like ENRICH_META)
        prefer_order = ['orders', 'INVENTORY', 'SEARCHRACK', 'searchrack', 'rack', 'items', 'bol_items']
        prefer = None
        for p in prefer_order:
            if p in tables:
                prefer = p
                break
        table = table_hint if table_hint in tables else (prefer or (tables[0] if tables else None))
        cur.execute(f"PRAGMA table_info('{table}')")
        cols = cur.fetchall()
        pk = None
        colnames = [c[1] for c in cols]
        for c in cols:
            if c[5] == 1:
                pk = c[1]
                break
        if not pk:
            if 'id' in colnames:
                pk = 'id'
            elif 'ID' in colnames:
                pk = 'ID'
            else:
                pk = colnames[0]
    finally:
        conn.close()
    return table, pk


@app.route('/api/update/<db_key>/<int:item_id>', methods=['POST'])
def api_update_row(db_key, item_id):
    data = request.get_json() or {}
    mapping = {
        'ebayStore': 'ebayStore.db',
        'amazonStore': 'amazonStore.db',
        'sold': 'sold.db',
        'searchRack': 'searchRack.db',
        'found': 'found.db',
        'bol': 'bol.db'
    }
    if db_key not in mapping:
        return jsonify({'error': 'Unknown db_key'}), 400
    if db_key == 'searchRack':
        quantity_key = next((key for key in data if key.lower() == 'quantity'), None)
        if quantity_key is not None:
            parsed_quantity = _strict_inventory_quantity(data.get(quantity_key))
            if parsed_quantity is None or parsed_quantity < 0:
                return jsonify({
                    'error': 'Quantity must be a whole number of 0 or more; 0 archives and removes the row'
                }), 400
            data[quantity_key] = parsed_quantity
    db_path = mapping[db_key]
    try:
        table, pk = _get_table_and_pk(db_path)
        if not table:
            return jsonify({'error': 'No table found in DB'}), 400
        conn = sqlite3.connect(db_path)
        cur = conn.cursor()
        cur.execute(f"PRAGMA table_info('{table}')")
        cols = [r[1] for r in cur.fetchall()]
        
        # Debug logging
        print(f"DEBUG UPDATE: db_key={db_key}, table={table}, columns={cols}")
        print(f"DEBUG UPDATE: incoming data={data}")
        
        # If updating searchRack quantity, log old value for history tracking
        old_qty = None
        old_barcode = None
        old_title = None
        old_location = None
        tracker_upc_key = None
        tracker_prev_total = None
        if db_key == 'searchRack' and any(k.lower() == 'quantity' for k in data.keys()):
            try:
                cur.execute(f'SELECT QUANTITY, BARCODE, TITLE, ITEM_POSITION FROM {table} WHERE {pk} = ?', (item_id,))
                old_row = cur.fetchone()
                if old_row:
                    old_qty, old_barcode, old_title, old_location = old_row
                    old_qty = _coerce_int(old_qty, 0)
                    tracker_upc_key = _listing_alert_upc_key(old_barcode)
                    if tracker_upc_key:
                        tracker_prev_total = _searchrack_total_qty_for_key(conn, tracker_upc_key)
            except Exception as e:
                print(f"Warning: Could not fetch old values for history: {e}")
        
        set_parts = []
        params = []
        
        # Create case-insensitive column mapping
        cols_lower = {c.lower(): c for c in cols}
        
        for k, v in data.items():
            k_lower = k.lower()
            # Find matching column name (case-insensitive)
            if k_lower in cols_lower:
                actual_col = cols_lower[k_lower]
                set_parts.append(f"{actual_col} = ?")
                params.append(v)
            else:
                print(f"DEBUG UPDATE: Field '{k}' not found in columns (tried lowercase '{k_lower}')")
        
        if not set_parts:
            print(f"ERROR UPDATE: No updatable fields. Data keys: {list(data.keys())}, Table cols: {cols}")
            return jsonify({
                'error': 'No updatable fields provided',
                'data_keys': list(data.keys()),
                'table_columns': cols
            }), 400
        
        params.append(item_id)
        sql = f"UPDATE {table} SET {', '.join(set_parts)} WHERE {pk} = ?"
        print(f"DEBUG UPDATE: SQL={sql}, params={params}")
        
        cur.execute(sql, params)
        conn.commit()
        updated = cur.rowcount
        
        # Log quantity changes to history for searchRack
        if db_key == 'searchRack' and old_qty is not None:
            new_qty_raw = next((v for k, v in data.items() if k.lower() == 'quantity'), None)
            if new_qty_raw is not None:
                new_qty = _coerce_int(new_qty_raw, old_qty)
            else:
                new_qty = None
            if new_qty is not None and new_qty != old_qty:
                try:
                    from datetime import datetime
                    now = datetime.now()
                    
                    removed_conn = sqlite3.connect('rackhistory.db')
                    removed_cur = removed_conn.cursor()
                    _ensure_removed_items_table(removed_cur)
                    removed_cur.execute('''
                        INSERT INTO removed_items 
                        (order_id, barcode, title, quantity_removed, removed_at, searchrack_id, old_quantity, new_quantity, removal_type, item_position)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (None, old_barcode, old_title, abs(new_qty - old_qty), now.isoformat(), item_id, old_qty, new_qty, 'manual_edit', old_location or ''))
                    removed_conn.commit()
                    print(f"✅ Logged manual edit to history: {old_title} ({old_qty} → {new_qty})")
                except Exception as log_err:
                    print(f"❌ Error logging to history: {log_err}")
                    import traceback
                    traceback.print_exc()
                finally:
                    removed_conn.close()
        
        # The SEARCHRACK trigger snapshots and physically deletes a row that reaches zero.
        if db_key == 'searchRack' and 'quantity' in [k.lower() for k in data.keys()]:
            qty_value_raw = next((v for k, v in data.items() if k.lower() == 'quantity'), None)
            qty_value = _coerce_int(qty_value_raw, 0)
            if qty_value <= 0:
                _clear_zero_qty_pending_deletions(item_id)
                print(f"✅ searchRack item {item_id} was archived to Rack History and removed at quantity 0")
                conn.commit()
            elif qty_value > 0:
                _clear_zero_qty_pending_deletions(item_id)
                conn.commit()

        if db_key == 'searchRack' and tracker_upc_key and tracker_prev_total is not None:
            try:
                tracker_current_total = _searchrack_total_qty_for_key(conn, tracker_upc_key)
                _record_inventory_zero_transition(tracker_upc_key, tracker_prev_total, tracker_current_total)
            except Exception as tracker_err:
                print(f"Warning: zero-transition write tracking failed in api_update_row: {tracker_err}")

        if db_key == 'searchRack':
            _invalidate_searchrack_cache()

        print(f"DEBUG UPDATE: Updated {updated} rows")
        return jsonify({'success': True, 'updated': updated})
    except Exception as e:
        import traceback
        print(f"ERROR UPDATE: {e}")
        print(traceback.format_exc())
        return jsonify({'error': _safe_error(e)}), 500
    finally:
        conn.close()

@app.route('/api/check_shelf_code', methods=['POST'])
def api_check_shelf_code():
    """Check if a shelf code already exists"""
    data = request.get_json() or {}
    code, code_error = _validate_shelf_code_input(data.get('code'))
    
    if code_error:
        return jsonify({'exists': True, 'valid': False, 'reason': code_error}), 200
    
    conn = None
    try:
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        result = _shelf_code_exists(cur, code)
        
        if result:
            return jsonify({
                'exists': True,
                'valid': False,
                'reason': f'Shelf "{code}" already exists'
            }), 200
        else:
            return jsonify({
                'exists': False,
                'valid': True,
                'reason': 'Code available'
            }), 200
            
    except Exception as e:
        print(f"Error checking shelf code: {e}")
        return jsonify({'exists': False, 'reason': 'Error checking code'}), 500
    finally:
        if conn is not None:
            conn.close()


@app.route('/api/create_shelf', methods=['POST'])
def api_create_shelf():
    """Create a new shelf entry. Expects JSON: { shelf_name, location, notes, group_id (optional, defaults to 1) }"""
    data = request.get_json() or {}
    shelf_name = (data.get('shelf_name') or '').strip()
    location = (data.get('location') or '').strip()
    notes = (data.get('notes') or '').strip()
    group_id = data.get('group_id', 1)  # Default to group 1
    
    shelf_name, code_error = _validate_shelf_code_input(shelf_name)
    if code_error:
        return jsonify({'success': False, 'error': code_error}), 400
    
    conn = None
    try:
        ensure_shelf_groups_table()
        # Store shelves in a simple table in searchRack.db
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        cur.execute('BEGIN IMMEDIATE')
        if _shelf_code_exists(cur, shelf_name):
            return jsonify({'success': False, 'error': f'Shelf "{shelf_name}" already exists'}), 409
        cur.execute('SELECT id FROM shelf_groups WHERE id = ?', (group_id,))
        if not cur.fetchone():
            return jsonify({'success': False, 'error': 'Selected group does not exist'}), 404
        
        # Insert the new shelf with group_id
        cur.execute('''
            INSERT INTO shelves (shelf_name, location, notes, group_id)
            VALUES (?, ?, ?, ?)
        ''', (shelf_name, location, notes, group_id))
        
        conn.commit()
        shelf_id = cur.lastrowid
        
        return jsonify({
            'success': True,
            'message': f'Shelf "{shelf_name}" created successfully',
            'shelf_id': shelf_id
        })
    
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()


@app.route('/api/update_shelf', methods=['POST'])
def api_update_shelf():
    """Update an existing shelf image and/or rename the shelf code.
    Expects form-data: old_code (required), new_code (optional), image (optional file)
    """
    conn = None
    file_snapshots = {}
    affected_paths = set()
    try:
        old_code = _safe_shelf_lookup_code(request.form.get('old_code'))
        requested_new_code = str(request.form.get('new_code') or '').strip()
        if not old_code:
            return jsonify({'success': False, 'error': 'A valid old_code is required'}), 400
        if requested_new_code:
            target_code, code_error = _validate_shelf_code_input(requested_new_code)
            if code_error:
                return jsonify({'success': False, 'error': code_error}), 400
        else:
            target_code = old_code

        file = request.files.get('image')
        orig_file = request.files.get('original_image')
        for upload in (file, orig_file):
            if upload and upload.filename and not str(upload.mimetype or '').casefold().startswith('image/'):
                return jsonify({'success': False, 'error': 'Only image uploads are allowed'}), 400

        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db', timeout=30.0)
        cur = conn.cursor()
        cur.execute('BEGIN IMMEDIATE')
        existing_row = _shelf_code_exists(cur, old_code)
        if requested_new_code and _shelf_code_exists(cur, target_code, exclude_code=old_code):
            conn.rollback()
            return jsonify({'success': False, 'error': f'Shelf "{target_code}" already exists'}), 409

        old_path = _resolve_exact_shelf_display_path(old_code, existing_only=True)
        old_orig_path = _resolve_exact_shelf_original_path(old_code, existing_only=True)
        target_path = _resolve_exact_shelf_display_path(target_code, existing_only=False)
        target_orig_path = _resolve_exact_shelf_original_path(target_code, existing_only=False)
        if target_path is None or target_orig_path is None:
            conn.rollback()
            return jsonify({'success': False, 'error': 'Could not resolve safe shelf image paths'}), 400
        if requested_new_code and target_path.exists() and target_path != old_path:
            conn.rollback()
            return jsonify({'success': False, 'error': f'An image already exists for shelf "{target_code}"'}), 409
        if requested_new_code and target_orig_path.exists() and target_orig_path != old_orig_path:
            conn.rollback()
            return jsonify({'success': False, 'error': f'An original image already exists for shelf "{target_code}"'}), 409

        for path in (old_path, old_orig_path, target_path, target_orig_path):
            if path is None:
                continue
            affected_paths.add(path)
            if path.exists():
                file_snapshots[path] = path.read_bytes()

        if existing_row:
            cur.execute(
                'UPDATE shelves SET shelf_name = ? WHERE id = ?',
                (target_code, existing_row[0])
            )
        else:
            cur.execute(
                'INSERT INTO shelves (shelf_name, group_id, created_at) VALUES (?, 1, CURRENT_TIMESTAMP)',
                (target_code,)
            )

        if target_code.casefold() != old_code.casefold():
            cur.execute('''
                UPDATE SEARCHRACK
                SET ITEM_POSITION = CASE
                        WHEN LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?)) THEN ?
                        ELSE ITEM_POSITION
                    END,
                    PICTUREPOSITION = CASE
                        WHEN LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?)) THEN ?
                        ELSE PICTUREPOSITION
                    END
                WHERE LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?))
                   OR LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?))
            ''', (old_code, target_code, old_code, target_code, old_code, old_code))

        original_only = _truthy_form_value(request.form.get('original_only'))
        saved_display = False
        if file and file.filename and (not original_only or old_path is None):
            target_path.parent.mkdir(parents=True, exist_ok=True)
            _save_uploaded_shelf_png(file, target_path)
            saved_display = True
        elif target_code.casefold() != old_code.casefold() and old_path and old_path.exists():
            target_path.parent.mkdir(parents=True, exist_ok=True)
            os.replace(str(old_path), str(target_path))

        if orig_file and orig_file.filename:
            target_orig_path.parent.mkdir(parents=True, exist_ok=True)
            _save_uploaded_shelf_png(orig_file, target_orig_path)
        elif target_code.casefold() != old_code.casefold() and old_orig_path and old_orig_path.exists():
            target_orig_path.parent.mkdir(parents=True, exist_ok=True)
            os.replace(str(old_orig_path), str(target_orig_path))

        if target_code.casefold() != old_code.casefold():
            if saved_display and old_path and old_path.exists() and old_path != target_path:
                old_path.unlink()
            if orig_file and orig_file.filename and old_orig_path and old_orig_path.exists() and old_orig_path != target_orig_path:
                old_orig_path.unlink()

        conn.commit()
        try:
            if saved_display and target_path.exists():
                _sync_preview_base_image(target_code, target_path)
            elif target_orig_path.exists():
                _sync_original_to_preview_base(target_code)
            if target_code.casefold() != old_code.casefold():
                _delete_preview_base_image(old_code)
        except Exception as preview_error:
            print(f'Warning: shelf preview sync failed for {target_code}: {preview_error}')
        _invalidate_searchrack_cache()
        return jsonify({'success': True, 'code': target_code})
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        for path in affected_paths:
            try:
                if path in file_snapshots:
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_bytes(file_snapshots[path])
                elif path.exists():
                    path.unlink()
            except Exception as restore_error:
                print(f'Failed to restore shelf file {path}: {restore_error}')
        status = 400 if isinstance(e, ValueError) else 500
        return jsonify({'success': False, 'error': _safe_error(e)}), status
    finally:
        if conn is not None:
            conn.close()


@app.route('/api/clear_shelf_inventory/<code>', methods=['POST'])
def api_clear_shelf_inventory(code):
    """Clear an exact shelf code from current and legacy inventory locations."""
    conn = None
    sconn = None
    try:
        code = _safe_shelf_lookup_code(code)
        if not code:
            return jsonify({'success': False, 'error': 'A valid shelf code is required'}), 400

        sconn = sqlite3.connect('searchRack.db', timeout=30.0)
        scur = sconn.cursor()
        scur.execute('BEGIN IMMEDIATE')
        scur.execute('''
            UPDATE SEARCHRACK
            SET ITEM_POSITION = CASE
                    WHEN LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?)) THEN ''
                    ELSE ITEM_POSITION
                END,
                PICTUREPOSITION = CASE
                    WHEN LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?)) THEN ''
                    ELSE PICTUREPOSITION
                END
            WHERE LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?))
               OR LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?))
        ''', (code, code, code, code))
        search_updated = scur.rowcount
        sconn.commit()

        # Legacy rack.db is best-effort compatibility; searchRack.db is the
        # authoritative warehouse database.
        legacy_updated = 0
        try:
            conn = sqlite3.connect('rack.db', timeout=10.0)
            cur = conn.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [str(row[0]) for row in cur.fetchall()]
            table_name = next(
                (name for name in tables if name.casefold() in ('items', 'inventory')),
                None
            )
            if table_name:
                cur.execute(f'PRAGMA table_info({_sqlite_ident(table_name)})')
                columns = [str(row[1]) for row in cur.fetchall()]
                location_columns = [
                    column for column in columns
                    if column.casefold() in ('item_position', 'itemposition', 'position', 'location', 'pictureposition')
                ]
                for column in location_columns:
                    cur.execute(
                        f'''UPDATE {_sqlite_ident(table_name)}
                            SET {_sqlite_ident(column)} = ''
                            WHERE LOWER(TRIM(COALESCE({_sqlite_ident(column)}, ''))) = LOWER(TRIM(?))''',
                        (code,)
                    )
                    legacy_updated += cur.rowcount
                conn.commit()
        except Exception as legacy_error:
            print(f'Warning: legacy rack.db shelf clear failed for {code}: {legacy_error}')

        _invalidate_searchrack_cache()
        return jsonify({
            'success': True,
            'updated': search_updated,
            'search_updated': search_updated,
            'legacy_updated': legacy_updated
        })
    except Exception as e:
        if sconn is not None:
            try:
                sconn.rollback()
            except Exception:
                pass
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()
        if sconn is not None:
            sconn.close()


@app.route('/api/list_shelves', methods=['GET'])
def api_list_shelves():
    """Return the union of shelf metadata and exact shelf image files."""
    try:
        sort = (request.args.get('sort') or 'created').lower()
        results = []
        files = _iter_shelf_display_files()
        file_map = {path.stem.casefold().strip(): path for path in files if path.stem.strip()}
        metadata_map = {}
        counts_map = {}

        ensure_shelf_groups_table()
        with db_connection('searchRack.db') as conn:
            cur = conn.cursor()
            cur.execute('SELECT shelf_name, created_at, group_id FROM shelves ORDER BY id')
            for row in cur.fetchall():
                code = str(row['shelf_name'] or '').strip()
                if code and code.casefold() not in metadata_map:
                    metadata_map[code.casefold()] = {
                        'code': code,
                        'created_at': row['created_at'],
                        'group_id': row['group_id']
                    }

            # Count physical units once per distinct location key on each row.
            cur.execute('''
                SELECT ITEM_POSITION, PICTUREPOSITION,
                       COALESCE(CAST(QUANTITY AS INTEGER), 0) AS quantity
                FROM SEARCHRACK
                WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
            ''')
            for row in cur.fetchall():
                qty = max(0, _coerce_int(row['quantity'], 0))
                keys = {
                    str(row['ITEM_POSITION'] or '').strip().casefold(),
                    str(row['PICTUREPOSITION'] or '').strip().casefold()
                }
                for key in keys:
                    if key:
                        counts_map[key] = counts_map.get(key, 0) + qty

        for normalized_code in sorted(set(file_map) | set(metadata_map)):
            path = file_map.get(normalized_code)
            metadata = metadata_map.get(normalized_code, {})
            code = str(metadata.get('code') or (path.stem if path else '')).strip()
            if not code:
                continue
            mtime = 0
            cache_version = ''
            if path is not None:
                try:
                    stat_info = path.stat()
                    mtime = stat_info.st_mtime
                    cache_version = str(getattr(stat_info, 'st_mtime_ns', int(mtime * 1000000000)))
                except Exception:
                    cache_version = str(int(time.time() * 1000000000))
            results.append({
                'code': code,
                'filename': path.name if path else '',
                'url': url_for('shelf_image', code=code) if path else '',
                'has_image': bool(path),
                'lastModified': int(mtime),
                'cacheVersion': cache_version,
                'created_at': metadata.get('created_at'),
                'count': int(counts_map.get(normalized_code, 0)),
                'group_id': metadata.get('group_id') or 1
            })

        if sort == 'items':
            results.sort(key=lambda x: x.get('count', 0), reverse=True)
        elif sort == 'created':
            def created_key(item):
                created_at = item.get('created_at')
                if created_at:
                    return str(created_at).replace('T', ' ')
                try:
                    return datetime.datetime.fromtimestamp(
                        item.get('lastModified', 0)
                    ).strftime('%Y-%m-%d %H:%M:%S')
                except Exception:
                    return '1970-01-01 00:00:00'
            results.sort(key=created_key, reverse=True)
        else:
            results.sort(key=lambda x: (x.get('code') or '').casefold())
        return jsonify({'success': True, 'shelves': results})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500


@app.route('/api/shelf_counts', methods=['POST'])
def api_shelf_counts():
    """Return physical-unit counts for shelf codes across both location columns."""
    sconn = None
    try:
        codes = request.get_json() or {}
        codes = codes.get('codes', []) if isinstance(codes, dict) else codes
        if not isinstance(codes, list):
            return jsonify({'success': False, 'error': 'codes must be a list'}), 400

        result = {}
        sconn = sqlite3.connect('searchRack.db')
        scur = sconn.cursor()
        for code in codes:
            scur.execute('''
                SELECT COALESCE(SUM(COALESCE(CAST(QUANTITY AS INTEGER), 0)), 0)
                FROM SEARCHRACK
                WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
                  AND (
                    LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?))
                    OR LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?))
                  )
            ''', (code, code))
            row = scur.fetchone()
            result[code] = {'searchrack': int(row[0] or 0) if row else 0}

        return jsonify({'success': True, 'counts': result})
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if sconn is not None:
            sconn.close()


# ============================================================================
# SHELF GROUPS API
# ============================================================================

def ensure_shelf_groups_table():
    """Ensure shelf_groups table exists and shelves table has group_id column"""
    conn = None
    try:
        if has_app_context():
            with db_connection('searchRack.db', row_factory=False) as conn_ctx:
                cur = conn_ctx.cursor()

                # Create shelves table if it doesn't exist
                cur.execute('''
                    CREATE TABLE IF NOT EXISTS shelves (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        shelf_name TEXT NOT NULL,
                        location TEXT,
                        notes TEXT,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    )
                ''')

                # Create shelf_groups table if it doesn't exist
                cur.execute('''
                    CREATE TABLE IF NOT EXISTS shelf_groups (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT NOT NULL,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    )
                ''')

                # Check if shelves table has group_id column
                cur.execute('PRAGMA table_info(shelves)')
                columns = [row[1] for row in cur.fetchall()]

                if 'group_id' not in columns:
                    # Add group_id column (defaults to NULL, meaning ungrouped)
                    cur.execute('ALTER TABLE shelves ADD COLUMN group_id INTEGER')
                    print('[SHELF_GROUPS] Added group_id column to shelves table')

                # Ensure default group exists (id=1, name="Default Group")
                cur.execute('SELECT id FROM shelf_groups WHERE id = 1')
                if not cur.fetchone():
                    cur.execute('INSERT INTO shelf_groups (id, name) VALUES (1, ?)', ('Default Group',))
                    print('[SHELF_GROUPS] Created default group')
        else:
            conn = sqlite3.connect(str(BASE_DIR / 'searchRack.db'), timeout=30.0)
            cur = conn.cursor()

            cur.execute('''
                CREATE TABLE IF NOT EXISTS shelves (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    shelf_name TEXT NOT NULL,
                    location TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            cur.execute('''
                CREATE TABLE IF NOT EXISTS shelf_groups (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            cur.execute('PRAGMA table_info(shelves)')
            columns = [row[1] for row in cur.fetchall()]
            if 'group_id' not in columns:
                cur.execute('ALTER TABLE shelves ADD COLUMN group_id INTEGER')
                print('[SHELF_GROUPS] Added group_id column to shelves table')
            cur.execute('SELECT id FROM shelf_groups WHERE id = 1')
            if not cur.fetchone():
                cur.execute('INSERT INTO shelf_groups (id, name) VALUES (1, ?)', ('Default Group',))
                print('[SHELF_GROUPS] Created default group')
            conn.commit()
        return True
    except Exception as e:
        print(f'[SHELF_GROUPS] Error ensuring tables: {e}')
        import traceback
        traceback.print_exc()
        return False
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/groups', methods=['GET'])
def api_get_groups():
    """Get all shelf groups with shelf counts"""
    conn = None
    try:
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db')
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        
        # Get all groups with shelf counts
        cur.execute('''
            SELECT 
                g.id,
                g.name,
                g.created_at,
                COUNT(CASE WHEN s.id = (
                    SELECT MIN(s2.id)
                    FROM shelves s2
                    WHERE LOWER(TRIM(s2.shelf_name)) = LOWER(TRIM(s.shelf_name))
                ) THEN 1 END) as shelf_count
            FROM shelf_groups g
            LEFT JOIN shelves s ON s.group_id = g.id
            GROUP BY g.id
            ORDER BY g.id
        ''')
        
        groups = [dict(row) for row in cur.fetchall()]
        
        return jsonify({'success': True, 'groups': groups})
    except Exception as e:
        print(f'[api_get_groups] Error: {e}')
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/create_group', methods=['POST'])
def api_create_group():
    """Create a new shelf group"""
    conn = None
    try:
        data = request.get_json() or {}
        name = (data.get('name') or '').strip()
        
        if not name:
            return jsonify({'success': False, 'error': 'Group name is required'}), 400
        if len(name) > 80:
            return jsonify({'success': False, 'error': 'Group name must be 80 characters or fewer'}), 400
        
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        cur.execute('BEGIN IMMEDIATE')
        cur.execute(
            'SELECT id FROM shelf_groups WHERE LOWER(TRIM(name)) = LOWER(TRIM(?)) LIMIT 1',
            (name,)
        )
        if cur.fetchone():
            return jsonify({'success': False, 'error': 'A group with that name already exists'}), 409
        
        cur.execute('INSERT INTO shelf_groups (name) VALUES (?)', (name,))
        group_id = cur.lastrowid
        
        conn.commit()
        
        return jsonify({
            'success': True,
            'group_id': group_id,
            'message': f'Group "{name}" created successfully'
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/delete_group', methods=['POST'])
def api_delete_group():
    """Delete a shelf group and move its shelves to Default Group (id=1)"""
    conn = None
    try:
        data = request.get_json() or {}
        try:
            group_id = int(data.get('group_id'))
        except (TypeError, ValueError):
            group_id = 0
        
        if not group_id:
            return jsonify({'success': False, 'error': 'group_id is required'}), 400
        
        if group_id == 1:
            return jsonify({'success': False, 'error': 'Cannot delete Default Group'}), 400
        
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        
        # Move all shelves from this group to Default Group (id=1)
        cur.execute('UPDATE shelves SET group_id = 1 WHERE group_id = ?', (group_id,))
        moved_count = cur.rowcount
        
        # Delete the group
        cur.execute('DELETE FROM shelf_groups WHERE id = ?', (group_id,))
        if cur.rowcount == 0:
            conn.rollback()
            return jsonify({'success': False, 'error': 'Group not found'}), 404
        
        conn.commit()
        
        return jsonify({
            'success': True,
            'moved_shelves': moved_count,
            'message': f'Group deleted. {moved_count} shelf(es) moved to Default Group.'
        })
    except Exception as e:
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/move_shelves', methods=['POST'])
def api_move_shelves():
    """Move shelves to a different group. Accepts shelf_codes (list of shelf names) and group_id (or target_group_id)."""
    conn = None
    try:
        data = request.get_json() or {}
        shelf_codes = data.get('shelf_codes', [])
        target_group_id = data.get('group_id') or data.get('target_group_id')
        
        if not isinstance(shelf_codes, list) or not shelf_codes or target_group_id is None:
            return jsonify({'success': False, 'error': 'shelf_codes and group_id are required'}), 400
        try:
            target_group_id = int(target_group_id)
        except (TypeError, ValueError):
            return jsonify({'success': False, 'error': 'group_id must be an integer'}), 400
        normalized_codes = []
        seen_codes = set()
        for value in shelf_codes:
            code = _safe_shelf_lookup_code(value)
            if not code:
                return jsonify({'success': False, 'error': 'Every shelf code must be valid'}), 400
            key = code.casefold()
            if key not in seen_codes:
                normalized_codes.append(code)
                seen_codes.add(key)
        
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db')
        cur = conn.cursor()
        
        # Verify target group exists
        cur.execute('SELECT id FROM shelf_groups WHERE id = ?', (target_group_id,))
        if not cur.fetchone():
            return jsonify({'success': False, 'error': 'Target group does not exist'}), 404
        
        # For each shelf code, ensure it exists in the shelves table (create if missing)
        moved_count = 0
        for code in normalized_codes:
            cur.execute(
                'SELECT id FROM shelves WHERE LOWER(TRIM(shelf_name)) = LOWER(TRIM(?)) LIMIT 1',
                (code,)
            )
            row = cur.fetchone()
            if not row:
                # Shelf doesn't exist in table, create it
                cur.execute('INSERT INTO shelves (shelf_name, group_id) VALUES (?, ?)', (code, target_group_id))
                print(f'[MOVE_SHELVES] Created missing shelf entry for {code}')
                moved_count += 1
            else:
                cur.execute(
                    'UPDATE shelves SET group_id = ? '
                    'WHERE LOWER(TRIM(shelf_name)) = LOWER(TRIM(?))',
                    (target_group_id, code)
                )
                moved_count += 1
        
        conn.commit()
        
        return jsonify({
            'success': True,
            'moved_count': moved_count,
            'message': f'{moved_count} shelf(es) moved successfully'
        })
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/upload_shelf', methods=['POST'])
def api_upload_shelf():
    """Upload a shelf image and associate it with a group"""
    conn = None
    created_paths = []
    try:
        group_id = request.form.get('group_id', 1)  # Default to group 1
        try:
            group_id = int(group_id)
        except Exception:
            group_id = 1
        
        if 'image' not in request.files:
            return jsonify({'success': False, 'error': 'No image file provided'}), 400
        
        file = request.files['image']
        if not file.filename:
            return jsonify({'success': False, 'error': 'Empty filename'}), 400
        if not str(file.mimetype or '').casefold().startswith('image/'):
            return jsonify({'success': False, 'error': 'Only image uploads are allowed'}), 400
        
        # Use provided code or generate a unique shelf code
        requested_code = request.form.get('code')
        if not requested_code:
            import uuid
            requested_code = str(uuid.uuid4())[:8].upper()
        shelf_code, code_error = _validate_shelf_code_input(requested_code)
        if code_error:
            return jsonify({'success': False, 'error': code_error}), 400

        original_only = _truthy_form_value(request.form.get('original_only'))
        ensure_shelf_groups_table()
        conn = sqlite3.connect('searchRack.db', timeout=30.0)
        cur = conn.cursor()
        cur.execute('BEGIN IMMEDIATE')
        if _shelf_code_exists(cur, shelf_code):
            conn.rollback()
            return jsonify({'success': False, 'error': f'Shelf "{shelf_code}" already exists'}), 409
        cur.execute('SELECT id FROM shelf_groups WHERE id = ?', (group_id,))
        if not cur.fetchone():
            conn.rollback()
            return jsonify({'success': False, 'error': 'Selected group does not exist'}), 404

        target_display_path = _resolve_exact_shelf_display_path(shelf_code, existing_only=False)
        orig_path = _resolve_exact_shelf_original_path(shelf_code, existing_only=False)
        if target_display_path is None or orig_path is None:
            conn.rollback()
            return jsonify({'success': False, 'error': 'Could not resolve safe shelf image paths'}), 400
        if any(path.exists() for path in _shelf_exact_display_path_candidates(shelf_code)):
            conn.rollback()
            return jsonify({'success': False, 'error': f'An image already exists for shelf "{shelf_code}"'}), 409

        cur.execute('''
            INSERT INTO shelves (shelf_name, group_id, created_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
        ''', (shelf_code, group_id))

        target_display_path.parent.mkdir(parents=True, exist_ok=True)
        _save_uploaded_shelf_png(file, target_display_path)
        created_paths.append(target_display_path)
        orig_file = request.files.get('original_image')
        if orig_file and orig_file.filename:
            if not str(orig_file.mimetype or '').casefold().startswith('image/'):
                raise ValueError('Only image uploads are allowed')
            orig_path.parent.mkdir(parents=True, exist_ok=True)
            _save_uploaded_shelf_png(orig_file, orig_path)
            created_paths.append(orig_path)

        conn.commit()
        try:
            if not original_only or target_display_path.exists():
                _sync_preview_base_image(shelf_code, target_display_path)
            elif orig_path.exists():
                _sync_original_to_preview_base(shelf_code)
        except Exception as preview_error:
            print(f'Warning: shelf preview sync failed for {shelf_code}: {preview_error}')
        
        return jsonify({
            'success': True,
            'code': shelf_code,
            'message': f'Shelf {shelf_code} uploaded successfully'
        })
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        for path in created_paths:
            try:
                path.unlink(missing_ok=True)
            except Exception:
                pass
        status = 400 if isinstance(e, ValueError) else 500
        return jsonify({'success': False, 'error': _safe_error(e)}), status
    finally:
        if conn is not None:
            conn.close()

@app.route('/api/delete_shelf', methods=['POST'])
def api_delete_shelf():
    """Delete an empty shelf, staging exact files until the DB commit succeeds."""
    conn = None
    staged_paths = []
    try:
        data = request.get_json() or {}
        shelf_id = data.get('shelf_id')
        shelf_code = _safe_shelf_lookup_code(data.get('code'))

        if not shelf_id and not shelf_code:
            return jsonify({'success': False, 'error': 'shelf_id or code is required'}), 400

        conn = sqlite3.connect('searchRack.db', timeout=30.0)
        cur = conn.cursor()
        cur.execute('BEGIN IMMEDIATE')
        code_to_delete = None

        if shelf_id:
            cur.execute('SELECT shelf_name FROM shelves WHERE id = ?', (shelf_id,))
            row = cur.fetchone()
            if row:
                code_to_delete = row[0]
            else:
                conn.rollback()
                return jsonify({'success': False, 'error': 'Shelf not found'}), 404
        else:
            cur.execute(
                'SELECT id, shelf_name FROM shelves WHERE LOWER(TRIM(shelf_name)) = LOWER(TRIM(?)) LIMIT 1',
                (shelf_code,)
            )
            row = cur.fetchone()
            if row:
                shelf_id = row[0]
                code_to_delete = row[1]
            else:
                code_to_delete = shelf_code

        cur.execute('''
            SELECT COUNT(*), COALESCE(SUM(COALESCE(CAST(QUANTITY AS INTEGER), 0)), 0)
            FROM SEARCHRACK
            WHERE COALESCE(CAST(QUANTITY AS INTEGER), 0) > 0
              AND (
                  LOWER(TRIM(COALESCE(ITEM_POSITION, ''))) = LOWER(TRIM(?))
                  OR LOWER(TRIM(COALESCE(PICTUREPOSITION, ''))) = LOWER(TRIM(?))
              )
        ''', (code_to_delete, code_to_delete))
        active_count, active_units = cur.fetchone()
        if active_count:
            conn.rollback()
            return jsonify({
                'success': False,
                'error': (
                    f'Shelf {code_to_delete} still contains {int(active_units or 0)} active unit(s). '
                    'Move or remove those items before deleting the shelf.'
                ),
                'active_items': int(active_count or 0),
                'active_units': int(active_units or 0)
            }), 409

        # Rename exact shelf files to hidden recovery names before changing the
        # database. This avoids both ghost records and irreversible partial deletes.
        import uuid
        exact_paths = (
            _shelf_exact_display_path_candidates(code_to_delete)
            + _shelf_exact_original_path_candidates(code_to_delete)
        )
        preview_path = _preview_base_path_for_code(code_to_delete)
        if preview_path is not None:
            exact_paths.append(preview_path)
        seen_paths = set()
        for path in exact_paths:
            if path in seen_paths or not path.exists():
                continue
            seen_paths.add(path)
            staged = path.with_name(f'.{path.name}.delete-{uuid.uuid4().hex}')
            os.replace(str(path), str(staged))
            staged_paths.append((path, staged))

        if shelf_id:
            cur.execute('DELETE FROM shelves WHERE id = ?', (shelf_id,))
        conn.commit()
        cleanup_warnings = []
        for _, staged in staged_paths:
            try:
                staged.unlink(missing_ok=True)
            except Exception as cleanup_error:
                cleanup_warnings.append(str(cleanup_error))
        _invalidate_searchrack_cache()
        return jsonify({
            'success': True,
            'message': f'Shelf {code_to_delete} deleted successfully',
            'cleanup_pending': bool(cleanup_warnings)
        })
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        for original, staged in reversed(staged_paths):
            try:
                if staged.exists():
                    original.parent.mkdir(parents=True, exist_ok=True)
                    os.replace(str(staged), str(original))
            except Exception as restore_error:
                print(f'Failed to restore staged shelf file {staged}: {restore_error}')
        return jsonify({'success': False, 'error': _safe_error(e)}), 500
    finally:
        if conn is not None:
            conn.close()

